# Standalone consolidated Resident Pipeline.
# This file intentionally does not source earlier Resident pipeline versions.

.resident_repo_root <-
function () 
{
    base <- normalizePath(getwd(), mustWork = FALSE)
    candidates <- unique(c(
        base,
        file.path(base, "Outputs"),
        file.path(base, ".."),
        file.path(base, "..", "Outputs"),
        if (!is.null(sys.frames()[[1]]$ofile)) dirname(normalizePath(sys.frames()[[1]]$ofile, mustWork = FALSE)) else NULL
    ))
    for (dir in candidates) {
        if (file.exists(file.path(dir, "resident_pipeline_v0.9.41.R")) ||
            file.exists(file.path(dir, "Outputs", "resident_pipeline_v0.9.41.R"))) {
            if (basename(dir) == "Outputs")
                return(normalizePath(dirname(dir), mustWork = FALSE))
            return(normalizePath(dir, mustWork = FALSE))
        }
    }
    normalizePath(base, mustWork = FALSE)
}
.resident_ensure_repo_root <-
function () 
{
    root <- .resident_repo_root()
    if (file.exists(file.path(root, "resident_pipeline_v0.9.41.R")) ||
        file.exists(file.path(root, "Outputs", "resident_pipeline_v0.9.41.R"))) {
        root <- normalizePath(root, mustWork = FALSE)
        if (!identical(normalizePath(getwd(), mustWork = FALSE), root)) 
            setwd(root)
    }
    invisible(root)
}
.resident_ensure_repo_root()

.adjust_transition_persistence <-
function (mat, matrix_type) 
{
    matrix_type <- match.arg(matrix_type, c("biologically_informed", 
        "conservative", "mobile"))
    if (matrix_type == "biologically_informed") 
        return(mat)
    out <- mat
    K <- nrow(out)
    for (i in seq_len(K)) {
        old_diag <- out[i, i]
        if (matrix_type == "conservative") {
            new_diag <- min(0.995, old_diag + 0.5 * (1 - old_diag))
        }
        else {
            new_diag <- max(0.050000000000000003, old_diag - 
                min(0.17999999999999999, 0.25 * old_diag))
        }
        off_old <- out[i, -i, drop = FALSE]
        off_sum <- sum(off_old)
        out[i, i] <- new_diag
        if (off_sum > 0) {
            out[i, -i] <- as.numeric(off_old)/off_sum * (1 - 
                new_diag)
        }
        else {
            out[i, -i] <- (1 - new_diag)/(K - 1L)
        }
    }
    out/rowSums(out)
}
