.as_positive_integer <-
function (x, name) 
{
    val <- suppressWarnings(as.integer(x))
    if (is.na(val) || val < 1 || as.character(val) != as.character(as.integer(val))) {
        stop(name, " must be a positive integer.")
    }
    val
}
.as_probability <-
function (x, name) 
{
    val <- suppressWarnings(as.numeric(x))
    if (!is.finite(val) || val < 0 || val > 1) 
        stop(name, " must be a probability between 0 and 1.")
    val
}
