.ask_choice <-
function (prompt, choices, input_provider = NULL, default = choices[1]) 
{
    repeat {
        cat(prompt, "\n", sep = "")
        for (i in seq_along(choices)) cat(i, ". ", choices[i], 
            "\n", sep = "")
        ans <- .resident_prompt("Enter option number or name: ", 
            input_provider)
        key <- tolower(trimws(as.character(ans)))
        if (!nzchar(key) && !is.null(default)) 
            return(default)
        if (key %in% as.character(seq_along(choices))) 
            return(choices[as.integer(key)])
        hit <- choices[tolower(choices) == key]
        if (length(hit)) 
            return(hit[1])
        cat("Please choose one of the listed options.\n")
    }
}
