.boundary_flag <-
function (x) 
is.finite(x) & (x <= 0.02 | x >= 0.97999999999999998)
.capture_matrix_from_object <-
function (x) 
{
    if (is.null(x)) 
        return(NULL)
    if (is.matrix(x)) 
        return(x)
    if (is.data.frame(x)) {
        num <- x[, vapply(x, is.numeric, logical(1)), drop = FALSE]
        if (ncol(num)) 
            return(as.matrix(num))
    }
    if (is.list(x)) {
        if (!is.null(x$observed)) 
            return(.capture_matrix_from_object(x$observed))
        if (!is.null(x$history)) 
            return(.capture_matrix_from_object(x$history))
        if (!is.null(x$sim)) {
            if (is.list(x$sim) && !is.null(x$sim$observed)) 
                return(.capture_matrix_from_object(x$sim$observed))
            return(.capture_matrix_from_object(x$sim))
        }
    }
    NULL
}
.cjs_formula_vector <-
function (formula, data, n, prefix) 
{
    f <- paste(deparse(formula), collapse = "")
    if (f %in% c("~1", "~ 1")) 
        return(rep(0, n))
    if (grepl("time", f)) 
        return(seq_len(n) - 1L)
    if (grepl("effort", f) && "effort" %in% names(data)) 
        return(as.numeric(data$effort[seq_len(n)]))
    rep(0, n)
}
.closed_prob_matrix <-
function (y, abundance_model, par) 
{
    y <- .as_history_matrix(y)
    K <- ncol(y)
    if (abundance_model == "closed_M0") {
        p <- rep(.invlogit(par[["lp"]]), K)
        prob <- exp(rowSums(y * log(p) + (1 - y) * log1p(-p)))
        q0 <- prod(1 - p)
        list(prob = prob, q0 = q0, p = p, c = NA_real_, pi = NA_real_)
    }
    else if (abundance_model == "closed_Mt") {
        lp <- par[paste0("lp", seq_len(K))]
        p <- .invlogit(lp)
        prob <- exp(rowSums(y * matrix(log(p), nrow(y), K, byrow = TRUE) + 
            (1 - y) * matrix(log1p(-p), nrow(y), K, byrow = TRUE)))
        q0 <- prod(1 - p)
        list(prob = prob, q0 = q0, p = p, c = NA_real_, pi = NA_real_)
    }
    else if (abundance_model == "closed_Mb") {
        p <- .invlogit(par[["lp"]])
        cc <- .invlogit(par[["lc"]])
        prob <- apply(y, 1, function(row) {
            seen <- FALSE
            ans <- 1
            for (val in row) {
                pr <- if (seen) 
                  cc
                else p
                ans <- ans * if (val > 0) 
                  pr
                else (1 - pr)
                if (val > 0) 
                  seen <- TRUE
            }
            ans
        })
        q0 <- (1 - p)^K
        list(prob = prob, q0 = q0, p = rep(p, K), c = rep(cc, 
            K), pi = NA_real_)
    }
    else if (abundance_model %in% c("closed_Mh_mixture", "closed_Mth_mixture")) {
        pi1 <- .invlogit(par[["lpi1"]])
        if (abundance_model == "closed_Mh_mixture") {
            p1 <- rep(.invlogit(par[["lp1"]]), K)
            p2 <- rep(.invlogit(par[["lp2"]]), K)
        }
        else {
            p1 <- .invlogit(par[paste0("lp1_", seq_len(K))])
            p2 <- .invlogit(par[paste0("lp2_", seq_len(K))])
        }
        prob_class <- function(p) {
            exp(rowSums(y * matrix(log(p), nrow(y), K, byrow = TRUE) + 
                (1 - y) * matrix(log1p(-p), nrow(y), K, byrow = TRUE)))
        }
        prob <- pi1 * prob_class(p1) + (1 - pi1) * prob_class(p2)
        q0 <- pi1 * prod(1 - p1) + (1 - pi1) * prod(1 - p2)
        list(prob = prob, q0 = q0, p = rbind(class_1 = p1, class_2 = p2), 
            c = NA_real_, pi = c(class_1 = pi1, class_2 = 1 - 
                pi1))
    }
    else {
        stop("Unsupported closed abundance model.", call. = FALSE)
    }
}
.configuration_parameter_section <-
function (parameter) 
{
    if (parameter %in% c("N", "initial_sampling_date", "final_sampling_date", 
        "requested_number_of_sampling_occasions", "number_of_sampling_occasions", 
        "occasion_unit")) 
        return("Population and time")
    if (parameter %in% c("sampling_design", "n_random_occasions", 
        "n_consecutive_days", "empirical_dates", "selected_sampling_dates")) 
        return("Sampling design")
    if (parameter %in% c("primary_period", "secondary_period_design", 
        "fixed_secondary_per_primary", "consecutive_secondary_days", 
        "empirical_secondary_dates")) 
        return("Robust-design structure")
    if (parameter %in% c("p", "detection_formula_mode", "detection_formula", 
        "baseline_detection_probability", "effort_detection_effect", 
        "beta", "detection_covariate_assumptions", "detection_covariate_assumption_notes", 
        "detection_assumption_option", "detection_assumption_formula", 
        "detection_assumption_required_covariates", "detection_assumption_parameter_count", 
        "detection_assumption_random_effects", "detection_assumption_backend_requirements", 
        "detection_assumption_diagnostic_status", "detection_assumption_identifiability_warning", 
        "detection_assumption_consequence_summary", "detection_assumption_warnings")) 
        return("Detection model")
    if (parameter %in% c("effort_beta", "effort_variable_type", 
        "effort_units", "effort_custom_definition", "effort_scaling")) 
        return("Effort covariates")
    if (parameter %in% c("states", "unavailable_states", "state_detection")) 
        return("State-detection values")
    if (parameter %in% c("transition_time_scale", "transition_matrix_source", 
        "transition_matrix_type", "transition_estimation", "transition_time_scale_explanation", 
        "transition_matrix", "initial_probs")) 
        return("Transition model")
    if (parameter %in% c("rmax", "recapture_distribution", "recapture_params", 
        "allow_zero")) 
        return("Recapture distribution")
    if (parameter %in% c("simulation_model", "phi", "entry_probability_mode", 
        "b", "drop_never_detected")) 
        return("Open-population parameters")
    if (parameter %in% c("individual_re_sd", "sigma_individual_detection", 
        "sigma_primary_detection", "sigma_state_detection")) 
        return("Random effects")
    if (parameter %in% c("display_discovery_plots", "export_discovery_jpg", 
        "discovery_jpg_prefix", "discovery_jpg_output_dir", "compare_to_observed", 
        "observed_data", "plot_capture_frequency_comparison", 
        "plot_discovery_curve_comparison", "configuration_review_verbosity", 
        "save_full_configuration_report", "show_full_configuration_in_console", 
        "robust_design_inference")) 
        return("Output and export settings")
    if (parameter %in% c("parameter_warnings", "validation_warnings")) 
        return("Warnings and diagnostics")
    if (parameter %in% c("possible_number_of_dates", "actual_number_of_sampling_occasions", 
        "actual_number_of_sampling_occasions_after_sampling_design", 
        "reason_actual_differs_from_requested")) 
        return("Derived values")
    if (parameter %in% c("seed", "configuration_report_path", 
        "pipeline_version", "reproducibility_command")) 
        return("Reproducibility")
    "Output and export settings"
}
.configuration_value_source <-
function (parameter, config, defaults) 
{
    if (parameter %in% c("possible_number_of_dates", "actual_number_of_sampling_occasions", 
        "actual_number_of_sampling_occasions_after_sampling_design", 
        "reason_actual_differs_from_requested", "selected_sampling_dates")) 
        return("derived")
    if (parameter %in% c("detection_assumption_parameter_count", 
        "detection_assumption_required_covariates", "detection_assumption_backend_requirements", 
        "detection_assumption_diagnostic_status", "detection_assumption_identifiability_warning", 
        "detection_assumption_consequence_summary", "detection_assumption_warnings")) 
        return("derived")
    if (parameter %in% c("transition_matrix") && (config$transition_matrix_source %||% 
        "default") == "default") 
        return("fixed_by_model")
    if (parameter %in% c("transition_matrix") && (config$transition_matrix_source %||% 
        "default") == "custom") 
        return("user_selected")
    if (parameter %in% c("configuration_report_path", "pipeline_version", 
        "reproducibility_command")) 
        return("derived")
    if (!is.null(defaults[[parameter]]) && identical(.resident_value_to_text(config[[parameter]]), 
        .resident_value_to_text(defaults[[parameter]]))) {
        return("default_accepted")
    }
    if (is.null(config[[parameter]]) || identical(config[[parameter]], 
        "")) 
        return("not_used")
    "user_selected"
}
.configured_sampling_dates <-
function (config) 
{
    start <- as.Date(config$initial_sampling_date)
    end <- as.Date(config$final_sampling_date)
    unit <- config$occasion_unit
    by <- switch(unit, day = "day", week = "week", month = "month", 
        stop("occasion_unit must be day, week, or month."))
    all_dates <- seq.Date(start, end, by = by)
    design <- config$sampling_design
    if (design == "daily") 
        return(all_dates)
    occ <- make_occasion_table(dates = all_dates)
    if (design == "random") {
        n <- config$n_random_occasions %||% config$number_of_sampling_occasions
        if (n > length(all_dates)) 
            stop("random n_random_occasions cannot exceed available dates.")
        return(sort(sample(all_dates, n)))
    }
    if (design == "empirical") {
        dates <- as.Date(config$empirical_dates)
        if (!length(dates) || any(is.na(dates))) 
            stop("empirical sampling requires valid empirical_dates.")
        if (any(dates < start | dates > end)) 
            stop("empirical_dates must fall between initial and final sampling dates.")
        return(sort(unique(dates)))
    }
    n <- if (design == "consecutive_month") 
        config$n_consecutive_days
    else NULL
    out <- sampling_schedule(occ, method = design, n = n, seed = config$seed)
    sort(as.Date(out$date))
}
.derived_row <-
function (model_name, derived_parameter, index, estimate, SE = NA_real_, 
    lower_95 = NA_real_, upper_95 = NA_real_, derivation_method = "model output", 
    uncertainty_method = "auto", uncertainty_status = "unavailable", 
    biological_meaning = "Derived parameter.", result_interpretation = "Derived estimate; interpret with assumptions.", 
    warning = "") 
{
    if ((is.na(lower_95) || is.na(upper_95)) && uncertainty_status %in% 
        c("computed", "approximated")) 
        uncertainty_status <- "unavailable"
    if ((is.na(lower_95) || is.na(upper_95)) && !nzchar(warning)) 
        warning <- "Confidence interval unavailable because no stable Hessian, profile likelihood, or bootstrap result was available."
    data.frame(model_name = model_name, derived_parameter = derived_parameter, 
        index = as.character(index), estimate = estimate, SE = SE, 
        lower_95 = lower_95, upper_95 = upper_95, derivation_method = derivation_method, 
        uncertainty_method = uncertainty_method, uncertainty_status = uncertainty_status, 
        biological_meaning = biological_meaning, result_interpretation = result_interpretation, 
        warning = warning, stringsAsFactors = FALSE)
}
.detection_data_diagnostics <-
function (data = NULL, config = NULL) 
{
    h <- .capture_matrix_from_object(data %||% config$observed_data)
    detections <- if (is.null(h)) 
        NA_integer_
    else as.integer(sum(h > 0, na.rm = TRUE))
    row_counts <- if (is.null(h)) 
        numeric()
    else rowSums(h > 0, na.rm = TRUE)
    n_ind <- if (is.null(h)) 
        config$N %||% NA_integer_
    else nrow(h)
    n_occ <- if (is.null(h)) 
        config$actual_number_of_sampling_occasions %||% config$number_of_sampling_occasions %||% 
            NA_integer_
    else ncol(h)
    data.frame(number_of_individuals = as.integer(n_ind), number_of_detections = detections, 
        number_of_singletons = as.integer(sum(row_counts == 1)), 
        number_of_primary_periods = as.integer(config$number_of_primary_periods %||% 
            length(unique(config$primary_id %||% character())) %||% 
            NA_integer_), number_of_secondary_occasions = as.integer(config$fixed_secondary_per_primary %||% 
            NA_integer_), effort_available = "effort" %in% names(config %||% 
            list()) || (!is.null(config$observed_data) && "effort" %in% 
            names(config$observed_data)), missing_effort_values = as.integer(sum(is.na(config$effort %||% 
            numeric()))), effort_scaling = as.character(config$effort_scaling %||% 
            "not_specified"), stringsAsFactors = FALSE)
}
.diag_status <-
function (diag, assumption) 
{
    hit <- diag$status[match(assumption, diag$assumption)]
    ifelse(is.na(hit), "not_applicable", hit)
}
.entry_probabilities_from_mode <-
function (mode, n, b = NULL) 
{
    mode <- tolower(mode)
    if (mode == "default") 
        return(make_entry_probabilities(n))
    if (mode == "uniform") 
        return(rep(1/n, n))
    if (mode == "early_entry") {
        w <- rev(seq_len(n))
        return(w/sum(w))
    }
    if (mode == "late_entry") {
        w <- seq_len(n)
        return(w/sum(w))
    }
    if (mode == "custom") {
        validate_entry_probabilities(b, n)
        if (abs(sum(b) - 1) > 9.9999999999999995e-07) 
            message("Custom b was normalized to sum to 1.")
        return(as.numeric(b)/sum(b))
    }
    stop("entry_probability_mode must be one of: default, uniform, early_entry, late_entry, custom")
}
.exit_like_label_v088 <-
function (x) 
grepl("^(exit|finish|cancel|back|return)$", tolower(trimws(as.character(x))))
.fit_optim <-
function (start, fn, maxit = 1000) 
{
    optim(start, function(z) {
        names(z) <- names(start)
        val <- fn(z)
        if (!is.finite(val)) 
            return(1.0000000000000002e+100)
        -val
    }, method = "BFGS", control = list(maxit = maxit), hessian = TRUE)
}
.fit_selected_abundance_model_v087 <-
function (prep, model, ...) 
{
    if (model %in% c("observed_only", "chao1_chao2")) 
        return(NULL)
    if (!(model %in% implemented_abundance_models())) {
        cat("This model family is not yet fully implemented. Available alternatives are:", 
            paste(implemented_abundance_models(), collapse = ", "), 
            "\n")
        return(NULL)
    }
    if (grepl("^robust_design", model)) {
        fit_robust_design_abundance(prep$history, prep$occasions, 
            model, ...)
    }
    else {
        fit_abundance_model(prep$history, model, ...)
    }
}
