.flatten_parameter_rows <-
function (fit) 
{
    rows <- list()
    add <- function(parameter, index, beta, real, link = "logit", 
        type = "detection", fixed = "estimated", meaning = "Detection probability under the selected abundance model.") {
        rows[[length(rows) + 1L]] <<- data.frame(model_name = fit$model_name, 
            parameter = parameter, parameter_type = type, index = as.character(index), 
            link_function = link, beta_estimate = beta, beta_SE = NA_real_, 
            beta_lower_95 = NA_real_, beta_upper_95 = NA_real_, 
            real_estimate = real, real_SE = NA_real_, real_lower_95 = NA_real_, 
            real_upper_95 = NA_real_, fixed_or_estimated = fixed, 
            boundary_flag = isTRUE(real < 0.02 || real > 0.97999999999999998), 
            identifiable_status = if (identical(fit$Hessian_status, 
                "stable")) 
                "supported"
            else "check diagnostics", biological_meaning = meaning, 
            result_interpretation = "Real-scale values describe detection, recapture, mixture, or abundance quantities used by the model.", 
            stringsAsFactors = FALSE)
    }
    if (inherits(fit, "resident_closed_abundance_fit")) {
        add("f0", "unobserved", fit$par[["log_f0"]], fit$f0_hat, 
            "log", "abundance", meaning = "Estimated number of individuals present but never detected.")
        if (fit$abundance_model %in% c("closed_M0", "closed_Mt")) {
            p <- as.numeric(fit$p_hat)
            beta_names <- grep("^lp", names(fit$par), value = TRUE)
            for (i in seq_along(p)) add("p", i, fit$par[[beta_names[min(i, 
                length(beta_names))]]], p[i])
        }
        else if (fit$abundance_model == "closed_Mb") {
            add("p", "first_capture", fit$par[["lp"]], fit$p_hat[1])
            add("c", "recapture", fit$par[["lc"]], fit$c_hat[1], 
                meaning = "Recapture probability after an individual has already been detected.")
        }
        else if (fit$abundance_model %in% c("closed_Mh_mixture", 
            "closed_Mth_mixture")) {
            for (i in seq_along(fit$mixture_probabilities)) {
                add("pi", names(fit$mixture_probabilities)[i], 
                  NA_real_, fit$mixture_probabilities[i], "multinomial logit", 
                  "mixture probability", meaning = "Probability of membership in a detection mixture class.")
            }
            pmat <- as.matrix(fit$p_hat)
            for (cl in seq_len(nrow(pmat))) for (j in seq_len(ncol(pmat))) {
                add("p", paste0(rownames(pmat)[cl], "_occasion_", 
                  j), NA_real_, pmat[cl, j])
            }
        }
    }
    else if (inherits(fit, "resident_huggins_abundance_fit")) {
        for (i in seq_along(fit$p_hat)) add("p", i, NA_real_, 
            fit$p_hat[i])
        if (is.finite(fit$c_hat[1])) 
            add("c", "recapture", NA_real_, fit$c_hat[1], meaning = "Recapture probability after first detection.")
        if (length(fit$mixture_probabilities) > 1L) {
            for (i in seq_along(fit$mixture_probabilities)) add("pi", 
                names(fit$mixture_probabilities)[i], NA_real_, 
                fit$mixture_probabilities[i], "multinomial logit", 
                "mixture probability")
        }
    }
    do.call(rbind, rows)
}
