.hessian_status <-
function (hessian) 
{
    if (is.null(hessian) || any(!is.finite(hessian))) 
        return("unavailable")
    ev <- tryCatch(eigen(hessian, symmetric = TRUE, only.values = TRUE)$values, 
        error = function(e) NA_real_)
    if (any(is.na(ev))) 
        "unavailable"
    else if (min(ev) <= 9.9999999999999995e-08) 
        "weak or singular"
    else "stable"
}
