.initial_closed_par <-
function (history, abundance_model) 
{
    y <- .observed_history(history)
    K <- ncol(y)
    p0 <- mean(y)
    p0 <- pmin(pmax(p0, 0.050000000000000003), 0.94999999999999996)
    f0_start <- max(1, round(nrow(y) * (1/max(0.050000000000000003, 
        1 - (1 - p0)^K) - 1)))
    if (abundance_model == "closed_M0") {
        c(log_f0 = log(f0_start), lp = .logit(p0))
    }
    else if (abundance_model == "closed_Mt") {
        pt <- pmin(pmax(colMeans(y), 0.029999999999999999), 0.96999999999999997)
        c(log_f0 = log(f0_start), setNames(.logit(pt), paste0("lp", 
            seq_len(K))))
    }
    else if (abundance_model == "closed_Mb") {
        c(log_f0 = log(f0_start), lp = .logit(p0), lc = .logit(pmin(0.94999999999999996, 
            pmax(0.029999999999999999, p0 * 1.1000000000000001))))
    }
    else if (abundance_model == "closed_Mh_mixture") {
        c(log_f0 = log(f0_start), lpi1 = .logit(0.59999999999999998), 
            lp1 = .logit(pmin(0.94999999999999996, p0 * 1.5)), 
            lp2 = .logit(pmax(0.02, p0 * 0.40000000000000002)))
    }
    else if (abundance_model == "closed_Mth_mixture") {
        pt <- pmin(pmax(colMeans(y), 0.040000000000000001), 0.95999999999999996)
        c(log_f0 = log(f0_start), lpi1 = .logit(0.59999999999999998), 
            setNames(.logit(pmin(0.96999999999999997, pt * 1.3999999999999999)), 
                paste0("lp1_", seq_len(K))), setNames(.logit(pmax(0.02, 
                pt * 0.5)), paste0("lp2_", seq_len(K))))
    }
    else {
        stop("Unsupported closed abundance model.", call. = FALSE)
    }
}
.initial_huggins_par <-
function (history, abundance_model) 
{
    y <- .observed_history(history)
    K <- ncol(y)
    p0 <- pmin(pmax(mean(y), 0.050000000000000003), 0.94999999999999996)
    if (abundance_model == "huggins_M0") 
        c(lp = .logit(p0))
    else if (abundance_model == "huggins_Mt") 
        setNames(.logit(pmin(pmax(colMeans(y), 0.029999999999999999), 
            0.96999999999999997)), paste0("lp", seq_len(K)))
    else if (abundance_model == "huggins_Mb") 
        c(lp = .logit(p0), lc = .logit(pmin(0.94999999999999996, 
            pmax(0.029999999999999999, p0 * 1.1000000000000001))))
    else if (abundance_model == "huggins_Mh") 
        c(lpi1 = .logit(0.59999999999999998), lp1 = .logit(pmin(0.94999999999999996, 
            p0 * 1.5)), lp2 = .logit(pmax(0.02, p0 * 0.40000000000000002)))
    else stop("Unsupported Huggins model.", call. = FALSE)
}
