.metadata_default_value <-
function (parameter, fallback = "varies by workflow") 
{
    d <- .metadata_defaults()
    if (!is.null(d[[parameter]])) {
        v <- d[[parameter]]
        if (inherits(v, "formula")) 
            return(deparse(v))
        if (is.matrix(v)) 
            return("matrix; see transition_matrix")
        return(paste(v, collapse = ", "))
    }
    fallback
}
