.old_abundance_model_recommendation_table_v089 <-
function (data, occasions = NULL) 
{
    diag <- abundance_assumption_diagnostics(data, occasions)
    ranked <- rank_abundance_model_suitability(data, occasions)
    suff <- .diag_status(diag, "data_sufficiency")
    robust <- .diag_status(diag, "robust_design_structure")
    closed <- .diag_status(diag, "closed_capture_closure")
    open <- .diag_status(diag, "open_population_signal")
    ranked$suitability <- ifelse(!ranked$implemented, "not_implemented", 
        ifelse(ranked$score >= 80, "recommended", ifelse(ranked$score >= 
            50, "acceptable_with_caution", ifelse(ranked$score > 
            0, "not_recommended", "not_applicable"))))
    ranked$reason <- ifelse(ranked$model_family == "robust_design", 
        paste("robust-design structure:", robust), ifelse(ranked$model_family %in% 
            c("closed_capture", "huggins_closed_capture"), paste("closure diagnostic:", 
            closed), ifelse(ranked$model_family == "open_population", 
            paste("open-population signal:", open), paste("data sufficiency:", 
                suff))))
    ranked$assumptions_status <- paste("closure", closed, "| robust", 
        robust, "| open", open, "| sufficiency", suff)
    ranked$data_support <- ifelse(suff == "pass", "adequate", 
        ifelse(suff == "review", "limited", "sparse"))
    ranked$expected_risk <- ifelse(ranked$suitability == "recommended", 
        "moderate", ifelse(ranked$suitability == "acceptable_with_caution", 
            "elevated", ifelse(ranked$suitability == "not_implemented", 
                "not available", "high")))
    ranked$recommendation <- ifelse(ranked$suitability == "not_implemented", 
        "This model family is not yet fully implemented. Available alternatives are observed_only, chao1_chao2, closed_M0, closed_Mt, closed_Mb, closed_Mh_mixture, huggins_M0, huggins_Mt, huggins_Mb, robust-design primary models, and state-space residency models.", 
        ifelse(ranked$suitability == "recommended", "Most suitable under current diagnostics.", 
            ifelse(ranked$suitability == "acceptable_with_caution", 
                "Use only with explicit diagnostic warnings.", 
                "Do not prioritize under current diagnostics.")))
    ranked[, c("model_family", "candidate_model", "suitability", 
        "reason", "assumptions_status", "data_support", "expected_risk", 
        "recommendation")]
}
.old_abundance_ready_check_v086 <-
function (data, abundance_model = "closed_M0") 
{
    prep <- if (is.list(data) && !is.null(data$history)) 
        data
    else prepare_abundance_data(data)
    y <- .as_history_matrix(prep$history)
    detected <- rowSums(y)
    warnings <- character()
    if (sum(y) < 10) 
        warnings <- c(warnings, "Few detections; prefer observed/Chao summaries or simpler models.")
    if (sum(detected == 1) > max(3, 0.5 * sum(detected > 0))) 
        warnings <- c(warnings, "Many singletons; abundance may depend strongly on model assumptions.")
    if (ncol(y) < 2) 
        warnings <- c(warnings, "At least two occasions are recommended for closed-capture abundance.")
    data.frame(number_of_individuals = nrow(y), number_of_occasions = ncol(y), 
        number_of_detections = sum(y), number_of_singletons = sum(detected == 
            1), all_zero_histories = sum(detected == 0), duplicate_ids_or_dates = FALSE, 
        closure_assumption_note = if (grepl("^closed|^huggins", 
            abundance_model)) 
            "Check closure for the modeled session."
        else "Check within-primary closure.", warning = paste(warnings, 
            collapse = " "), ready = !length(warnings), stringsAsFactors = FALSE)
}
.old_as_history_matrix_v086 <-
function (history) 
{
    if (is.null(history)) 
        stop("history is required.", call. = FALSE)
    if (is.data.frame(history)) {
        id_col <- intersect(c("id", "ID", "individual", "individual_id"), 
            names(history))
        if (length(id_col)) 
            rownames(history) <- as.character(history[[id_col[1]]])
        history <- history[, vapply(history, function(z) all(z %in% 
            c(0, 1, TRUE, FALSE, NA)), logical(1)), drop = FALSE]
    }
    mat <- as.matrix(history)
    storage.mode(mat) <- "numeric"
    mat[is.na(mat)] <- 0
    mat <- (mat > 0) * 1
    if (!nrow(mat) || !ncol(mat)) 
        stop("history must contain at least one individual and one occasion.", 
            call. = FALSE)
    mat
}
