.old_ballance_metrics_v086 <-
function (history, occasion_table) 
{
    history <- as_binary_matrix(history)
    dates <- as.Date(occasion_table$date)
    if (ncol(history) != length(dates)) {
        stop("history columns must match occasion_table rows.")
    }
    rows <- lapply(safe_seq_rows(history, context = "validated history row loop"), 
        function(i) {
            sight_idx <- which(history[i, ] > 0)
            occurrence <- length(sight_idx)
            permanence <- if (occurrence > 1) {
                as.numeric(max(dates[sight_idx]) - min(dates[sight_idx]))
            }
            else 0
            mean_interval <- if (occurrence > 1) {
                mean(as.numeric(diff(dates[sight_idx])))
            }
            else NA_real_
            periodicity <- if (occurrence > 1 && mean_interval > 
                0) 
                1/mean_interval
            else 0
            data.frame(id = rownames(history)[i] %||% as.character(i), 
                occurrence = occurrence, permanence_days = permanence, 
                mean_interval_days = mean_interval, periodicity_per_day = periodicity, 
                stringsAsFactors = FALSE)
        })
    do.call(rbind, rows)
}
.old_chao_discovery_curve_table_v086 <-
function (x, occasion_table = NULL) 
{
    history <- chao_history_matrix(x)
    occasion_table <- occasion_table %||% chao_occasion_table(x, 
        history)
    dates <- as.Date(occasion_table$date)
    if (length(dates) != ncol(history)) 
        dates <- seq_len(ncol(history))
    seen_before <- rep(FALSE, nrow(history))
    rows <- vector("list", ncol(history))
    for (k in seq_len(ncol(history))) {
        sub <- history[, seq_len(k), drop = FALSE]
        seen_now <- sub[, k] > 0
        c1 <- chao1_estimate(sub)
        c2 <- chao2_estimate(sub)
        warning <- paste(unique(c(c1$uncertainty_warning, c2$uncertainty_warning)), 
            collapse = "; ")
        rows[[k]] <- data.frame(occasion = k, date = dates[k], 
            cumulative_identifications = sum(sub, na.rm = TRUE), 
            cumulative_new_individuals = sum(seen_now & !seen_before), 
            S_obs = c1$S_obs, Chao1 = c1$estimate, Chao2 = c2$estimate, 
            Chao1_unseen = c1$unseen_estimate, Chao2_unseen = c2$unseen_estimate, 
            Chao1_completeness = c1$completeness, Chao2_completeness = c2$completeness, 
            f1 = c1$f1, f2 = c1$f2, Q1 = c2$Q1, Q2 = c2$Q2, T = k, 
            warning = warning, stringsAsFactors = FALSE)
        seen_before <- seen_before | seen_now
    }
    do.call(rbind, rows)
}
.old_chao1_estimate_v086 <-
function (history, detection_heterogeneity_high = FALSE) 
{
    history <- chao_history_matrix(history)
    if (!length(history) || nrow(history) == 0 || ncol(history) == 
        0) {
        return(data.frame(estimator = "Chao1", S_obs = 0L, f1 = NA_integer_, 
            f2 = NA_integer_, Q1 = NA_integer_, Q2 = NA_integer_, 
            T = NA_integer_, estimate = NA_real_, unseen_estimate = NA_real_, 
            completeness = NA_real_, singleton_fraction = NA_real_, 
            doubleton_fraction = NA_real_, uncertainty_warning = "No sampling data available.", 
            interpretation = chao_interpretation("Chao1"), stringsAsFactors = FALSE))
    }
    counts <- rowSums(history, na.rm = TRUE)
    observed_counts <- counts[counts > 0]
    S_obs <- length(observed_counts)
    f1 <- sum(observed_counts == 1)
    f2 <- sum(observed_counts == 2)
    estimate <- if (S_obs == 0) 
        NA_real_
    else if (f2 > 0) 
        S_obs + f1^2/(2 * f2)
    else S_obs + f1 * (f1 - 1)/2
    unseen <- if (is.finite(estimate)) 
        max(0, estimate - S_obs)
    else NA_real_
    completeness <- if (is.finite(estimate) && estimate > 0) 
        S_obs/estimate
    else NA_real_
    warning <- chao_warning_rules("Chao1", S_obs = S_obs, f1 = f1, 
        f2 = f2, detections = sum(history), detection_heterogeneity_high = detection_heterogeneity_high)
    data.frame(estimator = "Chao1", S_obs = S_obs, f1 = f1, f2 = f2, 
        Q1 = NA_integer_, Q2 = NA_integer_, T = NA_integer_, 
        estimate = estimate, unseen_estimate = unseen, completeness = completeness, 
        singleton_fraction = if (S_obs > 0) 
            f1/S_obs
        else NA_real_, doubleton_fraction = if (S_obs > 0) 
            f2/S_obs
        else NA_real_, uncertainty_warning = warning, interpretation = chao_interpretation("Chao1"), 
        stringsAsFactors = FALSE)
}
.old_chao2_estimate_v086 <-
function (history, detection_heterogeneity_high = FALSE) 
{
    history <- chao_history_matrix(history)
    if (!length(history) || nrow(history) == 0 || ncol(history) == 
        0) {
        return(data.frame(estimator = "Chao2", S_obs = 0L, f1 = NA_integer_, 
            f2 = NA_integer_, Q1 = NA_integer_, Q2 = NA_integer_, 
            T = 0L, estimate = NA_real_, unseen_estimate = NA_real_, 
            completeness = NA_real_, singleton_fraction = NA_real_, 
            doubleton_fraction = NA_real_, uncertainty_warning = "No sampling data available.", 
            interpretation = chao_interpretation("Chao2"), stringsAsFactors = FALSE))
    }
    incidence <- rowSums(history > 0, na.rm = TRUE)
    observed_incidence <- incidence[incidence > 0]
    S_obs <- length(observed_incidence)
    Q1 <- sum(observed_incidence == 1)
    Q2 <- sum(observed_incidence == 2)
    T <- ncol(history)
    estimate <- if (S_obs == 0 || T < 1) 
        NA_real_
    else if (Q2 > 0) {
        S_obs + ((T - 1)/T) * Q1^2/(2 * Q2)
    }
    else {
        S_obs + ((T - 1)/T) * Q1 * (Q1 - 1)/2
    }
    if (T < 2) 
        estimate <- NA_real_
    unseen <- if (is.finite(estimate)) 
        max(0, estimate - S_obs)
    else NA_real_
    completeness <- if (is.finite(estimate) && estimate > 0) 
        S_obs/estimate
    else NA_real_
    warning <- chao_warning_rules("Chao2", S_obs = S_obs, Q1 = Q1, 
        Q2 = Q2, T = T, detections = sum(history), detection_heterogeneity_high = detection_heterogeneity_high)
    data.frame(estimator = "Chao2", S_obs = S_obs, f1 = NA_integer_, 
        f2 = NA_integer_, Q1 = Q1, Q2 = Q2, T = T, estimate = estimate, 
        unseen_estimate = unseen, completeness = completeness, 
        singleton_fraction = if (S_obs > 0) 
            Q1/S_obs
        else NA_real_, doubleton_fraction = if (S_obs > 0) 
            Q2/S_obs
        else NA_real_, uncertainty_warning = warning, interpretation = chao_interpretation("Chao2"), 
        stringsAsFactors = FALSE)
}
.old_classify_rsf_indices_v086 <-
function (history, occasion_table) 
{
    history <- as_binary_matrix(history)
    metrics <- ballance_metrics(history, occasion_table)
    n_occ <- ncol(history)
    periods <- period_structure(occasion_table)
    year_g <- periods$year_g
    season_g <- periods$season_g
    n_years <- length(periods$year_levels)
    out <- metrics
    out$parra_msr <- metrics$occurrence/n_occ
    out$parra_ysr <- apply(history, 1, function(x) mean(presence_by_group(x, 
        year_g)))
    out$diaz_ssr <- apply(history, 1, function(x) mean(presence_by_group(x, 
        season_g)))
    out$diaz_ysr <- out$parra_ysr
    out$diaz_category <- with(out, ifelse(diaz_ssr >= 0.5 & diaz_ysr >= 
        0.5, "FRS", ifelse(diaz_ssr >= 0.25 & diaz_ysr >= 0.25, 
        "FRV", ifelse(diaz_ssr < 0.25 & diaz_ysr > 0.25, "OCV", 
            "SPV"))))
    out$quintana_general <- apply(history, 1, function(x) {
        cats <- ifelse(counts_by_group(x, year_g) >= 8, "Common", 
            ifelse(counts_by_group(x, year_g) > 5, "Frequent", 
                ifelse(counts_by_group(x, year_g) > 2, "Occasional", 
                  "Rare")))
        mode_ordered(cats, c("Rare", "Occasional", "Frequent", 
            "Common"))
    })
    sightings <- metrics$occurrence
    binsize <- (2 * IQR(sightings))/(length(sightings)^(1/3))
    out$balmer_sightings <- sightings
    out$balmer_category <- if (is.finite(binsize) && binsize > 
        0) {
        cut(sightings, breaks = seq(min(sightings), max(sightings) + 
            binsize, by = binsize), include.lowest = TRUE, labels = FALSE)
    }
    else 1L
    io <- ifelse(n_occ > 1, (metrics$occurrence - 1)/(n_occ - 
        1), 0)
    it <- ifelse(max(metrics$permanence_days, na.rm = TRUE) > 
        0, metrics$permanence_days/max(metrics$permanence_days, 
        na.rm = TRUE), 0)
    ip <- metrics$periodicity_per_day
    ip <- ifelse(max(ip, na.rm = TRUE) > 0, ip/max(ip, na.rm = TRUE), 
        0)
    safe_hmean <- function(...) {
        vals <- cbind(...)
        apply(vals, 1, function(z) if (any(z <= 0 | !is.finite(z))) 
            0
        else length(z)/sum(1/z))
    }
    out$tschopp_ia1 <- (io + it + ip)/3
    out$tschopp_ia2 <- (io + it)/2
    out$tschopp_ia3 <- (io + ip)/2
    out$tschopp_ia4 <- (it + ip)/2
    out$tschopp_ih1 <- safe_hmean(io, it, ip)
    out$tschopp_ih2 <- safe_hmean(io, it)
    out$tschopp_ih3 <- safe_hmean(io, ip)
    out$tschopp_ih4 <- safe_hmean(it, ip)
    out$ananias_general <- apply(history, 1, function(x) {
        cats <- ifelse(counts_by_group(x, year_g) > 5, "Year-round resident", 
            ifelse(counts_by_group(x, year_g) >= 3, "Seasonal resident", 
                "Transient"))
        mode_ordered(cats, c("Transient", "Seasonal resident", 
            "Year-round resident"))
    })
    out$chabanne_msr <- metrics$occurrence/n_occ
    out$chabanne_ssr <- apply(history, 1, function(x) mean(presence_by_group(x, 
        season_g)))
    out$chabanne_category <- with(out, ifelse(chabanne_msr >= 
        0.10000000000000001 & chabanne_ssr >= 0.75, "Resident", 
        ifelse(chabanne_ssr >= 0.125, "OCV", "TRS")))
    out$conway_general <- apply(history, 1, function(x) {
        y_count <- counts_by_group(x, year_g)
        y_n <- as.integer(table(year_g))
        y_prop <- y_count/y_n
        s_present <- presence_by_group(x, season_g)
        s_year <- tapply(s_present, periods$season_lookup$year, 
            sum)
        s_year_n <- table(periods$season_lookup$year)
        cats <- rep("Non resident", n_years)
        names(cats) <- periods$year_levels
        if (length(y_prop)) 
            cats[y_prop >= 0.5] <- "Resident"
        if (length(s_year)) 
            cats[names(s_year)[(s_year/s_year_n[names(s_year)]) > 
                0.5]] <- "Resident"
        mode_ordered(cats, c("Non resident", "Resident"))
    })
    out$dinis_category <- apply(history, 1, function(x) {
        s_by_year <- tapply(presence_by_group(x, season_g), periods$season_lookup$year, 
            sum)
        if (length(s_by_year) < 3) 
            return("Non resident")
        resident <- any(stats::filter(as.numeric(s_by_year > 
            2), rep(1, 3), sides = 1) == 3, na.rm = TRUE)
        if (resident) 
            "Resident"
        else "Non resident"
    })
    out$martin_category <- apply(history, 1, function(x) {
        y <- counts_by_group(x, year_g)
        if (all(y >= 7)) 
            "Permanent resident"
        else if (any(y >= 7)) 
            "Partial resident"
        else "Non resident"
    })
    out$moller_sighting_rate <- ifelse(metrics$occurrence/n_occ < 
        0.10000000000000001, "LSR", ifelse(metrics$occurrence/n_occ <= 
        0.29999999999999999, "MSR", "HSR"))
    out$moller_category <- apply(cbind(out$moller_sighting_rate, 
        history), 1, function(z) {
        rate <- z[1]
        x <- as.integer(z[-1])
        seasons_seen <- sum(presence_by_group(x, season_g) > 
            0)
        if (rate %in% c("HSR", "MSR") && seasons_seen > 1) 
            "Resident"
        else if (seasons_seen == 1) 
            "TRS"
        else if (rate == "LSR" && seasons_seen > 1) 
            "OCV"
        else "TRS"
    })
    out$rosel_general <- apply(history, 1, function(x) {
        y_count <- counts_by_group(x, year_g)
        y_n <- as.integer(table(year_g))
        cats <- ifelse(y_count/y_n > 0.5, "Resident", "Non resident")
        mode_ordered(cats, c("Non resident", "Resident"))
    })
    out$zolman_category <- apply(history, 1, function(x) {
        s_present <- presence_by_group(x, season_g)
        s_year <- periods$season_lookup$year
        by_year <- tapply(s_present, s_year, function(z) all(z > 
            0))
        if (any(by_year)) 
            return("Resident")
        by_season <- tapply(s_present, periods$season_lookup$season, 
            function(z) all(z > 0))
        if (any(by_season)) 
            "Seasonal resident"
        else "Transient"
    })
    out
}
.old_compact_table_view_v087 <-
function (x, key_columns = NULL, max_rows = 20L, max_col_width = 24L, 
    digits = 3L) 
{
    if (!is.data.frame(x)) 
        x <- as.data.frame(x)
    if (!is.null(key_columns)) {
        keep <- intersect(key_columns, names(x))
        if (length(keep)) 
            x <- x[, keep, drop = FALSE]
    }
    out <- head(x, max_rows)
    truncate_table_columns(out, max_col_width = max_col_width, 
        digits = digits)
}
