        data.frame(model_name = fit$model_name %||% fit$abundance_model, 
            abundance_model = fit$abundance_model, estimator_section = if (is.na(fit$logLik)) 
                "descriptive estimator"
            else "likelihood model", logLik = fit$logLik, n_parameters = fit$n_parameters, 
            AIC = fit$AIC, AICc = fit$AICc, BIC = fit$BIC, N_hat = fit$N_hat, 
            N_SE = fit$N_SE, convergence = fit$convergence, Hessian_status = fit$Hessian_status, 
            boundary_warnings = fit$boundary_warnings, identifiability_warnings = fit$identifiability_warnings, 
            recommendation = "", stringsAsFactors = FALSE)
    })
    tab <- do.call(rbind, rows)
    like <- which(tab$estimator_section == "likelihood model" & 
        is.finite(tab$AICc))
    if (length(like)) 
        tab$recommendation[like[which.min(tab$AICc[like])]] <- "Lowest AICc among fitted likelihood models; still check assumptions."
    tab
}
