.old_fit_closed_capture_abundance_v086 <-
function (history, abundance_model = "closed_M0", maxit = 1000) 
{
    validate_abundance_model(abundance_model)
    if (!abundance_model %in% c("closed_M0", "closed_Mt", "closed_Mb", 
        "closed_Mh_mixture", "closed_Mth_mixture")) {
        stop("fit_closed_capture_abundance requires a closed_* abundance model.", 
            call. = FALSE)
    }
    y <- .observed_history(history)
    start <- .initial_closed_par(y, abundance_model)
    opt <- .fit_optim(start, function(z) closed_capture_loglik(z, 
        y, abundance_model), maxit = maxit)
    par <- opt$par
    names(par) <- names(start)
    pieces <- .closed_prob_matrix(y, abundance_model, par)
    f0 <- exp(par[["log_f0"]])
    N <- nrow(y) + f0
    K <- ncol(y)
    np <- length(par)
    logLik <- -opt$value
    hstat <- .hessian_status(opt$hessian)
    vc <- tryCatch(solve(opt$hessian), error = function(e) NULL)
    se_log_f0 <- if (!is.null(vc) && "log_f0" %in% rownames(vc)) 
        sqrt(abs(vc["log_f0", "log_f0"]))
    else NA_real_
    N_se <- if (is.finite(se_log_f0)) 
        f0 * se_log_f0
    else NA_real_
    lower <- if (is.finite(N_se)) 
        max(nrow(y), N - 1.96 * N_se)
    else NA_real_
    upper <- if (is.finite(N_se)) 
        N + 1.96 * N_se
    else NA_real_
    boundary <- any(c(as.vector(pieces$p), pieces$c, pieces$pi) < 
        0.02 | c(as.vector(pieces$p), pieces$c, pieces$pi) > 
        0.97999999999999998, na.rm = TRUE)
    out <- list(model_name = abundance_model, abundance_model = abundance_model, 
        history = y, par = par, optim = opt, logLik = logLik, 
        n_parameters = np, AIC = -2 * logLik + 2 * np, AICc = -2 * 
            logLik + 2 * np + (2 * np * (np + 1))/max(1, nrow(y) - 
            np - 1), BIC = -2 * logLik + log(max(1, nrow(y))) * 
            np, N_hat = as.numeric(N), N_SE = as.numeric(N_se), 
        lower_95 = as.numeric(lower), upper_95 = as.numeric(upper), 
        n_observed = nrow(y), f0_hat = as.numeric(f0), p_hat = pieces$p, 
        c_hat = pieces$c, mixture_probabilities = pieces$pi, 
        convergence = opt$convergence, Hessian_status = hstat, 
        boundary_warnings = if (boundary) "One or more probabilities are near 0 or 1." else "", 
        identifiability_warnings = if (hstat == "stable") "" else "Curvature is weak; use profile or bootstrap uncertainty.", 
        warning = "Closed-capture model-based abundance requires closure during the modeled session.")
    class(out) <- c("resident_closed_abundance_fit", "resident_abundance_fit")
    out
}
.old_fit_huggins_abundance_v086 <-
function (history, abundance_model = "huggins_M0", maxit = 1000) 
{
    validate_abundance_model(abundance_model)
    if (!abundance_model %in% c("huggins_M0", "huggins_Mt", "huggins_Mb", 
        "huggins_Mh")) {
        stop("fit_huggins_abundance requires a huggins_* abundance model.", 
            call. = FALSE)
    }
    y <- .observed_history(history)
    start <- .initial_huggins_par(y, abundance_model)
    opt <- .fit_optim(start, function(z) huggins_loglik(z, y, 
        abundance_model), maxit = maxit)
    par <- opt$par
    names(par) <- names(start)
    cp <- huggins_capture_probability(y, abundance_model, par)
    N <- nrow(y)/cp$pstar
    np <- length(par)
    logLik <- -opt$value
    hstat <- .hessian_status(opt$hessian)
    out <- list(model_name = abundance_model, abundance_model = abundance_model, 
        history = y, par = par, optim = opt, logLik = logLik, 
        n_parameters = np, AIC = -2 * logLik + 2 * np, AICc = -2 * 
            logLik + 2 * np + (2 * np * (np + 1))/max(1, nrow(y) - 
            np - 1), BIC = -2 * logLik + log(max(1, nrow(y))) * 
            np, N_hat = as.numeric(N), N_SE = NA_real_, lower_95 = NA_real_, 
        upper_95 = NA_real_, n_observed = nrow(y), f0_hat = as.numeric(N - 
            nrow(y)), p_hat = cp$p, c_hat = cp$c, mixture_probabilities = cp$pi, 
        pstar = cp$pstar, convergence = opt$convergence, Hessian_status = hstat, 
        boundary_warnings = if (cp$pstar < 0.050000000000000003 || 
            cp$pstar > 0.98999999999999999) "Capture-at-least-once probability is near a boundary." else "", 
        identifiability_warnings = if (hstat == "stable") "" else "Curvature is weak; use bootstrap uncertainty.", 
        warning = "Huggins-style abundance is derived from capture probability; N is not directly estimated.")
    class(out) <- c("resident_huggins_abundance_fit", "resident_abundance_fit")
    out
}
.old_format_console_table_v087 <-
function (x, key_columns = NULL, max_rows = 20L, max_col_width = 24L, 
    digits = 3L) 
{
    tab <- compact_table_view(x, key_columns, max_rows, max_col_width, 
        digits = digits)
    if (!nrow(tab)) 
        return("(no rows)")
    widths <- vapply(names(tab), function(nm) {
        header_lines <- wrap_table_header(nm, max_col_width)
        max(nchar(c(header_lines, as.character(tab[[nm]]))), 
            na.rm = TRUE)
    }, integer(1))
    widths <- pmin(widths, max_col_width)
    fmt_row <- function(vals) {
        paste(mapply(function(v, w) {
            v <- as.character(v)
            if (is.na(v)) 
                v <- "NA"
            if (nchar(v) > w) 
                v <- paste0(substr(v, 1L, max(1L, w - 3L)), .ascii_ellipsis())
            sprintf(paste0("%-", w, "s"), v)
        }, vals, widths, SIMPLIFY = TRUE), collapse = " | ")
    }
    header_parts <- mapply(wrap_table_header, names(tab), widths, 
        SIMPLIFY = FALSE)
    header_height <- max(lengths(header_parts))
    header_rows <- vapply(seq_len(header_height), function(i) {
        vals <- mapply(function(parts, w) {
            if (i <= length(parts)) 
                parts[[i]]
            else ""
        }, header_parts, widths, SIMPLIFY = TRUE)
        fmt_row(vals)
    }, character(1))
    lines <- c(header_rows, paste(vapply(widths, function(w) paste(rep("-", 
        w), collapse = ""), character(1)), collapse = "-+-"))
    rows <- vapply(seq_len(nrow(tab)), function(i) fmt_row(tab[i, 
        , drop = FALSE][1, ]), character(1))
    paste(c(lines, rows), collapse = "\n")
}
.old_handle_post_simulation_menu_choice_v085 <-
function (ans, analysis, input_provider = NULL) 
{
    key <- tolower(trimws(ans))
    old_only <- c("old-20", "old 20")
    if (key %in% old_only) {
        cat("The menu was renumbered in v0.8.9. Please choose from the displayed options.\n")
        return(list(analysis = analysis, finished = FALSE))
    }
    if (key %in% c("1", "table", "show capture-recapture table", 
        "capture-recapture table")) {
        print_console_table(capture_recapture_table_from_analysis(analysis), 
            title = "Capture-recapture table", max_rows = 20, 
            export_prefix = "capture_recapture_table")
    }
    else if (key %in% c("2", "summary", "capture data summary", 
        "show capture data summary")) {
        cat("\nCapture data summary. This describes dates, individuals, occasions, and capture-record counts before model fitting.\n")
        print_capture_data_summary(analysis_capture_data_summary(analysis))
    }
    else if (key %in% c("3", "discovery", "discovery summary", 
        "show discovery-curve summary")) {
        cat("\nDiscovery-curve summary. This shows how quickly newly identified individuals accumulate through time.\n")
        print_discovery_curve_summary(analysis_discovery_curve_table(analysis))
    }
    else if (key %in% c("4", "model residency", "show model-based residency-state results")) {
        print_model_based_residency_results(analysis)
    }
    else if (key %in% c("5", "individual residency", "show individual residency classification")) {
        print_individual_residency_classification(analysis)
    }
    else if (key %in% c("6", "residency summary", "show residency-class summary")) {
        print_residency_class_summary(analysis)
    }
    else if (key %in% c("7", "literature comparison", "compare model-based residency with literature metrics")) {
        printed <- print_model_vs_literature_comparison(analysis)
        analysis <- printed$analysis
        analysis$model_literature_comparison <- printed$comparison
        analysis$model_literature_agreement_summary <- printed$agreement_summary
        assign("analysis", analysis, envir = .GlobalEnv)
    }
    else if (key %in% c("8", "category proportions", "show residency-category proportions")) {
        print_residency_category_proportion_table(analysis)
    }
    else if (key %in% c("9", "review", "detection review", "show detection-assumption review")) {
        print_detection_assumption_review(analysis$config %||% 
            simulation_parameter_defaults(), capture_recapture_table_from_analysis(analysis))
    }
    else if (key %in% c("10", "configuration report", "show full configuration report path")) {
        cat("Full configuration report path:\n", analysis$configuration_report_path %||% 
            analysis$config$configuration_report_path %||% "No configuration report path is stored.", 
            "\n", sep = "")
    }
    else if (key %in% c("11", "plot", "plot discovery curves")) {
        plot_discovery_curves(analysis_discovery_curve_table(analysis))
        cat("Discovery curves were sent to the active R graphics device.\n")
    }
    else if (key %in% c("12", "plot category proportions", "plot residency-category proportions")) {
        plot_residency_category_proportions(analysis)
        cat("Residency-category proportion plot was sent to the active R graphics device.\n")
    }
    else if (key %in% c("13", "plot chao discovery", "plot chao discovery curves")) {
        analysis <- update_analysis_with_chao_outputs(analysis)
        plot_chao_discovery_curves(analysis$chao_discovery_curve_table)
        cat("Chao discovery curves were sent to the active R graphics device.\n")
    }
    else if (key %in% c("14", "plot chao completeness", "plot chao sampling-completeness curves")) {
        analysis <- update_analysis_with_chao_outputs(analysis)
        plot_chao_completeness_curve(analysis$chao_discovery_curve_table)
        cat("Chao sampling-completeness curves were sent to the active R graphics device.\n")
    }
    else if (key %in% c("15", "export table", "export capture-recapture table")) {
        path <- .resident_prompt("Enter CSV path, or press Enter for capture_recapture_table.csv: ", 
            input_provider)
        if (!nzchar(trimws(path))) 
            path <- "capture_recapture_table.csv"
        cat("Saved:", export_capture_recapture_table(analysis, 
            path), "\n")
    }
    else if (key %in% c("16", "export summary", "export capture data summary")) {
        path <- .resident_prompt("Enter CSV path, or press Enter for capture_data_summary.csv: ", 
            input_provider)
        if (!nzchar(trimws(path))) 
            path <- "capture_data_summary.csv"
        cat("Saved:", export_capture_data_summary(analysis, path), 
            "\n")
    }
    else if (key %in% c("17", "export discovery", "export discovery curves as jpg")) {
        paths <- export_discovery_curves_jpg(analysis_discovery_curve_table(analysis), 
            output_dir = "outputs")
        cat("Saved:", paste(paths, collapse = ", "), "\n")
    }
    else if (key %in% c("18", "export residency", "export residency results")) {
        cat("Saved:", export_residency_results_csv(analysis), 
            "\n")
    }
    else if (key %in% c("19", "export literature", "export literature-comparison table")) {
        cat("Saved:", export_model_literature_comparison_csv(analysis), 
            "\n")
    }
    else if (key %in% c("20", "export chao", "export chao plots and tables")) {
        analysis <- update_analysis_with_chao_outputs(analysis)
        paths <- export_chao_outputs(analysis)
        cat("Saved Chao outputs:\n")
        print(paths)
    }
    else if (key %in% c("21", "finish", "exit", "done", "quit")) {
        cat("Workflow finished. The current analysis object is also available as analysis in the global R environment when created by this workflow.\n")
        return(list(analysis = analysis, finished = TRUE))
    }
    else if (grepl("^[0-9]+$", key)) {
        cat("The menu was renumbered in v0.8.9. Please choose from the displayed options.\n")
    }
    else {
        cat("Please choose an option from 1 to 21.\n")
    }
    list(analysis = analysis, finished = FALSE)
}
