.old_model_based_residency_results_v086 <-
function (analysis) 
{
    if (!is.null(analysis$residency_results)) 
        return(analysis$residency_results)
    fit <- analysis$fit
    sim <- analysis$sim
    if (!is.null(fit) && !is.null(fit$posterior)) {
        rows <- lapply(names(fit$posterior), function(id) {
            gamma <- fit$posterior[[id]]$gamma
            state_names <- rownames(gamma) %||% fit$states %||% 
                paste0("state_", seq_len(nrow(gamma)))
            probs <- rowMeans(gamma, na.rm = TRUE)
            names(probs) <- state_names
            best <- names(probs)[which.max(probs)]
            resident_prob <- sum(probs[grepl("resident|core|seasonal", 
                names(probs), ignore.case = TRUE)], na.rm = TRUE)
            visitor_prob <- sum(probs[grepl("outside|peripheral|visitor|transient", 
                names(probs), ignore.case = TRUE)], na.rm = TRUE)
            data.frame(id = id, most_likely_state = best, state_probability = max(probs, 
                na.rm = TRUE), availability_probability = sum(probs[!(names(probs) %in% 
                (fit$spec$unavailable_states %||% "outside"))], 
                na.rm = TRUE), resident_probability = resident_prob, 
                transient_or_visitor_probability = visitor_prob, 
                seasonal_resident_probability = probs["seasonal_resident"] %||% 
                  0, core_resident_probability = probs["core_resident"] %||% 
                  0, classification_confidence = max(probs, na.rm = TRUE), 
                classification_warning = if (max(probs, na.rm = TRUE) < 
                  0.59999999999999998) 
                  "low model-state confidence"
                else "", result_interpretation = "Model-based result from fitted posterior state probabilities; detection assumptions influence these probabilities.", 
                stringsAsFactors = FALSE)
        })
        out <- do.call(rbind, rows)
    }
    else if (!is.null(fit) && !is.null(fit$decoded_states)) {
        dec <- fit$decoded_states
        rows <- lapply(split(dec, dec$id), function(d) {
            state_tab <- sort(table(d$state), decreasing = TRUE)
            best <- names(state_tab)[1]
            data.frame(id = d$id[1], most_likely_state = best, 
                state_probability = mean(d$state_probability, 
                  na.rm = TRUE), availability_probability = mean(d$availability_probability, 
                  na.rm = TRUE), resident_probability = mean(.resident_label_from_state(d$state), 
                  na.rm = TRUE), transient_or_visitor_probability = mean(!.resident_label_from_state(d$state), 
                  na.rm = TRUE), seasonal_resident_probability = mean(d$state == 
                  "seasonal_resident", na.rm = TRUE), core_resident_probability = mean(d$state == 
                  "core_resident", na.rm = TRUE), classification_confidence = mean(d$state_probability, 
                  na.rm = TRUE), classification_warning = if (mean(d$state_probability, 
                  na.rm = TRUE) < 0.59999999999999998) 
                  "low model-state confidence"
                else "", result_interpretation = "Model-based result from decoded robust-design states; detection assumptions influence these probabilities.", 
                stringsAsFactors = FALSE)
        })
        out <- do.call(rbind, rows)
    }
    else {
        history <- .analysis_history(analysis)
        ids <- rownames(history) %||% paste0("Subject_", safe_seq_rows(history, 
            context = "validated history row loop"))
        captures <- rowSums(history, na.rm = TRUE)
        capture_rate <- captures/max(1L, ncol(history))
        out <- data.frame(id = ids, most_likely_state = ifelse(capture_rate >= 
            0.5, "frequently_detected_provisional", ifelse(captures > 
            0, "occasionally_detected_provisional", "not_detected")), 
            state_probability = NA_real_, availability_probability = capture_rate, 
            resident_probability = capture_rate, transient_or_visitor_probability = 1 - 
                capture_rate, seasonal_resident_probability = pmax(0, 
                pmin(1, capture_rate - 0.25)), core_resident_probability = pmax(0, 
                pmin(1, capture_rate - 0.5)), classification_confidence = pmax(capture_rate, 
                1 - capture_rate), classification_warning = "provisional observed-data summary; no fitted model was available", 
            result_interpretation = "Provisional classification from observed detections only. This is not a model-based estimate because no fitted model was available.", 
            stringsAsFactors = FALSE)
    }
    if (!is.null(sim$true_states)) {
        out$true_state_or_use_category <- NA_character_
        out$estimated_state <- out$most_likely_state
        out$correct_if_known <- NA
        out$discrepancy_note <- "Truth-state comparison is available only when true states can be aligned by individual and period."
    }
    out
}
.old_model_vs_literature_residency_comparison_v086 <-
function (analysis) 
{
    analysis <- ensure_residency_outputs_for_comparison(analysis)
    model <- analysis$individual_residency_classification %||% 
        individual_residency_classification(analysis)
    lit <- analysis$literature_metrics %||% literature_residency_metrics_table(analysis)
    keep <- setdiff(names(lit), "id")
    merged <- merge(model, lit, by = "id", all.x = TRUE, sort = FALSE)
    lit_resident_score <- vapply(seq_len(nrow(merged)), function(i) {
        vals <- unlist(merged[i, keep, drop = FALSE], use.names = FALSE)
        vals <- vals[!is.na(vals)]
        if (!length(vals)) 
            return(NA_real_)
        mean(.resident_label_from_state(vals))
    }, numeric(1))
    model_res <- merged$resident_probability >= 0.5
    agreement <- ifelse(is.na(lit_resident_score), NA_real_, 
        ifelse(model_res, lit_resident_score, 1 - lit_resident_score))
    category <- ifelse(is.na(agreement), "insufficient_information", 
        ifelse(agreement >= 0.75, "strong_agreement", ifelse(agreement >= 
            0.5, "partial_agreement", ifelse(model_res & lit_resident_score < 
            0.5, "model_more_resident_than_metrics", ifelse(!model_res & 
            lit_resident_score >= 0.5, "metrics_more_resident_than_model", 
            "conflicting_metrics")))))
    merged$model_based_state <- merged$most_likely_state
    merged$model_resident_probability <- merged$resident_probability
    merged$model_confidence <- merged$classification_confidence
    merged$agreement_score <- agreement
    merged$agreement_category <- category
    merged$disagreement_type <- ifelse(category %in% c("strong_agreement", 
        "partial_agreement"), "", category)
    merged$interpretation_note <- "Rule-based residency metrics summarize observed detections under published criteria. Model-based estimates account for imperfect detection and latent state uncertainty when a model has been fitted."
    merged$warning <- "Literature metrics are not a gold standard. Disagreement indicates individuals or assumptions that should be reviewed."
    front <- c("id", "model_based_state", "model_resident_probability", 
        "model_confidence", keep, "agreement_score", "agreement_category", 
        "disagreement_type", "interpretation_note", "warning")
    merged[, intersect(front, names(merged)), drop = FALSE]
}
