.old_population_summary_v086 <-
function (history, occasion_table, true_alive = NULL, plateau_fraction = 0.10000000000000001) 
{
    history <- as_binary_matrix(history)
    total <- colSums(history)
    ever_before <- rep(0L, nrow(history))
    new_ind <- integer(ncol(history))
    for (j in seq_len(ncol(history))) {
        seen_now <- history[, j] > 0
        new_ind[j] <- sum(seen_now & ever_before == 0L)
        ever_before[seen_now] <- 1L
    }
    cumulative_new <- cumsum(new_ind)
    last_new <- if (any(new_ind > 0)) 
        max(which(new_ind > 0))
    else NA_integer_
    plateau_len <- if (is.na(last_new)) 
        ncol(history)
    else ncol(history) - last_new
    data.frame(occasion = occasion_table$occasion, date = occasion_table$date, 
        total_sightings = total, cumulative_sightings = cumsum(total), 
        new_individuals = new_ind, cumulative_individuals = cumulative_new, 
        true_alive = if (!is.null(true_alive)) 
            colSums(true_alive)
        else NA_integer_, discovery_asymptotic = plateau_len >= 
            ceiling(ncol(history) * plateau_fraction), plateau_length = plateau_len, 
        stringsAsFactors = FALSE)
}
.old_prepare_abundance_data_v086 <-
function (data, occasion_dates = NULL, format = NULL) 
{
    fmt <- format %||% detect_abundance_data_format(data)
    if (fmt %in% c("socprog_long", "CSV_LONG")) {
        names(data) <- tolower(names(data))
        data$date <- as.Date(data$date)
        ids <- sort(unique(as.character(data$id)))
        dates <- sort(unique(data$date))
        mat <- matrix(0, length(ids), length(dates), dimnames = list(ids, 
            as.character(dates)))
        for (i in seq_len(nrow(data))) mat[as.character(data$id[i]), 
            as.character(data$date[i])] <- 1
        occasions <- data.frame(date = dates, primary_period = format(dates, 
            "%Y-%m"), stringsAsFactors = FALSE)
    }
    else if (fmt %in% c("program_mark", "PROGRAM_MARK")) {
        names(data) <- tolower(names(data))
        ids <- as.character(data$id)
        chars <- strsplit(gsub("[^01]", "", as.character(data$encounter_history)), 
            "")
        K <- max(lengths(chars))
        mat <- t(vapply(chars, function(z) as.numeric(c(z, rep(0, 
            K - length(z)))), numeric(K)))
        rownames(mat) <- ids
        dates <- if (!is.null(occasion_dates)) 
            as.Date(occasion_dates)
        else seq_len(K)
        occasions <- data.frame(date = dates, primary_period = if (inherits(dates, 
            "Date")) 
            format(dates, "%Y-%m")
        else rep(1, K), stringsAsFactors = FALSE)
    }
    else if (fmt %in% c("wide_history", "wide")) {
        if (is.data.frame(data)) {
            id_col <- which(tolower(names(data)) == "id")
            if (length(id_col)) {
                ids <- as.character(data[[id_col[1]]])
                mat <- as.matrix(data[, -id_col[1], drop = FALSE])
                rownames(mat) <- ids
            }
            else mat <- as.matrix(data)
        }
        else mat <- as.matrix(data)
        storage.mode(mat) <- "numeric"
        mat[is.na(mat)] <- 0
        mat <- (mat > 0) * 1
        dates <- occasion_dates %||% seq_len(ncol(mat))
        occasions <- data.frame(date = dates, primary_period = if (inherits(dates, 
            "Date")) 
            format(dates, "%Y-%m")
        else rep(1, ncol(mat)), stringsAsFactors = FALSE)
    }
    else {
        stop("Unrecognized abundance data format.", call. = FALSE)
    }
    list(history = mat, occasions = occasions, format = fmt)
}
