.old_read_empirical_csv_v086 <-
function (path, id_col = "id", date_col = "date", effort_dates = NULL) 
{
    dat <- read.csv(path, stringsAsFactors = FALSE)
    if (!all(c(id_col, date_col) %in% names(dat))) {
        stop("CSV must contain id_col and date_col.")
    }
    dat[[date_col]] <- as.Date(dat[[date_col]])
    raw_dat <- dat
    sighting_keys <- unique(dat[, c(id_col, date_col)])
    dates <- sort(unique(c(sighting_keys[[date_col]], as.Date(effort_dates))))
    ids <- sort(unique(sighting_keys[[id_col]]))
    history <- matrix(0L, nrow = length(ids), ncol = length(dates), 
        dimnames = list(ids, as.character(dates)))
    idx <- match(sighting_keys[[id_col]], ids)
    jdx <- match(sighting_keys[[date_col]], dates)
    history[cbind(idx, jdx)] <- 1L
    optional_cols <- intersect(c("site", "latitude", "longitude", 
        "area", "habitat", "survey_route", "group_id", "sighting_id", 
        "sex", "age_class", "photo_quality", "group_size", "effort"), 
        names(dat))
    metadata <- if (length(optional_cols)) 
        raw_dat[, c(id_col, date_col, optional_cols), drop = FALSE]
    else NULL
    social <- derive_social_metrics(raw_dat, id_col = id_col)
    list(history = history, occasions = make_occasion_table(dates = dates), 
        raw = raw_dat, metadata = metadata, social_metrics = social)
}
