.old_run_configured_simulation_v086 <-
function (config, observed = NULL, make_plots = NULL) 
{
    config <- validate_simulation_parameters(config)
    dates <- config$selected_sampling_dates
    n_occ <- length(dates)
    if (config$simulation_model == "closed") {
        sim <- simulate_closed_population(N = config$N, duration_days = n_occ, 
            rmax = config$rmax, start_date = min(dates), seed = config$seed, 
            recapture_distribution = config$recapture_distribution, 
            recapture_params = config$recapture_params, allow_zero = config$allow_zero)
        sim$occasions$date <- dates
        colnames(sim$observed) <- as.character(dates)
    }
    else if (config$simulation_model == "jolly_seber") {
        b <- .entry_probabilities_from_mode(config$entry_probability_mode, 
            n_occ, config$b)
        sim <- simulate_js_open_population(N = config$N, n_occasions = n_occ, 
            p = config$p, phi = config$phi, b = b, start_date = min(dates), 
            seed = config$seed, drop_never_detected = config$drop_never_detected)
        sim$occasions$date <- dates
        colnames(sim$observed) <- as.character(dates)
    }
    else if (config$simulation_model == "latent_residency") {
        sim <- simulate_latent_residency_model(N = config$N, 
            n_occasions = n_occ, states = config$states, initial_probs = config$initial_probs, 
            transition_matrix = config$transition_matrix, detection = config$state_detection, 
            start_date = min(dates), effort_beta = config$effort_beta, 
            individual_re_sd = config$individual_re_sd, seed = config$seed)
        sim$occasions$date <- dates
        colnames(sim$observed) <- as.character(dates)
    }
    else {
        occ <- make_occasion_table(dates = dates)
        primary <- if (config$primary_period == "custom") 
            "month"
        else config$primary_period
        occ <- make_robust_design(occ, primary = primary)
        spec <- state_space_specification(states = config$states, 
            unavailable_states = config$unavailable_states, transition_matrix = config$transition_matrix, 
            detection_formula = config$detection_formula, robust_primary = primary)
        sim <- simulate_state_space_cr(N = config$N, occasion_table = occ, 
            spec = spec, beta = config$beta, seed = config$seed)
    }
    sim$config <- config
    sim$configuration_review <- config$configuration_review
    sim$capture_data_summary <- capture_data_summary(sim)
    sim$discovery_curve_table <- discovery_curve_table(sim)
    sim$simulation_design_summary <- summarize_simulation_design(config)
    sim$expected_pattern_summary <- expected_simulation_pattern(config)
    sim$sampling_effort_summary <- expected_sampling_effort_summary(config)
    sim$comparison_summary <- if (isTRUE(config$compare_to_observed) || 
        !is.null(observed)) {
        compare_simulated_observed_summary(sim, observed %||% 
            config$observed_data)
    }
    else {
        compare_simulated_observed_summary(sim)
    }
    do_plot <- if (is.null(make_plots)) 
        isTRUE(config$display_discovery_plots)
    else isTRUE(make_plots)
    if (do_plot) 
        plot_discovery_curves(sim$discovery_curve_table)
    if (isTRUE(config$export_discovery_jpg)) {
        sim$discovery_jpg_files <- export_discovery_curves_jpg(sim$discovery_curve_table, 
            prefix = config$discovery_jpg_prefix, output_dir = config$discovery_jpg_output_dir)
    }
    if (isTRUE(config$plot_capture_frequency_comparison)) {
        plot_simulated_observed_capture_distribution(sim, observed %||% 
            config$observed_data)
    }
    if (isTRUE(config$plot_discovery_curve_comparison)) {
        plot_simulated_observed_discovery_curves(sim, observed %||% 
            config$observed_data)
    }
    sim
}
.old_run_interactive_simulation_workflow_v086 <-
function (input_provider = NULL, questionnaire = ask_simulation_parameters, 
    simulation_runner = run_configured_simulation, post_run_menu = is.null(input_provider) && 
        interactive()) 
{
    repeat {
        config <- questionnaire(interactive = TRUE, defaults = FALSE, 
            input_provider = input_provider)
        config <- validate_simulation_parameters(config)
        confirmed <- confirm_simulation_configuration(config, 
            input_provider = input_provider)
        report_path <- attr(confirmed, "configuration_report_path")
        if (isTRUE(confirmed)) {
            config$configuration_report_path <- report_path %||% 
                config$configuration_report_path
            sim <- simulation_runner(config)
            assign("sim", sim, envir = .GlobalEnv)
            analysis <- make_analysis_object(sim = sim, config = config)
            assign("analysis", analysis, envir = .GlobalEnv)
            if (isTRUE(post_run_menu)) 
                guided_analysis_next_step_menu(analysis, input_provider = input_provider)
            return(invisible(sim))
        }
        if (identical(attr(confirmed, "action"), "exit")) {
            cat("Simulation cancelled before running.\n")
            config$configuration_report_path <- report_path %||% 
                config$configuration_report_path
            return(invisible(list(status = "cancelled_before_simulation", 
                config = config)))
        }
        cat("Returning to parameter editing.\n")
    }
}
