.open_history_summary_v089 <-
function (history) 
{
    y <- coerce_history_matrix(history, stage = "open-population fit")
    n <- nrow(y)
    k <- ncol(y)
    first <- apply(y == 1, 1, function(z) if (any(z)) 
        min(which(z))
    else NA_integer_)
    last <- apply(y == 1, 1, function(z) if (any(z)) 
        max(which(z))
    else NA_integer_)
    list(y = y, n_detected = n, n_occasions = k, first = first, 
        last = last, detections = sum(y, na.rm = TRUE), ever = rowSums(y, 
            na.rm = TRUE) > 0)
}
.parameter_key <-
function (parameter) 
{
    key <- tolower(trimws(as.character(parameter)))
    key <- gsub("^parameter:[[:space:]]*", "", key)
    key <- gsub("[^a-z0-9]+", "_", key)
    key <- gsub("^_|_$", "", key)
    aliases <- c(occasion_unit_options = "occasion_unit", simulation_model_options = "simulation_model", 
        sampling_design_options = "sampling_design", primary_period_options = "primary_period", 
        secondary_period_design_options = "secondary_period_design", 
        recapture_distribution_options = "recapture_distribution", 
        detection_formula_options = "detection_formula_mode", 
        transition_estimation_options = "transition_estimation", 
        transition_matrix_source_options = "transition_matrix_source", 
        transition_matrix_type_options = "transition_matrix_type", 
        transition_time_scale_options = "transition_time_scale", 
        entry_probability_mode_options = "entry_probability_mode", 
        gaussian_mean = "gaussian_mean", gaussian_sd = "gaussian_sd", 
        negative_binomial_mu = "negative_binomial_mu", negative_binomial_size = "negative_binomial_size")
    out <- key
    hit <- key %in% names(aliases)
    out[hit] <- aliases[key[hit]]
    out
}
