.print_option_explanation <-
function (name) 
{
    opts <- .allowed_simulation_options(name)
    explanations <- switch(name, occasion_unit = c("day: each possible sampling occasion is a calendar day.", 
        "week: each occasion is separated by weeks.", "month: each occasion is separated by months."), 
        primary_period = c("month: primary periods are calendar months.", 
            "season: primary periods are 3-month seasonal blocks.", 
            "year: primary periods are calendar years.", "custom: user supplies grouping labels or a custom rule."), 
        secondary_period_design = c("all_occasions_within_primary: use every occasion inside each primary period.", 
            "fixed_number_per_primary: select a fixed number of secondary surveys inside each primary period.", 
            "consecutive_days_per_primary: select a block of consecutive days inside each primary period.", 
            "empirical: use the actual supplied dates."), sampling_design = c("daily: use all possible sampling dates.", 
            "weekly: randomly select one occasion per week.", 
            "monthly: randomly select one occasion per month.", 
            "twice_monthly: randomly select two occasions per month.", 
            "consecutive_month: select a block of consecutive days per month.", 
            "random: select a fixed number of random occasions.", 
            "empirical: use supplied empirical dates."), recapture_distribution = c("uniform: all recapture counts between minimum and maximum are equally likely.", 
            "gaussian: most individuals are near a central mean, with fewer very low or very high values.", 
            "exponential: many individuals have few recaptures and few individuals have many recaptures.", 
            "chisq: right-skewed; can represent many low-use individuals and fewer high-use individuals.", 
            "negative_binomial: overdispersed counts; useful when many individuals have few records but some have many.", 
            "poisson: mean approximately equals variance; often restrictive for heterogeneous dolphin data.", 
            "beta_binomial: heterogeneous individual detection/use probabilities; useful for overdispersion."), 
        transition_estimation = c("fixed: use the selected transition matrix as a biological modelling assumption.", 
            "estimate_full: estimate all transition probabilities from the encounter-history data.", 
            "estimate_diagonal_dominant: estimate transitions with a simpler same-state-persistence structure.", 
            "estimate_adjacent: estimate only same-state and adjacent-state movement.", 
            "estimate_custom_mask: estimate only the transitions selected in transition_free_mask."), 
        simulation_model = c("closed: all individuals are assumed available during the study; useful for survey-design sensitivity.", 
            "jolly_seber: individuals can enter and survive through time; useful for open-population scenarios.", 
            "latent_residency: individuals move among hidden residency states with imperfect detection.", 
            "state_space_robust_design: robust-design model with primary/secondary periods and availability."))
    cat(paste(seq_along(opts), explanations, sep = ". "), sep = "\n")
    invisible(data.frame(option = opts, explanation = explanations, 
        stringsAsFactors = FALSE))
}
.read_option <-
function (name, default, interactive = TRUE) 
{
    if (!interactive) 
        return(default)
    explain_parameter_before_prompt(name)
    cat("\n", gsub("_", " ", name), " options:\n", sep = "")
    .print_option_explanation(name)
    ans <- readline("Enter option number or name, or press Enter to use default: ")
    if (!nzchar(trimws(ans))) 
        return(default)
    opts <- .allowed_simulation_options(name)
    ans <- trimws(ans)
    if (grepl("^[0-9]+$", ans)) {
        idx <- as.integer(ans)
        if (idx >= 1 && idx <= length(opts)) 
            return(opts[idx])
    }
    ans <- tolower(ans)
    if (ans %in% opts) 
        return(ans)
    stop(name, " must be one of: ", paste(opts, collapse = ", "))
}
.read_parameter <-
function (name, default, meaning, valid, interactive = TRUE, 
    parser = identity) 
{
    if (!interactive) 
        return(default)
    explain_parameter_before_prompt(name)
    cat("\nParameter:", name, "\n")
    cat("Meaning:", meaning, "\n")
    cat("Valid values:", valid, "\n")
    cat("Default:", paste(default, collapse = ", "), "\n")
    ans <- readline(paste0("Enter ", name, ", or press Enter to use default: "))
    if (!nzchar(trimws(ans))) 
        return(default)
    parser(ans)
}
