.resident_existing_output_dir <-
"Outputs"
.resident_project_root <-
function () 
{
    base <- normalizePath(getwd(), mustWork = FALSE)
    candidates <- unique(c(base, file.path(base, "Outputs"), file.path(base, ".."),
        file.path(base, "..", "Outputs")))
    for (dir in candidates) {
        if (file.exists(file.path(dir, "resident_pipeline_v0.9.41.R")) ||
            file.exists(file.path(dir, "Outputs", "resident_pipeline_v0.9.41.R"))) {
            if (basename(dir) == "Outputs")
                return(normalizePath(dirname(dir), mustWork = FALSE))
            return(normalizePath(dir, mustWork = FALSE))
        }
    }
    parent <- dirname(base)
    while (!identical(parent, base)) {
        if (file.exists(file.path(parent, "resident_pipeline_v0.9.41.R")) ||
            file.exists(file.path(parent, "Outputs", "resident_pipeline_v0.9.41.R"))) {
            return(normalizePath(parent, mustWork = FALSE))
        }
        base <- parent
        parent <- dirname(base)
    }
    normalizePath(getwd(), mustWork = FALSE)
}
.resident_find_dependency <-
function (filename) 
{
    root <- .resident_project_root()
    candidates <- unique(c(
        filename,
        file.path(root, filename),
        file.path(root, "Outputs", filename),
        file.path("outputs", filename),
        file.path(getwd(), filename),
        file.path(getwd(), "outputs", filename),
        file.path(getwd(), "Outputs", filename),
        file.path(dirname(getwd()), "outputs", filename),
        file.path(dirname(getwd()), "Outputs", filename)
    ))
    hit <- candidates[file.exists(candidates)]
    if (!length(hit)) 
        stop("Required dependency not found: ", filename, call. = FALSE)
    normalizePath(hit[1])
}
