.resident_parse_logical <-
function (x) 
{
    if (is.logical(x) && length(x) == 1L && !is.na(x)) 
        return(x)
    key <- tolower(trimws(as.character(x)))
    if (key %in% c("1", "yes", "y", "true", "t")) 
        return(TRUE)
    if (key %in% c("0", "no", "n", "false", "f")) 
        return(FALSE)
    stop("Enter 1 for yes/TRUE or 0 for no/FALSE.")
}
