.resident_prompt_option <-
function (title, options, explanations, default = NULL, input_provider = NULL, 
    max_retries = if (is.null(input_provider)) Inf else 10L) 
{
    explain_parameter_before_prompt(title)
    cat("\n", title, " options:\n", sep = "")
    for (i in seq_along(options)) {
        cat(i, ". ", options[i], " - ", explanations[i], "\n", 
            sep = "")
    }
    if (!is.null(default)) 
        cat("Default:", default, "\n")
    parser <- function(ans) {
        ans <- trimws(as.character(ans))
        if (grepl("^[0-9]+$", ans)) {
            idx <- as.integer(ans)
            if (idx >= 1 && idx <= length(options)) 
                return(options[idx])
        }
        hit <- match(tolower(ans), tolower(options))
        if (!is.na(hit)) 
            return(options[hit])
        stop(title, " must be one of: ", paste(options, collapse = ", "), 
            ". You may enter the option number.")
    }
    reprompt_until_valid("Enter option number or name: ", parser, 
        input_provider = input_provider, default = default, example = paste0("1 or ", 
            options[1]), max_retries = max_retries, allow_default = !is.null(default))
}
.resident_prompt_parameter <-
function (name, meaning, valid, default, input_provider = NULL, 
    parser = identity, allow_default = TRUE, max_retries = if (is.null(input_provider)) Inf else 10L, 
    advice = NULL, example = NULL) 
{
    explain_parameter_before_prompt(name)
    cat("\nParameter:", name, "\n")
    cat("Meaning:", meaning, "\n")
    cat("Valid values:", valid, "\n")
    if (!is.null(advice) && nzchar(advice)) 
        cat("Practical advice:", advice, "\n")
    if (!is.null(default)) 
        cat("Default:", paste(default, collapse = ", "), "\n")
    prompt <- if (allow_default && !is.null(default)) {
        paste0("Enter ", name, ", or press Enter to use default: ")
    }
    else {
        paste0("Enter ", name, ": ")
    }
    reprompt_until_valid(prompt, parser, input_provider = input_provider, 
        default = default, example = example, max_retries = max_retries, 
        allow_default = allow_default)
}
