.resident_v089_route_selected_model <-
function (analysis, selected, ...) 
{
    model <- if (is.data.frame(selected)) 
        selected$candidate_model[1]
    else as.character(selected)[1]
    ent <- model_registry_entry(model)
    if (is.null(ent)) 
        stop("Selected model is not registered: ", model, call. = FALSE)
    if (!model_is_selectable(model)) 
        stop("Selected model is not selectable in this workflow: ", 
            model, call. = FALSE)
    y <- extract_history(analysis, stage = paste("route selected model", 
        model))
    occ <- tryCatch(extract_occasions(analysis, stage = paste("route selected model", 
        model)), error = function(e) NULL)
    fit <- switch(ent$model_role[1], descriptive = fit_abundance_model(y, 
        model, ...), closed_abundance = fit_abundance_model(y, 
        model, ...), huggins_abundance = fit_abundance_model(y, 
        model, ...), robust_design_abundance = fit_robust_design_abundance(y, 
        occ, model, ...), open_population_abundance = if (model == 
        "jolly_seber") fit_jolly_seber_abundance(y, occ, ...) else fit_popan_like_abundance(y, 
        occ, ...), markovian_state_space = fit_state_space_model_from_analysis(analysis, 
        ...), stop("No handler for model role: ", ent$model_role[1], 
        call. = FALSE))
    analysis$selected_model_registry_entry <- ent
    if (identical(ent$output_slots[1], "state_space_fit")) 
        analysis$state_space_fit <- fit
    else analysis$abundance_fit <- fit
    analysis$abundance_summary <- if (!is.null(analysis$abundance_fit)) 
        print_abundance_summary(analysis$abundance_fit, print = FALSE)
    else NULL
    analysis
}
