.resident_v090_build_design_data <-
function (history, occasions = NULL, group = NULL, effort = NULL) 
{
    y <- coerce_history_matrix(history, stage = "design data")
    K <- ncol(y)
    dates <- if (!is.null(occasions) && "date" %in% names(occasions)) 
        as.Date(occasions$date)
    else as.Date(Sys.Date()) + seq_len(K) - 1L
    data.frame(occasion = seq_len(K), time = seq_len(K), group = group %||% 
        "all", effort = effort %||% if (!is.null(occasions) && 
        "effort" %in% names(occasions)) 
        occasions$effort
    else 1, primary = if (!is.null(occasions) && "primary_period" %in% 
        names(occasions)) 
        occasions$primary_period
    else format(dates, "%Y-%m"), secondary = if (!is.null(occasions) && 
        "secondary_period" %in% names(occasions)) 
        occasions$secondary_period
    else ave(seq_len(K), format(dates, "%Y-%m"), FUN = seq_along), 
        date = dates, stringsAsFactors = FALSE)
}
