.resident_v090_fit_cjs_model <-
function (history, occasions = NULL, Phi = ~1, p = ~1, group = NULL, 
    covariates = NULL, maxit = 500, ...) 
{
    y <- coerce_history_matrix(history, stage = "CJS fit")
    if (ncol(y) < 3L) 
        stop("CJS requires at least three occasions with recapture opportunity.", 
            call. = FALSE)
    start <- c(Phi_intercept = .logit(0.80000000000000004), Phi_slope = 0, 
        p_intercept = .logit(max(0.050000000000000003, min(0.94999999999999996, 
            mean(y)))), p_slope = 0)
    opt <- optim(start, function(z) -cjs_loglik(z, y, Phi = Phi, 
        p = p, occasions = occasions, group = group, covariates = covariates), 
        method = "BFGS", hessian = TRUE, control = list(maxit = maxit))
    K <- ncol(y)
    dd <- cjs_design_data(y, occasions, group, covariates)
    Phi_v <- .invlogit(opt$par[1] + opt$par[2] * .cjs_formula_vector(Phi, 
        dd, K - 1L, "Phi"))
    p_v <- .invlogit(opt$par[3] + opt$par[4] * .cjs_formula_vector(p, 
        dd, K, "p"))
    np <- length(opt$par)
    ll <- -opt$value
    out <- list(model_name = "CJS", abundance_model = "CJS", 
        model_family = "open_population", model_role = "survival_detection", 
        history = y, occasions = occasions, par = opt$par, optim = opt, 
        logLik = ll, n_parameters = np, AIC = -2 * ll + 2 * np, 
        AICc = -2 * ll + 2 * np + (2 * np * (np + 1))/max(1, 
            nrow(y) - np - 1), BIC = -2 * ll + log(max(1, nrow(y))) * 
            np, convergence = opt$convergence, Phi = Phi_v, p = p_v, 
        beta_Phi = opt$par[1:2], beta_p = opt$par[3:4], Phi_formula = Phi, 
        p_formula = p, warning = "CJS estimates apparent survival/persistence and detection conditional on first capture; it does not estimate total abundance.")
    class(out) <- c("resident_cjs_fit", "resident_survival_detection_fit", 
        "list")
    out
}
.resident_v090_handle_post_simulation_menu_choice <-
function (choice, analysis, input_provider = NULL) 
{
    menu <- post_simulation_menu_definition()
    key <- normalize_menu_choice(choice, menu)
    if (is.na(key)) 
        return(list(analysis = analysis, finished = FALSE))
    if (key == "finish") 
        return(list(analysis = analysis, finished = TRUE))
    if (key == "capture_table") {
        print_console_table(capture_recapture_table_from_analysis(analysis), 
            title = "Capture-recapture table", max_rows = 20, 
            export_prefix = "capture_recapture_table")
    }
    else if (key == "capture_summary") {
