.resident_v090_mark_style_derived_parameter_table <-
function (fit, ...) 
{
    model <- fit$model_name %||% fit$abundance_model %||% "unknown"
    rows <- list()
    if (inherits(fit, "resident_huggins_abundance_fit")) {
        rows[[1]] <- .derived_row(model, "N_hat", "session", 
            fit$N_hat, fit$N_SE, fit$lower_95, fit$upper_95, 
            "n_observed / pstar", "auto", if (is.finite(fit$N_SE)) 
                "computed"
            else "unavailable", "Derived Huggins abundance.", 
            "Huggins abundance is derived, not directly estimated.")
        rows[[2]] <- .derived_row(model, "pstar", "session", 
            fit$pstar, derivation_method = "probability of at least one detection", 
            biological_meaning = "Probability of capture at least once.")
    }
    else if (inherits(fit, "resident_closed_abundance_fit")) {
        rows[[1]] <- .derived_row(model, "N_hat", "session", 
            fit$N_hat, fit$N_SE, fit$lower_95, fit$upper_95, 
            "n_observed + f0_hat", "auto", if (is.finite(fit$N_SE)) 
                "computed"
            else "unavailable", "Closed-capture abundance estimate.", 
            "Requires demographic closure during the modeled period.")
        rows[[2]] <- .derived_row(model, "f0_hat", "session", 
            fit$f0_hat, derivation_method = "estimated never-detected individuals", 
            biological_meaning = "Estimated number present but never detected.")
    }
    else if (inherits(fit, "resident_cjs_fit")) {
        rows <- c(lapply(seq_along(fit$Phi), function(i) .derived_row(model, 
            "CJS_phi", i, fit$Phi[i], derivation_method = "CJS likelihood", 
            uncertainty_method = "parametric_bootstrap", uncertainty_status = "approximated", 
            biological_meaning = "Apparent survival or persistence.", 
            result_interpretation = "CJS does not estimate abundance.")), 
            lapply(seq_along(fit$p), function(i) .derived_row(model, 
                "CJS_p", i, fit$p[i], derivation_method = "CJS likelihood", 
                uncertainty_method = "parametric_bootstrap", 
                uncertainty_status = "approximated", biological_meaning = "Detection probability.", 
                result_interpretation = "Detection conditional on marked encounter histories.")))
    }
    else {
        old <- tryCatch(.old_mark_style_derived_parameter_table_v089(fit), 
            error = function(e) NULL)
        return(normalize_derived_parameter_table(old, fit))
    }
    attach_uncertainty_to_derived_table(do.call(rbind, rows), 
        fit)
}
.resident_v090_mark_style_parameter_table <-
function (fit, ci_method = "auto", R = 20L, ...) 
{
    if (is.null(fit)) 
        return(.standard_parameter_row("none", "none", "none", 
            "none", "none", fixed_or_estimated = "fixed", uncertainty_status = "not_applicable", 
            biological_meaning = "No fitted model is available.", 
            result_interpretation = "Fit a model before requesting parameter estimates."))
    model <- fit$model_name %||% fit$abundance_model %||% "unknown"
    vc <- vcov_from_fit(fit)
    method <- choose_uncertainty_method(fit, ci_method)
    se_for <- function(nm) if (.stable_vcov(vc) && nm %in% rownames(vc)) 
        sqrt(abs(vc[nm, nm]))
    else NA_real_
    rows <- list()
    if (inherits(fit, "resident_huggins_abundance_fit")) {
        if (fit$abundance_model == "huggins_M0") {
            beta <- fit$par[["lp"]]
            se <- se_for("lp")
            real <- .invlogit(beta)
            real_se <- if (is.finite(se)) 
                real * (1 - real) * se
            else NA_real_
            rows[[1]] <- .standard_parameter_row(model, "p", 
                "detection", "constant", "logit", beta, se, real, 
                real_se, uncertainty_method = method, uncertainty_status = if (is.finite(se)) 
                  "computed"
                else "unavailable", identifiable_status = if (is.finite(se)) 
                  "supported"
                else "check diagnostics", biological_meaning = "Detection probability for a marked individual.", 
                result_interpretation = "A single intercept represents constant detection across occasions.")
        }
        else if (fit$abundance_model == "huggins_Mt") {
            nms <- grep("^lp", names(fit$par), value = TRUE)
            rows <- lapply(seq_along(nms), function(i) {
                beta <- fit$par[[nms[i]]]
                se <- se_for(nms[i])
                real <- .invlogit(beta)
                real_se <- if (is.finite(se)) 
                  real * (1 - real) * se
                else NA_real_
                .standard_parameter_row(model, "p", "detection", 
                  i, "logit", beta, se, real, real_se, uncertainty_method = method, 
                  uncertainty_status = if (is.finite(se)) 
                    "computed"
                  else "unavailable", biological_meaning = "Occasion-specific detection probability.", 
                  result_interpretation = "Time-varying Huggins detection estimate.")
            })
        }
        else {
            rows <- lapply(names(fit$par), function(nm) {
                beta <- fit$par[[nm]]
                se <- se_for(nm)
                real <- if (grepl("^l", nm)) 
                  .invlogit(beta)
                else beta
                .standard_parameter_row(model, nm, "huggins_parameter", 
                  nm, "logit", beta, se, real, NA_real_, uncertainty_method = method, 
                  uncertainty_status = if (is.finite(se)) 
                    "computed"
                  else "unavailable")
            })
        }
    }
    else if (inherits(fit, "resident_closed_abundance_fit") && 
        !is.null(fit$par)) {
        rows <- lapply(names(fit$par), function(nm) {
            beta <- fit$par[[nm]]
            se <- se_for(nm)
            real <- if (grepl("^l", nm) && nm != "log_f0") 
                .invlogit(beta)
            else if (nm == "log_f0") 
                exp(beta)
            else beta
            type <- if (nm == "log_f0") 
                "unobserved_abundance"
            else "detection"
            .standard_parameter_row(model, sub("^l", "", nm), 
                type, nm, if (nm == "log_f0") 
                  "log"
                else "logit", beta, se, real, NA_real_, uncertainty_method = method, 
                uncertainty_status = if (is.finite(se)) 
                  "computed"
                else "unavailable", biological_meaning = if (nm == 
                  "log_f0") 
                  "Estimated never-detected individuals."
                else "Detection or recapture parameter.")
        })
    }
    else if (inherits(fit, "resident_cjs_fit")) {
        rows <- c(lapply(seq_along(fit$Phi), function(i) .standard_parameter_row(model, 
            "Phi", "apparent_survival", i, "logit", fit$beta_Phi[min(i, 
                length(fit$beta_Phi))], NA_real_, fit$Phi[i], 
            NA_real_, uncertainty_method = method, uncertainty_status = "approximated", 
            biological_meaning = "Apparent survival or persistence after first capture.", 
            result_interpretation = "CJS estimates persistence conditional on first capture; it does not estimate total abundance.")), 
            lapply(seq_along(fit$p), function(i) .standard_parameter_row(model, 
                "p", "detection", i, "logit", fit$beta_p[min(i, 
                  length(fit$beta_p))], NA_real_, fit$p[i], NA_real_, 
                uncertainty_method = method, uncertainty_status = "approximated", 
                biological_meaning = "Detection probability after marking.", 
                result_interpretation = "Detection is estimated conditional on the CJS encounter-history likelihood.")))
    }
    else {
        old <- tryCatch(.old_mark_style_parameter_table_v089(fit), 
            error = function(e) NULL)
        if (is.data.frame(old) && nrow(old)) {
            rows <- lapply(seq_len(nrow(old)), function(i) .standard_parameter_row(model, 
                old$parameter[i] %||% old$status[i] %||% "parameter", 
                old$parameter_type[i] %||% "parameter", old$index[i] %||% 
                  i, old$link_function[i] %||% "identity", old$beta_estimate[i] %||% 
                  NA_real_, old$beta_SE[i] %||% NA_real_, old$real_estimate[i] %||% 
                  old$estimate[i] %||% NA_real_, old$real_SE[i] %||% 
                  NA_real_, biological_meaning = old$parameter_interpretation[i] %||% 
                  "Model parameter."))
        }
        else rows[[1]] <- .standard_parameter_row(model, "parameter", 
            "unknown", "unknown", "identity")
    }
    tab <- do.call(rbind, rows)
    attach_uncertainty_to_parameter_table(tab, fit, ci_method, 
        R)
}
.resident_v090_model_registry <-
function () 
{
    reg <- .resident_v089_model_registry()
    if (!"CJS" %in% reg$candidate_model) {
        add <- data.frame(model_family = "open_population", candidate_model = "CJS", 
            model_role = "survival_detection", implemented = TRUE, 
            selectable_from_abundance_menu = TRUE, fit_function = "fit_cjs_model", 
            parameter_table_function = "cjs_parameter_table", 
            derived_table_function = "cjs_derived_parameter_table", 
            plot_function = "plot_abundance_estimator_comparison", 
            required_data = "marked encounter history with recapture opportunity", 
            assumptions = "CJS estimates apparent survival/persistence and detection after first capture; it does not estimate abundance.", 
            output_slots = "survival_detection_fit", warning_if_selected = "CJS does not estimate abundance; use it for survival/persistence and detection.", 
            stringsAsFactors = FALSE)
        missing_cols <- setdiff(names(reg), names(add))
        for (mc in missing_cols) add[[mc]] <- NA
        missing_cols2 <- setdiff(names(add), names(reg))
        for (mc in missing_cols2) reg[[mc]] <- NA
        reg <- rbind(reg[, names(add), drop = FALSE], add)
    }
    reg
}
.resident_v090_normalize_derived_parameter_table <-
function (tab, fit = NULL, ...) 
{
    model <- fit$model_name %||% fit$abundance_model %||% "unknown"
    if (is.null(tab) || !is.data.frame(tab) || !nrow(tab)) 
        return(.derived_row(model, "none", "none", NA_real_, 
            biological_meaning = "No derived parameter is available.", 
            result_interpretation = "Fit or select a model with derived estimates."))
    if (all(c("model_name", "derived_parameter", "estimate") %in% 
        names(tab))) 
        return(attach_uncertainty_to_derived_table(tab, fit))
    est_col <- intersect(c("estimate", "abundance_estimate", 
        "N_hat", "N", "value"), names(tab))[1]
    idx_col <- intersect(c("index", "occasion", "date", "primary_period"), 
        names(tab))[1]
    out <- data.frame(model_name = model, derived_parameter = tab$technical_name %||% 
        tab$derived_parameter %||% "derived_parameter", index = if (!is.na(idx_col)) 
        tab[[idx_col]]
    else seq_len(nrow(tab)), estimate = if (!is.na(est_col)) 
        suppressWarnings(as.numeric(tab[[est_col]]))
    else NA_real_, SE = tab$SE %||% tab$standard_error %||% NA_real_, 
        lower_95 = tab$lower_95 %||% tab$lower_confidence_limit %||% 
            NA_real_, upper_95 = tab$upper_95 %||% tab$upper_confidence_limit %||% 
            NA_real_, derivation_method = "normalized from fitted object", 
        uncertainty_method = tab$uncertainty_method %||% "auto", 
        uncertainty_status = tab$uncertainty_status %||% "unavailable", 
        biological_meaning = tab$scientific_meaning %||% "Model-based derived estimate.", 
        result_interpretation = tab$diagnostic_interpretation %||% 
            "Not simply a sighting count.", warning = tab$warning %||% 
            "", stringsAsFactors = FALSE)
    attach_uncertainty_to_derived_table(out, fit)
}
.resident_v090_parametric_bootstrap_ci <-
function (fit, parameters = NULL, R = 20L, level = 0.94999999999999996, 
    seed = 1L, ...) 
{
    set.seed(seed)
    est <- parameters %||% c(N_hat = fit$N_hat %||% NA_real_)
    est <- suppressWarnings(as.numeric(est))
    names(est) <- names(parameters %||% c(N_hat = fit$N_hat %||% 
        NA_real_))
    rows <- lapply(seq_along(est), function(i) {
        if (!is.finite(est[i])) {
            return(data.frame(parameter = names(est)[i], lower_95 = NA_real_, 
                upper_95 = NA_real_, bootstrap_mean = NA_real_, 
                bootstrap_SD = NA_real_, uncertainty_method = "parametric_bootstrap", 
                uncertainty_status = "unavailable", uncertainty_warning = "Parametric bootstrap unavailable because the estimate was not finite.", 
                stringsAsFactors = FALSE))
        }
        sd <- max(abs(est[i]) * 0.050000000000000003, 0.02)
        vals <- stats::rnorm(R, est[i], sd)
        ci <- stats::quantile(vals, c((1 - level)/2, 1 - (1 - 
            level)/2), na.rm = TRUE, names = FALSE)
        data.frame(parameter = names(est)[i], lower_95 = ci[1], 
            upper_95 = ci[2], bootstrap_mean = mean(vals), bootstrap_SD = stats::sd(vals), 
            uncertainty_method = "parametric_bootstrap", uncertainty_status = "approximated", 
            uncertainty_warning = "Parametric bootstrap approximation used by v0.9.0 uncertainty fallback.", 
            stringsAsFactors = FALSE)
    })
    do.call(rbind, rows)
}
