.resident_v091_build_design_data <-
function (history, occasions = NULL, group = NULL, effort = NULL, 
    allow_synthetic_dates = FALSE, data_type = c("empirical", 
        "simulation", "test"), ...) 
{
    data_type <- match.arg(data_type)
    y <- coerce_history_matrix(history, stage = "design data")
    if (is.null(occasions)) {
        dates <- resident_require_dates(NULL, allow_synthetic_dates || 
            data_type != "empirical", ncol(y))
        occasions <- data.frame(occasion = seq_len(ncol(y)), 
            date = dates, stringsAsFactors = FALSE)
    }
    if (!"date" %in% names(occasions) || any(is.na(as.Date(occasions$date)))) {
        if (data_type == "empirical" && !isTRUE(allow_synthetic_dates)) 
            stop("Empirical design data require valid survey dates.", 
                call. = FALSE)
        occasions$date <- resident_require_dates(NULL, TRUE, 
            ncol(y))
    }
    dates <- as.Date(occasions$date)
    data.frame(occasion = seq_len(ncol(y)), time = seq_len(ncol(y)), 
        group = group %||% "all", effort = effort %||% if ("effort" %in% 
            names(occasions)) 
            occasions$effort
        else 1, primary = occasions$primary_period %||% occasions$primary %||% 
            format(dates, "%Y-%m"), secondary = occasions$secondary_period %||% 
            occasions$secondary %||% ave(seq_len(ncol(y)), format(dates, 
            "%Y-%m"), FUN = seq_along), date = dates, stringsAsFactors = FALSE)
}
