.resident_v091_fit_jolly_seber_abundance <-
function (history, occasions = NULL, maxit = 500, ...) 
{
    s <- .open_history_summary_v089(history)
    if (s$n_occasions < 2L) 
        stop("Jolly-Seber-style fitting needs at least two occasions.", 
            call. = FALSE)
    start <- c(logit(0.80000000000000004), logit(max(0.050000000000000003, 
        min(0.94999999999999996, s$detections/max(1, s$n_detected * 
            s$n_occasions)))), rep(0, s$n_occasions))
    opt <- tryCatch(optim(start, function(z) -jolly_seber_loglik(z, 
        s$y), method = "BFGS", control = list(maxit = maxit), 
        hessian = TRUE), error = function(e) e)
    if (inherits(opt, "error")) 
        stop(conditionMessage(opt), call. = FALSE)
    phi <- inv_logit(opt$par[1])
    p <- inv_logit(opt$par[2])
    b <- exp(opt$par[seq(3, length(opt$par))])
    b <- b/sum(b)
    detected_by_occ <- colSums(s$y > 0, na.rm = TRUE)
    N_by_occasion <- pmax(detected_by_occ, detected_by_occ/pmax(p, 
        9.9999999999999995e-07))
    out <- list(model_name = "jolly_seber", abundance_model = "jolly_seber", 
        model_family = "open_population", backend = "base_R_v0.8.9", 
        logLik = -opt$value, n_parameters = length(opt$par), 
        AIC = 2 * length(opt$par) + 2 * opt$value, AICc = NA_real_, 
        BIC = log(max(1, s$n_detected)) * length(opt$par) + 2 * 
            opt$value, convergence = opt$convergence, phi_hat = phi, 
        p_hat = p, b_hat = b, N_hat = max(N_by_occasion, na.rm = TRUE), 
        N_SE = NA_real_, N_by_occasion = N_by_occasion, occasions = occasions, 
        parameter_vector = opt$par, hessian = opt$hessian, warning = "Jolly-Seber-style open-population fit in v0.8.9; Program MARK numerical equivalence is not yet certified.")
    class(out) <- c("resident_open_population_fit", "resident_abundance_fit", 
        "list")
    out
}
.resident_v091_fit_popan_like_abundance <-
function (history, occasions = NULL, maxit = 500, ...) 
{
    js <- fit_jolly_seber_abundance(history, occasions = occasions, 
        maxit = maxit, ...)
    s <- .open_history_summary_v089(history)
    superN <- max(s$n_detected, ceiling(js$N_hat/max(sum(js$b_hat), 
        9.9999999999999995e-07)))
    js$model_name <- js$abundance_model <- "POPAN_like"
    js$N_super_hat <- superN
    js$N_hat <- superN
    js$warning <- "POPAN-like superpopulation fit in v0.8.9; Program MARK numerical equivalence is not yet certified."
    class(js) <- c("resident_popan_like_fit", class(js))
    js
}
