.resident_v091_model_registry <-
function () 
{
    reg <- .resident_v089_model_registry()
    if (!"CJS" %in% reg$candidate_model) {
        add <- data.frame(model_family = "open_population", candidate_model = "CJS", 
            model_role = "survival_detection", implemented = TRUE, 
            selectable_from_abundance_menu = TRUE, fit_function = "fit_cjs_model", 
            parameter_table_function = "cjs_parameter_table", 
            derived_table_function = "cjs_derived_parameter_table", 
            plot_function = "plot_abundance_estimator_comparison", 
            required_data = "marked encounter history with recapture opportunity", 
            assumptions = "CJS estimates apparent survival/persistence and detection after first capture; it does not estimate abundance.", 
            output_slots = "survival_detection_fit", warning_if_selected = "CJS does not estimate abundance; use it for survival/persistence and detection.", 
            stringsAsFactors = FALSE)
        missing_cols <- setdiff(names(reg), names(add))
        for (mc in missing_cols) add[[mc]] <- NA
        missing_cols2 <- setdiff(names(add), names(reg))
        for (mc in missing_cols2) reg[[mc]] <- NA
        reg <- rbind(reg[, names(add), drop = FALSE], add)
    }
    reg
}
.resident_v091_normalize_derived_parameter_table <-
function (tab, fit = NULL, ...) 
{
    model <- fit$model_name %||% fit$abundance_model %||% "unknown"
    if (inherits(fit, "resident_robust_design_abundance_fit") && 
        !is.null(fit$primary_abundance)) {
        pa <- fit$primary_abundance
        out <- data.frame(model_name = model, derived_parameter = "primary_period_N_hat", 
            index = as.character(pa$primary_period), estimate = pa$N_hat, 
            SE = pa$SE, lower_95 = pa$lower_95, upper_95 = pa$upper_95, 
            uncertainty_method = "primary_period_closed_submodel", 
            uncertainty_status = ifelse(is.finite(pa$SE), "computed", 
                "unavailable"), result_interpretation = "Primary-period robust-design abundance estimate with submodel uncertainty.", 
            warning = pa$warning %||% "", stringsAsFactors = FALSE)
        attr(out, "full_table") <- pa
        return(out)
    }
    out <- tryCatch(.resident_v090_normalize_derived_parameter_table(tab, 
        fit, ...), error = function(e) NULL)
    if (is.null(out)) 
        out <- .resident_v090_mark_style_derived_parameter_table(fit)
    canonical <- c("model_name", "derived_parameter", "index", 
        "estimate", "SE", "lower_95", "upper_95", "uncertainty_method", 
        "uncertainty_status", "result_interpretation", "warning")
    for (nm in canonical) if (!nm %in% names(out)) 
        out[[nm]] <- NA
    out[, canonical, drop = FALSE]
}
