.resident_v093_fit_abundance_model <-
function (history, abundance_model = "closed_M0", occasions = NULL, 
    temporal_structure = NULL, input_provider = NULL, data_type = "empirical", 
    ...) 
{
    if (requires_temporal_structure(abundance_model)) {
        if (grepl("^robust_design", abundance_model)) 
            return(fit_robust_design_abundance(history, occasions, 
                abundance_model, temporal_structure, input_provider, 
                data_type, ...))
        if (abundance_model == "jolly_seber") 
            return(fit_jolly_seber_abundance(history, occasions, 
                temporal_structure = temporal_structure, input_provider = input_provider, 
                data_type = data_type, ...))
        if (abundance_model == "POPAN_like") 
            return(fit_popan_like_abundance(history, occasions, 
                temporal_structure = temporal_structure, input_provider = input_provider, 
                data_type = data_type, ...))
        if (abundance_model %in% c("CJS", "CJS_like")) 
            return(fit_cjs_model(history, occasions, temporal_structure = temporal_structure, 
                input_provider = input_provider, data_type = data_type, 
                ...))
    }
    .resident_v093_fit_abundance_model(history, abundance_model, 
        ...)
}
.resident_v093_fit_from_model_specification <-
function (analysis, specification = analysis$model_specification %||% 
    NULL, input_provider = NULL, ...) 
{
    if (is.null(specification)) 
        stop("No model specification exists. Create one with empirical_model_setup_workflow().", 
            call. = FALSE)
    fam <- specification$model_family
    if (requires_temporal_structure(fam, formulas = specification$parameter_structures)) 
        analysis <- temporal_model_gate(analysis = analysis, 
            model = fam, input_provider = input_provider, formulas = specification$parameter_structures)$analysis
    if (fam %in% c("CJS", "cjs")) 
        return(fit_cjs_model(extract_history(analysis), extract_occasions(analysis), 
            Phi = specification$parameter_structures$Phi %||% 
                ~1, p = specification$parameter_structures$p %||% 
                ~1, temporal_structure = analysis$temporal_structure, 
            data_type = analysis$data_type %||% "empirical", 
            ...))
    .resident_v093_fit_from_model_specification(analysis, specification, 
        ...)
}
