.resident_v093_handle_post_simulation_menu_choice <-
function (choice, analysis, input_provider = NULL) 
{
    menu <- post_simulation_menu_definition()
    key <- normalize_menu_choice(choice, menu)
    if (is.na(key)) {
        cat("Invalid option. Please choose one of the menu numbers or names.\n")
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    if (identical(key, "finish")) 
        return(invisible(list(analysis = analysis, finished = TRUE)))
    if (identical(key, "capture_table")) {
        cat("\nCapture-recapture table. Rows are individuals; columns are sampling occasions; 1 means detected and 0 means not detected.\n")
        print_console_table(safe_capture_recapture_table_from_analysis(analysis), 
            title = "Capture-recapture table", max_rows = 20, 
            export_prefix = "capture_recapture_table")
    }
    else if (identical(key, "capture_summary")) {
        cat("\nCapture data summary. This describes dates, individuals, occasions, and capture-record counts before model fitting.\n")
        print_capture_data_summary(analysis_capture_data_summary(analysis))
    }
    else if (identical(key, "discovery_summary")) {
        cat("\nDiscovery summary. This describes how many new individuals appear through time and how the cumulative discovery curve grows.\n")
        analysis <- safe_print_discovery_summary_from_analysis(analysis)
    }
    else if (identical(key, "individual_residency")) {
        result <- print_literature_residency_classification(analysis)
        analysis <- result$analysis
    }
    else if (identical(key, "model_residency")) {
        tab <- safe_residency_result_table(analysis)
        if (is.null(tab)) {
            status <- print_model_based_residency_status(analysis)
            analysis <- status$analysis
        }
        else {
            print_console_table(tab, title = "Model-based residency-state results", 
                export_prefix = "model_based_residency_results")
        }
    }
    else if (identical(key, "residency_summary")) {
        result <- print_literature_classifier_summary(analysis)
        analysis <- result$analysis
    }
    else if (identical(key, "literature_comparison")) {
        analysis <- ensure_literature_residency_outputs(analysis)
        tab <- safe_literature_comparison_table(analysis)
        if (is.null(tab)) {
            status <- print_model_based_residency_status(analysis)
            analysis <- status$analysis
            resident_print_unavailable("Model-vs-literature comparison", 
                "A comparison requires both literature-based classifications and a fitted model-based individual residency-state table. The model-based table is not available in this analysis object.", 
                "Use Option 5 and Option 6 for literature-based classifications now. Use Option 22 and Option 23 for abundance-model outputs. A true comparison requires a supported residency-state model backend that stores individual state probabilities or classes.")
        }
        else {
            print_console_table(tab, title = "Model-vs-literature comparison", 
                export_prefix = "model_literature_comparison")
        }
    }
    else if (identical(key, "category_proportions")) {
        analysis <- ensure_literature_residency_outputs(analysis)
        tab <- safe_category_proportion_table(analysis)
        if (is.null(tab)) 
            resident_print_unavailable("Literature-classification category proportions", 
                "No category proportions could be computed from the current classification table.", 
                "Use option 5 first and review the individual literature-based classifications.")
        else print_console_table(tab, title = "Literature-classification category proportions", 
            export_prefix = "literature_classification_category_proportions")
    }
    else if (identical(key, "detection_review")) {
        analysis <- safe_detection_review_from_analysis(analysis)
    }
    else if (identical(key, "configuration_report")) {
        path <- ensure_configuration_report(analysis)
        analysis$configuration_report_path <- path
        cat("Full configuration report path:\n", path, "\n", 
            sep = "")
    }
    else if (identical(key, "plot_discovery")) {
        analysis <- safe_plot_discovery_from_analysis(analysis)
    }
    else if (identical(key, "plot_category")) {
        analysis <- safe_plot_category_from_analysis(analysis)
    }
    else if (identical(key, "plot_chao_discovery")) {
        analysis <- safe_plot_chao_discovery_from_analysis(analysis)
    }
    else if (identical(key, "plot_chao_completeness")) {
        analysis <- safe_plot_chao_completeness_from_analysis(analysis)
    }
    else if (identical(key, "export_capture_table")) {
        path <- .resident_prompt("Enter CSV path, or press Enter for Outputs/capture_recapture_table.csv: ", 
            input_provider)
        cat("Saved:", safe_export_capture_recapture_table(analysis, 
            path), "\n")
    }
    else if (identical(key, "export_capture_summary")) {
        path <- .resident_prompt("Enter CSV path, or press Enter for Outputs/capture_data_summary.csv: ", 
            input_provider)
        cat("Saved:", safe_export_capture_data_summary(analysis, 
            path), "\n")
    }
    else if (identical(key, "export_discovery")) {
        path <- .resident_prompt("Enter CSV path, or press Enter for Outputs/discovery_summary.csv: ", 
            input_provider)
        cat("Saved:", safe_export_discovery_summary(analysis, 
            path), "\n")
    }
    else if (identical(key, "export_residency")) {
        analysis <- ensure_literature_residency_outputs(analysis)
        path <- file.path("Outputs", "residency_classification_results.csv")
        saved <- safe_export_table_or_message(safe_individual_residency_table(analysis), 
            path, "Export residency classification results")
        if (!is.na(saved)) 
            cat("Saved:", saved, "\n")
    }
    else if (identical(key, "export_literature")) {
        analysis <- ensure_literature_residency_outputs(analysis)
        path <- file.path("Outputs", "model_literature_comparison.csv")
        saved <- safe_export_table_or_message(safe_literature_comparison_table(analysis), 
            path, "Export literature-comparison table")
        if (!is.na(saved)) 
            cat("Saved:", saved, "\n")
    }
    else if (identical(key, "export_chao")) {
        analysis <- safe_export_chao_from_analysis(analysis)
    }
    else if (identical(key, "abundance_recommendation")) {
        analysis <- safe_show_abundance_model_recommendation(analysis)
    }
    else if (identical(key, "select_fit_abundance")) {
        analysis <- safe_select_and_fit_abundance_model(analysis, 
            input_provider)
    }
    else if (identical(key, "abundance_estimates")) {
        fit <- safe_abundance_fit_from_analysis(analysis)
        if (is.null(fit)) 
            cat("No fitted abundance model is stored yet. Use option 22 to fit one first.\n")
        else show_abundance_estimates(fit)
    }
    else if (identical(key, "mark_parameter")) {
        fit <- safe_abundance_fit_from_analysis(analysis)
        if (is.null(fit)) 
            cat("No fitted abundance model is stored yet. Use option 22 to fit one first.\n")
        else print_mark_style_parameter_table(fit)
    }
    else if (identical(key, "mark_derived")) {
        safe_mark_derived_from_fit(safe_abundance_fit_from_analysis(analysis))
    }
    else if (identical(key, "plot_abundance")) {
        fit <- safe_abundance_fit_from_analysis(analysis)
        if (is.null(fit)) 
            cat("No fitted abundance model is stored yet. Use option 22 to fit one first.\n")
        else plot_abundance_estimates(fit)
    }
    else if (identical(key, "plot_true_estimated")) {
        fit <- safe_abundance_fit_from_analysis(analysis)
        if (is.null(fit)) 
            cat("No fitted abundance model is stored yet. Use option 22 to fit one first.\n")
        else if (!is.null(analysis$truth)) 
            plot_true_vs_estimated_abundance(analysis, fit)
        else cat("True abundance is available only for simulated datasets with stored truth.\n")
    }
    else if (identical(key, "export_abundance")) {
        fit <- safe_abundance_fit_from_analysis(analysis)
        if (is.null(fit)) 
            cat("No fitted abundance model is stored yet. Use option 22 to fit one first.\n")
        else {
            paths <- export_abundance_outputs(fit)
            cat("Saved abundance outputs:\n")
            print(paths)
        }
    }
    else {
        cat("This menu option is not recognized by the v0.9.14 direct handler. No older recursive handler was called.\n")
    }
    assign("analysis", analysis, envir = .GlobalEnv)
    invisible(list(analysis = analysis, finished = FALSE))
}
