.standard_parameter_row <-
function (model_name, parameter, parameter_type, index, link_function, 
    beta_estimate = NA_real_, beta_SE = NA_real_, real_estimate = NA_real_, 
    real_SE = NA_real_, fixed_or_estimated = "estimated", identifiable_status = "check diagnostics", 
    uncertainty_method = "auto", uncertainty_status = "unavailable", 
    biological_meaning = "Model parameter.", result_interpretation = "Interpret with model assumptions and uncertainty diagnostics.") 
{
    beta_ci <- hessian_delta_ci(beta_estimate, beta_SE, link = "identity")
    real_ci <- hessian_delta_ci(real_estimate, real_SE, link = "identity")
    status <- if (isTRUE(fixed_or_estimated == "fixed")) 
        "not_applicable"
    else uncertainty_status
    data.frame(model_name = model_name, parameter = parameter, 
        parameter_type = parameter_type, index = as.character(index), 
        link_function = link_function, beta_estimate = beta_estimate, 
        beta_SE = beta_SE, beta_lower_95 = beta_ci$lower, beta_upper_95 = beta_ci$upper, 
        real_estimate = real_estimate, real_SE = real_SE, real_lower_95 = real_ci$lower, 
        real_upper_95 = real_ci$upper, fixed_or_estimated = fixed_or_estimated, 
        boundary_flag = isTRUE(.boundary_flag(real_estimate)), 
        identifiable_status = identifiable_status, uncertainty_method = uncertainty_method, 
        uncertainty_status = status, uncertainty_warning = .row_warning(status, 
            fixed_or_estimated == "fixed"), biological_meaning = biological_meaning, 
        result_interpretation = result_interpretation, stringsAsFactors = FALSE)
}
