function (model_name, parameter, parameter_type, index = NA_character_, 
    link_function = "real", beta_estimate = NA_real_, beta_SE = NA_real_, 
    real_estimate = NA_real_, real_SE = NA_real_, fixed_or_estimated = "estimated", 
    identifiable_status = "not_assessed", uncertainty_method = "not_available", 
    uncertainty_status = "unavailable", uncertainty_warning = "", 
    biological_meaning = "", result_interpretation = "") 
{
    data.frame(model_name = model_name, parameter = parameter, 
        parameter_type = parameter_type, index = as.character(index), 
        link_function = link_function, beta_estimate = beta_estimate, 
        beta_SE = beta_SE, beta_lower_95 = ifelse(is.finite(beta_SE), 
            beta_estimate - 1.96 * beta_SE, NA_real_), beta_upper_95 = ifelse(is.finite(beta_SE), 
            beta_estimate + 1.96 * beta_SE, NA_real_), real_estimate = real_estimate, 
        real_SE = real_SE, real_lower_95 = ifelse(is.finite(real_SE), 
            real_estimate - 1.96 * real_SE, NA_real_), real_upper_95 = ifelse(is.finite(real_SE), 
            real_estimate + 1.96 * real_SE, NA_real_), fixed_or_estimated = fixed_or_estimated, 
        identifiable_status = identifiable_status, uncertainty_method = uncertainty_method, 
        uncertainty_status = uncertainty_status, uncertainty_warning = uncertainty_warning, 
        biological_meaning = biological_meaning, result_interpretation = result_interpretation, 
        stringsAsFactors = FALSE)
}
.summarize_estimates <-
function (vals, estimator, estimate_type, result_interpretation, 
    uncertainty_method = "descriptive_variation_across_periods") 
{
    vals <- suppressWarnings(as.numeric(vals))
    vals <- vals[is.finite(vals)]
    if (!length(vals)) 
        return(NULL)
    data.frame(estimator = estimator, estimate_type = estimate_type, 
        mean = mean(vals), SD = if (length(vals) > 1L) 
            stats::sd(vals)
        else NA_real_, median = stats::median(vals), lower_95 = if (length(vals) > 
            1L) 
            stats::quantile(vals, 0.025000000000000001, names = FALSE)
        else NA_real_, upper_95 = if (length(vals) > 1L) 
            stats::quantile(vals, 0.97499999999999998, names = FALSE)
        else NA_real_, number_of_periods_or_occasions = length(vals), 
        uncertainty_method = uncertainty_method, result_interpretation = result_interpretation, 
        stringsAsFactors = FALSE)
}
