.validate_program_mark_preflight <-
function (path) 
{
    problems <- character()
    corrections <- character()
    warnings <- character()
    lines <- tryCatch(readLines(path, warn = FALSE), error = function(e) e)
    if (inherits(lines, "error")) {
        return(list(ok = FALSE, problems = .import_problem_table("The file could not be read as text.", 
            conditionMessage(lines)), warnings = warnings, date_status = "unknown", 
            n_rows = NA_integer_, n_occasions = NA_integer_))
    }
    date_line <- lines[grepl("^\\s*#?\\s*dates\\s*:", lines, 
        ignore.case = TRUE)][1]
    dat <- tryCatch(.safe_read_delimited_preview(path, "PROGRAM_MARK"), 
        error = function(e) e)
    if (inherits(dat, "error")) {
        return(list(ok = FALSE, problems = .import_problem_table("The file is not readable as a Program MARK-style whitespace-delimited table.", 
            "Use columns named id and encounter_history separated by spaces or tabs."), 
            warnings = warnings, date_status = "unknown", n_rows = NA_integer_, 
            n_occasions = NA_integer_))
    }
    names(dat) <- tolower(names(dat))
    if (!"id" %in% names(dat)) {
        problems <- c(problems, "Missing required column: id.")
        corrections <- c(corrections, "Add an id column with one unique individual identifier per row.")
    }
    if (!"encounter_history" %in% names(dat)) {
        problems <- c(problems, "Missing required column: encounter_history.")
        corrections <- c(corrections, "Add encounter_history strings such as 100100 using only 0 and 1.")
    }
    widths <- integer(0)
    if (all(c("id", "encounter_history") %in% names(dat))) {
        if (any(is.na(dat$id) | !nzchar(trimws(dat$id)))) {
            problems <- c(problems, "Some individual ids are blank.")
            corrections <- c(corrections, "Fill every id value before importing.")
        }
        if (any(duplicated(dat$id))) {
            problems <- c(problems, "Duplicate individual ids were found.")
            corrections <- c(corrections, "Program MARK-style history must have one row per individual. Merge or rename duplicate ids.")
        }
        raw_hist <- trimws(as.character(dat$encounter_history))
        if (any(!grepl("^[01]+$", raw_hist))) {
            problems <- c(problems, "Some encounter_history values contain characters other than 0 or 1.")
            corrections <- c(corrections, "Remove spaces, punctuation, missing values, or letters from encounter_history.")
        }
        widths <- nchar(raw_hist)
        if (length(unique(widths)) > 1L) {
            problems <- c(problems, "Encounter histories have different lengths.")
            corrections <- c(corrections, "Make every encounter_history string the same length, one digit per sampling occasion.")
        }
    }
    date_status <- "no_dates_in_file"
    if (length(date_line) && !is.na(date_line)) {
        raw_dates <- sub("^\\s*#?\\s*dates\\s*:\\s*", "", date_line, 
            ignore.case = TRUE)
        raw_dates <- trimws(unlist(strsplit(raw_dates, "[,[:space:]]+")))
        raw_dates <- raw_dates[nzchar(raw_dates)]
        parsed <- suppressWarnings(as.Date(raw_dates))
        if (!length(raw_dates) || any(is.na(parsed))) {
            problems <- c(problems, "The optional dates line contains invalid dates.")
            corrections <- c(corrections, "Use one valid date per occasion, preferably YYYY-MM-DD.")
        }
        else if (length(widths) && length(parsed) != widths[1]) {
            problems <- c(problems, "The number of dates does not match the encounter-history length.")
            corrections <- c(corrections, "Provide exactly one date for each digit in encounter_history.")
        }
        else date_status <- "dates_supplied_need_confirmation"
    }
    list(ok = !length(problems), problems = .import_problem_table(problems, 
        corrections), warnings = warnings, date_status = date_status, 
        n_rows = nrow(dat), n_occasions = if (length(widths)) widths[1] else NA_integer_)
}
.validate_socprog_preflight <-
function (path) 
{
    problems <- character()
    corrections <- character()
    warnings <- character()
    dat <- tryCatch(.safe_read_delimited_preview(path, "SOCPROG"), 
        error = function(e) e)
    if (inherits(dat, "error")) {
        return(list(ok = FALSE, problems = .import_problem_table("The file is not readable as a CSV table.", 
            "Save the file as CSV with columns id and date."), 
            warnings = warnings, date_status = "unknown", n_rows = NA_integer_, 
            n_occasions = NA_integer_))
    }
    names(dat) <- tolower(names(dat))
    if (!"id" %in% names(dat)) {
        problems <- c(problems, "Missing required column: id.")
        corrections <- c(corrections, "Add an id column with one individual identifier per sighting row.")
    }
    if (!"date" %in% names(dat)) {
        problems <- c(problems, "Missing required column: date.")
        corrections <- c(corrections, "Add a date column using real survey dates, preferably YYYY-MM-DD.")
    }
    if ("id" %in% names(dat) && any(is.na(dat$id) | !nzchar(trimws(dat$id)))) {
        problems <- c(problems, "Some individual ids are blank.")
        corrections <- c(corrections, "Fill every id value before importing.")
    }
    n_occ <- NA_integer_
    date_status <- "missing_dates"
    if ("date" %in% names(dat)) {
        parsed <- suppressWarnings(as.Date(dat$date))
        if (any(is.na(parsed))) {
            problems <- c(problems, "Some date values could not be read by R.")
            corrections <- c(corrections, "Use a standard date format such as YYYY-MM-DD.")
        }
        else {
            n_occ <- length(unique(parsed))
            date_status <- "dates_supplied_need_confirmation"
        }
        if (all(c("id", "date") %in% names(dat)) && !any(is.na(parsed))) {
            dup <- duplicated(paste(dat$id, parsed))
            if (any(dup)) 
                warnings <- c(warnings, paste(sum(dup), "duplicate id-date records found; Resident will aggregate them to detected = 1 for that occasion."))
        }
    }
    list(ok = !length(problems), problems = .import_problem_table(problems, 
        corrections), warnings = warnings, date_status = date_status, 
        n_rows = nrow(dat), n_occasions = n_occ)
}
