abundance_assumption_diagnostics <-
function (data, occasions = NULL) 
{
    y <- extract_history(data, stage = "abundance assumption diagnostics")
    occ <- occasions %||% extract_occasions(data, stage = "abundance assumption diagnostics")
    freq <- rowSums(y)
    general <- data.frame(assumption = c("number_of_individuals", 
        "number_of_occasions", "total_detections", "singletons", 
        "doubletons", "survey_span_days", "median_gap_days"), 
        diagnostic_value = c(nrow(y), ncol(y), sum(y), sum(freq == 
            1), sum(freq == 2), .survey_span_days(occ), if (length(.occasion_gaps(occ))) stats::median(.occasion_gaps(occ)) else NA_real_), 
        status = "not_applicable", consequence = "Summary diagnostic used for model recommendation.", 
        recommendation = "Review with model-specific diagnostics.", 
        stringsAsFactors = FALSE)
    rbind(general, closure_assumption_check(y, occ), robust_design_structure_check(y, 
        occ), open_population_signal_check(y, occ), detection_heterogeneity_check(y, 
        occ), behavioral_response_check(y, occ), time_variation_check(y, 
        occ), data_sufficiency_for_abundance(y, occ))
}
abundance_bootstrap <-
function (fit, R = 20L, seed = 1L) 
{
    set.seed(seed)
    y <- fit$history
    vals <- replicate(R, {
        idx <- sample(seq_len(nrow(y)), nrow(y), replace = TRUE)
        boot_y <- y[idx, , drop = FALSE]
        tryCatch(fit_abundance_model(boot_y, fit$abundance_model, 
            maxit = 300)$N_hat, error = function(e) NA_real_)
    })
    data.frame(model_name = fit$model_name, R = R, mean = mean(vals, 
        na.rm = TRUE), SE = sd(vals, na.rm = TRUE), lower_95 = as.numeric(quantile(vals, 
        0.025000000000000001, na.rm = TRUE)), upper_95 = as.numeric(quantile(vals, 
        0.97499999999999998, na.rm = TRUE)), uncertainty_method = "individual bootstrap", 
        stringsAsFactors = FALSE)
}
abundance_confint <-
function (fit, method = c("auto", "hessian", "bootstrap", "profile"), 
    R = 20L) 
{
    method <- match.arg(method)
    if (method == "auto") 
        method <- if (is.finite(fit$N_SE)) 
            "hessian"
        else "bootstrap"
    if (method == "hessian") {
        data.frame(estimate = fit$N_hat, lower_95 = fit$lower_95, 
            upper_95 = fit$upper_95, method_used = "Hessian delta method", 
            stringsAsFactors = FALSE)
    }
    else if (method == "bootstrap") {
        b <- abundance_bootstrap(fit, R = R)
        data.frame(estimate = fit$N_hat, lower_95 = b$lower_95, 
            upper_95 = b$upper_95, method_used = "bootstrap", 
            stringsAsFactors = FALSE)
    }
    else {
        p <- abundance_profile_likelihood(fit)
        good <- p$N_fixed[p$likelihood_ratio <= 3.841459]
        data.frame(estimate = fit$N_hat, lower_95 = min(good, 
            na.rm = TRUE), upper_95 = max(good, na.rm = TRUE), 
            method_used = "profile likelihood", stringsAsFactors = FALSE)
    }
}
abundance_data_diagnostics <-
function (analysis) 
{
    tab <- tryCatch(safe_capture_recapture_table_from_analysis(analysis), 
        error = function(e) NULL)
    if (is.null(tab)) {
        return(list(ok = FALSE, reason = "No capture-history table was available for model-suitability diagnostics."))
    }
    mat <- as.matrix(tab[, setdiff(names(tab), "individual_id"), 
        drop = FALSE])
    suppressWarnings(storage.mode(mat) <- "numeric")
    mat[is.na(mat)] <- 0
    n_ids <- nrow(mat)
    n_occ <- ncol(mat)
    detections_by_individual <- rowSums(mat, na.rm = TRUE)
    detections_by_occasion <- colSums(mat, na.rm = TRUE)
    total_detections <- sum(mat, na.rm = TRUE)
    recaptured_individuals <- sum(detections_by_individual >= 
        2)
    singletons <- sum(detections_by_individual == 1)
    never_detected <- sum(detections_by_individual == 0)
    detection_rate <- if (n_ids * n_occ > 0) 
        total_detections/(n_ids * n_occ)
    else NA_real_
    recapture_fraction <- if (n_ids > 0) 
        recaptured_individuals/n_ids
    else NA_real_
    singleton_fraction <- if (n_ids > 0) 
        singletons/n_ids
    else NA_real_
    occasion_mean <- mean(detections_by_occasion)
    occasion_cv <- if (is.finite(occasion_mean) && occasion_mean > 
        0) 
        stats::sd(detections_by_occasion)/occasion_mean
    else NA_real_
    occasions_with_no_detections <- sum(detections_by_occasion == 
        0)
    first_occ <- apply(mat == 1, 1, function(z) if (any(z)) 
        min(which(z))
    else NA_integer_)
    last_occ <- apply(mat == 1, 1, function(z) if (any(z)) 
        max(which(z))
    else NA_integer_)
    open_signal <- sum(!is.na(first_occ) & first_occ > 1L) + 
        sum(!is.na(last_occ) & last_occ < n_occ)
    temporal_span_supported <- n_occ >= 6L
    robust_design_supported <- !is.null(analysis$temporal_structure) && 
        !is.null(analysis$temporal_structure$primary_period) && 
        length(unique(analysis$temporal_structure$primary_period)) >= 
            2L && any(table(analysis$temporal_structure$primary_period) >= 
        2L)
    list(ok = TRUE, n_ids = n_ids, n_occ = n_occ, total_detections = total_detections, 
        detection_rate = detection_rate, recaptured_individuals = recaptured_individuals, 
        recapture_fraction = recapture_fraction, singletons = singletons, 
        singleton_fraction = singleton_fraction, never_detected = never_detected, 
        occasion_cv = occasion_cv, occasions_with_no_detections = occasions_with_no_detections, 
        open_signal = open_signal, temporal_span_supported = temporal_span_supported, 
        robust_design_supported = robust_design_supported)
}
