abundance_estimator_comparison_table <-
function (analysis, fit = NULL, confirm_model_fits = FALSE) 
{
    y <- extract_history(analysis, stage = "estimator comparison")
    rows <- list(data.frame(estimator = "observed_detected_individuals", 
        estimate_type = "observed_count_minimum", mean = nrow(.observed_history(y)), 
        SD = NA_real_, median = nrow(.observed_history(y)), lower_95 = NA_real_, 
        upper_95 = NA_real_, number_of_periods_or_occasions = 1L, 
        uncertainty_method = "count", result_interpretation = "Observed count is the minimum detected, not true abundance.", 
        stringsAsFactors = FALSE))
    ch <- tryCatch(chao_discovery_estimates(y), error = function(e) NULL)
    if (is.data.frame(ch)) 
        for (i in seq_len(nrow(ch))) rows[[length(rows) + 1L]] <- data.frame(estimator = ch$estimator[i], 
            estimate_type = "descriptive_richness_or_completeness_estimator", 
            mean = ch$estimate[i], SD = NA_real_, median = ch$estimate[i], 
            lower_95 = NA_real_, upper_95 = NA_real_, number_of_periods_or_occasions = 1L, 
            uncertainty_method = "Chao_descriptive_estimator", 
            result_interpretation = "Chao estimates are descriptive richness/completeness estimators, not true abundance.", 
            stringsAsFactors = FALSE)
    fits <- list(fit, analysis$abundance_fit, analysis$state_space_fit, 
        analysis$survival_detection_fit)
    fits <- fits[!vapply(fits, is.null, logical(1))]
    for (ff in fits) {
        if (inherits(ff, "resident_cjs_fit")) 
            next
        model <- ff$model_name %||% ff$abundance_model %||% "fitted_model"
        if (inherits(ff, "resident_robust_design_abundance_fit") && 
            !is.null(ff$primary_abundance)) 
            rows[[length(rows) + 1L]] <- .summarize_estimates(ff$primary_abundance$N_hat, 
                model, "model_based_primary_period_estimates", 
                "Robust-design estimates vary by primary period; interval shown is descriptive variation unless model intervals are stored.")
        else if (inherits(ff, "resident_open_population_fit") && 
            !is.null(ff$N_by_occasion)) {
            rows[[length(rows) + 1L]] <- .summarize_estimates(ff$N_by_occasion, 
                model, "model_based_occasion_estimates", "Open-population estimates vary by occasion; interval shown is descriptive variation unless model intervals are stored.")
            if (!is.null(ff$N_super_hat)) 
                rows[[length(rows) + 1L]] <- .summarize_estimates(ff$N_super_hat, 
                  paste0(model, "_N_super"), "model_based_superpopulation_estimate", 
                  "POPAN-like superpopulation estimate across the full study period.", 
                  "not_available")
        }
    }
    do.call(rbind, rows[!vapply(rows, is.null, logical(1))])
}
