abundance_model_recommendation_table <-
function (data, occasions = NULL) 
{
    old <- tryCatch(.old_abundance_model_recommendation_table_v089(data, 
        occasions), error = function(e) data.frame())
    reg <- model_registry()
    if (!nrow(old)) {
        old <- reg[, c("model_family", "candidate_model"), drop = FALSE]
        old$suitability <- ifelse(reg$implemented, "acceptable_with_caution", 
            "not_implemented")
        old$reason <- "registry default"
        old$assumptions_status <- "diagnostics unavailable"
        old$data_support <- "review"
        old$expected_risk <- "elevated"
        old$recommendation <- "Review data diagnostics before fitting."
    }
    missing_models <- setdiff(reg$candidate_model, old$candidate_model)
    if (length(missing_models)) {
        add <- reg[match(missing_models, reg$candidate_model), 
            c("model_family", "candidate_model"), drop = FALSE]
        add$suitability <- ifelse(reg$implemented[match(missing_models, 
            reg$candidate_model)], "acceptable_with_caution", 
            "not_implemented")
        add$reason <- "registered model"
        add$assumptions_status <- "requires targeted diagnostics"
        add$data_support <- "review"
        add$expected_risk <- ifelse(add$suitability == "not_implemented", 
            "not available", "elevated")
        add$recommendation <- "Registered for routing; check assumptions before interpreting output."
        old <- rbind(old, add)
    }
    old <- merge(old, reg[, c("candidate_model", "model_role", 
        "implemented", "selectable_from_abundance_menu", "warning_if_selected")], 
        by = "candidate_model", all.x = TRUE, sort = FALSE)
    old$model_family <- ifelse(is.na(old$model_family), reg$model_family[match(old$candidate_model, 
        reg$candidate_model)], old$model_family)
    idx <- old$candidate_model %in% c("jolly_seber", "POPAN_like")
    old$implemented[idx] <- TRUE
    old$selectable_from_abundance_menu[idx] <- TRUE
    old$suitability[idx & old$suitability == "not_implemented"] <- "acceptable_with_caution"
    old$expected_risk[idx & old$expected_risk == "not available"] <- "elevated"
    old$recommendation[idx] <- paste(old$recommendation[idx], 
        "Open-population support is available in v0.8.9; Program MARK equivalence is not yet certified.")
    old$suitability[!old$implemented] <- "not_implemented"
    old$selectable <- old$implemented & old$selectable_from_abundance_menu
    old$row <- seq_len(nrow(old))
    old[, c("row", "model_family", "candidate_model", "model_role", 
        "suitability", "selectable", "reason", "assumptions_status", 
        "data_support", "expected_risk", "recommendation", "warning_if_selected")]
}
