abundance_profile_likelihood <-
function (fit, values = NULL) 
{
    if (!inherits(fit, "resident_closed_abundance_fit")) {
        return(data.frame(N_fixed = NA_real_, logLik = NA_real_, 
            likelihood_ratio = NA_real_, result_interpretation = "Profile likelihood is implemented for direct closed-capture N fits."))
    }
    y <- fit$history
    n <- fit$n_observed
    if (is.null(values)) 
        values <- unique(round(seq(max(n + 0.10000000000000001, 
            fit$N_hat * 0.75), fit$N_hat * 1.3500000000000001, 
            length.out = 7)))
    vals <- values[values > n]
    rows <- lapply(vals, function(Nv) {
        start <- fit$par[names(fit$par) != "log_f0"]
        opt <- .fit_optim(start, function(z) {
            par <- c(log_f0 = log(Nv - n), z)
            closed_capture_loglik(par, y, fit$abundance_model)
        })
        data.frame(N_fixed = Nv, logLik = -opt$value)
    })
    tab <- do.call(rbind, rows)
    tab$likelihood_ratio <- 2 * (max(tab$logLik, na.rm = TRUE) - 
        tab$logLik)
    tab$result_interpretation <- "Each row fixes N, refits detection parameters, and compares support with the best row."
    tab
}
abundance_ready_check <-
function (data, abundance_model = "closed_M0") 
{
    ed <- if (is_resident_encounter_data(data)) 
        data
    else {
        prep <- prepare_abundance_data(data)
        prep$encounter_data
    }
    y <- ed$history
    detected <- rowSums(y)
    warnings <- character()
    if (sum(y) < 10) 
        warnings <- c(warnings, "Few detections; prefer observed/Chao summaries or simpler models.")
    if (sum(detected == 1) > max(3, 0.5 * sum(detected > 0))) 
        warnings <- c(warnings, "Many singletons; abundance may depend strongly on model assumptions.")
    if (ncol(y) < 2) 
        warnings <- c(warnings, "At least two occasions are recommended for closed-capture abundance.")
    data.frame(number_of_individuals = nrow(y), number_of_occasions = ncol(y), 
        number_of_detections = sum(y), number_of_singletons = sum(detected == 
            1), all_zero_histories = sum(detected == 0), duplicate_ids_or_dates = anyDuplicated(ed$ids) > 
            0 || anyDuplicated(ed$dates[!is.na(ed$dates)]) > 
            0, closure_assumption_note = if (grepl("^closed|^huggins", 
            abundance_model)) 
            "Check closure for the modeled session."
        else "Check within-primary closure.", warning = paste(warnings, 
            collapse = " "), ready = !length(warnings), stringsAsFactors = FALSE)
}
abundance_simulation_validation_table <-
function (results) 
{
    if (inherits(results, "resident_abundance_fit")) 
        stop("Pass simulation comparison rows, not a single fit.", 
            call. = FALSE)
    x <- as.data.frame(results)
    data.frame(mean_bias = mean(x$bias, na.rm = TRUE), relative_bias = mean(x$relative_bias, 
        na.rm = TRUE), RMSE = sqrt(mean(x$bias^2, na.rm = TRUE)), 
        coverage = if (all(c("lower_95", "upper_95", "true_N") %in% 
            names(x))) {
            mean(x$lower_95 <= x$true_N & x$upper_95 >= x$true_N, 
                na.rm = TRUE)
        }
        else NA_real_, convergence_rate = mean(x$convergence_status == 
            0, na.rm = TRUE))
}
abundance_summary_from_fit <-
function (fit) 
{
    if (inherits(fit, "resident_robust_design_abundance_fit") && 
        !is.null(fit$primary_abundance)) {
        pa <- fit$primary_abundance
        se <- sqrt(sum(pa$SE^2, na.rm = TRUE))/max(1, nrow(pa))
        est <- mean(pa$N_hat, na.rm = TRUE)
        data.frame(model_name = fit$model_name, abundance_model = fit$abundance_model, 
            abundance_target = "mean_primary_period_N_hat", N_hat_summary = est, 
            N_SE_summary = se, lower_95 = est - 1.96 * se, upper_95 = est + 
                1.96 * se, n_primary_periods = nrow(pa), n_observed_total = sum(pa$n_detected, 
                na.rm = TRUE), uncertainty_method = "delta_aggregation_from_primary_period_SE", 
            uncertainty_status = if (is.finite(se)) 
                "computed"
            else "unavailable", result_interpretation = "Robust-design abundance summarized from primary-period closed submodels with available uncertainty.", 
            stringsAsFactors = FALSE)
    }
    else {
        print_abundance_summary(fit, print = FALSE)
    }
}
