as_resident_encounter_data <-
function (history, occasions = NULL, raw = NULL, source = NULL, 
    allow_synthetic_dates = FALSE, date_origin = "2000-01-01", 
    date_spacing = "day", ...) 
{
    y <- coerce_history_matrix(history, stage = "encounter data")
    if (is.null(occasions)) {
        dates <- resident_require_dates(NULL, allow_synthetic_dates, 
            ncol(y), date_origin, date_spacing)
        occasions <- data.frame(occasion = seq_len(ncol(y)), 
            date = dates, stringsAsFactors = FALSE)
        attr(occasions, "synthetic_dates_used") <- TRUE
        attr(occasions, "synthetic_date_warning") <- "Synthetic dates were created for testing/template validation and should not be used for scientific inference."
        attr(occasions, "date_origin") <- date_origin
        attr(occasions, "date_spacing") <- date_spacing
    }
    out <- .resident_v090_as_resident_encounter_data(y, occasions = occasions, 
        raw = raw, source = source, ...)
    attr(out, "synthetic_dates_used") <- isTRUE(attr(occasions, 
        "synthetic_dates_used"))
    attr(out, "synthetic_date_warning") <- attr(occasions, "synthetic_date_warning")
    out
}
ask_abundance_model_choice <-
function (input_provider = NULL) 
{
    menu <- print_abundance_model_menu()
    raw <- .resident_prompt("Choose abundance option number or name: ", 
        input_provider)
    family <- normalize_menu_choice(raw, menu)
    if (is.na(family) || family == "back") 
        return(list(model_family = "back", candidate_model = NA_character_))
    models <- specific_abundance_models(family)
    if (length(models) <= 1L) 
        return(list(model_family = family, candidate_model = models[1] %||% 
            family))
    model_menu <- menu_definition("specific_abundance_model", 
        paste("Models for", family), labels = c(models, "Back"), 
        keys = c(models, "back"), exit_label = "Back")
    print_menu(model_menu)
    selected <- normalize_menu_choice(.resident_prompt("Choose model number or name: ", 
        input_provider), model_menu)
    if (is.na(selected) || selected == "back") 
        return(list(model_family = "back", candidate_model = NA_character_))
    if (!(selected %in% implemented_abundance_models())) {
        cat("This model family is not yet fully implemented. Available alternatives are:", 
            paste(intersect(models, implemented_abundance_models()), 
                collapse = ", "), "\n")
    }
    list(model_family = family, candidate_model = selected)
}
