ask_jolly_seber_parameters <-
function (config, interactive = TRUE) 
{
    config$p <- .read_parameter("p", config$p, "detection probability for available individuals", 
        "probability from 0 to 1", interactive, function(x) .as_probability(x, 
            "p"))
    config$phi <- .read_parameter("phi", config$phi, "apparent survival or persistence through time", 
        "probability from 0 to 1", interactive, function(x) .as_probability(x, 
            "phi"))
    if (interactive) {
        cat("\nEntry probability mode options:\n")
        cat("1. default: uses make_entry_probabilities().\n")
        cat("2. uniform: equal entry probability across occasions.\n")
        cat("3. early_entry: more individuals enter near the beginning.\n")
        cat("4. late_entry: more individuals enter later.\n")
        cat("5. custom: user supplies vector b.\n")
    }
    opts <- c("default", "uniform", "early_entry", "late_entry", 
        "custom")
    ans <- if (interactive) 
        readline("Enter entry_probability_mode, or press Enter for default: ")
    else ""
    if (nzchar(trimws(ans))) 
        config$entry_probability_mode <- tolower(trimws(ans))
    if (!(config$entry_probability_mode %in% opts)) 
        stop("entry_probability_mode must be one of: ", paste(opts, 
            collapse = ", "))
    if (config$entry_probability_mode == "custom" && interactive) {
        txt <- readline("Enter comma-separated custom b probabilities: ")
        config$b <- as.numeric(trimws(strsplit(txt, ",")[[1]]))
    }
    config$drop_never_detected <- .read_parameter("drop_never_detected", 
        config$drop_never_detected, "whether never-detected individuals are removed from the returned encounter histories", 
        "TRUE or FALSE", interactive, function(x) as.logical(toupper(x)))
    config
}
ask_latent_residency_parameters <-
function (config, interactive = TRUE) 
{
    if (identical(config$states, simulation_parameter_defaults()$states)) {
        config$states <- c("unavailable", "visitor", "seasonal_resident", 
            "resident")
        config$unavailable_states <- "unavailable"
        config$state_detection <- c(unavailable = 0, visitor = 0.14999999999999999, 
            seasonal_resident = 0.34999999999999998, resident = 0.55000000000000004)
    }
    if (interactive) {
        cat("\nDefault latent residency states:\n")
        cat("unavailable: alive or in the theoretical population but not available to be detected.\n")
        cat("visitor: occasional user with low expected availability.\n")
        cat("seasonal_resident: recurring seasonal user.\n")
        cat("resident: high-use or persistent local user.\n")
        ans <- readline("Press Enter for default states, or enter comma-separated custom states: ")
        if (nzchar(trimws(ans))) 
            config$states <- trimws(strsplit(ans, ",")[[1]])
    }
    config$states <- validate_state_vector(config$states)
    if (interactive) {
        ans <- readline("Use default initial_probs? Press Enter for default or type custom: ")
        if (tolower(trimws(ans)) == "custom") {
            config$initial_probs <- as.numeric(trimws(strsplit(readline("Enter comma-separated initial probabilities: "), 
                ",")[[1]]))
        }
    }
    trans <- ask_transition_matrix_parameters(config$states, 
        transition_time_scale = config$transition_time_scale %||% 
            "month", matrix_type = config$transition_matrix_type %||% 
            "biologically_informed", interactive = interactive, 
        default_matrix = config$transition_matrix)
    config$transition_time_scale <- trans$transition_time_scale
    config$transition_matrix_source <- trans$transition_matrix_source
    config$transition_matrix_type <- trans$transition_matrix_type
    config$transition_matrix <- trans$transition_matrix
    if (interactive) {
        cat("\nEstimating transition probabilities requires enough repeated detections across primary periods. If the data are sparse, estimates may be weakly identifiable or unstable.\n")
        config$transition_estimation <- .read_option("transition_estimation", 
            config$transition_estimation %||% "fixed", interactive)
    }
    if (interactive) {
        cat("State detection probabilities must be between 0 and 1; unavailable/outside states must be 0.\n")
    }
    config$effort_beta <- .read_parameter("effort_beta", config$effort_beta, 
        "positive values increase detection with effort; negative values decrease it", 
        "numeric coefficient", interactive, as.numeric)
    config$individual_re_sd <- .read_parameter("individual_re_sd", 
        config$individual_re_sd, "larger values create stronger individual heterogeneity in detection", 
        "non-negative numeric value", interactive, as.numeric)
    config
}
