ask_primary_secondary_periods <-
function (history, occasions = NULL, input_provider = NULL, allow_automatic = TRUE) 
{
    mode <- .ask_choice("Define temporal structure", c("automatic inference with review", 
        "existing columns", "by month", "by year", "single primary period"), 
        input_provider, default = "automatic inference with review")
    if (identical(mode, "automatic inference with review")) {
        st <- infer_primary_secondary_periods(history, occasions)
        print_temporal_structure_review(st)
        ans <- .resident_prompt("Use this temporal structure? Enter 1 for yes or 0 for no: ", 
            input_provider)
        if (!isTRUE(tryCatch(resident_parse_yes_no_10(ans), error = function(e) FALSE))) 
            stop("Temporal-structure inference was not confirmed.", 
                call. = FALSE)
        validate_primary_secondary_periods(st, ncol(coerce_history_matrix(history)))
        return(st)
    }
    occ <- as.data.frame(occasions)
    dates <- if ("date" %in% names(occ)) 
        as.Date(occ$date)
    else rep(as.Date(NA), nrow(occ))
    primary <- switch(mode, `existing columns` = occ$primary_period %||% 
        occ$primary, `by month` = format(dates, "%Y-%m"), `by year` = format(dates, 
        "%Y"), `single primary period` = rep(1L, nrow(occ)))
    if (is.null(primary) || any(is.na(primary))) 
        stop("Selected temporal structure cannot be built from the supplied occasion table.", 
            call. = FALSE)
    secondary <- occ$secondary_period %||% occ$secondary %||% 
        ave(seq_len(nrow(occ)), primary, FUN = seq_along)
    interval <- .ask_choice("Time interval scale", c("equal", 
        "actual_elapsed_days", "user_defined"), input_provider, 
        default = "actual_elapsed_days")
    detect <- .ask_choice("Detection/capture probability varies by", 
        c("occasion", "primary period", "secondary period", "effort", 
            "group", "state", "covariates", "constant"), input_provider, 
        default = "occasion")
    trans <- .ask_choice("Movement/migration/transition probabilities are", 
        c("fixed", "estimated", "time-varying", "group-varying", 
            "covariate-dependent"), input_provider, default = "fixed")
    st <- list(primary_period = primary, secondary_period = secondary, 
        time_interval_scale = interval, interval_type = interval, 
        detection_structure = detect, transition_structure = trans, 
        automatic = FALSE, diagnostics = temporal_structure_diagnostics(history, 
            occasions))
    validate_primary_secondary_periods(st, ncol(coerce_history_matrix(history)))
    print_temporal_structure_review(st)
    st
}
ask_recapture_distribution_parameters <-
function (distribution, rmax, interactive = TRUE, defaults = simulation_parameter_defaults()$recapture_params, 
    input_provider = NULL) 
{
    distribution <- tolower(distribution)
    cat("\nRecapture-count distribution:\n")
    print(explain_recapture_distribution(distribution), row.names = FALSE)
    if (identical(distribution, "chisq")) 
        cat("\nChi-square advice:", chisq_recapture_advice(rmax), 
            "\n")
    if (!interactive) {
        params <- switch(distribution, uniform = list(), gaussian = list(mean = defaults$mean %||% 
            max(1, rmax/3), sd = defaults$sd %||% max(1, rmax/6)), 
            exponential = list(rate = defaults$rate %||% (3/max(1, 
                rmax))), chisq = list(df = defaults$df %||% 2, 
                scale = defaults$scale %||% 1), negative_binomial = list(mu = defaults$mu %||% 
                max(1, rmax/4), size = defaults$size %||% 1), 
            poisson = list(lambda = defaults$lambda %||% max(1, 
                rmax/4)), beta_binomial = list(shape1 = defaults$shape1 %||% 
                0.80000000000000004, shape2 = defaults$shape2 %||% 
                3))
        validate_recapture_distribution_parameters(distribution, 
            params, rmax)
        return(params)
    }
    read_pos <- function(name, meaning, default, advice = NULL) {
        .resident_prompt_parameter(name, meaning, "positive numeric value", 
            default, input_provider, parser = function(x) {
                v <- as.numeric(x)
                if (!is.finite(v) || v <= 0) 
                  stop(name, " must be positive.")
                v
            }, advice = advice)
    }
    params <- switch(distribution, uniform = {
        cat("uniform has no extra parameters; all counts between minimum and rmax are equally likely.\n")
        list()
    }, gaussian = list(mean = read_pos("gaussian mean", "central recapture count.", 
        defaults$mean %||% max(1, rmax/3), "Values near rmax make almost all animals look highly resident; values near zero create many rare detections."), 
        sd = read_pos("gaussian sd", "spread around the central recapture count.", 
            defaults$sd %||% max(1, rmax/6), "Larger values produce more extreme low and high counts; too large can create unrealistic truncation at 0 or rmax.")), 
        exponential = list(rate = read_pos("exponential rate", 
            "larger values produce more individuals with low recapture counts.", 
            defaults$rate %||% (3/max(1, rmax)), "Common exploratory values are roughly 1/rmax to 5/rmax; very high values may create too many singletons.")), 
        chisq = list(df = read_pos("chisq df", "shape of the right-skewed distribution.", 
            defaults$df %||% 2, chisq_recapture_advice(rmax)), 
            scale = read_pos("chisq scale", "expands or contracts the count range.", 
                defaults$scale %||% 1, "Higher scale shifts generated counts upward; too high can force many counts against rmax.")), 
        negative_binomial = list(mu = read_pos("negative_binomial mu", 
            "expected count.", defaults$mu %||% max(1, rmax/4), 
            "Use values well below rmax unless empirical sighting rates support high recurrent use."), 
            size = read_pos("negative_binomial size", "overdispersion control.", 
                defaults$size %||% 1, "Small values create strong heterogeneity; larger values approach a Poisson-like pattern.")), 
        poisson = list(lambda = read_pos("poisson lambda", "approximate mean and variance of counts.", 
            defaults$lambda %||% max(1, rmax/4), "Lambda near rmax makes detections unrealistically frequent in many closed-population scenarios.")), 
        beta_binomial = list(shape1 = read_pos("beta_binomial shape1", 
            "heterogeneity shape parameter.", defaults$shape1 %||% 
                0.80000000000000004), shape2 = read_pos("beta_binomial shape2", 
            "heterogeneity shape parameter.", defaults$shape2 %||% 
                3)), stop("Unsupported recapture distribution: ", 
            distribution))
    validate_recapture_distribution_parameters(distribution, 
        params, rmax)
    params
}
ask_simulation_parameters <-
function (interactive = TRUE, defaults = FALSE, input_provider = NULL) 
{
    if (!interactive && isTRUE(defaults)) 
        return(validate_simulation_parameters(simulation_parameter_defaults()))
    if (!interactive && !isTRUE(defaults)) 
        stop("Non-interactive simulation setup requires defaults = TRUE or an explicit configuration list.")
    d <- simulation_parameter_defaults()
    dict <- simulation_parameter_dictionary()
    meaning <- function(name) dict$meaning[match(name, dict$parameter)]
    valid <- function(name) {
        if (name %in% c("allow_zero", "drop_never_detected", 
            "display_discovery_plots", "export_discovery_jpg", 
            "compare_to_observed")) {
            return("1 = yes/TRUE, 0 = no/FALSE")
        }
        dict$valid_values[match(name, dict$parameter)]
    }
    cfg <- d
    cfg$simulation_model <- .resident_prompt_option("Simulation model", 
        c("closed", "jolly_seber", "latent_residency", "state_space_robust_design"), 
        c("all individuals are assumed available throughout the study", 
            "individuals may enter and persist through time", 
            "individuals move among hidden residency states with imperfect detection", 
            "robust-design model with primary/secondary periods and availability"), 
        default = d$simulation_model, input_provider = input_provider)
    cfg$N <- .resident_prompt_parameter("N", meaning("N"), valid("N"), 
        d$N, input_provider, function(x) .as_positive_integer(x, 
            "N"))
    cfg$initial_sampling_date <- .resident_prompt_parameter("initial_sampling_date", 
        meaning("initial_sampling_date"), valid("initial_sampling_date"), 
        d$initial_sampling_date, input_provider, as.Date)
    cfg$final_sampling_date <- .resident_prompt_parameter("final_sampling_date", 
        meaning("final_sampling_date"), valid("final_sampling_date"), 
        d$final_sampling_date, input_provider, as.Date)
    cfg$requested_number_of_sampling_occasions <- .resident_prompt_parameter("requested_number_of_sampling_occasions", 
        meaning("requested_number_of_sampling_occasions"), valid("requested_number_of_sampling_occasions"), 
        d$requested_number_of_sampling_occasions, input_provider, 
        function(x) .as_positive_integer(x, "requested_number_of_sampling_occasions"))
    cfg$number_of_sampling_occasions <- cfg$requested_number_of_sampling_occasions
    cat("\nOccasion unit defines the grid of possible dates before the sampling design is applied.\n")
    cat("For twice-monthly sampling across one calendar year, choose occasion_unit = day, then choose sampling_design = twice_monthly.\n")
    cfg$occasion_unit <- .resident_prompt_option("Occasion unit", 
        c("day", "week", "month"), c("calendar-day grid; use this for daily, random, empirical, consecutive-month, and twice-monthly designs", 
            "calendar-week grid; useful when possible surveys are weekly", 
            "calendar-month grid; useful when there can be only one possible survey per month"), 
        d$occasion_unit, input_provider)
    cfg$seed <- .resident_prompt_parameter("seed", meaning("seed"), 
        valid("seed"), d$seed, input_provider, function(x) .as_positive_integer(x, 
            "seed"), advice = "Use any positive whole number. Reusing the same seed repeats the same simulation.")
    cfg$sampling_design <- .resident_prompt_option("Sampling design", 
        c("daily", "weekly", "monthly", "twice_monthly", "consecutive_month", 
            "random", "empirical"), c("use all possible sampling dates", 
            "select one occasion per week", "select one occasion per month", 
            "select two occasions per month", "select a block of consecutive days per month", 
            "select a fixed number of random occasions", "use supplied empirical dates"), 
        d$sampling_design, input_provider)
    if (cfg$sampling_design == "random") {
        cfg$n_random_occasions <- .resident_prompt_parameter("n_random_occasions", 
            meaning("n_random_occasions"), valid("n_random_occasions"), 
            d$n_random_occasions, input_provider, function(x) .as_positive_integer(x, 
                "n_random_occasions"))
    }
    if (cfg$sampling_design == "consecutive_month") {
        cfg$n_consecutive_days <- .resident_prompt_parameter("n_consecutive_days", 
            meaning("n_consecutive_days"), valid("n_consecutive_days"), 
            d$n_consecutive_days, input_provider, function(x) .as_positive_integer(x, 
                "n_consecutive_days"))
    }
    if (cfg$sampling_design == "empirical") {
        cfg$empirical_dates <- .resident_prompt_parameter("empirical_dates", 
            meaning("empirical_dates"), valid("empirical_dates"), 
