ask_transition_matrix_parameters <-
function (states, transition_time_scale = "month", matrix_type = "biologically_informed", 
    interactive = TRUE, input_provider = NULL, default_matrix = NULL) 
{
    states <- validate_state_vector(states)
    transition_time_scale <- validate_transition_timescale(transition_time_scale)
    matrix_type <- match.arg(matrix_type, c("biologically_informed", 
        "conservative", "mobile"))
    if (!interactive) {
        mat <- default_matrix %||% default_transition_matrix_by_timescale(states, 
            transition_time_scale, matrix_type)
        return(list(transition_time_scale = transition_time_scale, 
            transition_matrix_source = "default", transition_matrix_type = matrix_type, 
            transition_matrix = mat, transition_time_scale_explanation = ""))
    }
    cat("\nParameter: transition_time_scale\n")
    cat("Meaning: one transition step in the hidden residency process. This may differ from the raw sampling grid. For example, daily survey dates can still use monthly transitions if states are intended to represent monthly residency status.\n")
    transition_time_scale <- .resident_prompt_option("Transition time scale", 
        c("day", "week", "month", "season", "year"), c("one model transition per day", 
            "one model transition per week", "one model transition per month", 
            "one model transition per season", "one model transition per year"), 
        default = transition_time_scale, input_provider = input_provider)
    cat("\nParameter: transition_matrix_source\n")
    cat("Meaning: choose whether to use a biologically informed default transition matrix or enter your own transition probabilities.\n")
    source <- .resident_prompt_option("Transition matrix source", 
        c("default", "custom"), c("use a time-scale-specific biologically informed starting matrix", 
            "enter transition probabilities row by row"), default = "default", 
        input_provider = input_provider)
    if (source == "default") {
        matrix_type <- .resident_prompt_option("Transition matrix type", 
            c("biologically_informed", "conservative", "mobile"), 
            c("balanced starting assumption for the selected time scale", 
                "stronger same-state persistence", "weaker same-state persistence and more movement among adjacent states"), 
            default = matrix_type, input_provider = input_provider)
        cat("\n")
        print_transition_matrix_explanation(states, transition_time_scale, 
            matrix_type)
        mat <- default_transition_matrix_by_timescale(states, 
            transition_time_scale, matrix_type)
    }
    else {
        m <- matrix(NA_real_, length(states), length(states), 
            dimnames = list(states, states))
        for (s in states) {
            valid_row <- FALSE
            while (!valid_row) {
                cat("\nThis row gives the probabilities of moving FROM state ", 
                  s, " TO each possible state during the next time step. The row must sum to 1.\n", 
                  sep = "")
                cat("State order:", paste(states, collapse = ", "), 
                  "\n")
                vals <- .resident_prompt_numeric_vector(paste0("transition row from ", 
                  s), length_expected = length(states), input_provider = input_provider, 
                  default = NULL, allow_default = FALSE)
                row_ok <- length(vals) == length(states) && all(is.finite(vals)) && 
                  all(vals >= 0) && abs(sum(vals) - 1) <= 9.9999999999999995e-07
                if (row_ok) {
                  m[s, ] <- vals
                  valid_row <- TRUE
                }
                else if (is.null(input_provider)) {
                  cat("Invalid row. Values must be finite, non-negative, and sum to 1. Please re-enter this row.\n")
                }
                else {
                  stop("Invalid transition row from ", s, "; values must be finite, non-negative, and sum to 1.")
                }
            }
        }
        mat <- validate_transition_matrix_timescale(m, states, 
            transition_time_scale, "custom")
        matrix_type <- "custom"
    }
    list(transition_time_scale = transition_time_scale, transition_matrix_source = source, 
        transition_matrix_type = matrix_type, transition_matrix = mat, 
        transition_time_scale_explanation = "")
}
assert_temporal_structure_available <-
function (structure, model = "model", n_occasions = NULL) 
{
