assess_abundance_model_suitability <-
function (details, analysis) 
{
    diag <- abundance_data_diagnostics(analysis)
    assessed <- details
    fields <- c("suitability", "assumptions_status", "data_support", 
        "expected_risk", "recommendation")
    for (f in fields) assessed[[f]] <- NA_character_
    for (i in seq_len(nrow(assessed))) {
        rec <- model_suitability_for_data(assessed$candidate_model[i], 
            diag)
        for (f in fields) assessed[[f]][i] <- unname(rec[[f]])
    }
    assessed <- add_display_suitability(assessed)
    attr(assessed, "diagnostics") <- diag
    assessed
}
attach_uncertainty_to_derived_table <-
function (tab, fit = NULL, ci_method = "auto", R = 20L) 
{
    if (!"uncertainty_method" %in% names(tab)) 
        tab$uncertainty_method <- choose_uncertainty_method(fit %||% 
            list(), ci_method)
    if (!"uncertainty_status" %in% names(tab)) 
        tab$uncertainty_status <- "unavailable"
    if (!"warning" %in% names(tab)) 
        tab$warning <- ""
    miss <- is.na(tab$lower_95) | is.na(tab$upper_95)
    tab$warning[miss & !nzchar(tab$warning)] <- "Confidence interval unavailable because no stable Hessian, profile likelihood, or bootstrap result was available."
    tab
}
attach_uncertainty_to_parameter_table <-
function (tab, fit = NULL, ci_method = "auto", R = 20L) 
{
    if (!nrow(tab)) 
        return(tab)
    if (!"uncertainty_method" %in% names(tab)) 
        tab$uncertainty_method <- choose_uncertainty_method(fit %||% 
            list(), ci_method)
    if (!"uncertainty_status" %in% names(tab)) 
        tab$uncertainty_status <- "unavailable"
    if (!"uncertainty_warning" %in% names(tab)) 
        tab$uncertainty_warning <- ""
    miss <- is.na(tab$beta_lower_95) & is.na(tab$real_lower_95) & 
        tab$fixed_or_estimated != "fixed"
    tab$uncertainty_warning[miss & !nzchar(tab$uncertainty_warning)] <- "Confidence interval unavailable because no stable Hessian, profile likelihood, or bootstrap result was available."
    tab$uncertainty_status[miss & tab$uncertainty_status == "computed"] <- "unavailable"
    tab
}
audit_direct_table_printing <-
function (file = "outputs/resident_pipeline_v0.8.9.R") 
{
    lines <- readLines(file, warn = FALSE)
    pat <- "print\\s*\\(|utils::head\\s*\\(|capture\\.output\\s*\\("
    hit <- grep(pat, lines)
    raw <- data.frame(line = hit, text = trimws(lines[hit]), 
        stringsAsFactors = FALSE)
    raw <- raw[!grepl("print_console_table|print_interpretation_box|print_warning_box|print_menu|print\\(paths\\)|print\\(TRUE\\)|print\\(FALSE\\)", 
        raw$text), , drop = FALSE]
    raw
}
audit_duplicate_function_definitions <-
function (file = "outputs/resident_pipeline_v0.9.0.R", from_marker = FALSE) 
{
    if (!file.exists(file)) {
        alt <- file.path(getwd(), basename(file))
        if (file.exists(alt)) 
            file <- alt
    }
    lines <- readLines(file, warn = FALSE)
    pat <- "^[[:space:]]*([A-Za-z.][A-Za-z0-9_.]*)[[:space:]]*(<-|=)[[:space:]]*function[[:space:]]*\\("
    hit <- grep(pat, lines)
    fn <- sub(pat, "\\1", lines[hit])
    core <- resident_v090_core_functions()
    data.frame(function_name = fn, line_number = hit, core_function = fn %in% 
        core, stringsAsFactors = FALSE)
}
audit_user_facing_terms <-
function (text = NULL, files = NULL, forbidden = forbidden_user_facing_terms(), 
    ignore_case = TRUE) 
{
    rows <- list()
    n <- 1L
    scan_text <- function(x, source) {
        haystack <- if (ignore_case) 
            tolower(x)
        else x
        for (term in forbidden) {
            needle <- if (ignore_case) 
                tolower(term)
            else term
            hit <- grep(needle, haystack, fixed = TRUE)
            if (length(hit)) {
                for (i in hit) {
                  context <- haystack[i]
                  if (grepl("legacy_names|add_legacy_interpretation_names|compatibility", 
                    context)) 
                    next
                  rows[[n]] <<- data.frame(source = source, line = i, 
                    forbidden_term = term, text = x[i], stringsAsFactors = FALSE)
                  n <<- n + 1L
                }
            }
        }
    }
    if (!is.null(text)) 
        scan_text(as.character(text), "text")
    if (!is.null(files)) {
        for (f in files) {
            if (!file.exists(f)) 
                stop("Cannot audit missing file: ", f)
            scan_text(readLines(f, warn = FALSE), f)
        }
    }
    if (!length(rows)) {
        return(data.frame(source = character(), line = integer(), 
            forbidden_term = character(), text = character(), 
            stringsAsFactors = FALSE))
    }
    do.call(rbind, rows)
}
