behavioral_response_check <-
function (history, occasions = NULL) 
{
    y <- extract_history(history, stage = "behavioral response check")
    has_pair <- ncol(y) >= 2
    after_capture <- recapture_next <- 0
    if (has_pair) {
        for (j in seq_len(ncol(y) - 1L)) {
            after_capture <- after_capture + sum(y[, j] == 1)
            recapture_next <- recapture_next + sum(y[, j] == 
                1 & y[, j + 1L] == 1)
        }
    }
    rate <- if (after_capture > 0) 
        recapture_next/after_capture
    else NA_real_
    status <- if (is.na(rate)) 
        "not_applicable"
    else if (rate < 0.050000000000000003 || rate > 0.80000000000000004) 
        "review"
    else "pass"
    data.frame(assumption = "behavioral_response", diagnostic_value = paste0("next_occasion_recapture_rate=", 
        round(rate, 3)), status = status, consequence = "Behavioral response means detection may change after first capture.", 
        recommendation = if (status == "review") 
            "Compare behavioral-response models when supported."
        else "No strong behavioral-response flag from this check.", 
        stringsAsFactors = FALSE)
}
benchmark_backends <-
function (scenarios = c("small"), seed = 1, maxit = 100) 
{
    defs <- list(small = list(N = 20, primary = 4, secondary = 3), 
        medium = list(N = 100, primary = 12, secondary = 4), 
        large = list(N = 500, primary = 24, secondary = 5), very_large = list(N = 1000, 
            primary = 36, secondary = 6))
    rows <- list()
    n <- 1L
    for (sc in scenarios) {
        d <- defs[[sc]]
        occ <- make_robust_design(make_occasion_table(n_occasions = d$primary * 
            d$secondary), primary = "month")
        occ$primary_period <- rep(seq_len(d$primary), each = d$secondary)
        occ$secondary_period <- ave(occ$occasion, occ$primary_period, 
            FUN = seq_along)
        spec <- state_space_specification()
        sim <- simulate_state_space_cr(d$N, occ, spec, seed = seed + 
            n)
        t0 <- proc.time()[["elapsed"]]
        base <- fit_robust_design_cr(sim$observed, sim$occasions, 
            spec, estimate_transition = FALSE, maxit = maxit, 
            hessian = FALSE)
        base_time <- proc.time()[["elapsed"]] - t0
        t0 <- proc.time()[["elapsed"]]
        tmb <- fit_robust_design_tmb(sim$observed, sim$occasions, 
            spec, estimate_transition = FALSE, maxit = maxit)
        tmb_time <- proc.time()[["elapsed"]] - t0
        rows[[n]] <- data.frame(scenario = sc, N = d$N, primary = d$primary, 
            secondary = d$secondary, base_logLik = base$logLik, 
            tmb_logLik = tmb$logLik, abs_logLik_difference = abs(base$logLik - 
                tmb$logLik), base_runtime_sec = base_time, tmb_runtime_sec = tmb_time, 
            relative_speedup = base_time/pmax(tmb_time, 1e-08), 
            tmb_backend = tmb$backend %||% "TMB", recommendation = if (d$N >= 
                100 || d$primary >= 12) {
                "Use TMB when available; base R is mainly a transparent reference."
            }
            else {
                "Base R is acceptable for small transparent checks."
            }, stringsAsFactors = FALSE)
        n <- n + 1L
    }
    do.call(rbind, rows)
}
benchmark_summary_graphics <-
function (scenarios = list(small = c(N = 50, T = 30), medium = c(N = 250, 
    T = 120), large = c(N = 1000, T = 365)), seed = 1) 
{
    rows <- list()
    n <- 1L
    for (nm in names(scenarios)) {
        N <- scenarios[[nm]][["N"]]
        Tn <- scenarios[[nm]][["T"]]
        occ <- make_occasion_table(n_occasions = Tn)
        set.seed(seed + n)
        h <- matrix(stats::rbinom(N * Tn, 1, 0.050000000000000003), 
            nrow = N)
        rownames(h) <- paste0("Subject_", seq_len(N))
        colnames(h) <- as.character(occ$date)
        for (fn in c("capture_data_summary", "discovery_curve_table", 
            "plot_discovery_curve_by_date", "plot_discovery_curve_by_effort")) {
            t0 <- proc.time()[["elapsed"]]
            if (fn == "capture_data_summary") 
                capture_data_summary(h, occ)
            if (fn == "discovery_curve_table") 
                d <- discovery_curve_table(h, occ)
            if (fn == "plot_discovery_curve_by_date") {
                d <- discovery_curve_table(h, occ)
                grDevices::pdf(tempfile(fileext = ".pdf"))
                plot_discovery_curve_by_date(d)
                grDevices::dev.off()
            }
            if (fn == "plot_discovery_curve_by_effort") {
                d <- discovery_curve_table(h, occ)
                grDevices::pdf(tempfile(fileext = ".pdf"))
                plot_discovery_curve_by_effort(d)
                grDevices::dev.off()
            }
            rows[[length(rows) + 1L]] <- data.frame(scenario = nm, 
                N = N, T = Tn, total_identifications = sum(h), 
                function_name = fn, runtime_seconds = proc.time()[["elapsed"]] - 
                  t0, stringsAsFactors = FALSE)
        }
        n <- n + 1L
    }
    do.call(rbind, rows)
}
