bootstrap_individuals <-
function (fit, nsim = 20, seed = 1, maxit = 200) 
{
    set.seed(seed)
    rows <- vector("list", nsim)
    ids <- seq_len(nrow(fit$history))
    for (b in seq_len(nsim)) {
        take <- sample(ids, length(ids), replace = TRUE)
        h <- fit$history[take, , drop = FALSE]
        rownames(h) <- paste0("Boot_", b, "_", seq_along(take))
        refit <- fit_robust_design_cr(h, fit$occasion_table, 
            fit$spec, transition_structure = fit$transition_structure, 
            detection_formula = fit$detection_design$formula, 
            estimate_transition = FALSE, maxit = maxit, hessian = FALSE)
        rows[[b]] <- data.frame(replicate = b, parameter = names(refit$beta), 
            estimate = as.numeric(refit$beta), stringsAsFactors = FALSE)
    }
    do.call(rbind, rows)
}
bootstrap_individuals_tmb <-
function (fit, nsim = 20, seed = 1, maxit = 300, store_fits = FALSE, 
    progress = TRUE) 
{
    set.seed(seed)
    ids <- seq_len(nrow(fit$history))
    rows <- vector("list", nsim)
    fits <- if (store_fits) 
        vector("list", nsim)
    else NULL
    for (b in seq_len(nsim)) {
        if (progress) 
            message("TMB individual bootstrap replicate ", b, 
                "/", nsim)
        t0 <- proc.time()[["elapsed"]]
        res <- tryCatch({
            take <- sample(ids, length(ids), TRUE)
            h <- fit$history[take, , drop = FALSE]
            rownames(h) <- paste0("TMB_boot_", b, "_", seq_along(take))
            refit <- fit_robust_design_tmb(h, fit$occasion_table, 
                fit$spec, detection_formula = fit$detection_design$formula, 
                estimate_transition = FALSE, maxit = maxit)
            if (store_fits) 
                fits[[b]] <<- refit
            data.frame(replicate = b, runtime_sec = proc.time()[["elapsed"]] - 
                t0, convergence = refit$convergence %||% NA_integer_, 
                warning = refit$tmb_status %||% "", parameter = names(refit$beta), 
                estimate = as.numeric(refit$beta), stringsAsFactors = FALSE)
        }, error = function(e) {
            data.frame(replicate = b, runtime_sec = proc.time()[["elapsed"]] - 
                t0, convergence = NA_integer_, warning = conditionMessage(e), 
                parameter = NA_character_, estimate = NA_real_, 
                stringsAsFactors = FALSE)
        })
        rows[[b]] <- res
    }
    list(summary = do.call(rbind, rows), fits = fits)
}
