}
bootstrap_refit <-
function (fit, R = 20L, type = c("parametric", "individual", 
    "block"), seed = 1L, ...) 
{
    type <- match.arg(type)
    set.seed(seed)
    rows <- list()
    failed <- 0L
    y <- fit$history
    for (r in seq_len(R)) {
        sim <- tryCatch({
            if (type == "parametric") 
                simulate_from_fit(fit)
            else if (type == "individual") 
                y[sample(seq_len(nrow(y)), replace = TRUE), , 
                  drop = FALSE]
            else y[, sample(seq_len(ncol(y)), replace = TRUE), 
                drop = FALSE]
        }, error = function(e) e)
        if (inherits(sim, "error")) {
            failed <- failed + 1L
            next
        }
        ref <- tryCatch(refit_model(fit, sim, ...), error = function(e) e)
        if (inherits(ref, "error")) {
            failed <- failed + 1L
            next
        }
        rows[[length(rows) + 1L]] <- data.frame(replicate = r, 
            N_hat = ref$N_hat %||% NA_real_, p = mean(as.numeric(ref$p_hat %||% 
                ref$p), na.rm = TRUE), Phi = mean(as.numeric(ref$Phi %||% 
                NA_real_), na.rm = TRUE), stringsAsFactors = FALSE)
    }
    out <- if (length(rows)) 
        do.call(rbind, rows)
    else data.frame()
    attr(out, "failed_refits") <- failed
    attr(out, "bootstrap_type") <- type
    out
}
bootstrap_summary_from_refits <-
function (refits, parameter = "N_hat", level = 0.94999999999999996) 
{
    vals <- suppressWarnings(as.numeric(refits[[parameter]]))
    vals <- vals[is.finite(vals)]
    if (!length(vals)) 
        return(data.frame(parameter = parameter, lower_95 = NA_real_, 
            upper_95 = NA_real_, uncertainty_status = "failed", 
            failed_refits = attr(refits, "failed_refits") %||% 
                NA_integer_, uncertainty_warning = "Bootstrap unavailable because refits failed or no finite estimates were returned.", 
            stringsAsFactors = FALSE))
    qs <- quantile(vals, c((1 - level)/2, 1 - (1 - level)/2), 
        names = FALSE, na.rm = TRUE)
    data.frame(parameter = parameter, lower_95 = qs[1], upper_95 = qs[2], 
        bootstrap_mean = mean(vals), bootstrap_SD = sd(vals), 
        uncertainty_method = paste0(attr(refits, "bootstrap_type") %||% 
            "parametric", "_bootstrap_refit"), uncertainty_status = "computed", 
        failed_refits = attr(refits, "failed_refits") %||% 0L, 
        uncertainty_warning = "", stringsAsFactors = FALSE)
}
build_design_data <-
function (history, occasions = NULL, group = NULL, effort = NULL, 
    allow_synthetic_dates = FALSE, data_type = c("empirical", 
        "simulation", "test"), temporal_structure = NULL, ...) 
{
    data_type <- match.arg(data_type)
    dd <- .resident_v093_build_design_data(history, occasions, 
        group = group, effort = effort, allow_synthetic_dates = allow_synthetic_dates, 
        data_type = data_type, temporal_structure = temporal_structure, 
        ...)
    if (!is.null(temporal_structure)) {
        validate_primary_secondary_periods(temporal_structure, 
            nrow(dd))
        dd$primary <- temporal_structure$primary_period
        dd$secondary <- temporal_structure$secondary_period
        dd$primary_period <- temporal_structure$primary_period
        dd$secondary_period <- temporal_structure$secondary_period
    }
    dd
}
build_design_matrix <-
function (formula, design_data) 
{
    vars <- all.vars(formula)
    miss <- setdiff(vars, names(design_data))
    if (length(miss)) 
        stop("Formula variables absent from design data: ", paste(miss, 
            collapse = ", "), call. = FALSE)
    mm <- model.matrix(formula, data = design_data)
    if (qr(mm)$rank < ncol(mm)) 
        warning("Design matrix is rank deficient; simplify formula or covariates.", 
            call. = FALSE)
    mm
}
build_detection_design_matrix <-
function (rd_array, formula = ~effort, individual_data = NULL, 
    observation_data = NULL, strict = FALSE) 
{
    dat <- prepare_detection_data(rd_array$history, rd_array$occasion_table, 
        individual_data, observation_data)
    problems <- validate_detection_covariates(formula, dat)
    if (strict && length(problems)) 
        stop(paste(problems, collapse = "; "))
    if (length(problems)) 
        formula <- ~1
    X <- safe_model_matrix(formula, dat)
    list(data = dat, X = X, formula = formula, original_formula = formula, 
        problems = problems)
}
