build_spatial_states <-
function (empirical, min_records = 5) 
{
    meta <- empirical$metadata
    if (is.null(meta) || !any(c("area", "site") %in% names(meta))) {
        warning("No area/site data available; using non-spatial states.")
        return(state_space_specification())
    }
    area_col <- if ("area" %in% names(meta)) 
        "area"
    else "site"
    tab <- table(meta[[area_col]])
    keep <- names(tab)[tab >= min_records]
    if (length(keep) < 2) {
        warning("Insufficient spatial replication; collapsing to non-spatial states.")
        return(state_space_specification())
    }
    states <- c("outside", paste0("area_", make.names(keep)))
    state_space_specification(states = states, unavailable_states = "outside")
}
build_tmb_detection_data <-
function (history, occasion_table, spec = state_space_specification(), 
    detection_formula = spec$detection_formula, individual_data = NULL, 
    observation_data = NULL) 
{
    rd <- prepare_robust_design_array(history, occasion_table)
    design <- build_detection_design_matrix(rd, detection_formula, 
        individual_data, observation_data)
    y <- rd$y
    y[is.na(y)] <- -1
    occ <- rd$occasion_index - 1
    occ[is.na(occ)] <- -1
    list(rd_array = rd, detection_design = design, data = list(y = y, 
        occasion_index = occ, X_detection = design$X, N = dim(y)[1], 
        Kp = dim(y)[2], Jmax = dim(y)[3], S = length(spec$states), 
        Tobs = nrow(occasion_table), unavailable = as.integer(spec$states %in% 
            spec$unavailable_states), initial_probs = as.numeric(spec$initial_probs), 
        Psi_fixed = unname(spec$transition_matrix)))
}
build_tmb_transition_data <-
function (rd_array, transition_formula = ~1, spatial_data = NULL, 
    social_data = NULL) 
{
    build_transition_design_matrix(rd_array$primary_table, transition_formula, 
        spatial_data, social_data)
}
build_transition_design_matrix <-
function (primary_table, formula = ~1, spatial_data = NULL, social_data = NULL, 
    strict = FALSE) 
{
    dat <- primary_table
    if (!is.null(spatial_data)) 
        dat <- merge(dat, spatial_data, by = intersect(names(dat), 
            names(spatial_data)), all.x = TRUE, sort = FALSE)
    if (!is.null(social_data)) 
        dat <- merge(dat, social_data, by = intersect(names(dat), 
            names(social_data)), all.x = TRUE, sort = FALSE)
    problems <- validate_detection_covariates(formula, dat)
    X <- safe_model_matrix(if (length(problems)) 
        ~1
    else formula, dat)
    qr_rank <- qr(X)$rank
    simplified <- length(problems) > 0 || qr_rank < ncol(X)
    if (simplified) {
        if (strict) 
            stop("Transition covariates are missing or collinear; simplify the transition model.")
        warning("Transition covariates are insufficient or collinear; simplifying to intercept-only transition model.")
        X <- stats::model.matrix(~1, dat)
    }
    list(data = dat, X = X, formula = if (simplified) ~1 else formula, 
        requested_formula = formula, simplified = simplified, 
        problems = problems, rank = qr_rank)
}
build_transition_parameter_map <-
function (transition_structure) 
{
    states <- transition_structure$states
    free <- transition_structure$free
    rows <- list()
    idx <- 1L
    for (r in seq_along(states)) {
        free_cols <- which(free[r, ])
        if (length(free_cols) <= 1L) 
            next
        for (c in free_cols[-length(free_cols)]) {
            rows[[length(rows) + 1L]] <- data.frame(parameter_index = idx, 
                from_state = states[r], to_state = states[c], 
                reference_to_state = states[free_cols[length(free_cols)]], 
                stringsAsFactors = FALSE)
            idx <- idx + 1L
        }
    }
    if (!length(rows)) {
        return(data.frame(parameter_index = integer(), from_state = character(), 
            to_state = character(), reference_to_state = character(), 
            stringsAsFactors = FALSE))
    }
    do.call(rbind, rows)
}
build_transition_structure <-
function (states = c("outside", "peripheral_user", "seasonal_resident", 
    "core_resident"), structure = c("diagonal_dominant", "fully_estimated", 
    "biologically_ordered", "fixed", "constrained", "partially_fixed"), 
    fixed_matrix = NULL, free = NULL, diagonal = 0.69999999999999996) 
{
    structure <- match.arg(structure)
    K <- length(states)
    if (structure == "fixed") {
        if (is.null(fixed_matrix)) 
            stop("fixed_matrix is required for fixed transition structure.")
        fixed_matrix <- validate_transition_matrix(fixed_matrix, 
            states)
        return(list(states = states, structure = structure, fixed = fixed_matrix, 
            free = matrix(FALSE, K, K, dimnames = list(states, 
                states))))
    }
    free_matrix <- matrix(TRUE, K, K, dimnames = list(states, 
        states))
    base <- matrix(1/K, K, K, dimnames = list(states, states))
    if (structure == "diagonal_dominant") {
        base[, ] <- (1 - diagonal)/pmax(1, K - 1)
        diag(base) <- diagonal
    }
    if (structure == "biologically_ordered") {
        base[, ] <- 0
        for (r in seq_len(K)) {
            allowed <- unique(pmax(1, pmin(K, c(r - 1, r, r + 
                1))))
            base[r, allowed] <- 1/length(allowed)
            free_matrix[r, setdiff(seq_len(K), allowed)] <- FALSE
        }
    }
    if (structure %in% c("constrained", "partially_fixed") && 
        !is.null(free)) {
        free_matrix[, ] <- free
    }
    base <- sweep(base, 1, rowSums(base), "/")
    list(states = states, structure = structure, fixed = base, 
        free = free_matrix)
}
