capture_data_summary <-
function (x, occasion_table = NULL, true_history = NULL, data_type = "empirical", 
    analysis = NULL) 
{
    inp <- resident_extract_summary_inputs(x, occasion_table)
    history <- inp$history
    occ <- inp$occasions
    captures <- rowSums(history, na.rm = TRUE)
    has_dates <- !is.null(occ) && "date" %in% names(occ)
    dates <- if (has_dates) 
        suppressWarnings(as.Date(occ$date))
    else rep(as.Date(NA), ncol(history))
    synthetic <- isTRUE(inp$synthetic) || isTRUE(attr(occ, "synthetic_dates_used")) || 
        resident_dates_look_generated_default(dates)
    confirmed_real <- has_dates && any(!is.na(dates)) && !synthetic && 
        resident_dates_are_confirmed_real(x, occ, analysis)
    date_status <- if (confirmed_real) 
        "observed_survey_dates_confirmed"
    else if (synthetic) 
        "generated_or_synthetic_dates_hidden_not_field_dates"
    else if (has_dates && any(!is.na(dates))) 
        "unconfirmed_dates_hidden_until_confirmed"
    else "missing_survey_dates"
    intervals <- if (confirmed_real) 
        diff(sort(unique(dates[!is.na(dates)])))
    else NA_real_
    if (!length(intervals)) 
        intervals <- NA_real_
    data.frame(initial_sampling_date = if (confirmed_real) 
        min(dates, na.rm = TRUE)
    else as.Date(NA), final_sampling_date = if (confirmed_real) 
        max(dates, na.rm = TRUE)
    else as.Date(NA), date_status = date_status, number_of_individuals = nrow(history), 
        number_of_different_individuals = nrow(history), number_of_sampling_occasions = ncol(history), 
        minimum_capture_records_per_individual = min(captures), 
        maximum_capture_records_per_individual = max(captures), 
        total_capture_records = sum(history, na.rm = TRUE), median_capture_records_per_individual = stats::median(captures), 
        mean_capture_records_per_individual = mean(captures), 
        number_of_singletons = sum(captures == 1), proportion_singletons = mean(captures == 
            1), number_of_never_detected_individuals = sum(captures == 
            0), sampling_period_days = if (confirmed_real) 
            as.integer(max(dates, na.rm = TRUE) - min(dates, 
                na.rm = TRUE))
        else NA_integer_, mean_sampling_interval_days = if (confirmed_real) 
            mean(as.numeric(intervals), na.rm = TRUE)
        else NA_real_, median_sampling_interval_days = if (confirmed_real) 
            stats::median(as.numeric(intervals), na.rm = TRUE)
        else NA_real_, interpretation = if (confirmed_real) 
            "A capture record means a detected individual on a sampling occasion. A zero means not detected, not necessarily absent."
        else "Survey dates are missing, generated, synthetic, or unconfirmed. Date fields are intentionally blank; capture counts remain valid for format checking and non-date summaries.", 
        stringsAsFactors = FALSE)
}
