capture_recapture_table_from_analysis <-
function (analysis) 
{
    if (is.null(analysis)) 
        stop("analysis object is missing.")
    if (!is.null(analysis$sim$observed)) 
        return(as_binary_matrix(analysis$sim$observed))
    if (!is.null(analysis$sim$history)) 
        return(as_binary_matrix(analysis$sim$history))
    if (!is.null(analysis$sim) && is.matrix(analysis$sim)) 
        return(as_binary_matrix(analysis$sim))
    if (!is.null(analysis$data$history)) 
        return(as_binary_matrix(analysis$data$history))
    if (!is.null(analysis$data) && is.matrix(analysis$data)) 
        return(as_binary_matrix(analysis$data))
    if (!is.null(analysis$observed)) 
        return(as_binary_matrix(analysis$observed))
    stop("No capture-recapture table was found in analysis.")
}
chao_curve_diagnostics <-
function (curve) 
{
    warnings <- unique(unlist(strsplit(paste(curve$warning %||% 
        character(), collapse = " "), "\\s*;\\s*")))
    warnings <- warnings[nzchar(warnings)]
    data.frame(n_occasions = nrow(curve), final_S_obs = if (nrow(curve)) 
        tail(curve$S_obs, 1)
    else NA_real_, final_Chao1 = if (nrow(curve)) 
        tail(curve$Chao1, 1)
    else NA_real_, final_Chao2 = if (nrow(curve)) 
        tail(curve$Chao2, 1)
    else NA_real_, final_Chao1_completeness = if (nrow(curve)) 
        tail(curve$Chao1_completeness, 1)
    else NA_real_, final_Chao2_completeness = if (nrow(curve)) 
        tail(curve$Chao2_completeness, 1)
    else NA_real_, diagnostic_interpretation = if (length(warnings)) 
        paste(unique(warnings), collapse = " ")
    else "No major Chao instability warning was detected.", stringsAsFactors = FALSE)
}
chao_discovery_curve_table <-
function (x, occasion_table = NULL) 
{
    history <- chao_history_matrix(x)
    occasion_table <- occasion_table %||% chao_occasion_table(x, 
        history)
    dates <- suppressWarnings(as.Date(occasion_table$date))
    if (length(dates) != ncol(history)) 
        dates <- rep(as.Date(NA), ncol(history))
    seen_before <- rep(FALSE, nrow(history))
    rows <- vector("list", ncol(history))
    for (k in seq_len(ncol(history))) {
        sub <- history[, seq_len(k), drop = FALSE]
        seen_now <- sub[, k] > 0
        c1 <- chao1_estimate(sub)
        c2 <- chao2_estimate(sub)
        warning <- paste(unique(c(c1$uncertainty_warning, c2$uncertainty_warning)), 
            collapse = "; ")
        rows[[k]] <- data.frame(occasion = k, date = dates[k], 
            cumulative_identifications = sum(sub, na.rm = TRUE), 
            cumulative_new_individuals = sum(seen_now & !seen_before), 
            S_obs = c1$S_obs, Chao1 = c1$estimate, Chao2 = c2$estimate, 
            Chao1_unseen = c1$unseen_estimate, Chao2_unseen = c2$unseen_estimate, 
            Chao1_completeness = c1$completeness, Chao2_completeness = c2$completeness, 
            f1 = c1$f1, f2 = c1$f2, Q1 = c2$Q1, Q2 = c2$Q2, T = k, 
            warning = warning, stringsAsFactors = FALSE)
        seen_before <- seen_before | seen_now
    }
    do.call(rbind, rows)
}
