chao_history_matrix <-
function (x) 
{
    if (is.list(x) && !is.null(x$history)) {
        history <- x$history
    }
    else if (is.list(x) && !is.null(x$observed)) {
        history <- x$observed
    }
    else if (is.list(x)) {
        tab <- safe_capture_recapture_table_from_analysis(x)
        id_cols <- intersect(c("individual_id", "id"), names(tab))
        history <- tab[, setdiff(names(tab), id_cols), drop = FALSE]
    }
    else {
        history <- x
    }
    history <- as.matrix(history)
    suppressWarnings(storage.mode(history) <- "numeric")
    history[is.na(history)] <- 0
    history <- ifelse(history > 0, 1, 0)
    if (is.null(dim(history))) 
        history <- matrix(history, nrow = 1)
    history
}
chao_interpretation <-
function (estimator = c("both", "Chao1", "Chao2")) 
{
    estimator <- match.arg(estimator)
    txt <- c(Chao1 = "Chao1 uses the number of individuals detected once and twice to estimate how many detectable individuals may remain unseen. Many single detections relative to double detections increase the estimated unseen component.", 
        Chao2 = "Chao2 uses incidence across sampling occasions. It uses individuals detected in only one occasion and exactly two occasions to estimate unseen individuals from survey-incidence patterns.", 
        role = "Chao estimates are not residency classifications and are not fitted mark-recapture abundance models. They describe discovery and sampling completeness.", 
        caution = "Chao estimates are sensitive to detection heterogeneity, sampling design, and rare detections. Treat them as descriptive richness and completeness indicators unless their assumptions are justified.")
    if (estimator == "Chao1") 
        return(paste(txt[c("Chao1", "role", "caution")], collapse = " "))
    if (estimator == "Chao2") 
        return(paste(txt[c("Chao2", "role", "caution")], collapse = " "))
    paste(txt, collapse = " ")
}
chao_occasion_table <-
function (x, history = NULL) 
{
    if (is.null(history)) 
        history <- chao_history_matrix(x)
    occ <- NULL
    if (is.list(x)) {
        occ <- tryCatch(extract_occasions(x, stage = "Chao discovery curves"), 
            error = function(e) NULL)
        if (is.null(occ)) 
            occ <- tryCatch(analysis_occasion_table(x), error = function(e) NULL)
        if (is.null(occ)) 
            occ <- x$occasions %||% x$sim$occasions %||% x$data$occasions %||% 
                NULL
    }
    if (is.null(occ) || !is.data.frame(occ) || nrow(occ) != ncol(history)) {
        occ <- data.frame(occasion = seq_len(ncol(history)), 
            date = as.Date(NA), stringsAsFactors = FALSE)
    }
    if (!"occasion" %in% names(occ)) 
        occ$occasion <- seq_len(nrow(occ))
    if (!"date" %in% names(occ)) 
        occ$date <- as.Date(NA)
    occ$occasion <- seq_len(nrow(occ))
    occ
}
