chao_warning_rules <-
function (estimator = c("Chao1", "Chao2"), S_obs = NA_real_, 
    f1 = NA_real_, f2 = NA_real_, Q1 = NA_real_, Q2 = NA_real_, 
    T = NA_integer_, detections = NA_real_, detection_heterogeneity_high = FALSE) 
{
    estimator <- match.arg(estimator)
    warnings <- character()
    if (!is.finite(S_obs) || S_obs <= 0) 
        warnings <- c(warnings, "No observed individuals yet; Chao estimate is not applicable.")
    if (is.finite(detections) && detections < 5) 
        warnings <- c(warnings, "Sparse data; interpret Chao estimates cautiously.")
    if (estimator == "Chao1") {
        if (is.finite(f2) && f2 == 0 && is.finite(f1) && f1 > 
            1) 
            warnings <- c(warnings, "f2 is zero; Chao1 fallback estimator used and may be unstable.")
        if (is.finite(f1) && is.finite(f2) && f1 > 2 * max(1, 
            f2)) 
            warnings <- c(warnings, "Many single detections relative to double detections; Chao1 may be unstable.")
    }
    if (estimator == "Chao2") {
        if (!is.finite(T) || T < 2) 
            warnings <- c(warnings, "T is less than 2; Chao2 is unreliable with fewer than two sampling occasions.")
        if (is.finite(Q2) && Q2 == 0 && is.finite(Q1) && Q1 > 
            1) 
            warnings <- c(warnings, "Q2 is zero; Chao2 fallback estimator used and may be unstable.")
        if (is.finite(Q1) && is.finite(Q2) && Q1 > 2 * max(1, 
            Q2)) 
            warnings <- c(warnings, "Many unique occasion detections relative to duplicated occasion detections; Chao2 may be unstable.")
    }
    if (isTRUE(detection_heterogeneity_high)) 
        warnings <- c(warnings, "High detection heterogeneity can bias Chao estimates upward.")
    paste(unique(warnings), collapse = " ")
}
chao1_estimate <-
function (history, detection_heterogeneity_high = FALSE) 
{
    history <- chao_history_matrix(history)
    if (!length(history) || nrow(history) == 0 || ncol(history) == 
        0) {
        return(data.frame(estimator = "Chao1", S_obs = 0L, f1 = NA_integer_, 
            f2 = NA_integer_, Q1 = NA_integer_, Q2 = NA_integer_, 
            T = NA_integer_, estimate = NA_real_, unseen_estimate = NA_real_, 
            completeness = NA_real_, singleton_fraction = NA_real_, 
            doubleton_fraction = NA_real_, uncertainty_warning = "No sampling data available.", 
            interpretation = chao_interpretation("Chao1"), stringsAsFactors = FALSE))
    }
    counts <- rowSums(history, na.rm = TRUE)
    observed_counts <- counts[counts > 0]
    S_obs <- length(observed_counts)
    f1 <- sum(observed_counts == 1)
    f2 <- sum(observed_counts == 2)
    estimate <- if (S_obs == 0) 
        NA_real_
    else if (f2 > 0) 
        S_obs + f1^2/(2 * f2)
    else S_obs + f1 * (f1 - 1)/2
    unseen <- if (is.finite(estimate)) 
        max(0, estimate - S_obs)
    else NA_real_
    completeness <- if (is.finite(estimate) && estimate > 0) 
        S_obs/estimate
    else NA_real_
    warning <- chao_warning_rules("Chao1", S_obs = S_obs, f1 = f1, 
        f2 = f2, detections = sum(history), detection_heterogeneity_high = detection_heterogeneity_high)
    data.frame(estimator = "Chao1", S_obs = S_obs, f1 = f1, f2 = f2, 
        Q1 = NA_integer_, Q2 = NA_integer_, T = NA_integer_, 
        estimate = estimate, unseen_estimate = unseen, completeness = completeness, 
        singleton_fraction = if (S_obs > 0) 
            f1/S_obs
        else NA_real_, doubleton_fraction = if (S_obs > 0) 
            f2/S_obs
        else NA_real_, uncertainty_warning = warning, interpretation = chao_interpretation("Chao1"), 
        stringsAsFactors = FALSE)
}
chao2_estimate <-
function (history, detection_heterogeneity_high = FALSE) 
{
    history <- chao_history_matrix(history)
    if (!length(history) || nrow(history) == 0 || ncol(history) == 
        0) {
        return(data.frame(estimator = "Chao2", S_obs = 0L, f1 = NA_integer_, 
            f2 = NA_integer_, Q1 = NA_integer_, Q2 = NA_integer_, 
            T = 0L, estimate = NA_real_, unseen_estimate = NA_real_, 
            completeness = NA_real_, singleton_fraction = NA_real_, 
            doubleton_fraction = NA_real_, uncertainty_warning = "No sampling data available.", 
            interpretation = chao_interpretation("Chao2"), stringsAsFactors = FALSE))
    }
    incidence <- rowSums(history > 0, na.rm = TRUE)
    observed_incidence <- incidence[incidence > 0]
    S_obs <- length(observed_incidence)
    Q1 <- sum(observed_incidence == 1)
    Q2 <- sum(observed_incidence == 2)
    T <- ncol(history)
    estimate <- if (S_obs == 0 || T < 1) 
        NA_real_
    else if (Q2 > 0) 
        S_obs + ((T - 1)/T) * Q1^2/(2 * Q2)
    else S_obs + ((T - 1)/T) * Q1 * (Q1 - 1)/2
    if (T < 2) 
        estimate <- NA_real_
    unseen <- if (is.finite(estimate)) 
        max(0, estimate - S_obs)
    else NA_real_
    completeness <- if (is.finite(estimate) && estimate > 0) 
        S_obs/estimate
    else NA_real_
    warning <- chao_warning_rules("Chao2", S_obs = S_obs, Q1 = Q1, 
        Q2 = Q2, T = T, detections = sum(history), detection_heterogeneity_high = detection_heterogeneity_high)
    data.frame(estimator = "Chao2", S_obs = S_obs, f1 = NA_integer_, 
        f2 = NA_integer_, Q1 = Q1, Q2 = Q2, T = T, estimate = estimate, 
        unseen_estimate = unseen, completeness = completeness, 
        singleton_fraction = if (S_obs > 0) 
            Q1/S_obs
        else NA_real_, doubleton_fraction = if (S_obs > 0) 
            Q2/S_obs
        else NA_real_, uncertainty_warning = warning, interpretation = chao_interpretation("Chao2"), 
        stringsAsFactors = FALSE)
}
check_capture_data_format <-
function (imported) 
{
    problems <- character()
    if (!is.list(imported)) 
        problems <- c(problems, "Imported data must be a list returned by an import function.")
    history <- if (is.list(imported)) 
        imported$history
    else NULL
    occasions <- if (is.list(imported)) 
        imported$occasions
    else NULL
    if (is.null(history)) 
        problems <- c(problems, "No history matrix was found.")
    if (!is.null(history)) {
        history <- tryCatch(as_binary_matrix(history), error = function(e) e)
        if (inherits(history, "error")) 
            problems <- c(problems, conditionMessage(history))
        if (!inherits(history, "error")) {
            if (nrow(history) < 1) 
                problems <- c(problems, "No individuals were found.")
            if (ncol(history) < 1) 
                problems <- c(problems, "No sampling occasions were found.")
            if (!all(history %in% c(0L, 1L))) 
                problems <- c(problems, "History values must be coded as 0/1.")
        }
    }
    if (is.null(occasions) || !"date" %in% names(occasions)) 
        problems <- c(problems, "No occasion date table was found.")
    ok <- length(problems) == 0L
    summary <- if (ok) 
        summarize_capture_data(imported)
    else data.frame(problem = problems, stringsAsFactors = FALSE)
    list(ok = ok, summary = summary, message = if (ok) "The file passed the basic capture-recapture format check." else paste(problems, 
        collapse = " "))
}
