choose_analysis_or_simulation <-
function (input_provider = NULL, max_attempts = if (is.null(input_provider)) Inf else 10L) 
{
    attempts <- 0L
    repeat {
        print_main_workflow_menu()
        ans <- .resident_prompt("Enter option number or name: ", 
            input_provider)
        key <- tolower(trimws(as.character(ans)))
        if (key %in% c("1", "analyze", "analyze existing data", 
            "data")) 
            return("analyze")
        if (key %in% c("2", "simulate", "simulate data", "simulation")) 
            return("simulate")
        if (key %in% c("3", "exit", "quit")) 
            return("exit")
        if (key %in% c("4", "example", "run documented example simulation", 
            "documented example")) 
            return("example")
        cat("Please choose 1, 2, 3, or 4. You can also type analyze, simulate, exit, or example.\n")
        attempts <- attempts + 1L
        if (attempts >= max_attempts) 
            stop("No valid workflow choice was provided after ", 
                max_attempts, " attempts.", call. = FALSE)
    }
}
choose_and_import_capture_data <-
function (format = c("PROGRAM_MARK", "SOCPROG", "CSV_LONG", "WIDE_CSV", 
    "MARK_INP", "EXCEL", "AUTO"), file = NULL, input_provider = NULL, 
    max_attempts = if (is.null(input_provider)) Inf else 10L) 
{
    format <- toupper(gsub("[ -]+", "_", as.character(format[1])))
    attempts <- 0L
    repeat {
        attempts <- attempts + 1L
        if (is.null(file) || !nzchar(trimws(file))) {
            if (!is.null(input_provider)) 
                file <- .resident_prompt("Enter the full path to the data file, type examples, or type exit: ", 
                  input_provider)
            else file <- readline("Enter the full path to the data file, type examples, or type exit: ")
            file <- gsub("^\"|\"$", "", trimws(file))
            if (tolower(file) %in% c("exit", "quit", "cancel", 
                "0")) 
                return(list(status = "cancelled"))
            if (tolower(file) %in% c("examples", "example", "templates")) {
                show_import_format_examples(format)
                print_console_table(write_import_templates(), 
                  title = "Template files written", max_rows = 3L, 
                  max_col_width = 80)
                file <- NULL
                next
            }
        }
        validation <- validate_import_file_before_analysis(file, 
            format)
        print_import_validation_result(validation)
        if (isTRUE(validation$ok)) {
            imported <- confirm_import_dates_if_needed(validation$imported, 
                validation, input_provider = input_provider)
            check <- check_capture_data_format(imported)
            check$summary <- capture_data_summary(imported$history, 
                imported$occasions, data_type = "empirical")
            imported$validation <- validation
            imported$source_file <- normalizePath(path.expand(file), 
                mustWork = FALSE)
            return(list(data = imported, check = check, status = "ok", 
                validation = validation))
        }
        file <- NULL
        if (attempts >= max_attempts) 
            stop("No valid data file was imported after ", max_attempts, 
                " attempts.", call. = FALSE)
    }
}
choose_output_layout <-
function (x, max_cols = 8, max_rows_for_transpose = 4) 
{
    x <- as.data.frame(x)
    if (nrow(x) == 1L) 
        return("rowwise_list")
    if (ncol(x) > max_cols && nrow(x) <= max_rows_for_transpose) 
        return("rowwise_list")
    if (length(table_note_columns(x)) > 0) 
        return("compact_with_notes")
    if (ncol(x) > max_cols) 
        return("rowwise_list")
    "compact"
}
