cjs_build_design_matrices <-
function (Phi = ~1, p = ~1, design_data) 
{
    vars <- unique(c(all.vars(Phi), all.vars(p)))
    miss <- setdiff(vars, names(design_data))
    if (length(miss)) 
        stop("Formula variables absent from design data: ", paste(miss, 
            collapse = ", "), call. = FALSE)
    X_Phi <- model.matrix(Phi, data = design_data[-nrow(design_data), 
        , drop = FALSE])
    X_p <- model.matrix(p, data = design_data)
    if (qr(X_Phi)$rank < ncol(X_Phi) || qr(X_p)$rank < ncol(X_p)) 
        warning("Design matrix is rank deficient; simplify formula or covariates.", 
            call. = FALSE)
    list(X_Phi = X_Phi, X_p = X_p)
}
