cjs_forward_algorithm <-
function (y, Phi, p) 
{
    y <- as.numeric(y)
    first <- which(y > 0)[1]
    if (is.na(first) || first >= length(y)) 
        return(0)
    alive <- 1
    dead <- 0
    ll <- 0
    for (t in (first + 1L):length(y)) {
        alive2 <- alive * Phi[t - 1L]
        dead2 <- dead + alive * (1 - Phi[t - 1L])
        if (y[t] > 0) {
            prob <- alive2 * p[t]
            if (prob <= 0 || !is.finite(prob)) 
                return(-1000000000000)
            ll <- ll + log(prob)
            alive <- 1
            dead <- 0
        }
        else {
            prob <- alive2 * (1 - p[t]) + dead2
            if (prob <= 0 || !is.finite(prob)) 
                return(-1000000000000)
            ll <- ll + log(prob)
            alive <- alive2 * (1 - p[t])/prob
            dead <- dead2/prob
        }
    }
    ll
}
cjs_loglik <-
function (par, history, X_Phi, X_p) 
{
    y <- validate_cjs_data(history)
    nPhi <- ncol(X_Phi)
    beta_Phi <- par[seq_len(nPhi)]
    beta_p <- par[nPhi + seq_len(ncol(X_p))]
    Phi <- plogis(as.numeric(X_Phi %*% beta_Phi))
    p <- plogis(as.numeric(X_p %*% beta_p))
    sum(vapply(seq_len(nrow(y)), function(i) cjs_forward_algorithm(y[i, 
        ], Phi, p), numeric(1)), na.rm = TRUE)
}
