cjs_parameter_table <-
function (fit, ...) 
{
    se <- tryCatch(sqrt(diag(solve(fit$optim$hessian))), error = function(e) rep(NA_real_, 
        length(fit$par)))
    names(se) <- names(fit$par)
    beta_names <- names(fit$par)
    beta_rows <- data.frame(model_name = "CJS", parameter = sub("_.*", 
        "", beta_names), parameter_type = "beta", index = beta_names, 
        link_function = "logit", beta_estimate = as.numeric(fit$par), 
        beta_SE = as.numeric(se), beta_lower_95 = as.numeric(fit$par) - 
            1.96 * as.numeric(se), beta_upper_95 = as.numeric(fit$par) + 
            1.96 * as.numeric(se), real_estimate = NA_real_, 
        real_SE = NA_real_, real_lower_95 = NA_real_, real_upper_95 = NA_real_, 
        fixed_or_estimated = "estimated", identifiable_status = fit$hessian_status %||% 
            "not_assessed", uncertainty_method = "hessian_delta_when_available", 
        uncertainty_status = ifelse(is.finite(se), "computed", 
            "unavailable"), uncertainty_warning = ifelse(is.finite(se), 
            "", "Hessian-based uncertainty unavailable."), biological_meaning = "CJS beta coefficient.", 
        result_interpretation = "CJS estimates apparent survival/persistence and detection conditional on first capture. It does not estimate total abundance.", 
        stringsAsFactors = FALSE)
    phi_rows <- data.frame(model_name = "CJS", parameter = "Phi", 
        parameter_type = "real_apparent_survival_or_persistence", 
        index = seq_along(fit$Phi), link_function = "real", beta_estimate = NA_real_, 
        beta_SE = NA_real_, beta_lower_95 = NA_real_, beta_upper_95 = NA_real_, 
        real_estimate = fit$Phi, real_SE = NA_real_, real_lower_95 = NA_real_, 
        real_upper_95 = NA_real_, fixed_or_estimated = "estimated", 
        identifiable_status = fit$hessian_status, uncertainty_method = "not_available", 
        uncertainty_status = "unavailable", uncertainty_warning = "Real-scale interval not computed in this table.", 
        biological_meaning = "Apparent survival or persistence interval probability.", 
        result_interpretation = "Phi applies between detection occasions after first capture.", 
        stringsAsFactors = FALSE)
    p_rows <- data.frame(model_name = "CJS", parameter = "p", 
        parameter_type = "real_detection_probability", index = seq_along(fit$p), 
        link_function = "real", beta_estimate = NA_real_, beta_SE = NA_real_, 
        beta_lower_95 = NA_real_, beta_upper_95 = NA_real_, real_estimate = fit$p, 
        real_SE = NA_real_, real_lower_95 = NA_real_, real_upper_95 = NA_real_, 
        fixed_or_estimated = "estimated", identifiable_status = fit$hessian_status, 
        uncertainty_method = "not_available", uncertainty_status = "unavailable", 
        uncertainty_warning = "Real-scale interval not computed in this table.", 
        biological_meaning = "Detection probability for an available marked individual.", 
        result_interpretation = "Detection is conditional on the individual being alive/available and previously marked.", 
        stringsAsFactors = FALSE)
    rbind(beta_rows, phi_rows, p_rows)
}
classification_accuracy_from_fit <-
function (fit, sim) 
{
    if (is.null(sim$latent_states)) 
        return(NA_real_)
    true <- apply(sim$latent_states, 1, function(z) {
        tab <- table(factor(sim$spec$states[z], levels = sim$spec$states))
        names(tab)[which.max(tab)]
    })
    dec <- aggregate(state ~ id, fit$decoded_states, function(x) names(which.max(table(x))))
    mean(true[seq_len(nrow(dec))] == dec$state)
}
classify_aurebesh_probabilistic <-
function (prob_table, classes = c("Aurek", "Besh", "Cresh", "Dorn", 
    "Esk", "Forn", "Grek", "Herf", "Isk"), class_map = NULL) 
{
    prob_cols <- grep("^prob_", names(prob_table), value = TRUE)
    state_probs <- as.matrix(prob_table[, prob_cols, drop = FALSE])
    state_probs <- state_probs/rowSums(state_probs)
    if (is.null(class_map)) {
        class_map <- matrix(1/length(classes), nrow = ncol(state_probs), 
            ncol = length(classes))
        rownames(class_map) <- sub("^prob_", "", prob_cols)
        colnames(class_map) <- classes
        class_map[, ] <- 0.02
        class_map[, 1] <- seq(0.29999999999999999, 0.02, length.out = nrow(class_map))
        class_map[, length(classes)] <- seq(0.02, 0.29999999999999999, 
            length.out = nrow(class_map))
        class_map <- class_map/rowSums(class_map)
    }
    class_probs <- state_probs %*% class_map
    class_probs <- class_probs/rowSums(class_probs)
    out <- data.frame(id = prob_table$id, aurebesh_class = colnames(class_probs)[max.col(class_probs)], 
        aurebesh_entropy = apply(class_probs, 1, state_entropy), 
        as.data.frame(class_probs, check.names = FALSE), stringsAsFactors = FALSE, 
        check.names = FALSE)
    out
}
classify_effort_detection_effect <-
function (beta) 
{
    beta <- as.numeric(beta)
    if (length(beta) != 1 || !is.finite(beta)) 
        stop("effort_detection_effect must be one finite numeric value.")
    if (abs(beta) > 5) 
        return("extreme effect requiring confirmation")
    if (beta < -2) 
        return("strong negative or potentially dominant negative effect")
    if (beta < -1) 
        return("strong negative effect")
    if (beta < -0.5) 
        return("moderate negative effect")
    if (beta < -0.25) 
        return("weak negative effect")
    if (beta <= 0.25) 
        return("neutral or very weak effect")
    if (beta <= 0.5) 
        return("weak positive effect")
    if (beta <= 1) 
        return("moderate positive effect")
    if (beta <= 2) 
        return("strong positive effect")
    "strong or potentially dominant positive effect"
}
