classify_sigma_individual_detection <-
function (value) 
{
    v <- as.numeric(value)
    if (length(v) != 1 || is.na(v) || !is.finite(v) || v < 0) 
        stop("sigma_individual_detection must be a finite numeric value >= 0.")
    if (v == 0) 
        return("no individual heterogeneity")
    if (v <= 0.29999999999999999) 
        return("very weak individual heterogeneity")
    if (v <= 0.69999999999999996) 
        return("weak to moderate heterogeneity")
    if (v <= 1.2) 
        return("moderate to strong heterogeneity")
    if (v <= 2) 
        return("strong heterogeneity")
    if (v <= 5) 
        return("very strong heterogeneity")
    "extreme heterogeneity requiring confirmation"
}
