closed_capture_loglik <-
function (par, history, abundance_model = "closed_M0") 
{
    validate_abundance_model(abundance_model)
    y <- .observed_history(history)
    n <- nrow(y)
    f0 <- exp(par[["log_f0"]])
    N <- n + f0
    pieces <- .closed_prob_matrix(y, abundance_model, par)
    if (!is.finite(pieces$q0) || pieces$q0 <= 0 || pieces$q0 >= 
        1) 
        return(-Inf)
    if (any(!is.finite(pieces$prob)) || any(pieces$prob <= 0)) 
        return(-Inf)
    lgamma(N + 1) - lgamma(f0 + 1) + f0 * log(pieces$q0) + sum(log(pieces$prob))
}
