closure_assumption_check <-
function (history, occasions = NULL) 
{
    y <- extract_history(history, stage = "closure assumption check")
    occ <- occasions %||% extract_occasions(history, stage = "closure assumption check")
    span <- .survey_span_days(occ)
    recaps <- sum(rowSums(y) > 1)
    status <- if (is.na(span)) 
        "review"
    else if (span <= 30 && recaps >= max(3, 0.10000000000000001 * 
        nrow(y))) 
        "pass"
    else if (span <= 120) 
        "review"
    else "fail"
    data.frame(assumption = "closed_capture_closure", diagnostic_value = paste0("span_days=", 
        span, "; recaptured_ids=", recaps), status = status, 
        consequence = "Closed-capture abundance depends on no major entry, exit, death, birth, or permanent emigration during the modeled session.", 
        recommendation = if (status == "pass") 
            "Closed-capture models may be considered with detection diagnostics."
        else "Use caution or consider robust-design, open-population, or state-space models.", 
        stringsAsFactors = FALSE)
}
coerce_abundance_estimates_to_plot_table <-
function (x) 
{
    if (is.null(x)) 
        return(NULL)
    if (is.atomic(x) && !is.null(names(x))) {
        return(data.frame(occasion = seq_along(x), abundance_estimate = as.numeric(x), 
            source = names(x), stringsAsFactors = FALSE))
    }
    if (is.numeric(x) && is.null(dim(x))) 
        return(data.frame(occasion = seq_along(x), abundance_estimate = as.numeric(x)))
    if (is.data.frame(x)) 
        return(normalize_derived_parameter_table(x))
    if (is.list(x) && !is.null(x$N_by_occasion)) 
        return(open_population_abundance_table(x))
    if (is.list(x) && !is.null(x$primary_abundance)) 
        return(as.data.frame(x$primary_abundance))
    if (is.list(x) && !is.null(x$N_hat)) 
        return(data.frame(occasion = 1L, abundance_estimate = as.numeric(x$N_hat), 
            stringsAsFactors = FALSE))
    NULL
}
coerce_history_matrix <-
function (history, allow_na_zero = FALSE, stage = "history coercion") 
{
    reject_summary_as_history(history, stage = stage)
    if (is_resident_encounter_data(history)) 
        return(history$history)
    if (is.null(history)) 
        stop_history_error(stage, history, "history is NULL.")
    if (is.list(history) && !(is.data.frame(history) || is.matrix(history))) {
        if (!is.null(history$encounter_data)) 
            return(coerce_history_matrix(history$encounter_data, 
                allow_na_zero, stage))
        if (!is.null(history$observed)) 
            return(coerce_history_matrix(history$observed, allow_na_zero, 
                stage))
        if (!is.null(history$history)) 
            return(coerce_history_matrix(history$history, allow_na_zero, 
                stage))
        if (!is.null(history$data$history)) 
            return(coerce_history_matrix(history$data$history, 
                allow_na_zero, stage))
        if (!is.null(history$sim$observed)) 
            return(coerce_history_matrix(history$sim$observed, 
                allow_na_zero, stage))
        stop_history_error(stage, history, "a list was supplied but no history-like field was found.")
    }
    if (!(is.matrix(history) || is.data.frame(history))) {
        stop_history_error(stage, history, "history is not a matrix or data.frame.")
    }
    original <- history
    if (is.data.frame(history)) {
        id_col <- which(tolower(names(history)) %in% c("id", 
            "individual", "individual_id"))
        if (length(id_col)) {
            ids <- as.character(history[[id_col[1]]])
            if (anyDuplicated(ids)) 
                stop_history_error(stage, original, "duplicate IDs were detected before matrix construction.")
            history <- history[, -id_col[1], drop = FALSE]
            rownames(history) <- ids
        }
    }
    if (is.null(dim(history)) || is.null(nrow(history)) || is.null(ncol(history))) {
        stop_history_error(stage, original, "nrow(history) or ncol(history) is NULL.")
    }
    if (!is.finite(nrow(history)) || !is.finite(ncol(history)) || 
        nrow(history) <= 0 || ncol(history) <= 0) {
        stop_history_error(stage, original, "history has zero rows, zero columns, or non-finite dimensions.")
    }
    mat_chr <- as.matrix(history)
    if (any(is.na(mat_chr))) {
        if (!allow_na_zero) {
            stop_history_error(stage, original, "NA values were found. They are not converted to nondetections unless allow_na_zero = TRUE.")
        }
        mat_chr[is.na(mat_chr)] <- 0
    }
    vals <- as.character(mat_chr)
    ok <- vals %in% c("0", "1", "FALSE", "TRUE", "false", "true")
    if (!all(ok)) {
        stop_history_error(stage, original, "encounter-history values must be 0/1 or TRUE/FALSE.")
    }
    mat <- matrix(as.numeric(vals %in% c("1", "TRUE", "true")), 
        nrow = nrow(mat_chr), ncol = ncol(mat_chr), dimnames = dimnames(mat_chr))
    if (is.null(rownames(mat)) || any(!nzchar(rownames(mat)))) {
        warning("Encounter-history row names were missing; generated Subject_### IDs.", 
            call. = FALSE)
        rownames(mat) <- sprintf("Subject_%03d", seq_len(nrow(mat)))
    }
    if (anyDuplicated(rownames(mat))) {
        stop_history_error(stage, original, "duplicate individual IDs were detected.")
    }
    if (is.null(colnames(mat)) || any(!nzchar(colnames(mat)))) {
        colnames(mat) <- paste0("occasion_", seq_len(ncol(mat)))
    }
    mat
}
collect_parameter_warnings <-
function (config) 
{
    rows <- list()
    for (nm in names(config)) {
        w <- tryCatch(flag_suspicious_parameter_value(nm, config[[nm]], 
            config), error = function(e) conditionMessage(e))
        if (length(w) && nzchar(paste(w, collapse = ""))) {
            rows[[length(rows) + 1L]] <- data.frame(parameter = nm, 
                warning = paste(w, collapse = " | "), stringsAsFactors = FALSE)
        }
    }
    if (!length(rows)) 
        return(data.frame(parameter = character(), warning = character(), 
            stringsAsFactors = FALSE))
    do.call(rbind, rows)
}
