function (fit, ...) 
{
    tab <- mark_style_derived_parameter_table(fit, ...)
    keep <- intersect(c("model_name", "derived_parameter", "index", 
        "estimate", "SE", "lower_95", "upper_95", "time_interval", 
        "uncertainty_method", "uncertainty_status", "result_interpretation", 
        "warning"), names(tab))
    tab[, keep, drop = FALSE]
}
compact_mark_style_parameter_table <-
function (fit) 
{
    tab <- mark_style_parameter_table(fit)
    if (!is.data.frame(tab) || !nrow(tab)) 
        return(tab)
    tab$type <- tab$parameter_type %||% tab$status %||% NA_character_
    tab$link <- tab$link_function %||% NA_character_
    tab$estimate <- tab$real_estimate %||% tab$beta_estimate %||% 
        NA_real_
    tab$SE <- tab$real_SE %||% tab$beta_SE %||% NA_real_
    tab$lower_95 <- tab$real_lower_95 %||% tab$beta_lower_95 %||% 
        NA_real_
    tab$upper_95 <- tab$real_upper_95 %||% tab$beta_upper_95 %||% 
        NA_real_
    tab$status <- tab$identifiable_status %||% NA_character_
    tab$uncertainty <- tab$uncertainty_status %||% NA_character_
    keep <- c("model_name", "parameter", "type", "index", "link", 
        "estimate", "SE", "lower_95", "upper_95", "status", "uncertainty")
    out <- tab[, intersect(keep, names(tab)), drop = FALSE]
    attr(out, "full_table") <- tab
    out
}
compact_simulation_configuration_review <-
function (config) 
{
    warnings <- config$parameter_warnings
    warning_count <- if (is.data.frame(warnings)) 
        nrow(warnings)
    else length(config$validation_warnings %||% character())
    state_det <- config$state_detection
    if (!is.null(names(state_det))) {
        state_det_txt <- paste(paste0(names(state_det), "=", 
            state_det), collapse = ", ")
    }
    else {
        state_det_txt <- paste(state_det, collapse = ", ")
    }
    data.frame(item = c("Model", "Population size", "Sampling dates", 
        "Requested occasions", "Actual occasions", "Sampling design", 
        "Detection assumption", "Transition mode", "State detection", 
        "Main warnings"), value = c(config$simulation_model, 
        as.character(config$N), paste(as.Date(config$initial_sampling_date), 
            "to", as.Date(config$final_sampling_date)), as.character(config$requested_number_of_sampling_occasions), 
        as.character(config$actual_number_of_sampling_occasions %||% 
            config$number_of_sampling_occasions), config$sampling_design, 
        config$detection_covariate_assumptions, paste(config$transition_estimation %||% 
            "fixed", config$transition_time_scale %||% "month", 
            "matrix"), state_det_txt, as.character(warning_count)), 
        stringsAsFactors = FALSE)
}
compact_table_view <-
function (x, key_columns = NULL, max_rows = 20L, max_col_width = table_output_options()$max_col_width, 
    digits = 3L, header_style = table_output_options()$header_style) 
{
    if (!is.data.frame(x)) 
        x <- as.data.frame(x)
    if (!is.null(key_columns)) {
        keep <- intersect(key_columns, names(x))
        if (length(keep)) 
            x <- x[, keep, drop = FALSE]
    }
    out <- head(x, max_rows)
    out <- truncate_table_columns(out, max_col_width = max_col_width, 
        digits = digits)
    if (identical(header_style, "short")) 
        out <- apply_table_display_labels(out)
    out
}
compare_abundance_estimators <-
function (analysis, fit = NULL, confirm_model_fits = FALSE) 
{
    y <- extract_history(analysis, stage = "estimator comparison")
    rows <- list(data.frame(estimator = "observed_detected_individuals", 
        estimate_type = "observed_count_minimum", mean = nrow(.observed_history(y)), 
        SD = NA_real_, median = nrow(.observed_history(y)), lower_95 = NA_real_, 
        upper_95 = NA_real_, number_of_periods_or_occasions = 1L, 
        uncertainty_method = "count", result_interpretation = "Observed count is the minimum detected, not true abundance.", 
        stringsAsFactors = FALSE))
    ch <- tryCatch(chao_discovery_estimates(y), error = function(e) NULL)
    if (is.data.frame(ch)) 
        for (i in seq_len(nrow(ch))) rows[[length(rows) + 1L]] <- data.frame(estimator = ch$estimator[i], 
            estimate_type = "descriptive_richness_or_completeness_estimator", 
            mean = ch$estimate[i], SD = NA_real_, median = ch$estimate[i], 
            lower_95 = NA_real_, upper_95 = NA_real_, number_of_periods_or_occasions = 1L, 
            uncertainty_method = "Chao_descriptive_estimator", 
            result_interpretation = "Chao estimates are descriptive richness/completeness estimators, not true abundance.", 
            stringsAsFactors = FALSE)
    fits <- list(fit, analysis$abundance_fit, analysis$state_space_fit, 
        analysis$survival_detection_fit)
    fits <- fits[!vapply(fits, is.null, logical(1))]
    for (ff in fits) {
        if (inherits(ff, "resident_cjs_fit")) 
            next
        model <- ff$model_name %||% ff$abundance_model %||% "fitted_model"
        if (inherits(ff, "resident_robust_design_abundance_fit") && 
            !is.null(ff$primary_abundance)) 
            rows[[length(rows) + 1L]] <- .summarize_estimates(ff$primary_abundance$N_hat, 
                model, "model_based_primary_period_estimates", 
                "Robust-design estimates vary by primary period; interval shown is descriptive variation unless model intervals are stored.")
        else if (inherits(ff, "resident_open_population_fit") && 
            !is.null(ff$N_by_occasion)) {
            rows[[length(rows) + 1L]] <- .summarize_estimates(ff$N_by_occasion, 
                model, "model_based_occasion_estimates", "Open-population estimates vary by occasion; interval shown is descriptive variation unless model intervals are stored.")
            if (!is.null(ff$N_super_hat)) 
                rows[[length(rows) + 1L]] <- .summarize_estimates(ff$N_super_hat, 
                  paste0(model, "_N_super"), "model_based_superpopulation_estimate", 
                  "POPAN-like superpopulation estimate across the full study period.", 
                  "not_available")
        }
    }
    do.call(rbind, rows[!vapply(rows, is.null, logical(1))])
}
