compare_base_vs_tmb_likelihood <-
function (history, occasion_table, spec = state_space_specification(), 
    tolerance = 0.0001, ...) 
{
    base_fit <- fit_robust_design_cr(history, occasion_table, 
        spec, estimate_transition = FALSE, maxit = 200)
    if (!tmb_available()) {
        return(list(ok = NA, status = "TMB_not_installed", base_logLik = base_fit$logLik, 
            message = "TMB unavailable; equivalence check skipped."))
    }
    tmb_fit <- fit_robust_design_tmb(history, occasion_table, 
        spec, estimate_transition = FALSE, fallback = FALSE, 
        maxit = 200, ...)
    if (!is.finite(tmb_fit$logLik %||% NA_real_)) {
        return(list(ok = NA, status = tmb_fit$status %||% "TMB_fit_unavailable", 
            base_logLik = base_fit$logLik, tmb_logLik = tmb_fit$logLik %||% 
                NA_real_, abs_difference = NA_real_, tolerance = tolerance, 
            message = tmb_fit$message %||% "TMB fit did not return a finite likelihood."))
    }
    diff <- abs(base_fit$logLik - tmb_fit$logLik)
    list(ok = is.finite(diff) && diff < tolerance, base_logLik = base_fit$logLik, 
        tmb_logLik = tmb_fit$logLik, abs_difference = diff, tolerance = tolerance)
}
compare_base_vs_tmb_open_population <-
function (history, occasions = NULL, model = c("jolly_seber", 
    "POPAN_like"), tolerance = 0.0001, ...) 
{
    model <- match.arg(model)
    base <- if (model == "jolly_seber") 
        fit_jolly_seber_abundance(history, occasions, data_type = "simulation", 
            allow_synthetic_dates = TRUE, ...)
    else fit_popan_like_abundance(history, occasions, data_type = "simulation", 
        allow_synthetic_dates = TRUE, ...)
    tmb <- if (model == "jolly_seber") 
        fit_jolly_seber_tmb(history, occasions, ...)
    else fit_popan_like_tmb(history, occasions, ...)
    data.frame(ok = isTRUE(all.equal(base$logLik, tmb$logLik, 
        tolerance = tolerance)), base_logLik = base$logLik, tmb_logLik = tmb$logLik, 
        abs_difference = abs(base$logLik - tmb$logLik), tolerance = tolerance, 
        status = "fallback_equivalence_only_TMB_planned_not_active", 
        stringsAsFactors = FALSE)
}
compare_classification <-
function (indices, truth, column = "conway_general") 
{
    if (is.null(truth)) 
        return(NULL)
    x <- merge(indices[, c("id", column), drop = FALSE], truth, 
        by = "id", all.x = TRUE)
    predicted <- tolower(as.character(x[[column]])) %in% c("resident", 
        "permanent resident", "year-round resident", "common", 
        "frs", "hsr")
    x$predicted_resident <- predicted
    x$correct <- x$predicted_resident == x$true_resident
    x
}
