compare_model_list <-
function (fits) 
{
    rows <- lapply(fits, function(f) data.frame(model_name = f$model_name %||% 
        "model", parameter_formulas = f$parameter_formulas %||% 
        "", logLik = f$logLik %||% NA_real_, n_parameters = f$n_parameters %||% 
        NA_integer_, AIC = f$AIC %||% NA_real_, AICc = f$AICc %||% 
        NA_real_, BIC = f$BIC %||% NA_real_, convergence = f$convergence %||% 
        NA_integer_, diagnostics = f$error %||% f$warning %||% 
        "", stringsAsFactors = FALSE))
    tab <- do.call(rbind, rows)
    tab$delta_AIC <- tab$AIC - min(tab$AIC, na.rm = TRUE)
    w <- exp(-0.5 * tab$delta_AIC)
    tab$AIC_weight <- w/sum(w, na.rm = TRUE)
    tab$recommendation <- ifelse(tab$delta_AIC == 0, "top ranked by AIC", 
        "compare with diagnostics")
    tab[order(tab$AIC), ]
}
compare_residency_models <-
function (..., criterion = c("AIC", "AICc", "QAIC", "BIC"), chat = 1) 
{
    criterion <- match.arg(criterion)
    models <- list(...)
    if (!length(models)) 
        stop("Provide at least one fitted model.")
    tab <- do.call(rbind, lapply(seq_along(models), function(i) {
        fit <- models[[i]]
        nobs <- length(fit$history %||% fit$observed %||% numeric(0))
        met <- model_selection_metrics(fit$logLik, fit$npar %||% 
            length(fit$optim$par), nobs, chat)
        data.frame(model_id = names(models)[i] %||% paste0("model_", 
            i), model = fit$model, logLik = fit$logLik, npar = fit$npar %||% 
            length(fit$optim$par), AIC = met["AIC"], AICc = met["AICc"], 
            QAIC = met["QAIC"], BIC = met["BIC"], stringsAsFactors = FALSE)
    }))
    tab <- tab[order(tab[[criterion]]), ]
    tab$delta <- tab[[criterion]] - min(tab[[criterion]], na.rm = TRUE)
    tab$weight <- exp(-0.5 * tab$delta)/sum(exp(-0.5 * tab$delta))
    rownames(tab) <- NULL
    tab
}
compare_simulated_observed_summary <-
function (simulated, observed = NULL) 
{
    sim_s <- capture_data_summary(simulated)
    sim_dates <- as.Date((simulated$occasions %||% make_occasion_table(n_occasions = ncol(.history_from_object(simulated))))$date)
    sim_row <- data.frame(dataset = "simulated", observed_data_supplied = !is.null(observed), 
        N = sim_s$number_of_individuals, number_of_occasions = sim_s$number_of_sampling_occasions, 
        date_range = paste(min(sim_dates), max(sim_dates), sep = " to "), 
        total_capture_records = sim_s$total_capture_records, 
        min_captures_per_individual = sim_s$minimum_capture_records_per_individual, 
        max_captures_per_individual = sim_s$maximum_capture_records_per_individual, 
        mean_captures_per_individual = sim_s$mean_capture_records_per_individual, 
        median_captures_per_individual = sim_s$median_capture_records_per_individual, 
        number_of_singletons = sim_s$number_of_singletons, proportion_singletons = sim_s$proportion_singletons, 
        stringsAsFactors = FALSE)
    if (is.null(observed)) {
        sim_row$comparison_note <- "No observed comparison was requested; only the simulated summary is returned."
        return(sim_row)
    }
    obs_h <- .history_from_object(observed)
    obs_s <- capture_data_summary(obs_h)
    obs_dates <- if (is.list(observed) && !is.null(observed$occasions)) 
        as.Date(observed$occasions$date)
    else seq_len(ncol(obs_h))
    obs_row <- data.frame(dataset = "observed", observed_data_supplied = TRUE, 
        N = obs_s$number_of_individuals, number_of_occasions = obs_s$number_of_sampling_occasions, 
        date_range = paste(min(obs_dates), max(obs_dates), sep = " to "), 
        total_capture_records = obs_s$total_capture_records, 
        min_captures_per_individual = obs_s$minimum_capture_records_per_individual, 
        max_captures_per_individual = obs_s$maximum_capture_records_per_individual, 
        mean_captures_per_individual = obs_s$mean_capture_records_per_individual, 
        median_captures_per_individual = obs_s$median_capture_records_per_individual, 
        number_of_singletons = obs_s$number_of_singletons, proportion_singletons = obs_s$proportion_singletons, 
        stringsAsFactors = FALSE)
    out <- rbind(sim_row, obs_row)
    counts_differ <- sim_row$number_of_occasions != obs_row$number_of_occasions
    out$occasion_counts_differ <- counts_differ
    out$date_ranges_differ <- sim_row$date_range != obs_row$date_range
    out$capture_frequency_distributions_comparable <- !counts_differ
    out$singleton_difference_observed_minus_simulated <- obs_row$number_of_singletons - 
        sim_row$number_of_singletons
    out$maximum_capture_difference_observed_minus_simulated <- obs_row$max_captures_per_individual - 
        sim_row$max_captures_per_individual
    out$total_identification_difference_observed_minus_simulated <- obs_row$total_capture_records - 
        sim_row$total_capture_records
    out$discovery_curve_shape_comparison <- if (counts_differ) {
        "Summaries can be compared, but direct occasion-by-occasion discovery-curve comparison is not valid because occasion counts differ."
    }
    else {
        "Occasion counts match; discovery-curve shapes can be compared descriptively."
    }
    out$comparison_note <- "Comparison is descriptive; non-detection is not absence and capture count alone is not biological residency."
    out
}
