compare_true_and_estimated_abundance <-
function (sim, fit) 
{
    history <- sim$observed %||% sim$history %||% fit$history
    true_N <- sim$N %||% sim$true_N %||% if (!is.null(sim$latent)) 
        nrow(sim$latent)
    else NA_real_
    observed_n <- nrow(.observed_history(history))
    ch <- tryCatch(chao_discovery_estimates(.observed_history(history)), 
        error = function(e) NULL)
    data.frame(true_N = true_N, observed_n = observed_n, Chao1 = if (!is.null(ch)) 
        ch$estimate[ch$estimator == "Chao1"]
    else NA_real_, Chao2 = if (!is.null(ch)) 
        ch$estimate[ch$estimator == "Chao2"]
    else NA_real_, model_based_N_hat = fit$N_hat, Huggins_derived_N_hat = if (inherits(fit, 
        "resident_huggins_abundance_fit")) 
        fit$N_hat
    else NA_real_, bias = if (is.finite(true_N)) 
        fit$N_hat - true_N
    else NA_real_, relative_bias = if (is.finite(true_N) && true_N != 
        0) 
        (fit$N_hat - true_N)/true_N
    else NA_real_, convergence_status = fit$convergence, stringsAsFactors = FALSE)
}
compile_resident_tmb <-
function (source = NULL, verbose = FALSE) 
{
    source <- source %||% file.path(getwd(), "resident_tmb.cpp")
    if (!file.exists(source)) {
        alt <- file.path(dirname(source), "outputs", "resident_tmb.cpp")
        if (file.exists(alt)) 
            source <- alt
    }
    if (!tmb_available()) {
        return(list(ok = FALSE, status = "TMB_not_installed", 
            message = "TMB is not installed. Install with install.packages('TMB'); base backend remains available.", 
            source = source))
    }
    if (!file.exists(source)) {
        return(list(ok = FALSE, status = "source_not_found", 
            message = paste("Could not find TMB source file:", 
                source), source = source))
    }
    oldwd <- getwd()
    on.exit(setwd(oldwd), add = TRUE)
    setwd(dirname(source))
    res <- tryCatch({
        TMB::compile(basename(source), verbose = verbose)
        list(ok = TRUE, status = "compiled", source = source, 
            dynlib = TMB::dynlib(tools::file_path_sans_ext(basename(source))))
    }, error = function(e) {
        list(ok = FALSE, status = "compile_failed", source = source, 
            message = conditionMessage(e))
    })
    res
}
