configure_detection_model_from_assumption <-
function (option, config = simulation_parameter_defaults(), input_provider = NULL, 
    interactive = TRUE, custom_formula = NULL) 
{
    option <- validate_detection_covariate_assumptions(option, 
        config$detection_formula)$detection_covariate_assumptions
    config$detection_covariate_assumptions <- option
    config$detection_formula <- detection_assumption_to_formula(option, 
        custom_formula)
    if (option == "custom_formula" && is.null(config$detection_formula)) {
        f <- .resident_prompt_parameter("detection_formula", 
            "custom detection formula.", "valid one-sided R formula such as ~ effort + state", 
            NULL, input_provider, as.character, allow_default = FALSE)
        config$detection_formula <- stats::as.formula(f)
    }
    if (option == "custom_formula") {
        trm <- attr(stats::terms(config$detection_formula), "term.labels")
        beta_names <- c("(Intercept)", trm)
        old_beta <- config$beta %||% numeric()
        beta <- setNames(rep(0, length(beta_names)), beta_names)
        shared <- intersect(names(old_beta), beta_names)
        beta[shared] <- old_beta[shared]
        config$beta <- beta
    }
    if (option %in% c("constant", "effort", "effort_plus_state", 
        "effort_plus_individual_random_effect", "effort_plus_state_plus_individual_random_effect", 
        "effort_plus_primary_period_random_effect")) {
        p0 <- if (interactive) {
            .resident_prompt_parameter("baseline_detection_probability", 
                "baseline detection probability when covariates are at reference values.", 
                "probability strictly between 0 and 1", config$baseline_detection_probability %||% 
                  0.25, input_provider, function(x) .as_probability(x, 
                  "baseline_detection_probability"), advice = "Low values create many missed detections; high values make individuals easier to classify but may be unrealistic.")
        }
        else config$baseline_detection_probability %||% 0.25
        config$baseline_detection_probability <- p0
        config$beta <- c(`(Intercept)` = detection_probability_to_intercept(p0))
    }
    if (grepl("effort", option)) {
        eff <- if (interactive) {
            .resident_prompt_parameter("effort_detection_effect", 
                "logit-scale coefficient describing how effort changes detection probability.", 
                "finite numeric coefficient", config$effort_detection_effect %||% 
                  0, input_provider, as.numeric, advice = "Values near 0 mean little effort effect; values above 1 or below -1 can drive detection sharply toward 1 or 0.")
        }
        else config$effort_detection_effect %||% 0
        config$effort_detection_effect <- eff
        config$effort_variable_type <- if (interactive) 
            .resident_prompt_option("effort_variable_type", effort_variable_type_options(), 
                explain_effort_variable_type()$scientific_meaning, 
                config$effort_variable_type %||% "survey_duration", 
                input_provider)
        else config$effort_variable_type %||% "survey_duration"
        if (interactive) {
            config$effort_units <- prompt_effort_units_for_type(config$effort_variable_type, 
                default = if ((config$effort_units %||% "") %in% 
                  allowed_effort_units_for_type(config$effort_variable_type)) 
                  config$effort_units
                else allowed_effort_units_for_type(config$effort_variable_type)[1], 
                input_provider = input_provider)
        }
        else {
            config$effort_units <- config$effort_units %||% allowed_effort_units_for_type(config$effort_variable_type)[1]
        }
        if (config$effort_variable_type == "custom" || config$effort_units == 
            "custom") {
            if (interactive) {
                config$effort_custom_definition <- .resident_prompt_parameter("effort_custom_definition", 
                  "short definition of the custom effort covariate or units.", 
                  "non-empty character note", config$effort_custom_definition %||% 
                    NULL, input_provider, as.character, allow_default = nzchar(config$effort_custom_definition %||% 
                    ""))
            }
        }
        config$effort_scaling <- if (interactive) 
            .resident_prompt_option("effort_scaling", c("raw", 
                "mean_centered", "z_score", "min_max_0_1"), c("unscaled effort values; requires careful biological units", 
                "subtract the mean effort", "standardize to mean 0 and standard deviation 1", 
                "rescale between 0 and 1"), config$effort_scaling %||% 
                "z_score", input_provider)
        else config$effort_scaling %||% "z_score"
        if (interactive) 
            config <- prompt_effort_values_for_simulation(config, 
                input_provider)
        config$beta <- c(config$beta, effort = eff)
    }
    if (option %in% c("state", "effort_plus_state", "state_plus_individual_random_effect", 
        "effort_plus_state_plus_individual_random_effect")) {
        states <- config$states %||% simulation_parameter_defaults()$states
        unavailable <- config$unavailable_states %||% character()
        det <- config$state_detection %||% setNames(ifelse(states %in% 
            unavailable, 0, 0.25), states)
        det[intersect(names(det), unavailable)] <- 0
        if (interactive) {
            det_default <- paste(as.numeric(det[states]), collapse = ",")
            det <- prompt_state_detection_vector(states, unavailable, 
                input_provider, default = det_default, auto_zero_unavailable = TRUE)
        }
        config$state_detection <- det
    }
    re <- detection_random_effects_from_assumption(option)
    if (re$individual_detection) {
        config$sigma_individual_detection <- if (interactive) {
            .resident_prompt_parameter("sigma_individual_detection", 
                "standard deviation of persistent individual detection heterogeneity.", 
                "non-negative numeric value", config$sigma_individual_detection %||% 
                  config$individual_re_sd %||% 0.5, input_provider, 
                as.numeric, advice = "Values above 2 imply very strong heterogeneity; values above 5 are usually extreme.")
        }
        else config$sigma_individual_detection %||% config$individual_re_sd %||% 
            0.5
        config$individual_re_sd <- config$sigma_individual_detection
    }
    if (re$primary_detection) {
        config$sigma_primary_detection <- if (interactive) {
            .resident_prompt_parameter("sigma_primary_detection", 
                "standard deviation of primary-period detection variation.", 
                "non-negative numeric value", config$sigma_primary_detection %||% 
                  0.5, input_provider, as.numeric)
        }
        else config$sigma_primary_detection %||% 0.5
    }
    if (re$state_detection) {
        config$sigma_state_detection <- if (interactive) {
            .resident_prompt_parameter("sigma_state_detection", 
                "standard deviation of additional detection variation among states.", 
                "non-negative numeric value", config$sigma_state_detection %||% 
                  0.5, input_provider, as.numeric)
        }
        else config$sigma_state_detection %||% 0.5
    }
    config$detection_random_effects <- re
    config$detection_parameter_count <- detection_assumption_parameter_count(option, 
        length(config$states %||% simulation_parameter_defaults()$states))
    validate_detection_covariate_assumptions(option, config$detection_formula)
    config
}
configure_temporal_structure <-
function (history, occasions = NULL, model = "model", input_provider = NULL, 
    data_type = "empirical") 
{
    y <- coerce_history_matrix(history, stage = "configure temporal structure")
    n_occasions <- ncol(y)
    method <- ask_temporal_grouping_method(input_provider)
    if (identical(method, "cancel")) 
        return(NULL)
    if (identical(method, "define manually")) {
        primary <- ask_manual_primary_periods(n_occasions, input_provider)
        secondary <- ask_manual_secondary_periods(n_occasions, 
            input_provider)
        intervals <- rep(1, max(0, n_occasions - 1L))
        st <- list(primary_period = primary, secondary_period = secondary, 
            time_intervals = intervals, time_interval_scale = "equal intervals", 
            source = "manual", user_choice = method, diagnostics = temporal_structure_diagnostics(history, 
                occasions))
    }
    else if (identical(method, "use existing columns if available")) {
        st <- infer_primary_secondary_periods(history, occasions, 
            primary_method = "existing column", secondary_method = "existing column")
        st$source <- "existing_columns"
        st$user_choice <- method
    }
    else {
        primary_method <- .ask_temporal_choice("What are the primary periods?", 
            c("one primary period", "by day", "by week", "by month", 
                "by season", "by year", "existing column", "custom date ranges", 
                "manual vector"), input_provider, default = "by month")
        if (primary_method == "manual vector") {
            primary <- ask_manual_primary_periods(n_occasions, 
                input_provider)
            secondary <- ave(seq_len(n_occasions), primary, FUN = seq_along)
            st <- list(primary_period = primary, secondary_period = as.character(secondary), 
                time_intervals = rep(1, max(0, n_occasions - 
                  1L)), source = "manual", user_choice = primary_method, 
                diagnostics = temporal_structure_diagnostics(history, 
                  occasions))
        }
        else {
            secondary_method <- .ask_temporal_choice("What are the secondary periods?", 
                c("each occasion within primary period", "existing column", 
                  "fixed number per primary", "manual vector"), 
                input_provider, default = "each occasion within primary period")
            st <- infer_primary_secondary_periods(history, occasions, 
                primary_method = primary_method, secondary_method = if (secondary_method %in% 
                  c("manual vector", "fixed number per primary")) 
                  "each occasion within primary period"
                else secondary_method)
            st$user_choice <- paste(primary_method, secondary_method, 
                sep = "; ")
        }
    }
    st$time_interval_scale <- .ask_temporal_choice("What time interval scale should be used?", 
        c("equal intervals", "actual elapsed days", "user-specified intervals"), 
        input_provider, default = st$time_interval_scale %||% 
            "actual elapsed days")
    st$detection_structure <- .ask_temporal_choice("Should detection/capture probability vary by:", 
        c("constant", "occasion", "primary period", "secondary period", 
            "effort", "group", "state", "covariates"), input_provider, 
        default = "occasion")
    st$transition_structure <- .ask_temporal_choice("Should movement/migration/transition probabilities be:", 
        c("fixed", "estimated", "time-varying", "group-varying", 
            "covariate-dependent"), input_provider, default = "fixed")
    st$confirmed <- FALSE
    st$confirmed_at <- NA
    st$model_requiring_structure <- model
    validate_primary_secondary_periods(st, n_occasions)
    confirm_inferred_temporal_structure(st, model = model, input_provider = input_provider)
}
confirm_import_dates_if_needed <-
function (imported, validation, input_provider = NULL) 
{
    if (is.null(imported$occasions) || !"date" %in% names(imported$occasions)) 
        return(imported)
    dates <- suppressWarnings(as.Date(imported$occasions$date))
    if (!any(!is.na(dates))) 
        return(imported)
    if (identical(validation$date_status, "no_dates_in_file")) 
        return(imported)
    ans <- .resident_prompt("Do these dates come from real field survey dates? Enter 1 for yes or 0 for no: ", 
        input_provider)
    yes <- tryCatch(resident_parse_yes_no_10(ans), error = function(e) FALSE)
    attr(imported$occasions, "real_dates_confirmed") <- isTRUE(yes)
    imported$date_confirmation <- if (isTRUE(yes)) 
        "confirmed_real_survey_dates"
    else "not_confirmed_dates_hidden_in_summaries"
    if (isTRUE(yes)) 
        cat("Dates confirmed. Later summaries may display the initial and final sampling dates.\n")
    else cat("Dates not confirmed. Later summaries will hide dates to avoid reporting unverified field dates.\n")
    imported
}
