confirm_simulation_configuration <-
function (config, input_provider = NULL) 
{
    config <- validate_simulation_parameters(config)
    report_path <- NULL
    if (isTRUE(config$save_full_configuration_report %||% TRUE)) {
        report_path <- write_configuration_report_txt(config, 
            output_dir = "outputs")
        config$configuration_report_path <- report_path
    }
    print_compact_simulation_configuration_review(config)
    if (!is.null(report_path)) 
        cat("\nFull configuration report saved to:\n", report_path, 
            "\n", sep = "")
    if (isTRUE(config$show_full_configuration_in_console)) 
        print_full_simulation_configuration_review(config)
    ans <- .resident_prompt("Run simulation with this configuration? Enter 1 for yes or 0 for no: ", 
        input_provider)
    ans_ok <- tryCatch(resident_parse_yes_no_10(ans), error = function(e) {
        tolower(trimws(ans)) %in% c("yes", "y")
    })
    if (isTRUE(ans_ok)) {
        confirmed <- TRUE
        attr(confirmed, "configuration_report_path") <- report_path
        return(confirmed)
    }
    cat("Would you like to edit the configuration or exit?\n1. Edit configuration\n2. Exit without simulation\n")
    edit <- .resident_prompt("Enter option number or name: ", 
        input_provider)
    if (tolower(trimws(edit)) %in% c("1", "edit", "edit configuration")) 
        return(FALSE)
    structure(FALSE, action = "exit", configuration_report_path = report_path)
}
constrain_transition_matrix <-
function (matrix, transition_structure) 
{
    states <- transition_structure$states
    matrix <- validate_transition_matrix(matrix, states)
    free <- transition_structure$free
    if (!is.null(free) && any(!free)) 
        matrix[!free] <- transition_structure$fixed[!free]
    matrix <- sweep(matrix, 1, rowSums(matrix), "/")
    validate_transition_matrix(matrix, states)
}
convert_effort_effect_to_odds_ratio <-
function (coefficient) 
{
    coefficient <- as.numeric(coefficient)
    if (length(coefficient) != 1 || !is.finite(coefficient)) 
        stop("coefficient must be one finite numeric value.")
    exp(coefficient)
}
convert_mark_to_encounter_data <-
function (mark_history, occasion_dates) 
{
    names(mark_history) <- tolower(names(mark_history))
    if (!"frequency" %in% names(mark_history)) 
        mark_history$frequency <- 1L
    if (!all(c("id", "encounter_history", "frequency") %in% names(mark_history))) {
        stop("MARK data require id, encounter_history, and frequency columns.", 
            call. = FALSE)
    }
    if (is.null(occasion_dates)) 
        stop("MARK conversion requires an occasion-date table.", 
            call. = FALSE)
    names(occasion_dates) <- tolower(names(occasion_dates))
    if (!all(c("occasion", "date") %in% names(occasion_dates))) {
        stop("MARK occasion dates require occasion and date columns.", 
            call. = FALSE)
    }
    occasion_dates$date <- as.Date(occasion_dates$date)
    K <- nrow(occasion_dates)
    chars <- gsub("\\s+", "", as.character(mark_history$encounter_history))
    if (any(!grepl("^[01]+$", chars))) 
        stop("MARK encounter_history strings must contain only 0 and 1.", 
            call. = FALSE)
    if (any(nchar(chars) != K)) 
        stop("MARK encounter_history length must match number of occasion dates.", 
            call. = FALSE)
    expanded <- mark_history[rep(seq_len(nrow(mark_history)), 
        pmax(1L, as.integer(mark_history$frequency))), , drop = FALSE]
    expanded$id <- make.unique(as.character(expanded$id), sep = "_freq")
    chars <- gsub("\\s+", "", as.character(expanded$encounter_history))
    mat <- t(vapply(strsplit(chars, ""), as.numeric, numeric(K)))
    rownames(mat) <- expanded$id
    colnames(mat) <- as.character(occasion_dates$date)
    occ <- data.frame(occasion = occasion_dates$occasion, date = occasion_dates$date, 
        stringsAsFactors = FALSE)
    as_resident_encounter_data(mat, occ, raw = mark_history, 
        source = "Program MARK")
}
convert_socprog_to_encounter_data <-
function (x) 
{
    names(x) <- tolower(names(x))
    if (!all(c("id", "date") %in% names(x))) 
        stop("SocProg data require id and date columns.", call. = FALSE)
    x$date <- as.Date(x$date)
    duplicate_count <- sum(duplicated(x[, c("id", "date")]))
    x <- unique(x[, c("id", "date", intersect(c("group_id", "site", 
        "area", "effort", "sex", "age_class"), names(x))), drop = FALSE])
    ids <- sort(unique(as.character(x$id)))
    dates <- sort(unique(x$date))
    mat <- matrix(0, length(ids), length(dates), dimnames = list(ids, 
        as.character(dates)))
    for (i in seq_len(nrow(x))) mat[as.character(x$id[i]), as.character(x$date[i])] <- 1
    occ <- data.frame(occasion = seq_along(dates), date = dates, 
        stringsAsFactors = FALSE)
    if ("effort" %in% names(x)) {
        eff <- aggregate(x$effort, list(date = x$date), function(z) mean(as.numeric(z), 
            na.rm = TRUE))
        occ$effort <- eff$x[match(occ$date, eff$date)]
    }
    ed <- as_resident_encounter_data(mat, occ, raw = x, source = "SocProg")
    ed$validation$duplicate_id_date_records_collapsed <- duplicate_count
    ed
}
convert_wide_to_encounter_data <-
function (x, occasion_dates = NULL, allow_synthetic_dates = FALSE, 
    ...) 
{
    id_col <- intersect(c("id", "ID", "individual", "Individual"), 
        names(x))[1]
    if (is.na(id_col)) 
        id_col <- names(x)[1]
    hist_cols <- setdiff(names(x), id_col)
    parsed_dates <- suppressWarnings(as.Date(rep(NA_character_, 
        length(hist_cols))))
    for (ii in seq_along(hist_cols)) parsed_dates[ii] <- tryCatch(suppressWarnings(as.Date(hist_cols[ii])), 
        error = function(e) as.Date(NA))
    date_like <- !is.na(parsed_dates)
    if (!any(date_like, na.rm = TRUE) && is.null(occasion_dates) && 
        !isTRUE(allow_synthetic_dates)) 
        stop("Wide input requires date-like columns, an occasion-date file, or explicit synthetic testing dates.", 
            call. = FALSE)
    y <- as.matrix(x[, hist_cols, drop = FALSE])
    storage.mode(y) <- "numeric"
    rownames(y) <- x[[id_col]]
    dates <- if (!is.null(occasion_dates)) 
        as.Date(occasion_dates)
    else if (any(date_like, na.rm = TRUE)) 
        parsed_dates
    else resident_require_dates(NULL, TRUE, ncol(y))
    out <- as_resident_encounter_data(y, data.frame(occasion = seq_len(ncol(y)), 
        date = dates), raw = x, source = "wide", allow_synthetic_dates = allow_synthetic_dates)
    if (isTRUE(allow_synthetic_dates) && !any(date_like, na.rm = TRUE) && 
        is.null(occasion_dates)) {
        attr(out, "synthetic_dates_used") <- TRUE
        attr(out, "synthetic_date_warning") <- "Synthetic dates were created for testing/template validation and should not be used for scientific inference."
    }
    out
}
