data_diagnostic_assessment <-
function (fit, min_events_per_parameter = 5) 
{
    old <- reviewer_stress_test(fit, min_events_per_parameter)
    flags <- old$flags
    flags$diagnostic_interpretation <- flags$critique
    flags$diagnostic_interpretation[flags$item == "weak_identifiability" & 
        flags$flag != "green"] <- "The data do not contain enough information to estimate this model stably (technical detail: weak identifiability)."
    flags$diagnostic_interpretation[flags$item == "singular_hessian" & 
        flags$flag != "green"] <- "The uncertainty calculations are unstable because the model surface is too flat or poorly supported by the data (technical detail: singular Hessian)."
    flags$diagnostic_interpretation[flags$item == "unstable_transitions" & 
        flags$flag != "green"] <- "Some movement/residency transition estimates are very close to zero or one, which may mean the data cannot estimate them reliably."
    list(flags = flags[, c("item", "flag", "diagnostic_interpretation", 
        "recommendation")], data_and_model_reliable = !any(flags$flag == 
        "red"), interpretation_summary = if (any(flags$flag == 
        "red")) {
        "The current data/model combination is failing at least one important diagnostic check. Try a simpler model, more data, or stronger constraints."
    } else if (any(flags$flag == "yellow")) {
        "The current data/model combination has caution flags. Interpret results carefully and check profiles or bootstrap summaries."
    } else {
        "No major diagnostic warning was detected."
    }, recommended_simplifications = old$recommended_simplifications)
}
data_stress_test <-
function (...) 
data_diagnostic_assessment(...)
data_sufficiency_for_abundance <-
function (history, occasions = NULL) 
{
    y <- extract_history(history, stage = "abundance data sufficiency")
    freq <- rowSums(y)
    total <- sum(y)
    recaps <- sum(freq > 1)
    status <- if (total < 10 || recaps < 3 || ncol(y) < 2) 
        "fail"
    else if (total < 30 || recaps < 10) 
        "review"
    else "pass"
    data.frame(assumption = "data_sufficiency", diagnostic_value = paste0("detections=", 
        total, "; recaptured_ids=", recaps, "; occasions=", ncol(y)), 
        status = status, consequence = "Sparse data can make abundance estimates unstable and model-sensitive.", 
        recommendation = if (status == "pass") 
            "Likelihood abundance models may be considered."
        else "Prefer observed-only and Chao summaries; treat complex models cautiously.", 
        stringsAsFactors = FALSE)
}
decode_residency_states <-
function (fit) 
{
    rows <- lapply(names(fit$posterior), function(id) {
        gamma <- fit$posterior[[id]]$gamma
        state_id <- max.col(t(gamma), ties.method = "first")
        data.frame(id = id, occasion = seq_along(state_id), state_id = state_id, 
            state = fit$states[state_id], state_probability = apply(gamma, 
                2, max), stringsAsFactors = FALSE)
    })
    do.call(rbind, rows)
}
decode_robust_design_states <-
function (fit) 
{
    rows <- lapply(seq_len(dim(fit$rd_array$y)[1]), function(i) {
        fa <- forward_algorithm_robust_design(robust_design_individual_matrix(fit$rd_array, 
            i), fit$rd_array, fit$initial_probs, fit$transition_matrix, 
            fit$detection_design, fit$beta, fit$states, fit$spec$unavailable_states, 
            i)
        Kstate <- length(fit$states)
        Kp <- length(fa$scale)
        beta_b <- matrix(1, Kstate, Kp)
        if (Kp > 1) {
            for (k in (Kp - 1):1) {
                beta_b[, k] <- fit$transition_matrix %*% (fa$emission[, 
                  k + 1] * beta_b[, k + 1])
                beta_b[, k] <- beta_b[, k]/fa$scale[k + 1]
            }
        }
        gamma <- fa$alpha * beta_b
        gamma <- sweep(gamma, 2, colSums(gamma), "/")
        id <- dimnames(fit$rd_array$y)[[1]][i]
        data.frame(id = id, primary_index = seq_len(Kp), state = fit$states[max.col(t(gamma))], 
            state_probability = apply(gamma, 2, max), availability_probability = colSums(gamma[!(fit$states %in% 
                fit$spec$unavailable_states), , drop = FALSE]), 
            stringsAsFactors = FALSE)
    })
    do.call(rbind, rows)
}
