default_transition_matrix_by_timescale <-
function (states = c("unavailable", "visitor", "seasonal_resident", 
    "resident"), transition_time_scale = c("day", "week", "month", 
    "season", "year"), matrix_type = c("biologically_informed", 
    "conservative", "mobile")) 
{
    states <- validate_state_vector(states)
    transition_time_scale <- match.arg(transition_time_scale)
    matrix_type <- match.arg(matrix_type)
    K <- length(states)
    if (K != 4L) {
        diag_value <- switch(transition_time_scale, day = 0.98499999999999999, 
            week = 0.93000000000000005, month = 0.81999999999999995, 
            season = 0.75, year = 0.65000000000000002)
        mat <- diag(diag_value, K)
        mat <- mat + (1 - rowSums(mat))/K
        mat <- mat/rowSums(mat)
        mat <- .adjust_transition_persistence(mat, matrix_type)
        rownames(mat) <- colnames(mat) <- states
        return(.attach_transition_matrix_attributes(mat, transition_time_scale, 
            matrix_type))
    }
    values <- switch(transition_time_scale, day = c(0.98499999999999999, 
        0.014, 0.001, 0, 0.02, 0.94999999999999996, 0.028000000000000001, 
        0.002, 0.0050000000000000001, 0.02, 0.95999999999999996, 
        0.014999999999999999, 0.001, 0.0040000000000000001, 0.01, 
        0.98499999999999999), week = c(0.93999999999999995, 0.055, 
        0.0050000000000000001, 0, 0.12, 0.78000000000000003, 
        0.089999999999999997, 0.01, 0.029999999999999999, 0.070000000000000007, 
        0.83999999999999997, 0.059999999999999998, 0.01, 0.02, 
        0.040000000000000001, 0.93000000000000005), month = c(0.88, 
        0.10000000000000001, 0.02, 0, 0.25, 0.55000000000000004, 
        0.17999999999999999, 0.02, 0.080000000000000002, 0.14000000000000001, 
        0.69999999999999996, 0.080000000000000002, 0.029999999999999999, 
        0.040000000000000001, 0.080000000000000002, 0.84999999999999998), 
        season = c(0.83999999999999997, 0.13, 0.029999999999999999, 
            0, 0.29999999999999999, 0.45000000000000001, 0.22, 
            0.029999999999999999, 0.10000000000000001, 0.14999999999999999, 
            0.65000000000000002, 0.10000000000000001, 0.040000000000000001, 
            0.050000000000000003, 0.11, 0.80000000000000004), 
        year = c(0.75, 0.20000000000000001, 0.050000000000000003, 
            0, 0.34999999999999998, 0.34999999999999998, 0.25, 
            0.050000000000000003, 0.14999999999999999, 0.20000000000000001, 
            0.5, 0.14999999999999999, 0.080000000000000002, 0.070000000000000007, 
            0.14999999999999999, 0.69999999999999996))
    mat <- .row_stochastic_with_names(values, states, transition_time_scale, 
        "biologically_informed")
    mat <- .adjust_transition_persistence(mat, matrix_type)
    .attach_transition_matrix_attributes(mat, transition_time_scale, 
        matrix_type)
}
default_transition_matrix_interpretation <-
