derive_robust_design_parameters <-
function (fit) 
{
    states <- fit$states
    unav <- states %in% fit$spec$unavailable_states
    avail <- !unav
    trans <- fit$transition_matrix
    gamma_prime <- if (any(avail) && any(unav)) 
        mean(trans[avail, unav, drop = FALSE])
    else NA_real_
    gamma_double_prime <- if (any(unav) && any(avail)) 
        mean(trans[unav, avail, drop = FALSE])
    else NA_real_
    phi_apparent <- if (any(avail)) 
        mean(rowSums(trans[avail, avail, drop = FALSE]))
    else NA_real_
    availability <- NA_real_
    if (!is.null(fit$posterior)) {
        availability <- colMeans(do.call(rbind, lapply(fit$posterior, 
            function(p) {
                colSums(p$gamma[avail, , drop = FALSE])
            })))
    }
    else if (!is.null(fit$decoded_states) && "availability_probability" %in% 
        names(fit$decoded_states)) {
        availability <- stats::aggregate(availability_probability ~ 
            primary_index, fit$decoded_states, mean, na.rm = TRUE)$availability_probability
    }
    list(apparent_survival_or_persistence = phi_apparent, temporary_emigration_gamma_prime = gamma_prime, 
        temporary_immigration_gamma_double_prime = gamma_double_prime, 
        availability_by_occasion = availability)
}
derive_social_metrics <-
function (dat, id_col = "id", group_col = NULL, sighting_col = NULL) 
{
    if (is.null(group_col)) {
        group_col <- intersect(c("group_id", "sighting_id"), 
            names(dat))[1]
    }
    if (is.na(group_col) || is.null(group_col) || !(group_col %in% 
        names(dat))) {
        ids <- sort(unique(dat[[id_col]]))
        return(data.frame(id = ids, degree = NA_real_, strength = NA_real_, 
            n_associates = NA_real_, group_encounter_frequency = NA_real_, 
            stringsAsFactors = FALSE))
    }
    ids <- sort(unique(dat[[id_col]]))
    groups <- split(dat[[id_col]], dat[[group_col]])
    assoc <- matrix(0, nrow = length(ids), ncol = length(ids), 
        dimnames = list(ids, ids))
    group_count <- setNames(rep(0, length(ids)), ids)
    for (g in groups) {
        members <- unique(g)
        group_count[members] <- group_count[members] + 1
        if (length(members) > 1) {
            cmb <- utils::combn(members, 2)
            for (j in seq_len(ncol(cmb))) {
                assoc[cmb[1, j], cmb[2, j]] <- assoc[cmb[1, j], 
                  cmb[2, j]] + 1
                assoc[cmb[2, j], cmb[1, j]] <- assoc[cmb[2, j], 
                  cmb[1, j]] + 1
            }
        }
    }
    data.frame(id = ids, degree = rowSums(assoc > 0), strength = rowSums(assoc), 
        n_associates = rowSums(assoc > 0), group_encounter_frequency = as.numeric(group_count), 
        stringsAsFactors = FALSE)
}
