detect_abundance_data_format <-
function (data) 
{
    if (is.matrix(data)) 
        return("wide_history")
    if (!is.data.frame(data)) 
        return("unknown")
    nms <- tolower(names(data))
    if (all(c("id", "date") %in% nms)) 
        "socprog_long"
    else if (all(c("id", "encounter_history") %in% nms)) 
        "program_mark"
    else if ("id" %in% nms && any(vapply(data, function(z) all(z %in% 
        c(0, 1, TRUE, FALSE, NA)), logical(1)))) 
        "wide_history"
    else "unknown"
}
