detection_assumption_warning_rules <-
function (option, data = NULL, config = list()) 
{
    option <- normalize_detection_covariate_assumptions(option, 
        config$detection_formula)$detection_covariate_assumptions
    d <- .detection_data_diagnostics(data, config)
    warnings <- character()
    if (option == "constant" && isTRUE(d$effort_available)) {
        warnings <- c(warnings, "Effort information is available but ignored by the constant detection model.")
    }
    if (grepl("effort", option)) {
        if (!isTRUE(d$effort_available)) {
            warnings <- c(warnings, "The selected detection assumption requires effort, but no effort covariate was found.")
        }
        if (identical(config$effort_scaling, "raw") && abs(as.numeric(config$effort_detection_effect %||% 
            0)) > 0.5) {
            warnings <- c(warnings, "Raw effort scaling with a large coefficient can force detection probabilities near 0 or 1.")
        }
        if (abs(as.numeric(config$effort_detection_effect %||% 
            0)) > 2) {
            warnings <- c(warnings, "The effort_detection_effect value is large and may dominate the detection model.")
        }
        if (identical(config$effort_variable_type, "number_of_photographs")) {
            warnings <- c(warnings, "The number of photographs is not the same as photographic efficiency. If many images are unusable, use photographic_efficiency or a quality covariate instead of raw photograph count.")
        }
        if (identical(config$effort_variable_type, "number_of_photographed_individuals")) {
            warnings <- c(warnings, "The number of photographed individuals is not the same as individualization efficiency. If group size is known or estimated, individualization_efficiency or group_coverage_fraction may better represent photo-ID success.")
        }
        if (identical(config$effort_scaling, "raw") && !is.null(config$effort) && 
            any(abs(as.numeric(config$effort)) > 10, na.rm = TRUE)) {
            warnings <- c(warnings, "Raw effort values exceed 10; raw effort should usually be centered or standardized.")
        }
    }
    if (grepl("state", option) && !option %in% c("state_random_effect")) {
        sd <- config$state_detection
        un <- config$unavailable_states %||% character()
        if (!is.null(sd) && length(intersect(names(sd), un)) && 
            any(sd[intersect(names(sd), un)] != 0)) {
            warnings <- c(warnings, "Unavailable states must have zero detection probability.")
        }
        if (is.finite(d$number_of_detections) && d$number_of_detections < 
            5 * length(config$states %||% character())) {
            warnings <- c(warnings, "Few detections per state may confound state occupancy with detection.")
        }
    }
    if (option %in% c("individual_random_effect", "effort_plus_individual_random_effect", 
        "state_plus_individual_random_effect", "effort_plus_state_plus_individual_random_effect")) {
        if (!tmb_available()) 
            warnings <- c(warnings, "TMB is recommended for individual random-effect detection models.")
        if (is.finite(d$number_of_singletons) && is.finite(d$number_of_individuals) && 
            d$number_of_individuals > 0 && d$number_of_singletons/d$number_of_individuals > 
            0.40000000000000002) {
            warnings <- c(warnings, "Many individuals are detected only once; individual detection heterogeneity may be weakly identifiable.")
        }
    }
    if (option %in% c("primary_period_random_effect", "effort_plus_primary_period_random_effect")) {
        if (!tmb_available()) 
            warnings <- c(warnings, "TMB is recommended for primary-period random-effect detection models.")
        if (!is.finite(d$number_of_primary_periods) || d$number_of_primary_periods < 
            5) {
            warnings <- c(warnings, "Few primary periods make primary-period detection heterogeneity weakly identifiable.")
        }
    }
    if (option == "effort_plus_state_plus_individual_random_effect") {
        if ((is.finite(d$number_of_individuals) && d$number_of_individuals < 
            50) || (is.finite(d$number_of_detections) && d$number_of_detections < 
            200)) {
            warnings <- c(warnings, "This rich detection model is not recommended for sparse data; compare simpler models first.")
        }
    }
    if (option == "custom_formula") {
        warnings <- c(warnings, "Custom formulas require the user to verify covariates, scaling, beta names, and interpretation.")
    }
    unique(warnings)
}
detection_heterogeneity_check <-
function (history, occasions = NULL) 
{
    y <- extract_history(history, stage = "detection heterogeneity check")
    freq <- rowSums(y)
    cv <- if (mean(freq) > 0) 
        stats::sd(freq)/mean(freq)
    else NA_real_
    status <- if (is.na(cv)) 
        "fail"
    else if (cv < 0.75) 
        "pass"
    else if (cv < 1.5) 
        "review"
    else "fail"
    data.frame(assumption = "detection_heterogeneity", diagnostic_value = paste0("capture_count_cv=", 
        round(cv, 3)), status = status, consequence = "Strong heterogeneity can make abundance estimates sensitive to model choice.", 
        recommendation = if (status == "pass") 
            "Simple detection structures may be adequate."
        else "Compare heterogeneity-aware models and report uncertainty.", 
        stringsAsFactors = FALSE)
}
detection_identifiability_check <-
function (option, data = NULL, config = list()) 
{
    option <- normalize_detection_covariate_assumptions(option, 
        config$detection_formula)$detection_covariate_assumptions
    d <- .detection_data_diagnostics(data, config)
    h <- .capture_matrix_from_object(data %||% config$observed_data)
    detected_individuals <- if (is.null(h)) 
        NA_integer_
    else as.integer(sum(rowSums(h > 0, na.rm = TRUE) > 0))
    warnings <- detection_assumption_warning_rules(option, data, 
        config)
    pcount <- detection_assumption_parameter_count(option, length(config$states %||% 
        character()))
    score <- detection_model_data_support_score(option, data, 
        config)
    status <- if (length(warnings) >= 3 || score <= 2) {
        "not_supported"
    }
    else if (length(warnings) >= 2 || score <= 3) {
        "weakly_supported"
    }
    else if (length(warnings) == 1 || score <= 5) {
        "review_required"
    }
    else {
        "likely_supported"
    }
    data.frame(option_name = option, total_detections = d$number_of_detections, 
        number_of_individuals = d$number_of_individuals, number_of_detected_individuals = detected_individuals, 
        number_of_singletons = d$number_of_singletons, singleton_proportion = if (is.finite(d$number_of_individuals) && 
            d$number_of_individuals > 0) 
            d$number_of_singletons/d$number_of_individuals
        else NA_real_, number_of_primary_periods = d$number_of_primary_periods, 
        number_of_secondary_occasions = d$number_of_secondary_occasions, 
        number_of_detection_parameters = pcount, effort_available = d$effort_available, 
        missing_effort_values = d$missing_effort_values, random_effects_requested = any(unlist(detection_random_effects_from_assumption(option))), 
        tmb_available = tmb_available(), state_detection_confounded_with_state_occupancy = grepl("state", 
            option) && length(warnings) > 0, data_support_score = score, 
        diagnostic_status = status, warnings = paste(warnings, 
            collapse = " | "), stringsAsFactors = FALSE)
}
detection_identifiability_warning <-
function () 
{
    paste("Selecting a detection structure does not prove that the selected detection model is identifiable from the data.", 
        "Complex detection models require enough detections, repeated observations, primary periods, and covariate variation.", 
        "Before accepting a detection model, review convergence, diagnostic warnings, AIC/AICc/BIC, parameter uncertainty, boundary estimates, and biological plausibility.")
}
detection_model_data_support_score <-
function (option, data = NULL, config = list()) 
{
    option <- normalize_detection_covariate_assumptions(option, 
        config$detection_formula)$detection_covariate_assumptions
    d <- .detection_data_diagnostics(data, config)
    pcount <- detection_assumption_parameter_count(option, length(config$states %||% 
        character()))
    score <- 0L
    if (is.finite(d$number_of_detections) && d$number_of_detections >= 
        10 * pcount) 
        score <- score + 2L
    if (is.finite(d$number_of_detections) && d$number_of_detections >= 
        5 * pcount) 
        score <- score + 1L
    if (is.finite(d$number_of_individuals) && d$number_of_individuals >= 
        50) 
        score <- score + 1L
    if (is.finite(d$number_of_singletons) && is.finite(d$number_of_individuals) && 
        d$number_of_individuals > 0 && d$number_of_singletons/d$number_of_individuals <= 
        0.40000000000000002) 
        score <- score + 1L
    if (is.finite(d$number_of_primary_periods) && d$number_of_primary_periods >= 
        5) 
        score <- score + 1L
    if (!grepl("effort", option) || isTRUE(d$effort_available)) 
        score <- score + 1L
    if (!any(unlist(detection_random_effects_from_assumption(option))) || 
        tmb_available()) 
        score <- score + 1L
    score
}
detection_probability_to_intercept <-
function (p) 
{
    p <- as.numeric(p)
    if (length(p) != 1 || !is.finite(p) || p <= 0 || p >= 1) {
        stop("p must be a single probability strictly between 0 and 1 for logit conversion.")
    }
    stats::qlogis(p)
}
detection_random_effects_from_assumption <-
function (option) 
{
    option <- normalize_detection_covariate_assumptions(option)$detection_covariate_assumptions
    list(individual_detection = option %in% c("individual_random_effect", 
        "effort_plus_individual_random_effect", "state_plus_individual_random_effect", 
        "effort_plus_state_plus_individual_random_effect"), primary_detection = option %in% 
        c("primary_period_random_effect", "effort_plus_primary_period_random_effect"), 
        state_detection = option == "state_random_effect")
}
diagnose_detection_assumption <-
function (option, data = NULL, config = list()) 
{
    option <- normalize_detection_covariate_assumptions(option, 
        config$detection_formula)$detection_covariate_assumptions
    d <- .detection_data_diagnostics(data, config)
    warnings <- detection_assumption_warning_rules(option, data, 
        config)
    d$option_name <- option
    d$number_of_detection_parameters <- detection_assumption_parameter_count(option, 
        length(config$states %||% character()))
    d$random_effects_requested <- any(unlist(detection_random_effects_from_assumption(option)))
    d$tmb_available <- tmb_available()
    d$warnings <- paste(warnings, collapse = " | ")
    d$diagnostic_interpretation <- if (length(warnings)) 
        "Review warnings before using this detection model."
    else "No major detection-assumption warning was detected."
    d
}
diagnose_history_object <-
function (x) 
{
    data.frame(object_class = paste(class(x), collapse = "/"), 
        is_null = is.null(x), is_matrix = is.matrix(x), is_data_frame = is.data.frame(x), 
        is_list = is.list(x), nrow = if (!is.null(dim(x))) 
            nrow(x)
        else NA_integer_, ncol = if (!is.null(dim(x))) 
            ncol(x)
        else NA_integer_, is_summary_table = is_data_summary_table(x), 
        is_likely_history = is_likely_history_matrix(x), diagnostic_interpretation = if (is_data_summary_table(x)) {
            "Summary table detected; do not use this object as encounter history."
        }
        else if (is_likely_history_matrix(x)) {
            "Object appears compatible with binary encounter-history validation."
        }
        else {
            "Object requires conversion or a different accessor."
        }, stringsAsFactors = FALSE)
}
diagnose_identifiability <-
function (fit) 
{
    id <- validate_multistate_identifiability(fit)
    flags <- c()
    if (id$sparse_data) 
        flags <- c(flags, "too few detections per estimated parameter")
    if (id$singular_hessian) 
        flags <- c(flags, "singular or near-singular Hessian")
    if (id$boundary_estimate) 
        flags <- c(flags, "boundary-scale parameter estimates")
    if (!length(flags)) 
        flags <- "no major identifiability warning"
    list(metrics = id, flags = flags, suitable_for_inference = isTRUE(id$identifiable))
}
diagnose_random_effects <-
function (fit, boundary = 0.001) 
{
    tab <- fit$random_effect_summary
    if (is.null(tab) || !nrow(tab)) {
        return(data.frame(component = "none", flag = "not_estimated", 
            message = "No TMB random effects were estimated."))
    }
    data.frame(component = tab$component, flag = ifelse(tab$estimate < 
        boundary, "boundary_near_zero", "ok"), message = ifelse(tab$estimate < 
        boundary, "Random-effect variance is near zero; simplify or treat as weakly supported.", 
        "Random-effect variance is away from zero."), stringsAsFactors = FALSE)
}
diagnose_transition_identifiability <-
function (fit) 
{
    ts <- fit$transition_structure %||% transition_estimation_specification("fixed", 
        fit$states, fit$transition_matrix)
    tbl <- transition_estimate_table(fit)
    ess <- transition_effective_sample_size(fit$history, fit$occasion_table)
    ratio <- transition_parameter_data_ratio(fit)
    hdiag <- transition_hessian_diagnostics(fit)
    sparse <- ess$individuals_detected_at_least_twice < max(5, 
        transition_parameter_count(ts))
    weak_ratio <- ratio$detections_per_transition_parameter < 
        10
    rows <- tbl
    rows$identifiable_status <- ifelse(rows$fixed_or_estimated == 
        "fixed", "fixed", ifelse(sparse | weak_ratio | isFALSE(hdiag$positive_definite), 
        "weakly_estimable", rows$identifiable_status))
    warnings <- character()
    if (sparse) 
        warnings <- c(warnings, "Few individuals detected at least twice.")
    if (weak_ratio) 
        warnings <- c(warnings, "Too few detections per estimated transition parameter.")
    if (isFALSE(hdiag$positive_definite)) 
        warnings <- c(warnings, "Hessian is not positive definite.")
    if (any(rows$on_boundary)) 
        warnings <- c(warnings, "Some transition estimates are near boundary values.")
    warnings <- unique(warnings)
    identifiable <- length(warnings) == 0
    list(parameter_diagnostics = rows, effective_sample_size = ess, 
        parameter_data_ratio = ratio, hessian = hdiag, boundary = transition_boundary_diagnostics(fit$transition_matrix), 
        warnings = warnings, identifiable = identifiable, diagnostic_interpretation = if (identifiable) {
            "The available encounter-history data pass the implemented checks for estimating transition probabilities."
        } else {
            paste0("The available encounter-history data may not support all requested transition estimates. ", 
                "Consider a fixed transition matrix, a simpler constrained matrix, profile likelihood, bootstrap checks, or more repeated detections.")
        }, recommendation = if (length(warnings)) "Use fixed/sensitivity or constrained transition models before manuscript-level transition claims." else "Transition estimates pass implemented diagnostic checks.")
}
direct_abundance_fit <-
function (analysis, model) 
{
    tab <- safe_capture_recapture_table_from_analysis(analysis)
    history <- as.matrix(tab[, setdiff(names(tab), "individual_id"), 
        drop = FALSE])
    storage.mode(history) <- "numeric"
    counts <- rowSums(history, na.rm = TRUE)
    n_obs <- sum(counts > 0)
    if (model == "observed_only") {
        out <- list(model_name = model, abundance_model = model, 
            backend = "direct_v0.9.14", history = history, estimates = data.frame(parameter = c("n_observed", 
                "N"), estimate = c(n_obs, n_obs)), logLik = NA_real_, 
            convergence = 0L, message = "Observed count only; no likelihood was fitted.", 
            warning = "This is not corrected for missed individuals.")
        class(out) <- c("resident_direct_abundance_fit", "list")
        return(out)
    }
    if (model == "chao1_chao2") {
        est <- direct_chao_estimates(counts)
        out <- list(model_name = model, abundance_model = model, 
            backend = "direct_v0.9.14", history = history, estimates = data.frame(parameter = rownames(est), 
                estimate = est$estimate), logLik = NA_real_, 
            convergence = 0L, message = "Chao-style lower-bound estimate; no likelihood was fitted.", 
            warning = "Sensitive to singletons and doubletons.")
        class(out) <- c("resident_direct_abundance_fit", "list")
        return(out)
    }
    if (model %in% c("closed_M0", "closed_Mt", "closed_Mb", "closed_Mh_mixture", 
        "huggins_M0", "huggins_Mt")) 
        return(direct_closed_m0_fit(history, model))
    if (model %in% c("robust_design_closed_primary", "robust_design_huggins_primary")) {
        fit <- direct_closed_m0_fit(history, model)
        fit$warning <- paste("Direct v0.9.14 fallback fitted a simplified closed-capture likelihood after temporal-structure gating. This is not a full robust-design likelihood; use it as a diagnostic result until the full robust-design backend is supported for these data.")
        fit$temporal_structure <- analysis$temporal_structure %||% 
            NULL
        return(fit)
    }
    if (model %in% c("jolly_seber", "POPAN_like")) {
        first_seen <- apply(history == 1, 1, function(z) if (any(z)) 
            min(which(z))
        else NA_integer_)
        last_seen <- apply(history == 1, 1, function(z) if (any(z)) 
            max(which(z))
        else NA_integer_)
        est <- data.frame(parameter = c("n_observed", "entered_after_first_occasion", 
            "last_seen_before_final_occasion", "total_detection_records"), 
            estimate = c(n_obs, sum(!is.na(first_seen) & first_seen > 
                1L), sum(!is.na(last_seen) & last_seen < ncol(history)), 
                sum(history, na.rm = TRUE)))
        out <- list(model_name = model, abundance_model = model, 
            backend = "direct_v0.9.14_open_population_diagnostic", 
            history = history, estimates = est, logLik = NA_real_, 
            convergence = 0L, message = "Diagnostic open-population summary after temporal-structure gating; no full JS/POPAN likelihood was fitted.", 
            warning = "Use this as a diagnostic result only. Full Jolly-Seber/POPAN inference requires a supported open-population likelihood backend and adequate temporal recaptures.", 
            temporal_structure = analysis$temporal_structure %||% 
                NULL)
        class(out) <- c("resident_direct_abundance_fit", "list")
        return(out)
    }
    stop("No direct fitter is available for model: ", model, 
        call. = FALSE)
}
direct_chao_estimates <-
function (counts) 
{
    n_obs <- sum(counts > 0)
    f1 <- sum(counts == 1)
    f2 <- sum(counts == 2)
    chao1 <- if (f2 > 0) 
        n_obs + (f1 * f1)/(2 * f2)
    else n_obs + f1 * (f1 - 1)/2
    data.frame(estimate = c(n_observed = n_obs, chao1 = chao1, 
        singletons = f1, doubletons = f2), stringsAsFactors = FALSE)
}
direct_closed_m0_fit <-
function (history, model = "closed_M0") 
{
    y <- as.matrix(history)
    storage.mode(y) <- "numeric"
    captures <- rowSums(y, na.rm = TRUE)
    n_obs <- sum(captures > 0)
    K <- ncol(y)
    total <- sum(y, na.rm = TRUE)
    negloglik <- function(par) {
        log_f0 <- par[1]
        eta <- par[2]
        f0 <- exp(log_f0)
        N <- n_obs + f0
        p <- stats::plogis(eta)
        q0 <- (1 - p)^K
        if (!is.finite(N) || p <= 0 || p >= 1 || q0 <= 0 || q0 >= 
            1) 
            return(1.0000000000000002e+100)
        -(lgamma(N + 1) - lgamma(f0 + 1) + total * log(p) + (N * 
            K - total) * log(1 - p))
    }
    start_p <- min(max(total/max(n_obs * K, 1), 0.02), 0.97999999999999998)
    opt <- tryCatch(stats::optim(c(log(max(n_obs * 0.25, 0.10000000000000001)), 
        stats::qlogis(start_p)), negloglik, method = "BFGS", 
        control = list(maxit = 1000)), error = function(e) e)
    if (inherits(opt, "error")) 
        stop(conditionMessage(opt), call. = FALSE)
    f0 <- exp(opt$par[1])
    p_hat <- stats::plogis(opt$par[2])
    N_hat <- n_obs + f0
    out <- list(model_name = model, abundance_model = model, 
        backend = "direct_v0.9.14", history = y, estimates = data.frame(parameter = c("N", 
            "n_observed", "f0", "p"), estimate = c(N_hat, n_obs, 
            f0, p_hat)), logLik = -opt$value, convergence = opt$convergence, 
        message = opt$message %||% "", warning = if (model != 
            "closed_M0") paste(model, "is using the direct closed_M0 fallback likelihood; interpret as a simplified approximation.") else "")
    class(out) <- c("resident_direct_abundance_fit", "list")
    out
}
discovery_curve_table <-
function (x, occasion_table = NULL, id_col = "id", date_col = "date") 
{
    if (is.data.frame(x) && all(c(id_col, date_col) %in% names(x))) {
        dat <- x
        dat[[date_col]] <- as.Date(dat[[date_col]])
        dates <- sort(unique(dat[[date_col]]))
        ids <- sort(unique(dat[[id_col]]))
        history <- matrix(0L, nrow = length(ids), ncol = length(dates), 
            dimnames = list(ids, as.character(dates)))
        ij <- cbind(match(dat[[id_col]], ids), match(dat[[date_col]], 
            dates))
        history[ij] <- 1L
        occasion_table <- make_occasion_table(dates = dates)
    }
    else if (is.list(x) && !is.null(x$history)) {
        history <- as_binary_matrix(x$history)
        occasion_table <- x$occasions %||% occasion_table
    }
    else if (is.list(x) && !is.null(x$observed)) {
        history <- as_binary_matrix(x$observed)
        occasion_table <- x$occasions %||% occasion_table
    }
    else {
        history <- as_binary_matrix(x)
    }
    if (is.null(occasion_table)) 
        occasion_table <- make_occasion_table(n_occasions = ncol(history))
    seen_before <- rep(FALSE, nrow(history))
    total_ids <- colSums(history, na.rm = TRUE)
    new_ids <- integer(ncol(history))
    for (j in seq_len(ncol(history))) {
        seen_now <- history[, j] > 0
        new_ids[j] <- sum(seen_now & !seen_before)
        seen_before <- seen_before | seen_now
    }
    cumulative_new <- cumsum(new_ids)
    total_ind <- max(cumulative_new, 1)
    data.frame(sampling_occasion = seq_len(ncol(history)), date = as.Date(occasion_table$date), 
        total_identifications_on_occasion = as.integer(total_ids), 
        cumulative_identifications = as.integer(cumsum(total_ids)), 
        new_individuals_on_occasion = as.integer(new_ids), cumulative_new_individuals = as.integer(cumulative_new), 
        cumulative_individuals = as.integer(cumulative_new), 
        proportion_of_total_individuals_discovered = cumulative_new/total_ind, 
        stringsAsFactors = FALSE)
}
discovery_threshold_date <-
function (tab, threshold) 
{
    idx <- which(tab$proportion_of_total_individuals_discovered >= 
        threshold)[1]
    if (is.na(idx)) 
        as.Date(NA)
    else tab$date[idx]
}
