duplicate_function_report <-
function (file = "outputs/resident_pipeline_v0.9.0.R") 
{
    audit <- audit_duplicate_function_definitions(file, from_marker = FALSE)
    if (!nrow(audit)) {
        return(data.frame(function_name = character(), number_of_definitions = integer(), 
            line_numbers = character(), core_function = logical(), 
            recommended_action = character()))
    }
    counts <- table(audit$function_name)
    dup_names <- names(counts[counts > 1L])
    if (!length(dup_names)) {
        return(data.frame(function_name = character(), number_of_definitions = integer(), 
            line_numbers = character(), core_function = logical(), 
            recommended_action = character()))
    }
    do.call(rbind, lapply(dup_names, function(nm) {
        rows <- audit[audit$function_name == nm, , drop = FALSE]
        data.frame(function_name = nm, number_of_definitions = nrow(rows), 
            line_numbers = paste(rows$line_number, collapse = ", "), 
            core_function = any(rows$core_function), recommended_action = if (any(rows$core_function)) 
                "Keep one canonical implementation; rename wrappers uniquely."
            else "Review duplicate helper definitions.", stringsAsFactors = FALSE)
    }))
}
effort_effect_consequence_summary <-
function (beta, baseline_detection_probability = 0.25, effort_scaling = "z_score", 
    effort_values = NULL) 
{
    cls <- classify_effort_detection_effect(beta)
    or <- exp(as.numeric(beta))
    ptab <- effort_effect_probability_table(beta, baseline_detection_probability)
    p1 <- ptab$detection_probability[ptab$standardized_effort == 
        1]
    msg <- paste0("effort_detection_effect = ", beta, " is classified as ", 
        cls, ". One unit more effort multiplies detection odds by exp(", 
        beta, ") = ", round(or, 3), ". With baseline detection ", 
        baseline_detection_probability, ", predicted detection is about ", 
        round(p1, 3), " at one standardized effort unit above average.")
    warns <- character()
    if (abs(beta) > 2) 
        warns <- c(warns, "Review effort scale and biological justification because absolute beta is greater than 2.")
    if (abs(beta) > 5) 
        warns <- c(warns, "Extreme effort effect requires confirmation.")
    if (identical(effort_scaling, "raw") && abs(beta) > 0.5) {
        warns <- c(warns, "Raw effort units with absolute beta greater than 0.5 may create unrealistic detection probabilities if effort values are large.")
    }
    if (identical(effort_scaling, "raw") && !is.null(effort_values) && 
        any(abs(as.numeric(effort_values)) > 10, na.rm = TRUE)) {
        warns <- c(warns, "Raw effort values exceed 10; raw effort should usually be centered or standardized.")
    }
    paste(c(msg, warns), collapse = " ")
}
effort_effect_probability_table <-
function (beta, baseline_detection_probability = 0.25, effort_values = c(-2, 
    -1, 0, 1, 2)) 
{
    beta <- as.numeric(beta)
    p0 <- as.numeric(baseline_detection_probability)
    if (length(beta) != 1 || !is.finite(beta)) 
        stop("beta must be one finite numeric value.")
    if (length(p0) != 1 || !is.finite(p0) || p0 <= 0 || p0 >= 
        1) {
        stop("baseline_detection_probability must be strictly between 0 and 1.")
    }
    data.frame(standardized_effort = effort_values, detection_probability = stats::plogis(stats::qlogis(p0) + 
        beta * effort_values), stringsAsFactors = FALSE)
}
