emission_matrix <-
function (observed, detection_prob, effort = NULL, effort_beta = 0) 
{
    observed <- as.integer(observed)
    K <- length(detection_prob)
    Tn <- length(observed)
    if (is.null(effort)) 
        effort <- rep(0, Tn)
    effort <- as.numeric(scale(effort))
    effort[!is.finite(effort)] <- 0
    p <- matrix(0, nrow = K, ncol = Tn)
    for (k in seq_len(K)) {
        if (detection_prob[k] <= 0) {
            p[k, ] <- 0
        }
        else {
            eta <- logit(pmin(1 - 1e-08, pmax(1e-08, detection_prob[k]))) + 
                effort_beta * effort
            p[k, ] <- inv_logit(eta)
        }
    }
    out <- matrix(0, nrow = K, ncol = Tn)
    for (t in seq_len(Tn)) {
        out[, t] <- if (observed[t] > 0) 
            p[, t]
        else 1 - p[, t]
    }
    pmax(out, 9.9999999999999936e-301)
}
emission_matrix_regression <-
function (observed, detection_design, beta, states, unavailable_states, 
    individual_index) 
{
    Tn <- length(observed)
    rows <- detection_design$data$individual_index == individual_index
    X <- detection_design$X[rows, , drop = FALSE]
    beta_vec <- rep(0, ncol(X))
    names(beta_vec) <- colnames(X)
    beta_vec[intersect(names(beta), names(beta_vec))] <- beta[intersect(names(beta), 
        names(beta_vec))]
    eta <- as.vector(X %*% beta_vec)
    base_p <- inv_logit(eta)
    K <- length(states)
    p <- matrix(rep(base_p, each = K), nrow = K)
    p[states %in% unavailable_states, ] <- 0
    out <- matrix(0, K, Tn)
    for (t in seq_len(Tn)) out[, t] <- if (observed[t] > 0) 
        p[, t]
    else 1 - p[, t]
    pmax(out, 9.9999999999999936e-301)
}
