function (analysis) 
{
    path <- analysis$configuration_report_path %||% analysis$config$configuration_report_path %||% 
        NULL
    if (!is.null(path) && nzchar(path) && file.exists(path)) 
        return(path)
    outdir <- analysis$run_output_dir %||% current_run_output_dir()
    dir.create(outdir, recursive = TRUE, showWarnings = FALSE)
    path <- file.path(outdir, paste0("configuration_report_", 
        format(Sys.time(), "%Y-%m-%d_%H%M%S"), ".txt"))
    lines <- c("Resident Pipeline configuration report", paste("version:", 
        resident_active_version()), paste("created:", Sys.time()), 
        "", "Capture data summary:", capture.output(print_capture_data_summary(analysis_capture_data_summary(analysis))))
    writeLines(lines, path)
    path
}
ensure_discovery_curve_table <-
function (analysis) 
{
    tab <- analysis$discovery_curve_table %||% NULL
    if (is.null(tab) || !is.data.frame(tab) || !nrow(tab)) {
        history <- tryCatch(extract_history(analysis, stage = "discovery curve"), 
            error = function(e) NULL)
        if (is.null(history)) 
            history <- tryCatch(capture_recapture_table_from_analysis(analysis), 
                error = function(e) analysis$observed)
        occasions <- tryCatch(extract_occasions(analysis, stage = "discovery curve"), 
            error = function(e) NULL)
        if (is.null(occasions)) 
            occasions <- tryCatch(analysis_occasion_table(analysis), 
                error = function(e) analysis$occasions)
        tab <- discovery_curve_table(history, occasions)
    }
    analysis$discovery_curve_table <- tab
    analysis
}
ensure_literature_residency_outputs <-
function (analysis) 
{
    if (is.null(analysis)) 
        stop("Cannot compute residency classifications because analysis is missing.", 
            call. = FALSE)
    classification <- safe_individual_residency_table(analysis)
    if (is.null(classification) || !is.data.frame(classification) || 
        !nrow(classification) || !"classifier_basis" %in% names(classification)) {
        metrics <- literature_residency_metrics_table(analysis)
        classification <- resident_literature_classification_table(analysis)
        primary_summary <- resident_literature_category_summary(classification)
        classifier_summary <- literature_classifier_summary_long(classification)
        analysis$literature_metrics <- metrics
        analysis$literature_residency_metrics <- metrics
        analysis$literature_residency_classification <- classification
        analysis$individual_residency_classification <- classification
        analysis$residency_classification <- classification
        analysis$primary_residency_category_summary <- primary_summary
        analysis$literature_classifier_summary <- classifier_summary
        analysis$residency_category_proportions <- classifier_summary
        analysis$category_proportions <- classifier_summary
        analysis$primary_classifier_recommendation <- recommend_primary_classifier(analysis, 
            metrics)
        analysis$primary_classifier_scores <- analysis$primary_classifier_recommendation$scores
        analysis$primary_classifier_temporal_diagnostics <- analysis$primary_classifier_recommendation$temporal_diagnostics
        analysis$residency_outputs_source <- "literature_based_from_encounter_history_v0.9.36"
    }
    analysis
}
