ensure_residency_outputs_for_comparison <-
function (analysis) 
{
    if (is.null(analysis)) 
        stop("Cannot compare residency outputs because analysis is missing.")
    has_history <- FALSE
    tryCatch({
        .analysis_history(analysis)
        has_history <- TRUE
    }, error = function(e) NULL)
    if (!has_history) {
        stop("Cannot compare residency outputs because no encounter-history table was found. Expected analysis$sim$observed or analysis$observed.")
    }
    if (is.null(analysis$fit) && !is.null(analysis$sim)) {
        warning("No fitted residency model was found. The comparison will use simulated truth/provisional observed summaries and should not be interpreted as fitted model-based inference.")
    }
    if (is.null(analysis$residency_results)) {
        analysis$residency_results <- model_based_residency_results(analysis)
    }
    if (is.null(analysis$individual_residency_classification)) {
        analysis$individual_residency_classification <- individual_residency_classification(analysis)
    }
    if (is.null(analysis$residency_class_summary)) {
        analysis$residency_class_summary <- residency_class_summary(analysis)
    }
    if (is.null(analysis$literature_metrics)) {
        analysis$literature_metrics <- literature_residency_metrics_table(analysis)
    }
    analysis
}
ensure_temporal_structure <-
function (analysis = NULL, history = NULL, occasions = NULL, 
    model = "model", input_provider = NULL, data_type = NULL, 
    temporal_structure = NULL) 
{
    y <- history %||% if (!is.null(analysis)) 
        extract_history(analysis, stage = "temporal gate")
    else NULL
    occ <- occasions %||% if (!is.null(analysis)) 
        tryCatch(extract_occasions(analysis, stage = "temporal gate"), 
            error = function(e) NULL)
    else NULL
    data_type <- data_type %||% analysis$data_type %||% if (!is.null(analysis$sim)) 
        "simulation"
    else "empirical"
    st <- temporal_structure %||% analysis$temporal_structure %||% 
        NULL
    if (!is.null(st)) {
        assert_temporal_structure_available(st, model, ncol(coerce_history_matrix(y)))
        return(st)
    }
    if (identical(data_type, "simulation")) {
        st <- infer_primary_secondary_periods(y, occ)
        st$source <- "simulation_configuration"
        st$confirmed <- TRUE
        st$confirmed_at <- Sys.time()
        st$model_requiring_structure <- model
        return(st)
    }
    if (is.null(input_provider)) 
        stop(temporal_structure_gate_error(model), call. = FALSE)
    st <- configure_temporal_structure(y, occ, model = model, 
        input_provider = input_provider, data_type = data_type)
    if (is.null(st)) 
        stop("Temporal-structure configuration was cancelled before fitting.", 
            call. = FALSE)
    st
}
