estimate_detection_probability <-
function (history, posterior = NULL, states = default_residency_states()) 
{
    history <- as_binary_matrix(history)
    if (is.null(posterior)) {
        return(sum(history)/length(history))
    }
    K <- length(states)
    numer <- denom <- numeric(K)
    for (i in safe_seq_rows(history, context = "validated history row loop")) {
        gamma <- posterior[[i]]$gamma
        numer <- numer + rowSums(sweep(gamma, 2, history[i, ], 
            "*"))
        denom <- denom + rowSums(gamma)
    }
    out <- numer/denom
    out[1] <- 0
    names(out) <- states
    out
}
estimate_transition_matrix <-
function (par, transition_structure) 
{
    states <- transition_structure$states
    K <- length(states)
    if (transition_structure$structure == "fixed") 
        return(transition_structure$fixed)
    out <- transition_structure$fixed
    pos <- 1L
    for (r in seq_len(K)) {
        free_cols <- which(transition_structure$free[r, ])
        if (length(free_cols) <= 1) 
            next
        eta <- c(par[pos:(pos + length(free_cols) - 2)], 0)
        pos <- pos + length(free_cols) - 1
        fixed_mass <- sum(out[r, !transition_structure$free[r, 
            ]])
        out[r, free_cols] <- (1 - fixed_mass) * softmax(eta)
    }
    constrain_transition_matrix(out, transition_structure)
}
