expected_model_specific_pattern <-
function (config) 
{
    config <- validate_simulation_parameters(config)
    data.frame(simulation_model = config$simulation_model, expected_model_specific_pattern = switch(config$simulation_model, 
        closed = paste("Closed model: approximate capture-count pattern follows", 
            config$recapture_distribution, "; allow_zero =", 
            config$allow_zero, "controls whether never-detected theoretical individuals are possible."), 
        jolly_seber = paste("Jolly-Seber model: p controls detection, phi controls apparent survival/persistence, entry mode is", 
            config$entry_probability_mode, "; never-detected individuals depend on p, entry timing, and drop_never_detected."), 
        latent_residency = paste("Latent residency model: dominant states depend on initial_probs and transition behavior; state_detection controls which states are easier to observe. The transition matrix represents", 
            config$transition_time_scale, "model time steps and should be treated as a starting assumption unless locally estimated."), 
        state_space_robust_design = paste("State-space robust design: primary/secondary structure controls availability summaries; unavailable states have zero detection; beta coefficients control detection through logistic regression. The transition matrix represents", 
            config$transition_time_scale, "model time steps and time scale must be reviewed because daily, monthly, seasonal, and yearly transitions imply different biological movement rates.")), 
        stringsAsFactors = FALSE)
}
expected_recapture_distribution_summary <-
function (config) 
{
    set.seed(config$seed)
    counts <- generate_recapture_counts(10000, config$rmax, config$recapture_distribution, 
        config$recapture_params, config$allow_zero)
    data.frame(recapture_distribution = config$recapture_distribution, 
        approximate_mean_capture_records = mean(counts), approximate_median_capture_records = stats::median(counts), 
        approximate_singleton_probability = mean(counts == 1), 
        approximate_zero_record_probability = mean(counts == 
            0), qualitative_skewness = if (mean(counts) > stats::median(counts)) 
            "right-skewed or heterogeneous"
        else "approximately symmetric", interpretation = paste("Expected pattern is approximate and based on the selected", 
            config$recapture_distribution, "recapture-count distribution."), 
        stringsAsFactors = FALSE)
}
expected_sampling_effort_summary <-
function (config) 
{
    config <- validate_simulation_parameters(config)
    data.frame(requested_number_of_sampling_occasions = config$requested_number_of_sampling_occasions, 
        possible_number_of_dates = config$possible_number_of_dates, 
        actual_number_of_sampling_occasions = config$actual_number_of_sampling_occasions, 
        sampling_design = config$sampling_design, reason_actual_differs_from_requested = config$reason_actual_differs_from_requested, 
        primary_periods = length(unique(.primary_ids(config$selected_sampling_dates, 
            config$primary_period))), expected_effect = .sampling_difference_reason(config), 
        stringsAsFactors = FALSE)
}
expected_simulation_pattern <-
function (config) 
{
    config <- validate_simulation_parameters(config)
    rec <- expected_recapture_distribution_summary(config)
    eff <- expected_sampling_effort_summary(config)
    approx_total <- if (config$simulation_model == "closed") {
        config$N * rec$approximate_mean_capture_records
    }
    else {
        config$N * eff$actual_number_of_sampling_occasions * 
            config$p * 0.5
    }
    cbind(data.frame(simulation_model = config$simulation_model, 
        expected_number_of_individuals = config$N, requested_number_of_sampling_occasions = config$requested_number_of_sampling_occasions, 
        possible_number_of_dates = config$possible_number_of_dates, 
        actual_number_of_sampling_occasions = config$actual_number_of_sampling_occasions, 
        approximate_expected_total_identifications = round(approx_total, 
            1), approximate_expected_singletons = round(config$N * 
            rec$approximate_singleton_probability, 1), expected_recapture_pattern = rec$interpretation, 
        expected_sampling_effect = eff$expected_effect, expected_detection_effect = if (config$simulation_model == 
            "state_space_robust_design") {
            paste("Detection is controlled by beta coefficients through", 
                deparse(config$detection_formula), "not directly by scalar p.")
        }
        else if (config$p < 0.050000000000000003) 
            "very low detection; many available individuals may be missed"
        else if (config$p > 0.80000000000000004) 
            "very high detection; simulated analysis may be easier than many field studies"
        else "moderate detection; non-detection should not be interpreted as absence", 
        expected_zero_capture_effect = if (isTRUE(config$allow_zero)) 
            "zero-capture individuals may exist in the theoretical population"
        else "the simulated dataset is conditioned on every individual being seen at least once", 
        stringsAsFactors = FALSE), expected_model_specific_pattern(config)["expected_model_specific_pattern"])
}
