explain_parameter_before_prompt <-
function (parameter, config = NULL) 
{
    key <- .parameter_key(parameter)
    if (key == "detection_covariate_assumptions") {
        print_detection_assumption_options()
        return(invisible(detection_assumption_metadata()))
    }
    if (key == "effort_detection_effect") {
        info <- tryCatch(parameter_metadata(parameter), error = function(e) NULL)
        if (!is.null(info) && nrow(info)) {
            cat("\nParameter:", info$parameter[1], "\n")
            cat("Scientific meaning:", info$scientific_meaning[1], 
                "\n")
            cat("Accepted values:", info$accepted_values[1], 
                "\n")
            cat("Mathematical range:", info$mathematical_range[1], 
                "\n")
            cat("Recommended practical range:", info$recommended_range[1], 
                "\n")
            cat("Units:", info$units[1], "\n")
            cat("Scale:", info$scale[1], "\n")
            cat("Extreme-value warning:", info$extreme_value_warning[1], 
                "\n")
        }
        cat("\nEffort-effect range table:\n")
        print(effort_effect_range_table(), row.names = FALSE)
        cat("\nExample using baseline_detection_probability = 0.25 and effort_detection_effect = 0.5:\n")
        explain_effort_detection_effect(0.5, 0.25)
        return(invisible(info))
    }
    if (key == "sigma_individual_detection") {
        explain_sigma_individual_detection((config %||% list())$sigma_individual_detection %||% 
            0)
        return(invisible(sigma_individual_detection_range_table()))
    }
    info <- tryCatch(parameter_metadata(parameter), error = function(e) NULL)
    if (is.null(info) || !nrow(info)) 
        return(invisible(NULL))
    cat("\nParameter:", info$parameter[1], "\n")
    cat("Scientific meaning:", info$scientific_meaning[1], "\n")
    cat("Accepted values:", info$accepted_values[1], "\n")
    cat("Mathematical range:", info$mathematical_range[1], "\n")
    cat("Recommended practical range:", info$recommended_range[1], 
        "\n")
    cat("Default:", info$default_value[1], "\n")
    cat("Units:", info$units[1], "\n")
    cat("Scale:", info$scale[1], "\n")
    cat("Computational role:", info$computational_role[1], "\n")
    cat("Consequence summary:", info$low_value_consequence[1], 
        info$high_value_consequence[1], "\n")
    cat("Extreme-value warning:", info$extreme_value_warning[1], 
        "\n")
    cat("Recommendation when unsure:", info$recommendation_when_unsure[1], 
        "\n")
    invisible(info)
}
