explain_state_detection <-
function (states = default_residency_states(), state_detection = c(outside = 0, 
    peripheral_user = 0.14999999999999999, seasonal_resident = 0.34999999999999998, 
    core_resident = 0.55000000000000004), unavailable_states = "outside") 
{
    states <- as.character(states)
    det <- as.numeric(state_detection[states] %||% state_detection)
    if (length(det) != length(states)) 
        det <- rep(NA_real_, length(states))
    names(det) <- states
    cat("\nState order matters. The values you enter will be assigned in this exact order.\n")
    cat("The first value is assigned to the first state, the second value to the second state, and so on.\n")
    cat("The values are not sorted or matched by size. Unavailable states should be 0 because unavailable animals cannot be detected.\n")
    cat("Higher detection values for resident/core states mean those states are easier to observe.\n\n")
    cat("Default state order:\n")
    for (i in seq_along(states)) cat(i, ". ", states[i], "\n", 
        sep = "")
    cat("\nDefault state_detection:\n")
    for (s in states) cat(s, " = ", det[s], "\n", sep = "")
    invisible(data.frame(state = states, state_detection = det, 
        unavailable = states %in% unavailable_states))
}
