export_abundance_outputs <-
function (fit, output_dir = "outputs") 
{
    if (!dir.exists(output_dir)) 
        dir.create(output_dir, recursive = TRUE)
    paths <- c(summary = .timestamped_output_path("abundance_summary", 
        "csv", output_dir), parameter = .timestamped_output_path("mark_style_parameter_table", 
        "csv", output_dir), derived = .timestamped_output_path("mark_style_derived_parameter_table", 
        "csv", output_dir))
    write.csv(print_abundance_summary(fit, print = FALSE), paths["summary"], 
        row.names = FALSE)
    write.csv(mark_style_parameter_table(fit), paths["parameter"], 
        row.names = FALSE)
    write.csv(mark_style_derived_parameter_table(fit), paths["derived"], 
        row.names = FALSE)
    paths
}
export_all_post_simulation_outputs <-
