extract_history <-
function (x, stage = "extract_history") 
{
    if (is_resident_encounter_data(x)) 
        return(validate_history_matrix(x$history, stage = stage))
    if (is.matrix(x) || is.data.frame(x)) 
        return(validate_history_matrix(x, stage = stage))
    if (is.list(x)) {
        if (!is.null(x$encounter_data)) 
            return(extract_history(x$encounter_data, stage = stage))
        if (!is.null(x$observed)) 
            return(validate_history_matrix(x$observed, stage = stage))
        if (!is.null(x$history)) 
            return(validate_history_matrix(x$history, stage = stage))
        if (!is.null(x$data$history)) 
            return(validate_history_matrix(x$data$history, stage = stage))
        if (!is.null(x$sim$observed)) 
            return(validate_history_matrix(x$sim$observed, stage = stage))
    }
    stop_history_error(stage, x, "no encounter-history matrix was found.")
}
extract_ids <-
function (x) 
rownames(extract_history(x, stage = "extract_ids"))
extract_occasions <-
function (x, stage = "extract_occasions") 
{
    if (is_resident_encounter_data(x)) 
        return(validate_occasion_table(x$occasions, x$history, 
            stage = stage))
    hist <- extract_history(x, stage = stage)
    if (is.list(x)) {
        occ <- x$occasions %||% x$occasion_table %||% x$sim$occasions %||% 
            x$data$occasions
        if (!is.null(occ)) 
            return(validate_occasion_table(occ, hist, stage = stage))
    }
    validate_occasion_table(NULL, hist, stage = stage)
}
extract_table_notes <-
function (x) 
{
    note_cols <- intersect(c("interpretation", "interpretation_note", 
        "result_interpretation", "warning", "warnings", "classification_warning", 
        "evidence_interpretation"), names(x))
    notes <- lapply(note_cols, function(nm) {
        vals <- unique(as.character(x[[nm]]))
        vals <- vals[nzchar(vals) & !is.na(vals)]
        vals
    })
    names(notes) <- note_cols
    notes[lengths(notes) > 0]
}
extract_tmb_random_effects <-
function (fit) 
{
    if (is.null(fit$sdreport)) 
        return(NULL)
    s <- summary(fit$sdreport, "random")
    if (is.null(s) || !nrow(s)) 
        return(NULL)
    data.frame(parameter = rownames(s), estimate = s[, "Estimate"], 
        SE = s[, "Std. Error"], stringsAsFactors = FALSE)
}
extract_tmb_transition_estimates <-
function (fit) 
{
    if (!is.null(fit$sdreport)) {
        s <- tryCatch(summary(fit$sdreport, "report"), error = function(e) NULL)
        if (!is.null(s)) {
            hit <- grep("^Psi", rownames(s))
            if (length(hit)) {
                vals <- s[hit, , drop = FALSE]
                K <- length(fit$spec$states)
                est <- matrix(vals[, "Estimate"], K, K, byrow = FALSE, 
                  dimnames = list(fit$spec$states, fit$spec$states))
                se <- matrix(vals[, "Std. Error"], K, K, byrow = FALSE, 
                  dimnames = list(fit$spec$states, fit$spec$states))
                return(list(Psi_estimate = est, Psi_SE = se))
            }
        }
    }
    list(Psi_estimate = fit$transition_matrix %||% fit$spec$transition_matrix, 
        Psi_SE = matrix(NA_real_, length(fit$spec$states), length(fit$spec$states), 
            dimnames = list(fit$spec$states, fit$spec$states)))
}
extract_true_abundance_series <-
function (analysis) 
{
    source <- analysis$sim %||% analysis
    mat <- source$true_alive %||% source$alive %||% source$true_state
    if (is.null(mat) && !is.null(source$latent_states)) 
        mat <- source$latent_states != "outside"
    if (is.null(mat)) 
        return(NULL)
    mat <- as.matrix(mat)
    vals <- colSums(mat > 0, na.rm = TRUE)
    data.frame(occasion = seq_along(vals), true_abundance = as.numeric(vals), 
        stringsAsFactors = FALSE)
}
