find_resident_companion_file <-
function (file, kind = c("occasion_dates", "occasion_table")) 
{
    kind <- match.arg(kind)
    dir <- dirname(file)
    base <- basename(file)
    stem <- sub("\\.[^.]+$", "", base)
    candidates <- character()
    if (kind == "occasion_dates") {
        candidates <- c(sub("PROGRAM_MARK_encounter_history$", 
            "PROGRAM_MARK_occasion_dates", stem), paste0(stem, 
            "_occasion_dates"), sub("encounter_history$", "occasion_dates", 
            stem))
        suffix <- c(".txt", ".csv")
    }
    else {
        dataset <- sub("_(PROGRAM_MARK_encounter_history|SOCPROG_sightings_long_format|encounter_history_wide)$", 
            "", stem)
        candidates <- c(paste0(dataset, "_occasion_table"), sub("encounter_history_wide$", 
            "occasion_table", stem))
        suffix <- ".csv"
    }
    paths <- unique(as.vector(outer(file.path(dir, candidates), 
        suffix, paste0)))
    source_path <- normalizePath(file, mustWork = FALSE)
    paths <- paths[normalizePath(paths, mustWork = FALSE) != 
        source_path]
    hit <- paths[file.exists(paths)]
    if (length(hit)) 
        hit[1]
    else NA_character_
}
finite_xy_check <-
function (data, x, y) 
{
    if (is.null(data) || !is.data.frame(data) || !nrow(data)) {
        return(list(ok = FALSE, reason = "plot data are empty"))
    }
    if (!all(c(x, y) %in% names(data))) {
        return(list(ok = FALSE, reason = paste("required columns are missing:", 
            paste(setdiff(c(x, y), names(data)), collapse = ", "))))
    }
    xx <- data[[x]]
    yy <- data[[y]]
    if (inherits(xx, "Date")) 
        xx <- as.numeric(xx)
    if (inherits(yy, "Date")) 
        yy <- as.numeric(yy)
    xx_original <- xx
    yy_original <- yy
    xx <- suppressWarnings(as.numeric(xx))
    yy <- suppressWarnings(as.numeric(yy))
    if (!any(is.finite(xx)) && any(!is.na(xx_original))) {
        xx <- seq_along(xx_original)
    }
    if (!any(is.finite(yy)) && any(!is.na(yy_original))) {
        yy <- seq_along(yy_original)
    }
    if (!any(is.finite(xx))) 
        return(list(ok = FALSE, reason = "no finite x values were available"))
    if (!any(is.finite(yy))) 
        return(list(ok = FALSE, reason = "no finite y values were available"))
    list(ok = TRUE, x = xx, y = yy)
}
fit_abundance_model <-
function (history, abundance_model = "closed_M0", occasions = NULL, 
    temporal_structure = NULL, input_provider = NULL, data_type = "empirical", 
    ...) 
{
    if (requires_temporal_structure(abundance_model)) {
        if (grepl("^robust_design", abundance_model)) 
            return(fit_robust_design_abundance(history, occasions, 
                abundance_model, temporal_structure, input_provider, 
                data_type, ...))
        if (abundance_model == "jolly_seber") 
            return(fit_jolly_seber_abundance(history, occasions, 
                temporal_structure = temporal_structure, input_provider = input_provider, 
                data_type = data_type, ...))
        if (abundance_model == "POPAN_like") 
            return(fit_popan_like_abundance(history, occasions, 
                temporal_structure = temporal_structure, input_provider = input_provider, 
                data_type = data_type, ...))
        if (abundance_model %in% c("CJS", "CJS_like")) 
            return(fit_cjs_model(history, occasions, temporal_structure = temporal_structure, 
                input_provider = input_provider, data_type = data_type, 
                ...))
    }
    .resident_v093_fit_abundance_model(history, abundance_model, 
        ...)
}
fit_abundance_model_set <-
function (data, models = NULL, candidate_models = NULL, occasions = NULL, 
    ...) 
{
    y <- extract_history(data, stage = "fit abundance model set")
    candidate_models <- candidate_models %||% models %||% c("closed_M0", 
        "closed_Mt", "closed_Mb", "closed_Mh_mixture")
    fits <- list()
    for (m in candidate_models) {
        if (!(m %in% implemented_abundance_models())) {
            fits[[m]] <- list(model_name = m, abundance_model = m, 
                error = "not implemented", logLik = NA_real_, 
                n_parameters = NA_integer_, AIC = NA_real_, AICc = NA_real_, 
                BIC = NA_real_, N_hat = NA_real_, N_SE = NA_real_, 
                convergence = 1L, Hessian_status = "not_implemented", 
                boundary_warnings = "", identifiability_warnings = "not implemented")
            next
        }
        fits[[m]] <- tryCatch({
            if (grepl("^robust_design", m)) 
                fit_robust_design_abundance(y, occasions %||% 
                  extract_occasions(data), m, ...)
            else if (m %in% c("observed_only", "chao1_chao2")) 
                fit_abundance_model(y, m, ...)
            else fit_abundance_model(y, m, ...)
        }, error = function(e) list(model_name = m, abundance_model = m, 
            error = conditionMessage(e), logLik = NA_real_, n_parameters = NA_integer_, 
            AIC = NA_real_, AICc = NA_real_, BIC = NA_real_, 
            N_hat = NA_real_, N_SE = NA_real_, convergence = 1L, 
            Hessian_status = "failed", boundary_warnings = "", 
            identifiability_warnings = conditionMessage(e)))
    }
    fits
}
fit_candidate_models <-
function (history, occasion_table, spec = state_space_specification(), 
    candidates = candidate_model_set(), maxit = 150) 
{
    fits <- list()
    for (i in seq_len(nrow(candidates))) {
        nm <- candidates$model_name[i]
        form <- stats::as.formula(candidates$formula[i])
        fits[[nm]] <- tryCatch({
            if (candidates$type[i] == "mixture") {
                fit_pledger_mixture_model(history, occasion_table, 
                  spec, detection_formula = form, maxit = maxit)
            }
            else if (candidates$type[i] == "random_effect") {
                fit_random_effect_detection_model(history, occasion_table, 
                  spec, detection_formula = form, maxit = maxit)
            }
            else if (candidates$type[i] == "hmm") {
                fit_residency_hmm(history, occasion_table, states = spec$states, 
                  transition_matrix = spec$transition_matrix, 
                  estimate_transition = FALSE, maxit = maxit)
            }
            else {
                fit_robust_design_cr(history, occasion_table, 
                  spec, detection_formula = form, estimate_transition = candidates$type[i] != 
                    "rd_fixed", maxit = maxit)
            }
        }, error = function(e) list(model = nm, error = conditionMessage(e), 
            logLik = NA_real_, npar = NA_integer_))
    }
    fits
}
fit_candidate_models_tmb <-
function (history, occasion_table, spec = state_space_specification(), 
    candidates = candidate_model_set_tmb(), maxit = 150) 
{
    fits <- list()
    for (i in seq_len(nrow(candidates))) {
        nm <- candidates$model_name[i]
        form <- stats::as.formula(candidates$formula[i])
        fits[[nm]] <- tryCatch({
            switch(candidates$type[i], hmm = fit_residency_hmm(history, 
                occasion_table, states = spec$states, transition_matrix = spec$transition_matrix, 
                estimate_transition = FALSE, maxit = maxit), 
                rd = if (candidates$backend[i] == "TMB") {
                  fit_robust_design_tmb(history, occasion_table, 
                    spec, detection_formula = form, estimate_transition = FALSE, 
                    maxit = maxit)
                } else {
                  fit_robust_design_cr(history, occasion_table, 
                    spec, detection_formula = form, estimate_transition = FALSE, 
                    maxit = maxit)
                }, random_effect = fit_robust_design_tmb(history, 
                  occasion_table, spec, detection_formula = form, 
                  random_effects = list(individual_detection = TRUE), 
                  estimate_transition = FALSE, maxit = maxit), 
                mixture = fit_pledger_mixture_model(history, 
                  occasion_table, spec, detection_formula = form, 
                  maxit = maxit), spatial = fit_spatial_transition_tmb(history, 
                  occasion_table, spec, maxit = maxit), social = fit_social_transition_tmb(history, 
                  occasion_table, spec, maxit = maxit), spatial_social = fit_spatial_social_transition_tmb(history, 
                  occasion_table, spec, maxit = maxit))
        }, error = function(e) list(model = nm, error = conditionMessage(e), 
            logLik = NA_real_, npar = NA_integer_))
    }
    fits
}
fit_cjs_model <-
function (history, occasions = NULL, Phi = ~1, p = ~1, group = NULL, 
    covariates = NULL, temporal_structure = NULL, input_provider = NULL, 
    data_type = "empirical", maxit = 500, allow_synthetic_dates = FALSE, 
    ...) 
{
    gate <- temporal_model_gate(history = history, occasions = occasions, 
        model = "CJS", input_provider = input_provider, data_type = data_type, 
        temporal_structure = temporal_structure, formulas = list(Phi = Phi, 
            p = p))
    y <- validate_cjs_data(gate$history)
    dd <- cjs_design_data(y, gate$occasions, group = group, covariates = covariates, 
        temporal_structure = gate$temporal_structure, allow_synthetic_dates = allow_synthetic_dates || 
            data_type != "empirical")
    mats <- cjs_build_design_matrices(Phi, p, dd)
    start <- c(setNames(rep(0, ncol(mats$X_Phi)), paste0("Phi_", 
        colnames(mats$X_Phi))), setNames(rep(0, ncol(mats$X_p)), 
        paste0("p_", colnames(mats$X_p))))
    start[1] <- qlogis(0.80000000000000004)
    start[ncol(mats$X_Phi) + 1L] <- qlogis(max(0.050000000000000003, 
        min(0.94999999999999996, mean(y, na.rm = TRUE))))
    opt <- optim(start, function(z) -cjs_loglik(z, y, mats$X_Phi, 
        mats$X_p), method = "BFGS", hessian = TRUE, control = list(maxit = maxit))
    nPhi <- ncol(mats$X_Phi)
    beta_Phi <- opt$par[seq_len(nPhi)]
    beta_p <- opt$par[nPhi + seq_len(ncol(mats$X_p))]
    Phi_hat <- plogis(as.numeric(mats$X_Phi %*% beta_Phi))
    p_hat <- plogis(as.numeric(mats$X_p %*% beta_p))
    hstat <- tryCatch({
        ev <- eigen(opt$hessian, symmetric = TRUE, only.values = TRUE)$values
        if (all(is.finite(ev)) && min(abs(ev)) > 9.9999999999999995e-08) 
            "usable"
        else "weak"
    }, error = function(e) "unavailable")
    npar <- length(opt$par)
    nobs <- sum(rowSums(y > 0) > 0)
    fit <- list(model_name = "CJS", abundance_model = "CJS", 
        model_family = "open_population", model_role = "survival_detection", 
        history = y, occasions = gate$occasions, temporal_structure = gate$temporal_structure, 
        design_data = dd, X_Phi = mats$X_Phi, X_p = mats$X_p, 
        beta_Phi = beta_Phi, beta_p = beta_p, Phi = Phi_hat, 
        p = p_hat, time_intervals = gate$temporal_structure$time_intervals %||% 
            rep(1, ncol(y) - 1L), par = opt$par, optim = opt, 
        logLik = -opt$value, n_parameters = npar, AIC = 2 * npar + 
            2 * opt$value, AICc = 2 * npar + 2 * opt$value + 
            (2 * npar * (npar + 1))/max(1, nobs - npar - 1), 
        BIC = log(max(1, nobs)) * npar + 2 * opt$value, convergence = opt$convergence, 
        hessian_status = hstat, Phi_formula = Phi, p_formula = p, 
        warning = "CJS estimates apparent survival/persistence and detection conditional on first capture. It does not estimate total abundance.")
    class(fit) <- c("resident_cjs_fit", "resident_survival_detection_fit", 
        "list")
    fit
}
