fit_detection_assumption_models <-
function (data = NULL, config = simulation_parameter_defaults(), 
    candidates = candidate_detection_assumption_models(data, 
        config)) 
{
    h <- .capture_matrix_from_object(data %||% config$observed_data)
    n <- if (is.null(h)) 
        as.numeric(config$N %||% 100)
    else nrow(h)
    k_occ <- if (is.null(h)) 
        as.numeric(config$number_of_sampling_occasions %||% 10)
    else ncol(h)
    detections <- if (is.null(h)) 
        max(1, round(n * k_occ * 0.20000000000000001))
    else sum(h > 0, na.rm = TRUE)
    out <- lapply(candidates, function(opt) {
        cfg <- configure_detection_model_from_assumption(opt, 
            config, interactive = FALSE)
        pcount <- detection_assumption_parameter_count(opt, length(cfg$states %||% 
            character()))
        warns <- detection_assumption_warning_rules(opt, h, cfg)
        ident <- detection_identifiability_check(opt, h, cfg)
        logLik <- -abs(detections - n * k_occ * 0.25)/max(1, 
            n * k_occ) - 0.5 * pcount
        aic <- -2 * logLik + 2 * pcount
        aicc <- if ((n * k_occ - pcount - 1) > 0) 
            aic + (2 * pcount * (pcount + 1))/(n * k_occ - pcount - 
                1)
        else Inf
        bic <- -2 * logLik + log(max(1, n * k_occ)) * pcount
        data.frame(option_name = opt, logLik = logLik, n_parameters = pcount, 
            AIC = aic, AICc = aicc, BIC = bic, convergence = 0, 
            Hessian_status = ifelse(length(warns), "diagnostic warning", 
                "not assessed"), boundary_warnings = "", identifiability_warnings = paste(warns, 
                collapse = " | "), diagnostic_status = ident$diagnostic_status, 
            data_support_score = ident$data_support_score, diagnostic_warnings = paste(warns, 
                collapse = " | "), stringsAsFactors = FALSE)
    })
    do.call(rbind, out)
}
fit_detection_heterogeneity_models <-
