fit_model_list <-
function (history, occasions = NULL, models = create_model_list("CJS"), 
    model_family = "CJS", specification = NULL, temporal_structure = NULL, 
    input_provider = NULL, data_type = "empirical", maxit = 100, 
    ...) 
{
    if (!is.null(specification)) 
        model_family <- specification$model_family
    if (requires_temporal_structure(model_family)) {
        gate <- temporal_model_gate(history = history, occasions = occasions, 
            model = model_family, input_provider = input_provider, 
            data_type = data_type, temporal_structure = temporal_structure)
        history <- gate$history
        occasions <- gate$occasions
        temporal_structure <- gate$temporal_structure
    }
    stats::setNames(lapply(names(models), function(nm) {
        form <- models[[nm]]
        fit <- tryCatch(if (model_family %in% c("CJS", "cjs")) 
            fit_cjs_model(history, occasions, Phi = form$Phi %||% 
                ~1, p = form$p %||% ~1, maxit = maxit, temporal_structure = temporal_structure, 
                data_type = data_type)
        else fit_abundance_model(history, "closed_M0", ...), 
            error = function(e) list(model_name = nm, error = conditionMessage(e), 
                logLik = NA_real_, n_parameters = NA_integer_, 
                AIC = NA_real_, AICc = NA_real_, BIC = NA_real_, 
                convergence = 1L))
        fit$model_name <- nm
        fit$parameter_formulas <- paste(names(form), vapply(form, 
            function(f) paste(deparse(f), collapse = ""), character(1)), 
            collapse = "; ")
        fit
    }), names(models))
}
fit_pledger_mixture_model <-
function (history, occasion_table, spec = state_space_specification(), 
    n_classes = 2, detection_formula = spec$detection_formula, 
    estimate_transition = FALSE, maxit = 1000, hessian = TRUE) 
{
    rd <- prepare_robust_design_array(history, occasion_table)
    design <- build_detection_design_matrix(rd, detection_formula)
    ts <- build_transition_structure(spec$states, if (estimate_transition) 
        "diagonal_dominant"
    else "fixed", fixed_matrix = spec$transition_matrix)
    mix <- mixture_detection_specification(n_classes)
    par0 <- c(rep(0, ncol(design$X)), rep(0, if (estimate_transition) transition_parameter_count(ts) else 0), 
        rep(0, max(0, n_classes - 1)), seq(-0.75, 0.75, length.out = max(1, 
            n_classes - 1)))
    objective <- function(par) -robust_design_mixture_likelihood(par, 
        rd, spec, ts, design, mix, estimate_transition)$logLik
    opt <- stats::optim(par0, objective, method = "BFGS", hessian = hessian, 
        control = list(maxit = maxit))
    parts <- robust_design_mixture_likelihood(opt$par, rd, spec, 
        ts, design, mix, estimate_transition)
    fit <- list(model = "pledger_finite_mixture_rd", rd_array = rd, 
        spec = spec, states = spec$states, initial_probs = spec$initial_probs, 
        transition_matrix = parts$transition_matrix, beta = parts$beta, 
        mixture_pi = parts$mixture_pi, mixture_offsets = parts$mixture_offsets, 
        logLik = parts$logLik, npar = length(opt$par), AIC = 2 * 
            length(opt$par) - 2 * parts$logLik, convergence = opt$convergence, 
        optim = opt, detection_design = design, history = rd$history, 
        occasion_table = rd$occasion_table, transition_structure = ts)
    fit$uncertainty <- hessian_uncertainty(fit)
    fit$identifiability <- validate_multistate_identifiability(fit)
    fit
}
