fit_random_effect_detection_model <-
function (history, occasion_table, spec = state_space_specification(), 
    detection_formula = spec$detection_formula, backend = c("base", 
        "TMB", "nimble", "stan"), n_quad = 11, maxit = 500) 
{
    backend <- match.arg(backend)
    if (backend != "base") {
        warning("External backend requested. v0.5.0 exposes the backend path but only base Gauss-Hermite quadrature is implemented here.")
        return(list(model = "random_effect_detection_rd", backend = backend, 
            status = "backend_not_available", recommendation = "Use backend='base' or implement the TMB/NIMBLE/Stan module."))
    }
    rd <- prepare_robust_design_array(history, occasion_table)
    design <- build_detection_design_matrix(rd, detection_formula)
    ts <- build_transition_structure(spec$states, "fixed", fixed_matrix = spec$transition_matrix)
    par0 <- c(rep(0, ncol(design$X)), log(0.29999999999999999))
    objective <- function(par) -integrated_random_effect_likelihood(par, 
        rd, spec, ts, design, n_quad)$logLik
    opt <- stats::optim(par0, objective, method = "BFGS", hessian = TRUE, 
        control = list(maxit = maxit))
    parts <- integrated_random_effect_likelihood(opt$par, rd, 
        spec, ts, design, n_quad)
    list(model = "random_effect_detection_rd", backend = "base", 
        logLik = parts$logLik, beta = parts$beta, sigma = parts$sigma, 
        npar = length(opt$par), AIC = 2 * length(opt$par) - 2 * 
            parts$logLik, convergence = opt$convergence, optim = opt, 
        rd_array = rd, detection_design = design, spec = spec, 
        history = rd$history)
}
fit_residency_hmm <-
function (history, occasion_table = NULL, states = default_residency_states(), 
    initial_probs = NULL, transition_matrix = NULL, detection = NULL, 
    effort = NULL, estimate_transition = TRUE, maxit = 1000) 
{
    history <- as_binary_matrix(history)
    K <- length(states)
    if (is.null(occasion_table)) {
        occasion_table <- make_occasion_table(n_occasions = ncol(history))
    }
    if (is.null(initial_probs)) 
        initial_probs <- c(0.55000000000000004, 0.25, 0.14999999999999999, 
            0.050000000000000003)[seq_len(K)]
    initial_probs <- normalize_prob(initial_probs)
    if (is.null(transition_matrix)) 
        transition_matrix <- default_transition_matrix(states)
    transition_matrix <- validate_transition_matrix(transition_matrix, 
        states)
    detection <- state_detection_probabilities(states, detection)
    effort <- effort %||% occasion_table$effort
    par0 <- hmm_pack_params(initial_probs, transition_matrix, 
        detection)
    if (!estimate_transition) {
        fixed_transition <- transition_matrix
        n_init <- K - 1
        n_trans <- K * (K - 1)
        free_index <- c(seq_len(n_init), (n_init + n_trans + 
            1):length(par0))
        par_start <- par0[free_index]
    }
    else {
        free_index <- seq_along(par0)
        par_start <- par0
        fixed_transition <- NULL
    }
    objective <- function(par_free) {
        par <- par0
        par[free_index] <- par_free
        spec <- hmm_unpack_params(par, K, states)
        if (!estimate_transition) 
            spec$transition_matrix <- fixed_transition
        ll <- 0
        for (i in safe_seq_rows(history, context = "validated history row loop")) {
            ll <- ll + forward_algorithm(history[i, ], spec$initial_probs, 
                spec$transition_matrix, spec$detection_prob, 
                effort)$logLik
        }
        -ll
    }
    opt <- stats::optim(par_start, objective, method = "BFGS", 
        control = list(maxit = maxit))
    par_hat <- par0
    par_hat[free_index] <- opt$par
    spec <- hmm_unpack_params(par_hat, K, states)
    if (!estimate_transition) 
        spec$transition_matrix <- fixed_transition
    posterior <- lapply(safe_seq_rows(history, context = "validated history row loop"), 
        function(i) {
            forward_backward(history[i, ], spec$initial_probs, 
                spec$transition_matrix, spec$detection_prob, 
                effort)
        })
    names(posterior) <- rownames(history) %||% paste0("Subject_", 
        safe_seq_rows(history, context = "validated history row loop"))
    logLik <- -opt$value
    npar <- length(opt$par)
    fit <- list(model = "residency_hmm_mle", states = states, 
        initial_probs = spec$initial_probs, transition_matrix = spec$transition_matrix, 
        detection_prob = spec$detection_prob, logLik = logLik, 
        AIC = 2 * npar - 2 * logLik, convergence = opt$convergence, 
        optim = opt, posterior = posterior, history = history, 
        occasion_table = occasion_table)
    fit$decoded_states <- decode_residency_states(fit)
    fit$classification <- classify_probabilistic_residency(fit)
    fit
}
