fit_robust_design_cr <-
function (history, occasion_table, spec = state_space_specification(), 
    transition_structure = NULL, detection_formula = spec$detection_formula, 
    individual_data = NULL, observation_data = NULL, estimate_transition = TRUE, 
    transition_estimation = if (estimate_transition) "estimate_diagonal_dominant" else "fixed", 
    transition_free_mask = NULL, fixed = list(), maxit = 1000, 
    hessian = TRUE) 
{
    rd <- prepare_robust_design_array(history, occasion_table)
    transition_estimation <- match.arg(transition_estimation, 
        c("fixed", "estimate_full", "estimate_diagonal_dominant", 
            "estimate_adjacent", "estimate_custom_mask"))
    estimate_transition <- transition_estimation != "fixed"
    transition_structure <- transition_structure %||% transition_estimation_specification(transition_estimation, 
        spec$states, fixed_matrix = spec$transition_matrix, transition_free_mask = transition_free_mask)
    design <- build_detection_design_matrix(rd, detection_formula, 
        individual_data, observation_data)
    beta0 <- rep(0, ncol(design$X))
    names(beta0) <- colnames(design$X)
    trans0 <- rep(0, if (estimate_transition) transition_parameter_count(transition_structure) else 0)
    par0 <- c(beta0, trans0)
    objective <- function(par) {
        -robust_design_likelihood(par, rd, spec, transition_structure, 
            design, estimate_transition, fixed)$logLik
    }
    opt <- stats::optim(par0, objective, method = "BFGS", hessian = hessian, 
        control = list(maxit = maxit))
    fit_parts <- robust_design_likelihood(opt$par, rd, spec, 
        transition_structure, design, estimate_transition, fixed)
    fit <- list(model = "robust_design_multistate_cr", rd_array = rd, 
        spec = spec, states = spec$states, initial_probs = spec$initial_probs, 
        transition_matrix = fit_parts$transition_matrix, beta = fit_parts$beta, 
        logLik = fit_parts$logLik, npar = length(opt$par), AIC = 2 * 
            length(opt$par) - 2 * fit_parts$logLik, BIC = log(length(rd$y[!is.na(rd$y)])) * 
            length(opt$par) - 2 * fit_parts$logLik, convergence = opt$convergence, 
        optim = opt, detection_design = design, transition_structure = transition_structure, 
        transition_estimation = transition_estimation, estimate_transition = estimate_transition, 
        history = rd$history, occasion_table = rd$occasion_table)
    fit$decoded_states <- decode_robust_design_states(fit)
    fit$derived <- derive_robust_design_parameters(fit)
    fit$uncertainty <- hessian_uncertainty(fit)
    fit$identifiability <- validate_multistate_identifiability(fit)
    fit
}
fit_robust_design_tmb <-
function (history, occasion_table, spec = state_space_specification(), 
    detection_formula = spec$detection_formula, individual_data = NULL, 
    observation_data = NULL, estimate_transition = FALSE, transition_estimation = if (estimate_transition) "estimate_full" else "fixed", 
    transition_free_mask = NULL, random_effects = list(individual_detection = FALSE, 
        primary_detection = FALSE, state_detection = FALSE, residency_propensity = FALSE), 
    source = NULL, compile = FALSE, fallback = TRUE, maxit = 1000) 
{
    transition_estimation <- match.arg(transition_estimation, 
        c("fixed", "estimate_full", "estimate_diagonal_dominant", 
            "estimate_adjacent", "estimate_custom_mask"))
    estimate_transition <- transition_estimation != "fixed"
    if (transition_estimation %in% c("estimate_diagonal_dominant", 
        "estimate_adjacent", "estimate_custom_mask")) {
        fit <- fit_robust_design_cr(history, occasion_table, 
            spec, detection_formula = detection_formula, individual_data = individual_data, 
            observation_data = observation_data, transition_estimation = transition_estimation, 
            transition_free_mask = transition_free_mask, maxit = maxit)
        fit$backend <- "base_for_constrained_transition"
        return(fit)
    }
    if (!tmb_available()) {
        msg <- "TMB is not installed. Falling back to base backend."
        if (!fallback) 
            return(list(model = "robust_design_tmb", backend = "TMB", 
                status = "TMB_not_installed", message = msg))
        fit <- fit_robust_design_cr(history, occasion_table, 
            spec, detection_formula = detection_formula, individual_data = individual_data, 
            observation_data = observation_data, transition_estimation = transition_estimation, 
            maxit = maxit)
        fit$backend <- "base_fallback"
        fit$tmb_status <- msg
        return(fit)
    }
    source <- source %||% file.path(getwd(), "resident_tmb.cpp")
    if (!file.exists(source)) {
        alt <- file.path(getwd(), "outputs", "resident_tmb.cpp")
        if (file.exists(alt)) 
            source <- alt
    }
    load <- load_resident_tmb(source, compile = compile)
    if (!isTRUE(load$ok)) {
        if (!fallback) 
            return(c(list(model = "robust_design_tmb", backend = "TMB"), 
                load))
        fit <- fit_robust_design_cr(history, occasion_table, 
            spec, detection_formula = detection_formula, individual_data = individual_data, 
            observation_data = observation_data, transition_estimation = transition_estimation, 
            maxit = maxit)
        fit$backend <- "base_fallback"
        fit$tmb_status <- load$message %||% load$status
        return(fit)
    }
    td <- build_tmb_detection_data(history, occasion_table, spec, 
        detection_formula, individual_data, observation_data)
    vd <- validate_tmb_design_matrices(td)
    if (!vd$ok) 
        stop(paste(vd$problems, collapse = "; "))
    data <- td$data
    data$estimate_transition <- as.integer(estimate_transition)
    data$re_individual_detection <- as.integer(isTRUE(random_effects$individual_detection))
    data$re_primary_detection <- as.integer(isTRUE(random_effects$primary_detection))
    data$re_state_detection <- as.integer(isTRUE(random_effects$state_detection))
    parameters <- list(beta_detection = rep(0, ncol(data$X_detection)), 
        trans_par = rep(0, if (estimate_transition) length(spec$states) * 
            (length(spec$states) - 1) else 0), u_individual = rep(0, 
            if (data$re_individual_detection) data$N else 0), 
        u_primary = rep(0, if (data$re_primary_detection) data$Kp else 0), 
        u_state = rep(0, if (data$re_state_detection) data$S else 0), 
        log_sigma_individual_detection = log(0.20000000000000001), 
        log_sigma_primary_detection = log(0.20000000000000001), 
        log_sigma_state_detection = log(0.20000000000000001))
    random <- c(if (data$re_individual_detection) "u_individual", 
        if (data$re_primary_detection) "u_primary", if (data$re_state_detection) "u_state")
    obj <- TMB::MakeADFun(data, parameters, random = random, 
        DLL = tools::file_path_sans_ext(basename(source)), silent = TRUE)
    opt <- stats::optim(obj$par, obj$fn, obj$gr, method = "BFGS", 
        control = list(maxit = maxit))
    rep <- tryCatch(TMB::sdreport(obj), error = function(e) NULL)
    beta <- obj$env$last.par.best[names(obj$env$last.par.best) == 
        "beta_detection"]
    names(beta) <- colnames(data$X_detection)
    fit <- list(model = "robust_design_tmb", backend = "TMB", 
        status = "fit", logLik = -opt$value, npar = length(opt$par), 
        AIC = 2 * length(opt$par) + 2 * opt$value, convergence = opt$convergence, 
        optim = opt, sdreport = rep, beta = beta, spec = spec, 
        history = td$rd_array$history, occasion_table = td$rd_array$occasion_table, 
        rd_array = td$rd_array, detection_design = td$detection_design, 
        random_effects = random_effects, tmb_data = data, source = source)
    fit$transition_estimation <- transition_estimation
    fit$estimate_transition <- estimate_transition
    ext <- extract_tmb_transition_estimates(fit)
    fit$transition_matrix <- ext$Psi_estimate
    fit$transition_sd_table <- transition_sdreport_table(fit)
    fit$transition_structure <- transition_estimation_specification(transition_estimation, 
        spec$states, fixed_matrix = spec$transition_matrix)
    fit$random_effect_summary <- summarize_random_effects(fit)
    fit$random_effect_diagnostics <- diagnose_random_effects(fit)
    fit
}
