fit_state_space_cr <-
function (history, occasion_table, spec = state_space_specification(), 
    individual_data = NULL, observation_data = NULL, estimate_transition = TRUE, 
    maxit = 1000, hessian = TRUE) 
{
    history <- as_binary_matrix(history)
    states <- spec$states
    K <- length(states)
    design <- state_detection_design(history, occasion_table, 
        states, spec$unavailable_states, spec$detection_formula, 
        individual_data, observation_data)
    X <- design$X
    beta0 <- rep(0, ncol(X))
    names(beta0) <- colnames(X)
    trans0 <- spec$transition_matrix
    init0 <- spec$initial_probs
    par0_hmm <- hmm_pack_params(init0, trans0, state_detection_probabilities(states, 
        setNames(rep(0.29999999999999999, K), states)))
    n_init <- K - 1
    n_trans <- K * (K - 1)
    trans_par0 <- par0_hmm[(n_init + 1):(n_init + n_trans)]
    par0 <- c(beta0, if (estimate_transition) trans_par0 else numeric(0))
    unpack <- function(par) {
        beta <- par[seq_along(beta0)]
        names(beta) <- names(beta0)
        if (estimate_transition) {
            pos <- length(beta0) + 1
            transition <- matrix(0, K, K)
            for (i in seq_len(K)) {
                eta <- c(par[pos:(pos + K - 2)], 0)
                transition[i, ] <- softmax(eta)
                pos <- pos + K - 1
            }
            rownames(transition) <- colnames(transition) <- states
        }
        else {
            transition <- trans0
        }
        list(beta = beta, transition = transition)
    }
    objective <- function(par) {
        pp <- unpack(par)
        ll <- 0
        for (i in safe_seq_rows(history, context = "validated history row loop")) {
            ll <- ll + forward_algorithm_regression(history[i, 
                ], init0, pp$transition, design, pp$beta, states, 
                spec$unavailable_states, i)$logLik
        }
        -ll
    }
    opt <- stats::optim(par0, objective, method = "BFGS", hessian = hessian, 
        control = list(maxit = maxit))
    pp <- unpack(opt$par)
    posterior <- lapply(safe_seq_rows(history, context = "validated history row loop"), 
        function(i) {
            fa <- forward_algorithm_regression(history[i, ], 
                init0, pp$transition, design, pp$beta, states, 
                spec$unavailable_states, i)
            K <- length(states)
            Tn <- ncol(history)
            beta_b <- matrix(1, K, Tn)
            if (Tn > 1) {
                for (t in (Tn - 1):1) {
                  beta_b[, t] <- pp$transition %*% (fa$emission[, 
                    t + 1] * beta_b[, t + 1])
                  beta_b[, t] <- beta_b[, t]/fa$scale[t + 1]
                }
            }
            gamma <- fa$alpha * beta_b
            gamma <- sweep(gamma, 2, colSums(gamma), "/")
            list(logLik = fa$logLik, alpha = fa$alpha, beta = beta_b, 
                gamma = gamma, emission = fa$emission)
        })
    names(posterior) <- rownames(history) %||% paste0("Subject_", 
        safe_seq_rows(history, context = "validated history row loop"))
    fit <- list(model = "state_space_cr_mle", spec = spec, states = states, 
        initial_probs = init0, transition_matrix = pp$transition, 
        beta = pp$beta, logLik = -opt$value, npar = length(opt$par), 
        AIC = 2 * length(opt$par) + 2 * opt$value, BIC = log(length(history)) * 
            length(opt$par) + 2 * opt$value, convergence = opt$convergence, 
        optim = opt, posterior = posterior, detection_design = design, 
        history = history, occasion_table = occasion_table)
    fit$decoded_states <- decode_residency_states(fit)
    fit$classification <- classify_probabilistic_residency(fit)
    fit$derived <- derive_robust_design_parameters(fit)
    fit$uncertainty <- hessian_uncertainty(fit)
    fit
}
fit_state_space_model_from_analysis <-
function (analysis, ...) 
{
    y <- tryCatch(extract_history(analysis, stage = "state-space route"), 
        error = function(e) NULL)
    occ <- tryCatch(extract_occasions(analysis, stage = "state-space route"), 
        error = function(e) NULL)
    if (is.null(y) || is.null(occ)) {
        out <- list(model_name = "state_space_robust_design", 
            error = "State-space route needs an encounter history and occasion table.")
        class(out) <- c("resident_state_space_route", "list")
        return(out)
    }
    spec <- tryCatch(state_space_specification(), error = function(e) NULL)
    fit <- tryCatch(fit_robust_design_cr(y, occ, spec = spec, 
        estimate_transition = FALSE, ...), error = function(e) e)
    if (inherits(fit, "error")) {
        out <- list(model_name = "state_space_robust_design", 
            error = conditionMessage(fit), history = y, occasions = occ)
        class(out) <- c("resident_state_space_route", "list")
        return(out)
    }
    fit$model_name <- "state_space_robust_design"
    class(fit) <- c("resident_state_space_route", class(fit))
    fit
}
