fit_transition_model_base <-
function (history, occasion_table, spec = state_space_specification(), 
    transition_estimation = c("fixed", "estimate_full", "estimate_diagonal_dominant", 
        "estimate_adjacent", "estimate_custom_mask"), transition_free_mask = NULL, 
    maxit = 1000, hessian = TRUE, ...) 
{
    transition_estimation <- match.arg(transition_estimation)
    ts <- transition_estimation_specification(transition_estimation, 
        spec$states, fixed_matrix = spec$transition_matrix, transition_free_mask = transition_free_mask)
    fit <- fit_robust_design_cr(history, occasion_table, spec = spec, 
        transition_structure = ts, estimate_transition = transition_estimation != 
            "fixed", maxit = maxit, hessian = hessian, ...)
    fit$transition_estimation <- transition_estimation
    fit$estimate_transition <- transition_estimation != "fixed"
    fit$transition_structure <- ts
    fit$transition_time_scale <- attr(spec$transition_matrix, 
        "transition_time_scale") %||% "month"
    fit$transition_identifiability <- diagnose_transition_identifiability(fit)
    fit
}
fit_transition_model_tmb <-
function (history, occasion_table, spec = state_space_specification(), 
    transition_estimation = c("fixed", "estimate_full", "estimate_diagonal_dominant", 
        "estimate_adjacent", "estimate_custom_mask"), transition_free_mask = NULL, 
    fallback = TRUE, maxit = 1000, ...) 
{
    transition_estimation <- match.arg(transition_estimation)
    if (transition_estimation %in% c("estimate_diagonal_dominant", 
        "estimate_adjacent", "estimate_custom_mask")) {
        fit <- fit_transition_model_base(history, occasion_table, 
            spec, transition_estimation, transition_free_mask, 
            maxit = maxit, ...)
        fit$backend <- "base_for_constrained_transition"
        return(fit)
    }
    fit <- fit_robust_design_tmb(history, occasion_table, spec, 
        estimate_transition = transition_estimation != "fixed", 
        fallback = fallback, maxit = maxit, ...)
    fit$transition_estimation <- transition_estimation
    fit$estimate_transition <- transition_estimation != "fixed"
    if (is.null(fit$transition_matrix)) {
        ext <- extract_tmb_transition_estimates(fit)
        fit$transition_matrix <- ext$Psi_estimate
    }
    fit$transition_structure <- transition_estimation_specification(transition_estimation, 
        spec$states, fixed_matrix = spec$transition_matrix)
    fit$transition_sd_table <- if (!is.null(fit$sdreport)) 
        transition_sdreport_table(fit)
    else NULL
    fit$transition_identifiability <- diagnose_transition_identifiability(fit)
    fit
}
fit_warning_summary <-
function (fit) 
{
    warnings <- character(0)
    if (!is.null(fit$tmb_status)) 
        warnings <- c(warnings, fit$tmb_status)
    id <- tryCatch(validate_multistate_identifiability(fit), 
        error = function(e) NULL)
    if (!is.null(id)) {
        if (id$sparse_data) 
            warnings <- c(warnings, "Sparse data for requested model complexity.")
        if (id$singular_hessian) 
            warnings <- c(warnings, "Singular or near-singular Hessian.")
        if (id$boundary_estimate) 
            warnings <- c(warnings, "Boundary-scale parameter estimates.")
    }
    re <- fit$random_effect_diagnostics
    if (!is.null(re) && nrow(re) && any(re$flag == "boundary_near_zero")) {
        warnings <- c(warnings, "At least one random-effect variance is near zero.")
    }
    data.frame(warning = unique(warnings), stringsAsFactors = FALSE)
}
flag_suspicious_parameter_value <-
function (parameter, value, config = list()) 
{
    p <- .parameter_key(parameter)
    warnings <- character()
    if (p == "sigma_individual_detection") {
        validate_parameter_value(parameter, value, config)
        v <- as.numeric(value)
        if (v > 2) 
            warnings <- c(warnings, "sigma_individual_detection > 2 implies very strong individual heterogeneity and may create near-zero or near-one detection probabilities.")
        if (v > 5) 
            warnings <- c(warnings, "sigma_individual_detection > 5 is extreme and should require explicit confirmation.")
        return(warnings)
    }
    if (p == "n") {
        v <- as.numeric(value)
        if (is.finite(v) && v < 20) 
            warnings <- c(warnings, "N < 20 may produce unstable estimates.")
        if (is.finite(v) && v > 1000) 
            warnings <- c(warnings, "N > 1000 may be slow.")
    }
    else if (p %in% c("p", "baseline_detection_probability")) {
        v <- as.numeric(value)
        if (is.finite(v) && v < 0.050000000000000003) 
            warnings <- c(warnings, p, "is very low; detections may be sparse.")
        if (is.finite(v) && v > 0.80000000000000004) 
            warnings <- c(warnings, p, "is very high; simulations may be overoptimistic.")
    }
    else if (p == "phi") {
        v <- as.numeric(value)
        if (is.finite(v) && v < 0.5) 
            warnings <- c(warnings, "phi < 0.5 implies low persistence.")
        if (is.finite(v) && v > 0.98999999999999999) 
            warnings <- c(warnings, "phi > 0.99 is near-boundary.")
    }
    else if (p == "rmax") {
        v <- as.numeric(value)
        actual <- as.numeric(config$actual_number_of_sampling_occasions %||% 
            config$number_of_sampling_occasions %||% NA)
        if (is.finite(v) && is.finite(actual) && v > actual) 
            warnings <- c(warnings, "rmax exceeds actual occasions.")
        if (is.finite(v) && is.finite(actual) && v > 0.80000000000000004 * 
            actual) 
            warnings <- c(warnings, "rmax is close to the number of occasions.")
    }
    else if (p == "individual_re_sd") {
        v <- as.numeric(value)
        if (is.finite(v) && v > 2) 
            warnings <- c(warnings, "individual_re_sd > 2 may create extreme detection heterogeneity.")
    }
    else if (p == "effort_detection_effect") {
        v <- as.numeric(value)
        if (is.finite(v) && abs(v) > 2) 
            warnings <- c(warnings, "Absolute effort_detection_effect > 2 can dominate the detection model unless effort is standardized and justified.")
        if (is.finite(v) && abs(v) > 5) 
            warnings <- c(warnings, "Absolute effort_detection_effect > 5 is extreme and should require strong justification.")
        if (identical(config$effort_scaling, "raw") && is.finite(v) && 
            abs(v) > 0.5) 
            warnings <- c(warnings, "Raw effort with large beta can create unrealistic probabilities.")
    }
    else if (p == "beta") {
        vals <- as.numeric(value)
        if (any(is.finite(vals) & abs(vals) > 5)) 
            warnings <- c(warnings, "beta contains large logit-scale values.")
    }
    else if (p == "state_detection") {
        vals <- as.numeric(value)
        if (any(vals < 0 | vals > 1 | !is.finite(vals))) 
            warnings <- c(warnings, "state_detection values must be probabilities in [0,1].")
        hit <- intersect(config$unavailable_states %||% character(), 
            names(value))
        if (length(hit) && any(value[hit] != 0)) 
            warnings <- c(warnings, "Unavailable states must have detection probability 0.")
    }
    else if (p == "transition_matrix") {
        mat <- as.matrix(value)
        if (any(abs(rowSums(mat) - 1) > 9.9999999999999995e-07)) 
            warnings <- c(warnings, "transition_matrix rows must sum to 1.")
        if (identical(config$transition_time_scale, "year") && 
            any(diag(mat) > 0.97999999999999998)) 
            warnings <- c(warnings, "Yearly transition diagonal probabilities are very high.")
        if (identical(config$transition_time_scale, "day") && 
            any(diag(mat) < 0.90000000000000002)) 
            warnings <- c(warnings, "Daily transition diagonal probabilities may be too low.")
    }
    warnings
}
