format_comparative_classification_table <-
function (fit, literature_classifications = NULL, n = 12, digits = 3, 
    columns = c("id", "primary_index", "state", "state_probability", 
        "availability_probability", "conway_general", "dinis_category", 
        "zolman_category", "chabanne_category", "moller_category")) 
{
    tab <- robust_literature_comparison_table(fit, literature_classifications)
    keep <- intersect(columns, names(tab))
    out <- head(tab[, keep, drop = FALSE], n)
    num <- vapply(out, is.numeric, logical(1))
    out[num] <- lapply(out[num], round, digits)
    attr(out, "interpretation") <- attr(tab, "interpretation")
    out
}
format_configuration_report_txt <-
function (config, review = NULL, timestamp = Sys.time()) 
{
    review <- review %||% full_simulation_configuration_review(config)
    sections <- split_configuration_review_by_section(review)
    lines <- c("Resident Pipeline simulation configuration report", 
        paste("Timestamp:", format(timestamp, "%Y-%m-%d %H:%M:%S %Z")), 
        "Pipeline version: v0.8.9", paste("Simulation model:", 
            config$simulation_model %||% ""), paste("Random seed:", 
            config$seed %||% ""), "", "Interpretation notes:", 
        "This report preserves the full configuration used for simulation or analysis setup.", 
        "The compact console summary omits many details; this file is the reproducibility record.", 
        "Detection assumptions affect residency classification because missed detections are part of the model.", 
        "", "Reproducibility information:", "source(\"outputs/resident_pipeline_v0.8.9.R\")", 
        "config <- documented_example_simulation_config()  # replace with the saved settings below when customized", 
        "sim <- run_configured_simulation(config)", "")
    for (section in names(sections)) {
        tab <- sections[[section]]
        lines <- c(lines, paste0("## ", section))
        if (!nrow(tab)) {
            lines <- c(lines, "No active parameters were recorded for this section in the current configuration.", 
                "")
        }
        else {
            lines <- c(lines, utils::capture.output(print(format_review_section_table(tab), 
                row.names = FALSE)), "")
        }
    }
    lines <- c(lines, "## Glossary of table fields", utils::capture.output(print(configuration_review_field_dictionary(), 
        row.names = FALSE)), "", "## Section dictionary", utils::capture.output(print(configuration_section_dictionary(), 
        row.names = FALSE)), "")
    paste(lines, collapse = "\n")
}
