format_decoded_states <-
function (fit, n = 12, digits = 3, literature_classifications = NULL, 
    include_literature = !is.null(literature_classifications)) 
{
    if (is.null(fit$decoded_states)) 
        stop("fit does not contain decoded_states.")
    decoded <- fit$decoded_states
    if (include_literature) {
        decoded <- robust_literature_comparison_table(fit, literature_classifications)
    }
    out <- head(decoded, n)
    num <- vapply(out, is.numeric, logical(1))
    out[num] <- lapply(out[num], round, digits)
    attr(out, "interpretation") <- paste("availability_probability is the model-estimated probability that the individual was available to be seen.", 
        "An individual can have availability_probability greater than 0.5 and still have no detection in that period.", 
        "That means the model estimates that the dolphin may have been available but missed.", 
        if (include_literature) {
            "Literature classification columns are rule-based categories added for comparison with the robust-design state."
        }
        else "")
    out
}
