format_table_value <-
function (value, digits = 3L) 
{
    if (length(value) != 1L) 
        value <- value[1L]
    if (is.na(value)) 
        return("NA")
    if (is.numeric(value)) {
        if (is.infinite(value)) 
            return(as.character(value))
        if (abs(value) > 0 && abs(value) < 10^(-digits)) {
            return(trimws(formatC(value, format = "e", digits = digits)))
        }
        return(trimws(formatC(value, format = "fg", digits = digits)))
    }
    as.character(value)
}
