forward_algorithm <-
function (y, initial_probs, transition_matrix, detection_prob, 
    effort = NULL, effort_beta = 0) 
{
    transition_matrix <- validate_transition_matrix(transition_matrix)
    K <- length(initial_probs)
    Tn <- length(y)
    B <- emission_matrix(y, detection_prob, effort, effort_beta)
    alpha <- matrix(0, nrow = K, ncol = Tn)
    scale <- numeric(Tn)
    alpha[, 1] <- normalize_prob(initial_probs) * B[, 1]
    scale[1] <- sum(alpha[, 1])
    alpha[, 1] <- alpha[, 1]/scale[1]
    if (Tn > 1) {
        for (t in 2:Tn) {
            alpha[, t] <- as.vector(alpha[, t - 1] %*% transition_matrix) * 
                B[, t]
            scale[t] <- sum(alpha[, t])
            alpha[, t] <- alpha[, t]/scale[t]
        }
    }
    list(logLik = sum(log(scale)), alpha = alpha, scale = scale, 
        emission = B)
}
forward_algorithm_regression <-
function (y, initial_probs, transition_matrix, detection_design, 
    beta, states, unavailable_states, individual_index) 
{
    transition_matrix <- validate_transition_matrix(transition_matrix, 
        states)
    K <- length(states)
    Tn <- length(y)
    B <- emission_matrix_regression(y, detection_design, beta, 
        states, unavailable_states, individual_index)
    alpha <- matrix(0, K, Tn)
    scale <- numeric(Tn)
    alpha[, 1] <- normalize_prob(initial_probs) * B[, 1]
    scale[1] <- sum(alpha[, 1])
    alpha[, 1] <- alpha[, 1]/scale[1]
    if (Tn > 1) {
        for (t in 2:Tn) {
            alpha[, t] <- as.vector(alpha[, t - 1] %*% transition_matrix) * 
                B[, t]
            scale[t] <- sum(alpha[, t])
            alpha[, t] <- alpha[, t]/scale[t]
        }
    }
    list(logLik = sum(log(scale)), alpha = alpha, scale = scale, 
        emission = B)
}
forward_algorithm_robust_design <-
function (y_i, rd_array, initial_probs, transition_matrix, design, 
    beta, states, unavailable_states, individual_index, detection_offset = 0) 
{
    B <- primary_emission_probabilities(y_i, rd_array, design, 
        beta, states, unavailable_states, individual_index, detection_offset)
    Kstate <- length(states)
    Kp <- ncol(B)
    alpha <- matrix(0, Kstate, Kp)
    scale <- numeric(Kp)
    alpha[, 1] <- normalize_prob(initial_probs) * B[, 1]
    scale[1] <- sum(alpha[, 1])
    alpha[, 1] <- alpha[, 1]/scale[1]
    if (Kp > 1) {
        for (k in 2:Kp) {
            alpha[, k] <- as.vector(alpha[, k - 1] %*% transition_matrix) * 
                B[, k]
            scale[k] <- sum(alpha[, k])
            alpha[, k] <- alpha[, k]/scale[k]
        }
    }
    list(logLik = sum(log(scale)), alpha = alpha, scale = scale, 
        emission = B)
}
forward_backward <-
function (y, initial_probs, transition_matrix, detection_prob, 
    effort = NULL, effort_beta = 0) 
{
    fa <- forward_algorithm(y, initial_probs, transition_matrix, 
        detection_prob, effort, effort_beta)
    transition_matrix <- validate_transition_matrix(transition_matrix)
    K <- length(initial_probs)
    Tn <- length(y)
    beta <- matrix(1, nrow = K, ncol = Tn)
    if (Tn > 1) {
        for (t in (Tn - 1):1) {
            beta[, t] <- transition_matrix %*% (fa$emission[, 
                t + 1] * beta[, t + 1])
            beta[, t] <- beta[, t]/fa$scale[t + 1]
        }
    }
    gamma <- fa$alpha * beta
    gamma <- sweep(gamma, 2, colSums(gamma), "/")
    gamma[!is.finite(gamma)] <- 0
    xi <- vector("list", max(0, Tn - 1))
    if (Tn > 1) {
        for (t in seq_len(Tn - 1)) {
            m <- transition_matrix * (fa$alpha[, t] %o% (fa$emission[, 
                t + 1] * beta[, t + 1]))
            xi[[t]] <- m/sum(m)
        }
    }
    list(logLik = fa$logLik, alpha = fa$alpha, beta = beta, gamma = gamma, 
        xi = xi, emission = fa$emission)
}
