full_simulation_configuration_review <-
function (config) 
{
    defaults <- simulation_parameter_defaults()
    config <- modifyList(defaults, config)
    base <- tryCatch(parameter_review_table(config), error = function(e) data.frame())
    det <- tryCatch(detection_assumption_review_table(config, 
        config$observed_data), error = function(e) NULL)
    det_rows <- data.frame()
    if (!is.null(det)) {
        det_rows <- data.frame(parameter = c("detection_assumption_option", 
            "detection_assumption_formula", "detection_assumption_required_covariates", 
            "detection_assumption_parameter_count", "detection_assumption_random_effects", 
            "detection_assumption_backend_requirements", "detection_assumption_diagnostic_status", 
            "detection_assumption_identifiability_warning", "detection_assumption_consequence_summary", 
            "detection_assumption_warnings"), selected_value = c(det$selected_detection_covariate_assumptions, 
            det$detection_formula, det$required_covariates, det$parameter_count, 
            det$random_effects_used, det$backend_requirements, 
            det$diagnostic_status, det$identifiability_warning, 
            det$consequence_summary, det$warnings), default_value = c("constant", 
            "~ 1", "none", "1", "FALSE", "base or TMB", "review_required", 
            detection_identifiability_warning(), detection_assumption_consequence_summary("constant"), 
            ""), units = "unitless", scale = "detection-model assumption", 
            recommended_range = "Use the simplest supported model before richer detection structures.", 
            consequence_summary = c(rep(det$consequence_summary, 
                9), det$warnings), warnings = c(rep("", 9), det$warnings), 
            stringsAsFactors = FALSE)
    }
    if (nrow(base)) {
        if (!"selected_value" %in% names(base)) 
            base$selected_value <- base$value %||% ""
        if (!"default_value" %in% names(base)) 
            base$default_value <- ""
        if (!"units" %in% names(base)) 
            base$units <- ""
        if (!"scale" %in% names(base)) 
            base$scale <- ""
        if (!"recommended_range" %in% names(base)) 
            base$recommended_range <- ""
        if (!"consequence_summary" %in% names(base)) 
            base$consequence_summary <- ""
        if (!"warnings" %in% names(base)) 
            base$warnings <- ""
        base <- base[, c("parameter", "selected_value", "default_value", 
            "units", "scale", "recommended_range", "consequence_summary", 
            "warnings"), drop = FALSE]
    }
    extra_names <- c("configuration_review_verbosity", "save_full_configuration_report", 
        "show_full_configuration_in_console", "configuration_report_path", 
        "pipeline_version")
    config$pipeline_version <- "v0.8.9"
    extra_rows <- lapply(extra_names, function(nm) {
        data.frame(parameter = nm, selected_value = .resident_value_to_text(config[[nm]]), 
            default_value = .resident_value_to_text(defaults[[nm]]), 
            units = "unitless", scale = "workflow-control", recommended_range = "Use documented defaults unless the workflow requires a different reporting level.", 
            consequence_summary = "Controls how much configuration detail is printed or saved.", 
            warnings = "", stringsAsFactors = FALSE)
    })
    extra_rows <- do.call(rbind, extra_rows)
    out <- rbind(base, det_rows, extra_rows)
    out$category <- vapply(out$parameter, .configuration_parameter_section, 
        character(1))
    out$value_source <- vapply(out$parameter, .configuration_value_source, 
        character(1), config = config, defaults = defaults)
    out$value <- out$selected_value
    out$warning <- out$warnings
    out <- out[, c("parameter", "category", "selected_value", 
        "default_value", "value_source", "units", "scale", "recommended_range", 
        "consequence_summary", "warning", "value", "warnings"), 
        drop = FALSE]
    out
}
gaussian_quadrature_nodes <-
function (n = 15) 
{
    i <- seq_len(n - 1)
    J <- matrix(0, n, n)
    J[cbind(i, i + 1)] <- sqrt(i/2)
    J[cbind(i + 1, i)] <- sqrt(i/2)
    eg <- eigen(J, symmetric = TRUE)
    nodes <- eg$values
    weights <- sqrt(pi) * eg$vectors[1, ]^2
    o <- order(nodes)
    data.frame(node = nodes[o], weight = weights[o])
}
generate_recapture_counts <-
function (N, rmax, distribution = "gaussian", params = list(), 
    allow_zero = TRUE) 
{
    distribution <- tolower(distribution)
    lower <- if (allow_zero) 
        0L
    else 1L
    clamp <- function(x) pmin(rmax, pmax(lower, as.integer(round(x))))
    counts <- switch(distribution, uniform = sample(lower:rmax, 
        N, replace = TRUE), gaussian = {
        mean <- params$mean %||% (rmax/3)
        sd <- params$sd %||% max(1, rmax/6)
        clamp(stats::rnorm(N, mean = mean, sd = sd))
    }, normal = {
        mean <- params$mean %||% (rmax/3)
        sd <- params$sd %||% max(1, rmax/6)
        clamp(stats::rnorm(N, mean = mean, sd = sd))
    }, exponential = {
        rate <- params$rate %||% (3/max(1, rmax))
        clamp(stats::rexp(N, rate = rate))
    }, negexp = {
        rate <- params$rate %||% (3/max(1, rmax))
        clamp(stats::rexp(N, rate = rate))
    }, chisq = {
        df <- params$df %||% 2
        scale <- params$scale %||% (rmax/stats::qchisq(0.94999999999999996, 
            df = df))
        clamp(stats::rchisq(N, df = df) * scale)
    }, chi_square = {
        df <- params$df %||% 2
        scale <- params$scale %||% (rmax/stats::qchisq(0.94999999999999996, 
            df = df))
        clamp(stats::rchisq(N, df = df) * scale)
    }, negative_binomial = {
        size <- params$size %||% 1
        mu <- params$mu %||% (rmax/4)
        clamp(stats::rnbinom(N, size = size, mu = mu))
    }, negbin = {
        size <- params$size %||% 1
        mu <- params$mu %||% (rmax/4)
        clamp(stats::rnbinom(N, size = size, mu = mu))
    }, poisson = {
        lambda <- params$lambda %||% (rmax/4)
        clamp(stats::rpois(N, lambda = lambda))
    }, beta_binomial = {
        shape1 <- params$shape1 %||% 0.69999999999999996
        shape2 <- params$shape2 %||% 3
        prob <- stats::rbeta(N, shape1 = shape1, shape2 = shape2)
        as.integer(stats::rbinom(N, size = rmax, prob = prob))
    }, stop("Unknown recapture_distribution: ", distribution))
    if (!allow_zero) 
        counts[counts < 1L] <- 1L
    as.integer(pmin(rmax, pmax(lower, counts)))
}
