guided_analysis_next_step_menu <-
function (analysis, input_provider = NULL, max_steps = if (is.null(input_provider)) Inf else 50L) 
{
    steps <- 0L
    repeat {
        print_post_simulation_menu()
        ans <- .resident_prompt("Enter option number or name: ", 
            input_provider)
        handled <- handle_post_simulation_menu_choice(ans, analysis, 
            input_provider = input_provider)
        if (is.list(handled) && !is.null(handled$analysis)) 
            analysis <- handled$analysis
        assign("analysis", analysis, envir = .GlobalEnv)
        if (is.list(handled) && isTRUE(handled$finished)) {
            cat("Workflow finished. The current analysis object is available as analysis in the global R environment.\n")
            return(invisible(analysis))
        }
        steps <- steps + 1L
        if (steps >= max_steps) 
            return(invisible(analysis))
        print_post_option_menu_return()
    }
}
