hessian_delta_ci <-
function (estimate, se = NULL, level = 0.94999999999999996, link = "identity", 
    vcov = NULL, parameter_index = NULL) 
{
    if (is.null(se) && !is.null(vcov) && !is.null(parameter_index)) {
        se <- sqrt(abs(vcov[parameter_index, parameter_index]))
    }
    z <- stats::qnorm(1 - (1 - level)/2)
    if (!is.finite(estimate) || !is.finite(se)) {
        return(list(lower = NA_real_, upper = NA_real_, SE = NA_real_, 
            status = "unavailable", warning = "Confidence interval unavailable because no stable Hessian, profile likelihood, or bootstrap result was available."))
    }
    list(lower = estimate - z * se, upper = estimate + z * se, 
        SE = se, status = "computed", warning = "")
}
hessian_uncertainty <-
function (fit, level = 0.94999999999999996) 
{
    h <- fit$optim$hessian
    if (is.null(h) || any(!is.finite(h))) 
        return(NULL)
    vc <- tryCatch(solve(h), error = function(e) NULL)
    if (is.null(vc)) 
        vc <- tryCatch(qr.solve(h), error = function(e) NULL)
    if (is.null(vc)) 
        return(NULL)
    se <- sqrt(pmax(0, diag(vc)))
    z <- stats::qnorm(1 - (1 - level)/2)
    est <- fit$optim$par
    data.frame(parameter = names(est) %||% paste0("par_", seq_along(est)), 
        estimate = est, SE = se, lower_CI = est - z * se, upper_CI = est + 
            z * se, stringsAsFactors = FALSE)
}
history_error_context <-
function (stage = NULL, object = NULL, expected = "binary matrix with individuals as rows and sampling occasions as columns", 
    likely_cause = NULL, suggested_fix = "use extract_history(analysis) or as_resident_encounter_data().") 
{
    received <- if (is.null(object)) {
        "NULL"
    }
    else if (is.data.frame(object)) {
        paste0("data.frame with ", nrow(object), " row(s) and ", 
            ncol(object), " column(s)")
    }
    else if (is.matrix(object)) {
        paste0("matrix with ", nrow(object), " row(s) and ", 
            ncol(object), " column(s)")
    }
    else if (is.list(object)) {
        paste0("list with names: ", paste(names(object), collapse = ", "))
    }
    else {
        paste(class(object), collapse = "/")
    }
    paste("Encounter-history error.", paste0("Stage: ", stage %||% 
        "unspecified"), paste0("Object received: ", received, 
        "."), paste0("Expected: ", expected, "."), paste0("Likely cause: ", 
        likely_cause %||% "a malformed object was passed where an encounter-history matrix was expected."), 
        paste0("Suggested fix: ", suggested_fix), sep = "\n")
}
hmm_pack_params <-
function (initial_probs, transition_matrix, detection_prob) 
{
    K <- length(initial_probs)
    c(log(initial_probs[-K]/initial_probs[K]), unlist(lapply(seq_len(K), 
        function(i) {
            log(transition_matrix[i, -K]/transition_matrix[i, 
                K])
        })), logit(pmin(1 - 9.9999999999999995e-07, pmax(9.9999999999999995e-07, 
        detection_prob[-1]))))
}
hmm_unpack_params <-
function (par, K, states) 
{
    pos <- 1
    init_eta <- c(par[pos:(pos + K - 2)], 0)
    pos <- pos + K - 1
    initial_probs <- softmax(init_eta)
    transition_matrix <- matrix(0, nrow = K, ncol = K)
    for (i in seq_len(K)) {
        eta <- c(par[pos:(pos + K - 2)], 0)
        transition_matrix[i, ] <- softmax(eta)
        pos <- pos + K - 1
    }
    detection_prob <- c(0, inv_logit(par[pos:(pos + K - 2)]))
    names(initial_probs) <- names(detection_prob) <- states
    rownames(transition_matrix) <- colnames(transition_matrix) <- states
    list(initial_probs = initial_probs, transition_matrix = transition_matrix, 
        detection_prob = detection_prob)
}
huggins_capture_probability <-
function (history, abundance_model = "huggins_M0", par = NULL) 
{
    y <- .observed_history(history)
    K <- ncol(y)
    if (is.null(par)) 
        par <- .initial_huggins_par(y, abundance_model)
    if (abundance_model == "huggins_M0") {
        p <- rep(.invlogit(par[["lp"]]), K)
        q0 <- prod(1 - p)
        list(p = p, c = NA_real_, pi = NA_real_, pstar = 1 - 
            q0)
    }
    else if (abundance_model == "huggins_Mt") {
        p <- .invlogit(par[paste0("lp", seq_len(K))])
        q0 <- prod(1 - p)
        list(p = p, c = NA_real_, pi = NA_real_, pstar = 1 - 
            q0)
    }
    else if (abundance_model == "huggins_Mb") {
        p <- .invlogit(par[["lp"]])
        cc <- .invlogit(par[["lc"]])
        list(p = rep(p, K), c = rep(cc, K), pi = NA_real_, pstar = 1 - 
            (1 - p)^K)
    }
    else if (abundance_model == "huggins_Mh") {
        pi1 <- .invlogit(par[["lpi1"]])
        p1 <- rep(.invlogit(par[["lp1"]]), K)
        p2 <- rep(.invlogit(par[["lp2"]]), K)
        pstar <- pi1 * (1 - prod(1 - p1)) + (1 - pi1) * (1 - 
            prod(1 - p2))
        list(p = rbind(class_1 = p1, class_2 = p2), c = NA_real_, 
            pi = c(class_1 = pi1, class_2 = 1 - pi1), pstar = pstar)
    }
    else {
        stop("Unsupported Huggins abundance model.", call. = FALSE)
    }
}
