huggins_loglik <-
function (par, history, abundance_model = "huggins_M0") 
{
    y <- .observed_history(history)
    cp <- huggins_capture_probability(y, abundance_model, par)
    if (abundance_model %in% c("huggins_M0", "huggins_Mt")) {
        pieces <- .closed_prob_matrix(y, sub("huggins", "closed", 
            abundance_model), c(log_f0 = 0, par))
        sum(log(pieces$prob)) - nrow(y) * log(cp$pstar)
    }
    else if (abundance_model == "huggins_Mb") {
        pieces <- .closed_prob_matrix(y, "closed_Mb", c(log_f0 = 0, 
            par))
        sum(log(pieces$prob)) - nrow(y) * log(cp$pstar)
    }
    else if (abundance_model == "huggins_Mh") {
        pieces <- .closed_prob_matrix(y, "closed_Mh_mixture", 
            c(log_f0 = 0, par))
        sum(log(pieces$prob)) - nrow(y) * log(cp$pstar)
    }
    else {
        stop("Unsupported Huggins abundance model.", call. = FALSE)
    }
}
