infer_detection_assumption_from_formula <-
function (detection_formula) 
{
    if (is.null(detection_formula)) 
        return("constant")
    f <- if (inherits(detection_formula, "formula")) 
        paste(deparse(detection_formula), collapse = " ")
    else as.character(detection_formula)
    f <- gsub("\\s+", " ", trimws(f))
    has_effort <- grepl("effort", f)
    has_state <- grepl("state", f)
    if (has_effort && has_state) 
        return("effort_plus_state")
    if (has_effort) 
        return("effort")
    if (has_state) 
        return("state")
    if (f %in% c("~ 1", "~1")) 
        return("constant")
    "custom_formula"
}
infer_primary_secondary_periods <-
function (history, occasions = NULL, primary_method = "by month", 
    secondary_method = "each occasion within primary period") 
{
    y <- coerce_history_matrix(history, stage = "temporal inference")
    occ <- as.data.frame(occasions %||% data.frame(occasion = seq_len(ncol(y))))
    dates <- if ("date" %in% names(occ)) 
        as.Date(occ$date)
    else rep(as.Date(NA), nrow(occ))
    primary <- switch(primary_method, `one primary period` = rep("primary_1", 
        ncol(y)), `by day` = format(dates, "%Y-%m-%d"), `by week` = paste0(format(dates, 
        "%Y"), "-W", format(dates, "%U")), `by month` = format(dates, 
        "%Y-%m"), `by season` = paste0(format(dates, "%Y"), "-S", 
        ((as.integer(format(dates, "%m")) - 1L)%/%3L) + 1L), 
        `by year` = format(dates, "%Y"), `existing column` = occ$primary_period %||% 
            occ$primary, occ$primary_period %||% occ$primary %||% 
            rep("primary_1", ncol(y)))
    if (is.null(primary) || length(primary) != ncol(y) || any(is.na(primary))) 
        stop("Primary periods could not be inferred from the supplied occasion table.", 
            call. = FALSE)
    secondary <- switch(secondary_method, `each occasion within primary period` = ave(seq_len(ncol(y)), 
        primary, FUN = seq_along), `existing column` = occ$secondary_period %||% 
        occ$secondary, occ$secondary_period %||% occ$secondary %||% 
        ave(seq_len(ncol(y)), primary, FUN = seq_along))
    if (is.null(secondary) || length(secondary) != ncol(y) || 
        any(is.na(secondary))) 
        stop("Secondary periods could not be inferred from the supplied occasion table.", 
            call. = FALSE)
    intervals <- if (all(!is.na(dates)) && length(dates) > 1L) 
        as.numeric(diff(dates))
    else rep(1, max(0, ncol(y) - 1L))
    list(primary_period = as.character(primary), secondary_period = as.character(secondary), 
        time_intervals = intervals, time_interval_scale = if (all(!is.na(dates))) "actual_elapsed_days" else "equal intervals", 
        detection_structure = "occasion", transition_structure = "fixed", 
        source = "diagnostic_inference", confirmed = FALSE, confirmed_at = NA, 
        user_choice = primary_method, diagnostics = temporal_structure_diagnostics(history, 
            occasions))
}
inference_reliability_assessment <-
function (fit) 
{
    old <- publication_readiness_report(fit)
    warnings <- if (nrow(old$warnings)) 
        translate_warning_interpretation(old$warnings$warning)
    else character(0)
    list(inference_reliable = isTRUE(old$suitable_for_publication_inference), 
        parameter_identifiability = transform(old$parameter_identifiability, 
            reliability_interpretation = translate_warning_interpretation(reason)), 
        warnings = data.frame(warning = warnings, stringsAsFactors = FALSE), 
        recommended_next_steps = old$recommended_simplifications, 
        interpretation_summary = if (isTRUE(old$suitable_for_publication_inference)) {
            "The data and model passed the current reliability checks. Continue by checking profiles, bootstrap intervals, and biological plausibility."
        } else {
            "The data or model did not pass the current reliability checks. This does not mean the data are unusable; it means the current model may be too complex or uncertainty is not stable enough."
        })
}
