integrated_random_effect_likelihood <-
function (par, rd_array, spec, transition_structure, design, 
    n_quad = 11) 
{
    nbeta <- ncol(design$X)
    beta <- par[seq_len(nbeta)]
    names(beta) <- colnames(design$X)
    sigma <- exp(par[nbeta + 1])
    gh <- gaussian_quadrature_nodes(n_quad)
    ll <- 0
    for (i in seq_len(dim(rd_array$y)[1])) {
        vals <- vapply(seq_len(nrow(gh)), function(q) {
            off <- sqrt(2) * sigma * gh$node[q]
            forward_algorithm_robust_design(robust_design_individual_matrix(rd_array, 
                i), rd_array, spec$initial_probs, spec$transition_matrix, 
                design, beta, spec$states, spec$unavailable_states, 
                i, detection_offset = off)$logLik + log(gh$weight[q]/sqrt(pi))
        }, numeric(1))
        m <- max(vals)
        ll <- ll + m + log(sum(exp(vals - m)))
    }
    list(logLik = ll, beta = beta, sigma = sigma)
}
