function (x) 
{
    if (is_resident_encounter_data(x)) 
        return(TRUE)
    if (!(is.matrix(x) || is.data.frame(x))) 
        return(FALSE)
    if (is_data_summary_table(x)) 
        return(FALSE)
    z <- if (is.data.frame(x)) {
        id_col <- which(tolower(names(x)) %in% c("id", "individual", 
            "individual_id"))
        if (length(id_col)) 
            x[, -id_col[1], drop = FALSE]
        else x
    }
    else x
    vals <- unlist(z, use.names = FALSE)
    vals <- vals[!is.na(vals)]
    length(vals) > 0L && all(as.character(vals) %in% c("0", "1", 
        "FALSE", "TRUE", "false", "true"))
