jolly_seber_derived_parameter_table <-
function (fit) 
{
    rows <- list(data.frame(model_name = fit$model_name %||% 
        "jolly_seber", derived_parameter = "apparent_survival_or_persistence", 
        index = "constant", estimate = fit$phi_hat, SE = NA_real_, 
        lower_95 = NA_real_, upper_95 = NA_real_, uncertainty_method = "not_available", 
        uncertainty_status = "unavailable", result_interpretation = "Probability of staying in the available/open-population process between occasions.", 
        warning = fit$warning %||% "", stringsAsFactors = FALSE), 
        data.frame(model_name = fit$model_name %||% "jolly_seber", 
            derived_parameter = "detection_probability", index = "constant", 
            estimate = fit$p_hat, SE = NA_real_, lower_95 = NA_real_, 
            upper_95 = NA_real_, uncertainty_method = "not_available", 
            uncertainty_status = "unavailable", result_interpretation = "Probability that an available individual is detected on an occasion.", 
            warning = "", stringsAsFactors = FALSE))
    if (!is.null(fit$b_hat)) {
        for (i in seq_along(fit$b_hat)) rows[[length(rows) + 
            1L]] <- data.frame(model_name = fit$model_name %||% 
            "jolly_seber", derived_parameter = "pent", index = as.character(i), 
            estimate = fit$b_hat[i], SE = NA_real_, lower_95 = NA_real_, 
            upper_95 = NA_real_, uncertainty_method = "not_available", 
            uncertainty_status = "unavailable", result_interpretation = "Entry probability for this occasion.", 
            warning = "", stringsAsFactors = FALSE)
        cb <- cumsum(fit$b_hat)
        for (i in seq_along(cb)) rows[[length(rows) + 1L]] <- data.frame(model_name = fit$model_name %||% 
            "jolly_seber", derived_parameter = "cumulative_entry", 
            index = as.character(i), estimate = cb[i], SE = NA_real_, 
            lower_95 = NA_real_, upper_95 = NA_real_, uncertainty_method = "not_available", 
            uncertainty_status = "unavailable", result_interpretation = "Cumulative entry probability through this occasion.", 
            warning = "", stringsAsFactors = FALSE)
    }
    if (!is.null(fit$N_by_occasion)) 
        for (i in seq_along(fit$N_by_occasion)) rows[[length(rows) + 
            1L]] <- data.frame(model_name = fit$model_name %||% 
            "jolly_seber", derived_parameter = "N_by_occasion", 
            index = as.character(i), estimate = fit$N_by_occasion[i], 
            SE = NA_real_, lower_95 = NA_real_, upper_95 = NA_real_, 
            uncertainty_method = "not_available", uncertainty_status = "unavailable", 
            result_interpretation = "Model-based abundance by occasion.", 
            warning = "", stringsAsFactors = FALSE)
    do.call(rbind, rows)
}
jolly_seber_loglik <-
function (par, history) 
{
    s <- .open_history_summary_v089(history)
    phi <- inv_logit(par[1])
    p <- inv_logit(par[2])
    pent_raw <- exp(par[seq(3, length(par))])
    pent <- pent_raw/sum(pent_raw)
    ll <- 0
    for (i in seq_len(s$n_detected)) {
        fi <- s$first[i]
        if (!is.finite(fi)) 
            next
        entry_prob <- pent[fi]
        yi <- s$y[i, fi:s$n_occasions]
        alive_len <- seq_along(yi) - 1
        prob_obs <- ifelse(yi == 1, p, 1 - p)
        surv_weight <- phi^alive_len
        ll <- ll + log(pmax(entry_prob, 9.9999999999999998e-13)) + 
            sum(log(pmax(prob_obs * pmax(surv_weight, 1e-08), 
                9.9999999999999998e-13)))
    }
    ll
}
