likelihood_surface_grid <-
function (fit, par1, values1, par2, values2) 
{
    if (!(par1 %in% names(fit$beta)) || !(par2 %in% names(fit$beta))) {
        stop("likelihood_surface_grid currently supports beta coefficients.")
    }
    rows <- list()
    n <- 1L
    for (v1 in values1) for (v2 in values2) {
        beta <- fit$beta
        beta[par1] <- v1
        beta[par2] <- v2
        ll <- robust_design_likelihood(c(beta, numeric(0)), fit$rd_array, 
            fit$spec, fit$transition_structure, fit$detection_design, 
            estimate_transition = FALSE)$logLik
        rows[[n]] <- data.frame(parameter1 = par1, value1 = v1, 
            parameter2 = par2, value2 = v2, logLik = ll)
        n <- n + 1L
    }
    do.call(rbind, rows)
}
