literature_classifier_summary_long <-
function (classification) 
{
    if (is.null(classification) || !is.data.frame(classification) || 
        !nrow(classification)) 
        return(NULL)
    meta <- literature_classifier_metadata()
    cols <- intersect(meta$classifier_column, names(classification))
    if (!length(cols)) 
        return(NULL)
    pieces <- lapply(cols, function(col) {
        values <- format_literature_category_label(classification[[col]], 
            col)
        tab <- as.data.frame(table(factor(values, levels = sort(unique(values))), 
            useNA = "ifany"), stringsAsFactors = FALSE)
        names(tab) <- c("category", "number_of_individuals")
        info <- meta[match(col, meta$classifier_column), , drop = FALSE]
        data.frame(classifier = info$classifier, classifier_column = col, 
            assessment_type = info$assessment_type, category_type = info$category_type, 
            category = as.character(tab$category), number_of_individuals = as.integer(tab$number_of_individuals), 
            proportion = round(as.integer(tab$number_of_individuals)/nrow(classification), 
                3), result_meaning = paste0("This row counts individuals assigned to '", 
                as.character(tab$category), "' by the ", info$classifier, 
                " rule."), note = info$plain_language_note, stringsAsFactors = FALSE)
    })
    out <- do.call(rbind, pieces)
    rownames(out) <- NULL
    attr(out, "interpretation") <- "This long-format table summarizes every implemented literature-based residency/site-fidelity classifier separately. Different classifiers can disagree because they use different thresholds and definitions."
    out
}
