    is_true_site_fidelity <- grepl("true_site_fidelity|spatial site-fidelity|spatial fidelity", 
        txt, ignore.case = TRUE)
    is_proxy <- grepl("sighting[- ]?frequency|frequency|site-use proxy|residency/site-fidelity|site[- ]?fidelity grouping", 
        txt, ignore.case = TRUE)
    ifelse(is_true_site_fidelity, "true_site_fidelity", ifelse(is_proxy, 
        "sighting_frequency_proxy", "residency"))
}
