literature_residency_overview_table <-
function (classification) 
{
    if (is.null(classification) || !is.data.frame(classification) || 
        !nrow(classification)) 
        return(NULL)
    cols <- intersect(c("id", "occurrence", "permanence_days", 
        "mean_interval_days", "primary_literature_category", 
        "primary_classifier", "primary_classifier_confidence"), 
        names(classification))
    out <- classification[, cols, drop = FALSE]
    if (!"primary_literature_category" %in% names(out)) {
        cats <- literature_category_columns(classification)
        if (length(cats)) {
            out$primary_literature_category <- classification[[cats[1]]]
            out$primary_classifier <- resident_literature_classifier_label(cats[1])
        }
    }
    if (!"primary_classifier" %in% names(out)) 
        out$primary_classifier <- "No literature classifier available"
    confidence <- if ("primary_classifier_confidence" %in% names(out)) 
        out$primary_classifier_confidence
    else "unknown"
    out$result_note <- paste0("Rule: ", out$primary_classifier, 
        "; confidence: ", confidence, ".")
    out
}
load_resident_tmb <-
function (source = NULL, compile = FALSE, verbose = FALSE) 
{
    if (!tmb_available()) {
        return(list(ok = FALSE, status = "TMB_not_installed", 
            message = "TMB is not installed; using backend='base' is recommended."))
    }
    source <- source %||% file.path(getwd(), "resident_tmb.cpp")
    if (!file.exists(source)) {
        alt <- file.path(getwd(), "outputs", "resident_tmb.cpp")
        if (file.exists(alt)) 
            source <- alt
    }
    if (compile) {
        comp <- compile_resident_tmb(source, verbose)
        if (!isTRUE(comp$ok)) 
            return(comp)
    }
    oldwd <- getwd()
    on.exit(setwd(oldwd), add = TRUE)
    setwd(dirname(source))
    lib <- TMB::dynlib(tools::file_path_sans_ext(basename(source)))
    res <- tryCatch({
        if (!is.loaded("objective_function", PACKAGE = basename(lib))) 
            dyn.load(lib)
        list(ok = TRUE, status = "loaded", dynlib = lib, source = source)
    }, error = function(e) list(ok = FALSE, status = "load_failed", 
        dynlib = lib, source = source, message = conditionMessage(e)))
    res
}
