make_analysis_object <-
function (sim = NULL, imported = NULL, fit = NULL, config = NULL) 
{
    if (!is.null(imported)) {
        if (!isTRUE(imported$check$ok)) 
            stop("Cannot create analysis object because the imported data failed validation: ", 
                imported$check$message)
        data <- imported$data
        return(list(data = data, import_check = imported$check, 
            model_recommendation = recommend_model_structure(data), 
            capture_data_summary = capture_data_summary(data), 
            discovery_curve_table = discovery_curve_table(data), 
            fit = fit, config = config))
    }
    capture_ok <- tryCatch(!is.null(capture_recapture_table_from_analysis(list(sim = sim))), 
        error = function(e) FALSE)
    if (!isTRUE(capture_ok)) {
        return(list(sim = sim, fit = fit, config = config, capture_data_summary = NULL, 
            discovery_curve_table = NULL))
    }
    list(sim = sim, fit = fit, config = config, capture_data_summary = sim$capture_data_summary %||% 
        capture_data_summary(sim), discovery_curve_table = sim$discovery_curve_table %||% 
        discovery_curve_table(sim))
}
make_entry_probabilities <-
function (n_occasions, b = NULL, b_first_range = c(0.050000000000000003, 
    0.14999999999999999)) 
{
    if (!is.null(b)) {
        if (length(b) != n_occasions) 
            stop("b must have length n_occasions.")
        b <- b/sum(b)
        return(b)
    }
    b1 <- runif(1, min = b_first_range[1], max = b_first_range[2])
    c(b1, rep((1 - b1)/(n_occasions - 1L), n_occasions - 1L))
}
make_occasion_table <-
function (start_date = Sys.Date(), n_occasions = NULL, dates = NULL, 
    occasion_unit = "day") 
{
    if (!is.null(dates)) {
        dates <- as.Date(dates)
    }
    else {
        if (is.null(n_occasions)) 
            stop("Provide either dates or n_occasions.")
        step <- switch(occasion_unit, day = "day", week = "week", 
            month = "month", stop("occasion_unit must be day, week, or month."))
        dates <- seq.Date(as.Date(start_date), by = step, length.out = n_occasions)
    }
    data.frame(occasion = seq_along(dates), date = dates, year = as.integer(format(dates, 
        "%Y")), month = as.integer(format(dates, "%m")), season = ((as.integer(format(dates, 
        "%m")) - 1L)%/%3L) + 1L, effort = 1, stringsAsFactors = FALSE)
}
make_robust_design <-
function (occasion_table, primary = c("season", "year", "month"), 
    secondary = "survey") 
{
    primary <- match.arg(primary)
    primary_id <- switch(primary, year = as.character(occasion_table$year), 
        season = paste(occasion_table$year, occasion_table$season, 
            sep = "-S"), month = format(occasion_table$date, 
            "%Y-%m"))
    out <- occasion_table
    out$primary_period <- match(primary_id, unique(primary_id))
    out$primary_label <- primary_id
    out$secondary_period <- ave(out$occasion, out$primary_period, 
        FUN = seq_along)
    out$secondary_label <- paste(out$primary_label, out$secondary_period, 
        sep = ":")
    out
}
make_spatial_state_spec <-
function (empirical, area_col = "area", site_col = "site") 
{
    meta <- empirical$metadata
    if (is.null(meta)) 
        return(state_space_specification())
    area_var <- if (area_col %in% names(meta)) 
        area_col
    else if (site_col %in% names(meta)) 
        site_col
    else NULL
    if (is.null(area_var)) 
        return(state_space_specification())
    areas <- sort(unique(na.omit(meta[[area_var]])))
    states <- c("outside", paste0("area_", make.names(areas)))
    state_space_specification(states = states, unavailable_states = "outside", 
        detection_formula = ~effort)
}
