menu_definition <-
function (id, title, labels, keys = NULL, exit_label = "Exit") 
{
    labels <- as.character(labels)
    keys <- keys %||% tolower(gsub("[^a-z0-9]+", "_", labels))
    if (length(labels) != length(keys)) 
        stop("Menu labels and keys must have the same length.", 
            call. = FALSE)
    exit_like <- .exit_like_label_v088(labels)
    if (any(exit_like)) {
        exit_lab <- labels[which(exit_like)[length(which(exit_like))]]
        exit_key <- keys[which(exit_like)[length(which(exit_like))]]
        labels <- labels[!exit_like]
        keys <- keys[!exit_like]
    }
    else {
        exit_lab <- exit_label
        exit_key <- tolower(exit_label)
    }
    out <- data.frame(option = seq_along(labels), key = keys, 
        label = labels, stringsAsFactors = FALSE)
    out <- rbind(out, data.frame(option = 0L, key = exit_key, 
        label = exit_lab, stringsAsFactors = FALSE))
    attr(out, "menu_id") <- id
    attr(out, "title") <- title
    validate_menu_definition(out)
    out
}
