merge_abundance_recommendation_details <-
function (details, rec) 
{
    tab <- NULL
    if (is.list(rec) && !is.null(rec$recommendation_table)) 
        tab <- rec$recommendation_table
    else if (is.data.frame(rec)) 
        tab <- rec
    if (is.null(tab) || !"candidate_model" %in% names(tab)) 
        return(details)
    keep <- intersect(c("candidate_model", "suitability", "assumptions_status", 
        "data_support", "expected_risk", "recommendation"), names(tab))
    tab <- tab[, keep, drop = FALSE]
    merge(details, tab, by = "candidate_model", all.x = TRUE, 
        sort = FALSE)
}
