model_based_residency_status_report <-
function (analysis) 
{
    state_tab <- .safe_model_based_residency_table(analysis)
    slot_fit <- model_fit_slot_for_residency_status(analysis)
    fit <- slot_fit$fit
    model_name <- model_fit_name_for_residency_status(fit)
    output_type <- if (is.na(model_name)) 
        "none"
    else classify_model_output_target(model_name)
    stored_fit <- !is.null(fit)
    state_table_available <- !is.null(state_tab) && is.data.frame(state_tab) && 
        nrow(state_tab) > 0
    fit_explanation <- if (!stored_fit) {
        "No fitted model object is currently stored in analysis."
    }
    else if (identical(output_type, "abundance")) {
        "The stored fit is an abundance or abundance-diagnostic model. It can estimate counts or abundance-related summaries, but it does not assign individual residency states."
    }
    else if (identical(output_type, "survival_detection")) {
        "The stored fit is a survival/detection model. It estimates apparent survival or persistence and detection, but it does not assign individual residency states."
    }
    else if (identical(output_type, "residency_state_space")) {
        "The selected model family is intended for residency states, but no individual state-classification table is stored yet."
    }
    else {
        "The stored fit does not advertise an individual residency-state output."
    }
    legacy_state_wrappers <- all(c("fit_state_space_robust_design", 
        "fit_latent_residency_model", "fit_markovian_state_model") %in% 
        ls(envir = .GlobalEnv))
    data.frame(check = c("model_based_residency_state_table", 
        "current_fitted_model", "state_model_backend", "recommended_next_step"), 
        status = c(if (state_table_available) "available" else "not_available", 
            if (stored_fit) "fit_stored" else "no_fit_stored", 
            if (legacy_state_wrappers) "legacy_wrappers_present" else "not_detected", 
            "action"), detail = c(if (state_table_available) "A fitted model-based individual residency-state table is stored and can be displayed." else "No fitted model-based individual residency-state table is stored in this analysis object.", 
            fit_explanation, if (legacy_state_wrappers) "Legacy state-model wrapper function names are still present in the code, but the current stable menu workflow does not claim a completed individual residency-state backend unless it stores state probabilities or assigned states in the analysis object." else "No state-model wrapper functions were detected in the active session.", 
            "Use Option 5 and Option 6 for literature-based residency and site-use classifications. Use Option 22 and Option 23 for abundance-model outputs. A true model-based residency-state table requires a supported residency-state model backend that stores individual state probabilities or classes."), 
        fit_slot = c(NA_character_, slot_fit$slot, NA_character_, 
            NA_character_), model_name = c(NA_character_, model_name, 
            NA_character_, NA_character_), output_type = c("residency_state_table", 
            output_type, "backend_status", "guidance"), stringsAsFactors = FALSE)
}
