model_registry <-
function () 
{
    reg <- .resident_v093_model_registry()
    reg <- reg[reg$candidate_model != "CJS_like", , drop = FALSE]
    if (!"estimates_abundance" %in% names(reg)) 
        reg$estimates_abundance <- vapply(reg$candidate_model, 
            function(m) classify_model_output_target(m) == "abundance", 
            logical(1))
    if (!"target" %in% names(reg)) 
        reg$target <- NA_character_
    if (!"parameter_table_function" %in% names(reg)) 
        reg$parameter_table_function <- NA_character_
    if (!"derived_table_function" %in% names(reg)) 
        reg$derived_table_function <- NA_character_
    hit <- reg$candidate_model == "CJS"
    if (!any(hit)) {
        add <- reg[1, , drop = FALSE]
        add[1, ] <- NA
        add$candidate_model <- "CJS"
        reg <- rbind(reg, add)
        hit <- reg$candidate_model == "CJS"
    }
    reg$model_family[hit] <- "open_population"
    reg$model_role[hit] <- "survival_detection"
    reg$implemented[hit] <- TRUE
    reg$selectable_from_abundance_menu[hit] <- FALSE
    reg$fit_function[hit] <- "fit_cjs_model"
    reg$parameter_table_function[hit] <- "cjs_parameter_table"
    reg$derived_table_function[hit] <- "cjs_derived_parameter_table"
    reg$output_slots[hit] <- "survival_detection_fit"
    reg$target[hit] <- "survival/detection parameter model, not abundance model"
    reg$estimates_abundance[hit] <- FALSE
    reg
}
