model_selection_metrics <-
function (logLik, npar, nobs, chat = 1) 
{
    aic <- 2 * npar - 2 * logLik
    aicc <- aic + (2 * npar * (npar + 1))/max(1, nobs - npar - 
        1)
    bic <- log(nobs) * npar - 2 * logLik
    qaic <- (-2 * logLik/chat) + 2 * npar
    c(AIC = aic, AICc = aicc, QAIC = qaic, BIC = bic)
}
