model_suitability_for_data <-
function (model, diag) 
{
    if (!isTRUE(diag$ok)) {
        return(c(suitability = "not_assessable", assumptions_status = "data unavailable", 
            data_support = "cannot evaluate", expected_risk = "unknown", 
            recommendation = diag$reason))
    }
    sparse <- diag$total_detections < 20 || diag$recaptured_individuals < 
        5 || diag$recapture_fraction < 0.14999999999999999
    very_sparse <- diag$total_detections < 10 || diag$recaptured_individuals < 
        2
    high_singletons <- is.finite(diag$singleton_fraction) && 
        diag$singleton_fraction >= 0.34999999999999998
    time_variation <- is.finite(diag$occasion_cv) && diag$occasion_cv >= 
        0.5
    empty_occasions <- diag$occasions_with_no_detections > 0
    enough_closed <- diag$n_ids >= 10 && diag$n_occ >= 3 && diag$total_detections >= 
        20
    enough_time <- diag$n_occ >= 5 && diag$total_detections >= 
        25
    enough_open <- diag$n_occ >= 6 && diag$recaptured_individuals >= 
        5 && diag$total_detections >= 30
    if (model == "observed_only") {
        return(c(suitability = "useful_baseline", assumptions_status = "minimal assumptions", 
            data_support = "always computable from detections", 
            expected_risk = "underestimates abundance if animals were missed", 
            recommendation = "Use as a transparent observed count, not as a corrected abundance estimate."))
    }
    if (model == "chao1_chao2") {
        suit <- if (diag$total_detections >= 10 && (diag$singletons > 
            0 || diag$recaptured_individuals > 0)) 
            "recommended_as_simple_correction"
        else "weak_support"
        return(c(suitability = suit, assumptions_status = "uses sparse-detection structure rather than explicit detection model", 
            data_support = if (high_singletons) "many singletons support a missed-individual correction" else "limited singleton information", 
            expected_risk = if (very_sparse) "unstable with very sparse data" else "lower-bound estimate; can still be biased", 
            recommendation = if (suit == "recommended_as_simple_correction") "Use as an initial conservative abundance correction." else "Use cautiously; sparse detections may make the estimate unstable."))
    }
    if (model %in% c("closed_M0", "huggins_M0")) {
        bad <- c()
        if (!enough_closed) 
            bad <- c(bad, "few detections or recaptures for closed-population estimation.")
        if (time_variation) 
            bad <- c(bad, "detections vary by occasion, weakening the constant-detection assumption.")
        if (empty_occasions) 
            bad <- c(bad, "some occasions have no detections.")
        suit <- if (!length(bad)) 
            "recommended_if_population_was_closed"
        else if (enough_closed) 
            "acceptable_with_caution"
        else "not_recommended_for_current_data"
        return(c(suitability = suit, assumptions_status = if (!length(bad)) "main data checks passed; biological closure still must be justified" else join_reasons(bad), 
            data_support = paste0("detections=", diag$total_detections, 
                "; recaptured individuals=", diag$recaptured_individuals), 
            expected_risk = if (time_variation) "constant detection may be unrealistic" else "main risk is untested population closure", 
            recommendation = if (suit == "not_recommended_for_current_data") "Do not use as the main model unless more detections/recaptures are available." else "Use only if the sampling period can be treated as closed."))
    }
    if (model %in% c("closed_Mt", "huggins_Mt")) {
        bad <- c()
        if (!enough_time) 
            bad <- c(bad, "not enough detections across occasions for time-varying detection.")
        if (empty_occasions) 
            bad <- c(bad, "empty occasions can destabilize occasion effects.")
        suit <- if (!length(bad) && time_variation) 
            "recommended_if_population_was_closed"
        else if (!length(bad)) 
            "acceptable_with_caution"
        else "not_recommended_for_current_data"
        return(c(suitability = suit, assumptions_status = if (!length(bad)) "time-varying detection can be estimated; biological closure still must be justified" else join_reasons(bad), 
            data_support = paste0("occasion detection variation=", 
                ifelse(is.na(diag$occasion_cv), "not estimable", 
                  round(diag$occasion_cv, 3))), expected_risk = "more parameters than constant-detection models; needs enough detections by occasion", 
            recommendation = if (time_variation && suit != "not_recommended_for_current_data") "Prefer over constant-detection closed models if closure is defensible." else "Use only if there is a reason to model occasion-specific detection."))
    }
    if (model == "closed_Mb") {
        suit <- if (diag$recaptured_individuals >= 8 && diag$total_detections >= 
            30) 
            "acceptable_with_caution"
        else "weak_support"
        return(c(suitability = suit, assumptions_status = "behavior after first detection cannot be proven from the summary alone", 
            data_support = paste0("recaptured individuals=", 
                diag$recaptured_individuals), expected_risk = "behavioral response may be confused with heterogeneity or effort changes", 
            recommendation = if (suit == "acceptable_with_caution") "Consider only if field biology supports trap response or attraction/avoidance." else "Usually avoid unless more recaptures and a biological reason exist."))
    }
    if (model == "closed_Mh_mixture") {
        suit <- if (diag$recaptured_individuals >= 10 && diag$total_detections >= 
            40) 
            "acceptable_with_caution"
        else "weak_support"
        return(c(suitability = suit, assumptions_status = "individual detection heterogeneity needs many recaptures", 
            data_support = paste0("recaptured individuals=", 
                diag$recaptured_individuals, "; singletons=", 
                diag$singletons), expected_risk = "mixture models can overfit sparse data", 
            recommendation = if (suit == "acceptable_with_caution") "Consider as a sensitivity model for detection heterogeneity." else "Avoid as a primary model with sparse recaptures."))
    }
    if (model %in% c("robust_design_closed_primary", "robust_design_huggins_primary")) {
        bad <- c()
        if (!diag$robust_design_supported) 
            bad <- c(bad, "no confirmed primary/secondary robust-design temporal structure was detected.")
        if (diag$total_detections < 30) 
            bad <- c(bad, "few detections for primary-period estimation.")
        suit <- if (!length(bad)) 
            "recommended_for_robust_design_data"
        else "not_recommended_for_current_data"
        return(c(suitability = suit, assumptions_status = if (!length(bad)) "robust-design temporal structure is available" else join_reasons(bad), 
            data_support = paste0("robust-design structure=", 
                ifelse(diag$robust_design_supported, "yes", "no")), 
            expected_risk = "invalid if primary and secondary periods are not correctly defined", 
            recommendation = if (diag$robust_design_supported) "Use if closure within primary periods is biologically defensible." else "Do not use until primary/secondary occasions are defined and confirmed."))
    }
    if (model %in% c("jolly_seber", "POPAN_like")) {
        bad <- c()
        if (!enough_open) 
            bad <- c(bad, "few occasions, detections, or recaptures for open-population estimation.")
        if (diag$open_signal < 2) 
            bad <- c(bad, "little evidence of staggered entry or exit in the observed histories.")
        suit <- if (!length(bad)) 
            "acceptable_open_population_candidate"
        else "not_recommended_for_current_data"
        return(c(suitability = suit, assumptions_status = if (!length(bad)) "basic temporal support for open-population modeling is present" else join_reasons(bad), 
            data_support = paste0("occasions=", diag$n_occ, "; recaptured individuals=", 
                diag$recaptured_individuals, "; entry/exit signal=", 
                diag$open_signal), expected_risk = "survival, entry, and detection can be confounded when data are sparse", 
            recommendation = if (suit == "acceptable_open_population_candidate") "Consider if the biological population is open across the study period." else "Do not use as the main model without stronger temporal recapture support."))
    }
    c(suitability = "not_assessed", assumptions_status = "no rule available", 
        data_support = "not assessed", expected_risk = "unknown", 
        recommendation = "No recommendation available.")
}
