normal_approximation_interval <-
function (estimate, SE, level = 0.94999999999999996) 
{
    z <- qnorm(1 - (1 - level)/2)
    data.frame(lower_95 = estimate - z * SE, upper_95 = estimate + 
        z * SE, uncertainty_method = "normal_approximation_interval", 
        uncertainty_status = "approximated")
}
