normalize_detection_covariate_assumptions <-
function (value, detection_formula = NULL) 
{
    allowed <- detection_assumption_options()
    if (is.null(value) || !nzchar(trimws(as.character(value)[1]))) {
        return(list(detection_covariate_assumptions = infer_detection_assumption_from_formula(detection_formula), 
            detection_covariate_assumption_notes = "", migrated = FALSE, 
            warning = character()))
    }
    v <- tolower(trimws(as.character(value)[1]))
    v <- gsub("[ -]+", "_", v)
    if (v %in% allowed) {
        return(list(detection_covariate_assumptions = v, detection_covariate_assumption_notes = "", 
            migrated = FALSE, warning = character()))
    }
    inferred <- infer_detection_assumption_from_formula(detection_formula)
    list(detection_covariate_assumptions = inferred, detection_covariate_assumption_notes = as.character(value)[1], 
        migrated = TRUE, warning = "A free-text detection assumption note was detected. It has been retained as notes, but model structure now uses a validated detection-assumption option.")
}
normalize_import_choice <-
function (choice) 
{
    if (length(choice) != 1L) 
        return(vapply(choice, normalize_import_choice, character(1)))
    key <- toupper(trimws(as.character(choice)))
    if (key %in% c("0", "RETURN", "EXIT", "QUIT", "CANCEL")) 
        return("return")
    if (key %in% c("1", "PROGRAM_MARK", "PROGRAM MARK", "MARK")) 
        return("PROGRAM_MARK")
    if (key %in% c("2", "SOCPROG", "SOC PROG", "CSV_LONG", "LONG")) 
        return("SOCPROG")
    if (key %in% c("3", "AUTO", "NOT SURE", "UNSURE")) 
        return("AUTO")
    if (key %in% c("4", "EXAMPLES", "TEMPLATES", "EXAMPLE")) 
        return("examples")
    if (key %in% c("5", "WIDE", "WIDE_CSV", "WIDE CSV", "ENCOUNTER_HISTORY_WIDE")) 
        return("WIDE_CSV")
    if (key %in% c("6", "INP", "MARK_INP", "MARK INP")) 
        return("MARK_INP")
    if (key %in% c("7", "EXCEL", "XLSX", "XLS")) 
        return("EXCEL")
    NA_character_
}
normalize_menu_choice <-
function (choice, menu) 
{
    key <- tolower(trimws(as.character(choice)))
    if (!nzchar(key)) 
        return(NA_character_)
    if (grepl("^[0-9]+$", key)) {
        n <- as.integer(key)
        if (n %in% menu$option) 
            return(menu$key[match(n, menu$option)])
        cat("Menu navigation changed in v0.8.9. Use 0 to return, finish, cancel, or exit.\n")
        return(NA_character_)
    }
    idx <- match(key, tolower(menu$key))
    if (!is.na(idx)) 
        return(menu$key[idx])
    idx <- match(key, tolower(menu$label))
    if (!is.na(idx)) 
        return(menu$key[idx])
    cat("Menu navigation changed in v0.8.9. Use 0 to return, finish, cancel, or exit.\n")
    NA_character_
}
normalize_model_suitability_label <-
function (x) 
{
    x <- as.character(x %||% "not_assessed")
    if (x %in% c("recommended", "recommended_if_population_was_closed", 
        "recommended_as_simple_correction", "recommended_for_robust_design_data")) 
        return("recommended")
    if (x %in% c("useful_baseline")) 
        return("useful_baseline")
    if (x %in% c("acceptable_with_caution", "acceptable_open_population_candidate")) 
        return("acceptable_with_caution")
    if (x %in% c("weak_support", "not_recommended_for_current_data")) 
        return("not_recommended")
    if (x %in% c("not_assessable", "not_assessed")) 
        return(x)
    x
}
normalize_prob <-
function (x) 
{
    x <- pmax(as.numeric(x), 0)
    if (sum(x) <= 0) 
        rep(1/length(x), length(x))
    else x/sum(x)
}
