open_population_ready_check <-
function (history, occasions = NULL, requested_bootstrap = FALSE, 
    requested_profile = FALSE, random_effects_requested = FALSE, 
    covariates_requested = FALSE, estimated_parameters = NULL) 
{
    y <- coerce_history_matrix(history, stage = "open-population ready check")
    data.frame(number_of_individuals = nrow(y), number_of_occasions = ncol(y), 
        number_of_detections = sum(y > 0, na.rm = TRUE), number_of_recaptures = sum(rowSums(y > 
            0, na.rm = TRUE) > 1L), number_of_parameters = estimated_parameters %||% 
            (ncol(y) + 2L), requested_bootstrap = requested_bootstrap, 
        requested_profile_likelihood = requested_profile, random_effects_requested = random_effects_requested, 
        covariates_requested = covariates_requested, stringsAsFactors = FALSE)
}
open_population_signal_check <-
function (history, occasions = NULL) 
{
    y <- extract_history(history, stage = "open-population signal check")
    occ <- occasions %||% extract_occasions(history, stage = "open-population signal check")
    span <- .survey_span_days(occ)
    first <- apply(y == 1, 1, function(z) if (any(z)) 
        min(which(z))
    else NA_integer_)
    late_entry <- sum(!is.na(first) & first > max(1, floor(ncol(y)/3)))
    status <- if (!is.na(span) && span >= 180 && ncol(y) >= 6 && 
        late_entry > 0) 
        "pass"
    else if (ncol(y) >= 4) 
        "review"
    else "fail"
    data.frame(assumption = "open_population_signal", diagnostic_value = paste0("span_days=", 
        span, "; late_first_detections=", late_entry), status = status, 
        consequence = "Open-population models are more relevant when entry, exit, death, or emigration is plausible.", 
        recommendation = if (status == "pass") 
            "Open-population or state-space models should be considered."
        else "Open dynamics may be weakly supported by this encounter history.", 
        stringsAsFactors = FALSE)
}
output_path <-
function (filename, analysis = NULL, ext = NULL, prefix = NULL) 
{
    outdir <- analysis$run_output_dir %||% current_run_output_dir()
    dir.create(outdir, recursive = TRUE, showWarnings = FALSE)
    if (is.null(filename)) 
        filename <- paste0(prefix %||% "output", "_", format(Sys.time(), 
            "%Y-%m-%d_%H%M%S"), if (!is.null(ext)) 
            paste0(".", ext)
        else "")
    file.path(outdir, basename(filename))
}
parameter_confounding_matrix <-
function (bootstrap_table) 
{
    wide <- reshape(bootstrap_table, idvar = "replicate", timevar = "parameter", 
        direction = "wide")
    vals <- wide[setdiff(names(wide), "replicate")]
    if (ncol(vals) < 2) 
        return(matrix(NA_real_, ncol(vals), ncol(vals)))
    stats::cor(vals, use = "pairwise.complete.obs")
}
