parameter_identifiability_table <-
function (fit, profile = NULL) 
{
    pars <- names(fit$beta %||% numeric(0))
    if (!length(pars)) 
        pars <- "model"
    out <- data.frame(parameter = pars, classification = "estimable", 
        reason = "No major warning detected.", stringsAsFactors = FALSE)
    id <- if (!is.null(fit$identifiability)) 
        fit$identifiability
    else tryCatch(validate_multistate_identifiability(fit), error = function(e) NULL)
    if (!is.null(id) && isTRUE(id$sparse_data)) {
        out$classification <- "weakly estimable"
        out$reason <- "Sparse data relative to number of parameters."
    }
    if (!is.null(id) && (isTRUE(id$singular_hessian) || isTRUE(id$boundary_estimate))) {
        out$classification <- "non-identifiable"
        out$reason <- "Singular Hessian or boundary-scale estimate."
    }
    if (!is.null(profile) && "LR" %in% names(profile) && max(profile$LR, 
        na.rm = TRUE) < 1) {
        out$classification[out$parameter %in% unique(profile$parameter %||% 
            profile$from_state)] <- "weakly estimable"
        out$reason[out$parameter %in% unique(profile$parameter %||% 
            profile$from_state)] <- "Flat likelihood profile."
    }
    out
}
