parameter_metadata <-
function (parameter = NULL) 
{
    tab <- parameter_metadata_table()
    if (is.null(parameter)) 
        return(tab)
    key <- .parameter_key(parameter)
    hit <- match(key, .parameter_key(tab$parameter))
    if (is.na(hit)) 
        stop("No parameter metadata is registered for: ", parameter)
    tab[hit, , drop = FALSE]
}
