parameter_review_table <-
function (config, customized_only = FALSE) 
{
    defaults <- .metadata_defaults()
    names_to_review <- unique(c(names(defaults), names(config)))
    names_to_review <- setdiff(names_to_review, c("configuration_review", 
        "parameter_warnings", "validation_warnings", "accepted_defaults", 
        "modified_parameters", "selected_sampling_dates"))
    names_to_review <- names_to_review[!vapply(names_to_review, 
        function(nm) is.null(config[[nm]]), logical(1))]
    rows <- lapply(names_to_review, function(nm) {
        md <- tryCatch(parameter_metadata(nm), error = function(e) NULL)
        val <- config[[nm]]
        def <- defaults[[nm]]
        selected <- if (is.matrix(val)) 
            paste(capture.output(print(val)), collapse = " | ")
        else paste(deparse(val), collapse = " ")
        default_txt <- if (is.null(def)) 
            "not defined"
        else if (is.matrix(def)) 
            "matrix"
        else paste(deparse(def), collapse = " ")
        customized <- !identical(val, def)
        warnings <- tryCatch(parameter_warning_message(nm, val, 
            config), error = function(e) conditionMessage(e))
        data.frame(parameter = nm, selected_value = selected, 
            default_value = if (is.null(md)) 
                default_txt
            else md$default_value, units = if (is.null(md)) 
                "Not registered."
            else md$units, scale = if (is.null(md)) 
                "Not registered."
            else md$scale, recommended_range = if (is.null(md)) 
                "Not registered."
            else md$recommended_range, consequence_summary = if (is.null(md)) 
                "No metadata registered."
            else paste(md$low_value_consequence, md$high_value_consequence, 
                md$extreme_value_warning, sep = " "), warnings = warnings, 
            customized = customized, stringsAsFactors = FALSE)
    })
    out <- do.call(rbind, rows)
    if (customized_only) 
        out <- out[out$customized, , drop = FALSE]
    rownames(out) <- NULL
    out
}
