parameter_table <-
function (fit, bootstrap = NULL, profile_intervals = NULL, level = 0.94999999999999996) 
{
    est <- c(fit$beta)
    if (!is.null(fit$mixture_pi)) 
        est <- c(est, stats::setNames(fit$mixture_pi, paste0("pi_", 
            seq_along(fit$mixture_pi))))
    if (!is.null(fit$mixture_offsets)) 
        est <- c(est, stats::setNames(fit$mixture_offsets, paste0("offset_", 
            seq_along(fit$mixture_offsets))))
    se <- rep(NA_real_, length(est))
    names(se) <- names(est)
    if (!is.null(fit$uncertainty)) {
        common <- intersect(names(est), fit$uncertainty$parameter)
        se[common] <- fit$uncertainty$SE[match(common, fit$uncertainty$parameter)]
    }
    z <- stats::qnorm(1 - (1 - level)/2)
    out <- data.frame(parameter = names(est), estimate = as.numeric(est), 
        SE = as.numeric(se), lower_95_CI = as.numeric(est - z * 
            se), upper_95_CI = as.numeric(est + z * se), bootstrap_mean = NA_real_, 
        bootstrap_SD = NA_real_, profile_lower = NA_real_, profile_upper = NA_real_, 
        stringsAsFactors = FALSE)
    if (!is.null(bootstrap) && all(c("parameter", "estimate") %in% 
        names(bootstrap))) {
        bmean <- tapply(bootstrap$estimate, bootstrap$parameter, 
            mean, na.rm = TRUE)
        bsd <- tapply(bootstrap$estimate, bootstrap$parameter, 
            stats::sd, na.rm = TRUE)
        m <- match(out$parameter, names(bmean))
        out$bootstrap_mean[!is.na(m)] <- bmean[m[!is.na(m)]]
        out$bootstrap_SD[!is.na(m)] <- bsd[m[!is.na(m)]]
    }
    if (!is.null(profile_intervals)) {
        m <- match(out$parameter, profile_intervals$parameter)
        ok <- !is.na(m)
        out$profile_lower[ok] <- profile_intervals$lower[m[ok]]
        out$profile_upper[ok] <- profile_intervals$upper[m[ok]]
    }
    out
}
