parametric_bootstrap <-
function (fit, nsim = 20, seed = 1, maxit = 200) 
{
    set.seed(seed)
    rows <- vector("list", nsim)
    for (b in seq_len(nsim)) {
        sim <- simulate_state_space_cr(N = nrow(fit$history), 
            occasion_table = fit$occasion_table, spec = fit$spec, 
            beta = fit$beta, seed = seed + b)
        refit <- fit_state_space_cr(sim$observed, sim$occasions, 
            fit$spec, estimate_transition = FALSE, maxit = maxit, 
            hessian = FALSE)
        rows[[b]] <- data.frame(replicate = b, parameter = names(refit$beta), 
            estimate = as.numeric(refit$beta), stringsAsFactors = FALSE)
    }
    do.call(rbind, rows)
}
