    level = level)
parse_numeric_vector_input <-
function (text, length_expected = NULL) 
{
    if (is.numeric(text)) {
        vals <- as.numeric(text)
    }
    else {
        x <- trimws(as.character(text))
        x <- gsub("^c\\s*\\((.*)\\)$", "\\1", x)
        x <- gsub("^\\[(.*)\\]$", "\\1", x)
        bad <- regexpr("[0-9]+\\.[0-9]+\\.", x)
        if (bad[1] > 0) {
            near <- substr(x, bad[1], min(nchar(x), bad[1] + 
                8))
            stop("Two decimal points were found near '", near, 
                "'. Did you mean '0.72, 0.49'?")
        }
        x <- gsub("[,;]+", " ", x)
        parts <- strsplit(trimws(x), "\\s+")[[1]]
        parts <- parts[nzchar(parts)]
        if (!length(parts)) 
            stop("No numeric values were entered.")
        ok <- grepl("^[+-]?(?:[0-9]+\\.?[0-9]*|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?$", 
            parts)
        if (!all(ok)) 
            stop("Non-numeric token found: ", paste(parts[!ok], 
                collapse = ", "))
        vals <- as.numeric(parts)
    }
    if (any(!is.finite(vals))) 
        stop("Vector values must be finite numbers.")
    if (!is.null(length_expected) && length(vals) != length_expected) {
        if (length(vals) == 1 && length_expected > 1) {
            stop("state_detection requires one value per state. You entered one value, but there are ", 
                length_expected, " states.")
        }
        stop("Expected ", length_expected, " values, but received ", 
            length(vals), ".")
    }
    vals
}
parse_probability_vector_input <-
function (text, length_expected = NULL) 
{
    vals <- parse_numeric_vector_input(text, length_expected)
    if (any(vals < 0 | vals > 1)) 
        stop("All values must be probabilities between 0 and 1.")
    vals
}
parse_program_mark_dates_from_comments <-
function (lines, n_occasions) 
{
    survey_line <- lines[grepl("survey_date_order", lines, ignore.case = TRUE)][1]
    if (length(survey_line) && !is.na(survey_line)) {
        dates <- regmatches(survey_line, gregexpr("[0-9]{4}-[0-9]{2}-[0-9]{2}", 
            survey_line))[[1]]
        parsed <- suppressWarnings(as.Date(dates))
        if (length(parsed) == n_occasions && all(!is.na(parsed))) 
            return(parsed)
    }
    date_line <- lines[grepl("^\\s*#?\\s*dates\\s*:", lines, 
        ignore.case = TRUE)][1]
    if (length(date_line) && !is.na(date_line)) {
        raw_dates <- sub("^\\s*#?\\s*dates\\s*:\\s*", "", date_line, 
            ignore.case = TRUE)
        raw_dates <- trimws(unlist(strsplit(raw_dates, "[,[:space:]]+")))
        parsed <- suppressWarnings(as.Date(raw_dates[nzchar(raw_dates)]))
        if (length(parsed) == n_occasions && all(!is.na(parsed))) 
            return(parsed)
    }
    NULL
}
parse_state_detection_input <-
function (text, states, unavailable = character(), auto_zero_unavailable = TRUE) 
{
    states <- validate_state_vector(states)
    vals <- parse_probability_vector_input(text, length(states))
    names(vals) <- states
    hit <- intersect(unavailable, states)
    if (length(hit) && any(vals[hit] != 0)) {
        if (isTRUE(auto_zero_unavailable)) {
            vals[hit] <- 0
        }
        else {
            stop("Unavailable states must have detection = 0. Nonzero unavailable state(s): ", 
                paste(hit[vals[hit] != 0], collapse = ", "))
        }
    }
    vals
}
period_groups <-
function (occasion_table, unit = c("month", "season", "year")) 
{
    unit <- match.arg(unit)
    switch(unit, month = format(occasion_table$date, "%Y-%m"), 
        season = paste(occasion_table$year, occasion_table$season, 
            sep = "-S"), year = as.character(occasion_table$year))
}
period_structure <-
function (occasion_table) 
{
    year_g <- period_groups(occasion_table, "year")
    season_g <- period_groups(occasion_table, "season")
    month_g <- period_groups(occasion_table, "month")
    season_lookup <- unique(data.frame(season_group = season_g, 
        year = occasion_table$year, season = occasion_table$season, 
        stringsAsFactors = FALSE))
    year_levels <- unique(year_g)
    season_levels <- unique(season_g)
    month_levels <- unique(month_g)
    list(year_g = year_g, season_g = season_g, month_g = month_g, 
        season_lookup = season_lookup, year_levels = year_levels, 
        season_levels = season_levels, month_levels = month_levels)
}
