plot_chao_completeness_curve <-
function (x, occasion_table = NULL, add_interpretation = TRUE) 
{
    curve <- if (is.data.frame(x) && all(c("Chao1_completeness", 
        "Chao2_completeness") %in% names(x))) 
        x
    else chao_discovery_curve_table(x, occasion_table)
    dates <- suppressWarnings(as.Date(curve$date))
    xval <- if ("date" %in% names(curve) && any(!is.na(dates))) 
        dates
    else curve$occasion
    y1 <- pmin(curve$Chao1_completeness, 1)
    y2 <- pmin(curve$Chao2_completeness, 1)
    graphics::plot(xval, y1, type = "l", lwd = 2, col = "steelblue", 
        ylim = c(0, 1), xlab = "Sampling date or occasion", ylab = "Estimated completeness", 
        main = "Estimated sampling completeness")
    graphics::lines(xval, y2, col = "firebrick", lwd = 2, lty = 2)
    graphics::abline(h = 0.94999999999999996, col = "gray50", 
        lty = 3)
    graphics::legend("bottomright", legend = c("Chao1 completeness", 
        "Chao2 completeness", "0.95 reference"), col = c("steelblue", 
        "firebrick", "gray50"), lty = c(1, 2, 3), lwd = 2, bty = "n", 
        cex = 0.81999999999999995)
    graphics::mtext("Completeness near 1 suggests most detectable individuals may have been observed.", 
        side = 3, line = 0.29999999999999999, cex = 0.71999999999999997)
    if (isTRUE(add_interpretation)) 
        print_chao_interpretation("both")
    invisible(curve)
}
plot_chao_discovery_curves <-
function (x, occasion_table = NULL, add_interpretation = TRUE) 
{
    curve <- if (is.data.frame(x) && all(c("Chao1", "Chao2", 
        "S_obs") %in% names(x))) 
        x
    else chao_discovery_curve_table(x, occasion_table)
    dates <- suppressWarnings(as.Date(curve$date))
    xval <- if ("date" %in% names(curve) && any(!is.na(dates))) 
        dates
    else curve$occasion
    ymat <- cbind(curve$S_obs, curve$Chao1, curve$Chao2)
    ylim <- range(ymat, na.rm = TRUE)
    if (!all(is.finite(ylim))) 
        ylim <- c(0, 1)
    graphics::plot(xval, curve$S_obs, type = "l", lwd = 2, col = "black", 
        ylim = ylim, xlab = "Sampling date or occasion", ylab = "Number of individuals", 
        main = "Discovery curve with Chao1 and Chao2 estimates")
    graphics::lines(xval, curve$Chao1, col = "steelblue", lwd = 2, 
        lty = 2)
    graphics::lines(xval, curve$Chao2, col = "firebrick", lwd = 2, 
        lty = 3)
    graphics::legend("topleft", legend = c("Observed cumulative individuals", 
        "Chao1 estimated total", "Chao2 estimated total"), col = c("black", 
        "steelblue", "firebrick"), lty = c(1, 2, 3), lwd = 2, 
        bty = "n", cex = 0.81999999999999995)
    graphics::mtext("Chao estimates approximate detectable individuals after accounting for rare detections.", 
        side = 3, line = 0.29999999999999999, cex = 0.75)
    if (isTRUE(add_interpretation)) 
        print_chao_interpretation("both")
    invisible(curve)
}
