predict_detection_from_effort <-
function (baseline_detection_probability, effort_detection_effect, 
    effort_values = c(low = -1, average = 0, high = 1)) 
{
    p0 <- as.numeric(baseline_detection_probability)
    beta_eff <- as.numeric(effort_detection_effect)
    if (length(p0) != 1 || !is.finite(p0) || p0 <= 0 || p0 >= 
        1) {
        stop("baseline_detection_probability must be strictly between 0 and 1.")
    }
    if (length(beta_eff) != 1 || !is.finite(beta_eff)) 
        stop("effort_detection_effect must be finite.")
    eta <- qlogis(p0) + beta_eff * as.numeric(effort_values)
    data.frame(effort_label = names(effort_values) %||% paste0("effort_", 
        seq_along(effort_values)), effort_value = as.numeric(effort_values), 
        detection_probability = plogis(eta), stringsAsFactors = FALSE)
}
prepare_abundance_data <-
function (data, occasion_dates = NULL, format = NULL) 
{
    if (is_resident_encounter_data(data)) {
        return(list(history = data$history, occasions = data$occasions, 
            format = data$source %||% "resident_encounter_data", 
            encounter_data = data))
    }
    fmt <- format %||% detect_abundance_data_format(data)
    if (fmt %in% c("socprog_long", "CSV_LONG")) {
        ed <- convert_socprog_to_encounter_data(data)
    }
    else if (fmt %in% c("program_mark", "PROGRAM_MARK")) {
        dates <- if (is.null(occasion_dates)) 
            NULL
        else data.frame(occasion = seq_along(occasion_dates), 
            date = as.Date(occasion_dates))
        ed <- convert_mark_to_encounter_data(data, dates)
    }
    else if (fmt %in% c("wide_history", "wide")) {
        ed <- convert_wide_to_encounter_data(data, occasion_dates = occasion_dates)
    }
    else {
        ed <- as_resident_encounter_data(extract_history(data, 
            stage = "prepare abundance data"), extract_occasions(data, 
            stage = "prepare abundance data"), raw = data, source = fmt)
    }
    list(history = ed$history, occasions = ed$occasions, format = fmt, 
        encounter_data = ed)
}
