prepare_detection_data <-
function (history, occasion_table, individual_data = NULL, observation_data = NULL) 
{
    history <- as_binary_matrix(history)
    ids <- rownames(history) %||% paste0("Subject_", safe_seq_rows(history, 
        context = "validated history row loop"))
    rownames(history) <- ids
    rows <- vector("list", nrow(history) * ncol(history))
    k <- 1L
    for (i in safe_seq_rows(history, context = "validated history row loop")) {
        for (t in seq_len(ncol(history))) {
            rows[[k]] <- data.frame(id = ids[i], individual_index = i, 
                occasion_index = t, y = history[i, t], occasion_table[t, 
                  , drop = FALSE], stringsAsFactors = FALSE)
            k <- k + 1L
        }
    }
    dat <- do.call(rbind, rows)
    rownames(dat) <- NULL
    if (!is.null(individual_data)) 
        dat <- merge(dat, individual_data, by = "id", all.x = TRUE, 
            sort = FALSE)
    if (!is.null(observation_data)) {
        keys <- intersect(c("id", "date", "occasion"), names(observation_data))
        if (length(keys)) 
            dat <- merge(dat, observation_data, by = keys, all.x = TRUE, 
                sort = FALSE)
    }
    dat <- dat[order(dat$individual_index, dat$occasion_index), 
        , drop = FALSE]
    rownames(dat) <- NULL
    dat
}
