prepare_robust_design_array <-
function (history, occasion_table, primary_col = "primary_period", 
    secondary_col = "secondary_period") 
{
    history <- as_binary_matrix(history)
    if (!(primary_col %in% names(occasion_table))) {
        occasion_table <- make_robust_design(occasion_table, 
            primary = "season")
    }
    if (!(secondary_col %in% names(occasion_table))) {
        occasion_table[[secondary_col]] <- ave(occasion_table$occasion, 
            occasion_table[[primary_col]], FUN = seq_along)
    }
    if (ncol(history) != nrow(occasion_table)) {
        stop("history columns must match rows in occasion_table.")
    }
    primary_levels <- sort(unique(occasion_table[[primary_col]]))
    Kp <- length(primary_levels)
    Jmax <- max(tabulate(match(occasion_table[[primary_col]], 
        primary_levels)))
    N <- nrow(history)
    y <- array(NA_integer_, dim = c(N, Kp, Jmax), dimnames = list(rownames(history) %||% 
        paste0("Subject_", seq_len(N)), paste0("primary_", primary_levels), 
        paste0("secondary_", seq_len(Jmax))))
    occasion_index <- matrix(NA_integer_, nrow = Kp, ncol = Jmax)
    primary_table <- data.frame(primary_index = seq_len(Kp), 
        primary_period = primary_levels, n_secondary = integer(Kp), 
        stringsAsFactors = FALSE)
    for (k in seq_along(primary_levels)) {
        idx <- which(occasion_table[[primary_col]] == primary_levels[k])
        idx <- idx[order(occasion_table[[secondary_col]][idx])]
        primary_table$n_secondary[k] <- length(idx)
        y[, k, seq_along(idx)] <- history[, idx, drop = FALSE]
        occasion_index[k, seq_along(idx)] <- idx
    }
    list(y = y, observed = !is.na(y), occasion_index = occasion_index, 
        primary_table = primary_table, occasion_table = occasion_table, 
        history = history)
}
