primary_classifier_temporal_diagnostics <-
function (analysis, tab = NULL) 
{
    occ <- tryCatch(extract_occasions(analysis, stage = "primary classifier recommendation"), 
        error = function(e) analysis_occasion_table(analysis))
    history <- tryCatch(extract_history(analysis, stage = "primary classifier recommendation"), 
        error = function(e) NULL)
    dates <- if (!is.null(occ) && "date" %in% names(occ)) 
        suppressWarnings(as.Date(occ$date))
    else as.Date(character())
    valid_dates <- dates[!is.na(dates)]
    n_occ <- if (!is.null(history)) 
        ncol(as.matrix(history))
    else if (!is.null(occ)) 
        nrow(occ)
    else 0L
    n_years <- if (length(valid_dates)) 
        length(unique(format(valid_dates, "%Y")))
    else 0L
    n_months <- if (length(valid_dates)) 
        length(unique(format(valid_dates, "%Y-%m")))
    else 0L
    seasons <- if (length(valid_dates)) 
        paste0(format(valid_dates, "%Y"), "-S", ((as.integer(format(valid_dates, 
            "%m")) - 1L)%/%3L) + 1L)
    else character()
    n_seasons <- length(unique(seasons))
    complete_month_fraction <- if (n_years > 0) 
        n_months/(12 * n_years)
    else 0
    complete_season_fraction <- if (n_years > 0) 
        n_seasons/(4 * n_years)
    else 0
    has_monthly_support <- n_months >= 6L && complete_month_fraction >= 
        0.5
    has_seasonal_support <- n_seasons >= 4L && complete_season_fraction >= 
        0.5
    has_annual_support <- n_years >= 2L
    has_temporal_gaps <- length(valid_dates) > 1L && (complete_month_fraction < 
        0.75 || any(diff(sort(unique(valid_dates))) > 62))
    data.frame(number_of_sampling_occasions = n_occ, number_of_years = n_years, 
        number_of_months = n_months, number_of_seasons = n_seasons, 
        monthly_coverage = round(complete_month_fraction, 3), 
        seasonal_coverage = round(complete_season_fraction, 3), 
        has_monthly_support = has_monthly_support, has_seasonal_support = has_seasonal_support, 
        has_annual_support = has_annual_support, has_temporal_gaps = has_temporal_gaps, 
        stringsAsFactors = FALSE)
}
primary_emission_probabilities <-
function (y_i, rd_array, design, beta, states, unavailable_states, 
    individual_index, detection_offset = 0) 
{
    Kstate <- length(states)
    Kp <- dim(rd_array$y)[2]
    out <- matrix(1, nrow = Kstate, ncol = Kp, dimnames = list(states, 
        NULL))
    rows_i <- design$data$individual_index == individual_index
    X_i <- design$X[rows_i, , drop = FALSE]
    beta_vec <- rep(0, ncol(X_i))
    names(beta_vec) <- colnames(X_i)
    beta_vec[intersect(names(beta), names(beta_vec))] <- beta[intersect(names(beta), 
        names(beta_vec))]
    p_occ <- inv_logit(as.vector(X_i %*% beta_vec) + detection_offset)
    for (k in seq_len(Kp)) {
        occ <- rd_array$occasion_index[k, ]
        occ <- occ[!is.na(occ)]
        if (!length(occ)) 
            next
        yk <- y_i[k, seq_along(occ)]
        pk <- p_occ[occ]
        for (s in seq_len(Kstate)) {
            if (states[s] %in% unavailable_states) {
                out[s, k] <- if (any(yk > 0, na.rm = TRUE)) 
                  0
                else 1
            }
            else {
                out[s, k] <- prod(ifelse(yk > 0, pk, 1 - pk))
            }
        }
    }
    pmax(out, 9.9999999999999936e-301)
}
