print_abundance_model_detail_list <-
function (details, title = "Abundance model details") 
{
    cat("\n", title, "\n", strrep("=", nchar(title)), "\n", sep = "")
    if (!is.data.frame(details) || !nrow(details)) {
        cat("No model details are available.\n")
        return(invisible(details))
    }
    diag <- attr(details, "diagnostics")
    if (!is.null(diag)) 
        cat("\nData diagnostics used for suitability: ", format_abundance_diagnostics(diag), 
            "\n", sep = "")
    ranked <- "suitability_rank" %in% names(details)
    if (ranked) {
        cat("\nNumbering note: the leading number below is the suitability rank for the current data. The separate 'Model menu option' line is the number to type in the abundance-model fitting menu.\n")
    }
    else {
        cat("\nNumbering note: the leading number below is only this display-list number. The 'Model menu option' line is the number to type in the abundance-model fitting menu.\n")
    }
    for (i in seq_len(nrow(details))) {
        row <- details[i, , drop = FALSE]
        lead <- if (ranked) 
            paste0("Suitability rank ", row$suitability_rank)
        else paste0("List item ", i)
        cat("\n", lead, ": ", row$candidate_model, "\n", sep = "")
        cat("   Model menu option: ", row$option, "\n", sep = "")
        cat("   Model family: ", row$model_family, "\n", sep = "")
        cat("   What it estimates: ", row$estimates, "\n", sep = "")
        cat("   Best used when: ", row$best_used_when, "\n", 
            sep = "")
        cat("   Main assumption/caution: ", row$main_assumption_or_caution, 
            "\n", sep = "")
        cat("   Implementation status: ", row$implementation_status, 
            "\n", sep = "")
        if ("display_suitability" %in% names(row) && !is.na(row$display_suitability) && 
            nzchar(as.character(row$display_suitability))) 
            cat("   Suitability for these data: ", row$display_suitability, 
                "\n", sep = "")
        if ("suitability" %in% names(row) && !is.na(row$suitability) && 
            nzchar(as.character(row$suitability)) && !identical(as.character(row$suitability), 
            as.character(row$display_suitability))) 
            cat("   Technical suitability detail: ", row$suitability, 
                "\n", sep = "")
        if ("assumptions_status" %in% names(row) && !is.na(row$assumptions_status) && 
            nzchar(as.character(row$assumptions_status))) 
            cat("   Assumptions checked against data: ", row$assumptions_status, 
                "\n", sep = "")
        if ("data_support" %in% names(row) && !is.na(row$data_support) && 
            nzchar(as.character(row$data_support))) 
            cat("   Data support: ", row$data_support, "\n", 
                sep = "")
        if ("expected_risk" %in% names(row) && !is.na(row$expected_risk) && 
            nzchar(as.character(row$expected_risk))) 
            cat("   Expected risk: ", row$expected_risk, "\n", 
                sep = "")
        if ("recommendation" %in% names(row) && !is.na(row$recommendation) && 
            nzchar(as.character(row$recommendation))) 
            cat("   Recommendation: ", row$recommendation, "\n", 
                sep = "")
    }
    cat("\nNote: these recommendations are screening diagnostics, not final proof that a model is correct. A more complex model is not automatically better; it needs enough detections, recaptures, and the right sampling design.\n")
    invisible(details)
}
