print_abundance_summary <-
function (fit, print = TRUE) 
{
    if (is.null(fit)) {
        tab <- data.frame(status = "no_fitted_model", diagnostic_interpretation = "No fitted model exists yet. Use option 22 to select and fit a model first.", 
            stringsAsFactors = FALSE)
        if (print) 
            print_console_table(tab, title = "Abundance estimates")
        return(tab)
    }
    if (inherits(fit, "resident_state_space_route")) {
        tab <- state_space_derived_parameter_table(fit)
        if (print) {
            print_console_table(tab, title = "State-space residency output")
            print_interpretation_box("State-space output describes availability or residency-state probabilities. It is not the same target as closed-population abundance unless the model and design explicitly support that interpretation.")
        }
        return(tab)
    }
    if (inherits(fit, "resident_open_population_fit") || inherits(fit, 
        "resident_popan_like_fit")) {
        tab <- open_population_abundance_table(fit)
        if (print) {
            print_console_table(tab, title = "Open-population abundance estimates")
            print_interpretation_box("These are model-based abundance estimates through time. They are not simply counts of sightings.")
        }
        return(tab)
    }
    out <- tryCatch(.old_print_abundance_summary_v089(fit, print = print), 
        error = function(e) NULL)
    if (!is.null(out)) 
        return(out)
    tab <- data.frame(model = fit$abundance_model %||% fit$model_name %||% 
        "unknown", abundance_estimate = round(as.numeric(fit$N_hat %||% 
        NA_real_), 3), diagnostic_interpretation = "Fallback abundance summary from the fitted object.", 
        stringsAsFactors = FALSE)
    if (print) 
        print_console_table(tab, title = "Abundance estimates")
    tab
}
