print_console_table <-
function (x, title = NULL, key_columns = NULL, max_rows = table_output_options()$max_rows, 
    max_col_width = table_output_options()$max_col_width, mode = table_output_options()$mode, 
    export_prefix = "table", output_dir = table_output_options()$output_dir, 
    header_style = table_output_options()$header_style) 
{
    if (!is.data.frame(x)) 
        x <- as.data.frame(x)
    if (resident_should_print_as_summary_list(x, mode = mode, 
        key_columns = key_columns)) {
        print_summary_list(x, title = title %||% "Summary")
        path <- export_table_if_wide(x, prefix = export_prefix, 
            output_dir = output_dir, max_rows = max_rows, force = FALSE)
        if (!is.null(path)) 
            cat("Full table saved to:", path, "\n")
        notes <- extract_table_notes(x)
        if (length(notes)) {
            note_text <- unique(unlist(notes, use.names = FALSE))
            note_text <- note_text[nzchar(note_text)]
            if (length(note_text)) 
                print_interpretation_box(note_text[seq_len(min(3L, 
                  length(note_text)))])
        }
        return(invisible(x))
    }
    .resident_v095_print_console_table(x, title = title, key_columns = key_columns, 
        max_rows = max_rows, max_col_width = max_col_width, mode = mode, 
        export_prefix = export_prefix, output_dir = output_dir, 
        header_style = header_style)
}
