print_derived_parameter_interpretation <-
function (fit_or_analysis, digits = 3) 
{
    if (is.data.frame(fit_or_analysis) && all(c("technical_name", 
        "estimate", "parameter_meaning") %in% names(fit_or_analysis))) {
        tab <- fit_or_analysis
    }
    else if (is.list(fit_or_analysis) && !is.null(fit_or_analysis$derived_parameters)) {
        tab <- fit_or_analysis$derived_parameters
    }
    else if (is.list(fit_or_analysis) && !is.null(fit_or_analysis$fit)) {
        tab <- interpret_derived_parameters(fit_or_analysis$fit, 
            digits = digits)
    }
    else {
        tab <- interpret_derived_parameters(fit_or_analysis, 
            digits = digits)
    }
