print_discovery_curve_summary <-
function (discovery_table) 
{
    total <- max(discovery_table$cumulative_new_individuals, 
        na.rm = TRUE)
    ids <- max(discovery_table$cumulative_identifications, na.rm = TRUE)
    last_new <- max(which(discovery_table$new_individuals_on_occasion > 
        0), na.rm = TRUE)
    plateau <- is.finite(last_new) && (nrow(discovery_table) - 
        last_new) >= ceiling(0.10000000000000001 * nrow(discovery_table))
    out <- data.frame(final_number_of_discovered_individuals = total, 
        total_identifications = ids, date_50_percent_discovered = discovery_threshold_date(discovery_table, 
            0.5), date_75_percent_discovered = discovery_threshold_date(discovery_table, 
            0.75), date_90_percent_discovered = discovery_threshold_date(discovery_table, 
            0.90000000000000002), appears_to_plateau_simple_rule = plateau, 
        interpretation = "The plateau flag is a descriptive rule only; it is not a formal asymptote estimate.", 
        stringsAsFactors = FALSE)
    print(out, row.names = FALSE)
    invisible(out)
}
