print_literature_classifier_summary <-
function (analysis, max_classifiers = Inf) 
{
    analysis <- ensure_literature_residency_outputs(analysis)
    classification <- safe_individual_residency_table(analysis)
    summary <- literature_classifier_summary_long(classification)
    if (is.null(summary) || !nrow(summary)) {
        resident_print_unavailable("Residency/site-fidelity class summary", 
            "No literature classifier summary could be computed from the current encounter history.", 
            "Use option 5 first and check whether the encounter history has detections across occasions.")
        return(invisible(list(analysis = analysis, table = NULL, 
            full_table_path = NA_character_)))
    }
    analysis$literature_classifier_summary <- summary
    analysis$residency_category_proportions <- summary
    analysis$category_proportions <- summary
    full_path <- .timestamped_output_path("literature_classifier_summary_full", 
        "csv", output_dir = table_output_options()$output_dir)
    utils::write.csv(summary, full_path, row.names = FALSE)
    analysis$literature_classifier_summary_full_csv <- full_path
    cat("\nResidency/site-fidelity class summary\n")
    cat("=====================================\n")
    cat("Each block summarizes one published literature rule. These are observed-detection classifications, not fitted model estimates, so missed detections are not corrected here.\n")
    if ("Balmer" %in% summary$classifier) 
        cat("Balmer note: Balmer categories are numerical sighting-frequency groups; 01 is the lowest observed group and larger numbers are higher observed groups when present. Zero padding keeps 01, 02, ..., 10 in natural order.\n")
    classifiers <- unique(summary$classifier)
    if (is.finite(max_classifiers)) 
        classifiers <- head(classifiers, max_classifiers)
    for (classifier in classifiers) {
        block <- summary[summary$classifier == classifier, , 
            drop = FALSE]
        cat("\n", classifier, "\n", sep = "")
        cat(paste(rep("-", nchar(classifier)), collapse = ""), 
            "\n", sep = "")
        cat("Assessment type: ", block$assessment_type[1], "\n", 
            sep = "")
        cat("Category type: ", block$category_type[1], "\n", 
            sep = "")
        cat("Note: ", block$note[1], "\n", sep = "")
        compact <- block[, c("category", "number_of_individuals", 
            "proportion"), drop = FALSE]
        print_console_table(compact, title = paste0(classifier, 
            " categories"), max_rows = nrow(compact), export_prefix = paste0("literature_classifier_summary_", 
            gsub("[^A-Za-z0-9]+", "_", tolower(classifier))))
    }
    if (!is.na(full_path)) 
        cat("\nFull all-classifier summary saved to:", full_path, 
            "\n")
    invisible(list(analysis = analysis, table = summary, full_table_path = full_path))
}
