    analysis <- ensure_literature_residency_outputs(analysis)
    tab <- safe_individual_residency_table(analysis)
    overview <- literature_residency_overview_table(tab)
    full_path <- export_literature_residency_classification(tab)
    analysis$literature_residency_classification_full_csv <- full_path
    cat("\nLiterature-based residency and site-fidelity classifications\n")
    cat("===========================================================\n")
    cat("These classifications are computed directly from the encounter history using published residency/site-fidelity rules already included in Resident. They are not fitted model-state estimates.\n")
    cat("The primary classifier is selected by Huesca-style suitability scoring from the stated goal and temporal support in the data; the fixed order is only a fallback.\n")
    if ("primary_classifier_reason" %in% names(tab)) {
        cat("Recommended primary rule: ", unique(tab$primary_classifier)[1], 
            "\n", sep = "")
        cat("Primary-classifier reason: ", unique(tab$primary_classifier_reason)[1], 
            "\n", sep = "")
    }
    cat("The console shows a compact overview and a short per-individual list; the complete table with every literature classifier is saved for inspection.\n")
    print_console_table(overview, title = "Individual literature-based classification overview", 
        max_rows = n, export_prefix = "literature_residency_classification_overview")
    print_literature_residency_details(tab, n = detail_n)
    if (!is.na(full_path)) 
        cat("\nFull classification table saved to:", full_path, 
            "\n")
    invisible(list(analysis = analysis, table = tab, overview = overview, 
        full_table_path = full_path))
}
print_literature_residency_details <-
function (classification, n = 5L, max_width = 72L) 
{
    if (is.null(classification) || !is.data.frame(classification) || 
        !nrow(classification)) 
        return(invisible(classification))
    n <- min(as.integer(n %||% 5L), nrow(classification))
    if (is.na(n) || n < 1L) 
        n <- min(5L, nrow(classification))
    fields <- literature_residency_detail_fields(classification)
    cat("\nDetailed classifications for first ", n, " individual", 
        if (n == 1L) 
            ""
        else "s", "\n", sep = "")
    cat("---------------------------------------------------\n")
    cat("This list is easier to read than the full wide table. It shows the main encounter-history metrics and the literature rules available for each individual.\n")
    for (i in seq_len(n)) {
        row <- classification[i, fields, drop = FALSE]
        id <- if ("id" %in% names(row)) 
            as.character(row$id[1])
        else paste0("Row ", i)
        cat("\n", id, "\n", sep = "")
        for (field in setdiff(fields, "id")) {
            value <- resident_format_summary_value(row[[field]], 
                digits = 3L)
            if (nchar(value) > max_width) 
                value <- paste0(substr(value, 1L, max_width - 
                  3L), "...")
            cat("- ", resident_pretty_summary_label(field), ": ", 
                value, "\n", sep = "")
        }
    }
    if (nrow(classification) > n) 
        cat("\nShowing details for ", n, " of ", nrow(classification), 
            " individuals. Use the CSV file to inspect all rows and all columns.\n", 
            sep = "")
    invisible(classification)
}
