print_parameter_interpretation <-
function (parameter, value = NULL, config = NULL) 
{
    key <- .parameter_key(parameter)
    if (key == "effort_detection_effect") {
        beta <- as.numeric(value %||% 0.5)
        p0 <- as.numeric((config %||% list())$baseline_detection_probability %||% 
            0.25)
        scaling <- (config %||% list())$effort_scaling %||% "z_score"
        out <- explain_effort_detection_effect(beta, p0, scaling)
        return(invisible(out))
    }
    if (key == "state_detection") {
        cat("\nState detection interpretation:\n")
        cat("state_detection gives one detection probability per state. Values must be probabilities in [0,1], and unavailable states must be 0.\n")
        if (!is.null(config$states)) {
            cat("State order:\n")
            for (i in seq_along(config$states)) cat(i, ". ", 
                config$states[i], "\n", sep = "")
        }
        return(invisible(value))
    }
    print(parameter_metadata(parameter), row.names = FALSE)
    invisible(parameter_metadata(parameter))
}
