print_summary_list <-
function (x, title = "Summary", max_width = getOption("resident.console.summary_width", 
    88L), digits = getOption("resident.console.summary_digits", 
    3L)) 
{
    if (!is.data.frame(x)) 
        x <- as.data.frame(x)
    if (!nrow(x)) {
        cat("\n", title, "\n", strrep("=", nchar(title)), "\nNo rows are available.\n", 
            sep = "")
        return(invisible(x))
    }
    cat("\n", title, "\n", strrep("=", nchar(title)), "\n", sep = "")
    rows_to_show <- seq_len(min(nrow(x), getOption("resident.console.list_max_rows", 
        3L)))
    for (row_index in rows_to_show) {
        if (nrow(x) > 1L) 
            cat("\nRecord ", row_index, "\n", sep = "")
        row <- x[row_index, , drop = FALSE]
        sections <- resident_summary_sections(row)
        for (section in unique(sections)) {
            fields <- names(sections)[sections == section]
            cat("\n", section, "\n", sep = "")
            for (field in fields) {
                value <- resident_format_summary_value(row[[field]], 
                  digits = digits)
                if (nchar(value) > max_width) 
                  value <- paste0(substr(value, 1, max_width - 
                    3L), "...")
                cat("- ", resident_pretty_summary_label(field), 
                  ": ", value, "\n", sep = "")
            }
        }
    }
    if (nrow(x) > length(rows_to_show)) 
        cat("\nShowing ", length(rows_to_show), " of ", nrow(x), 
            " records. Export the table to inspect all rows.\n", 
            sep = "")
    invisible(x)
}
