profile_ci_from_lr <-
function (profile, cutoff = qchisq(0.94999999999999996, 1)) 
{
    ok <- profile[is.finite(profile$LR) & profile$LR <= cutoff, 
        , drop = FALSE]
    data.frame(lower_95 = if (nrow(ok)) 
        min(ok$real_value)
    else NA_real_, upper_95 = if (nrow(ok)) 
        max(ok$real_value)
    else NA_real_, cutoff = cutoff)
}
profile_confint <-
function (profile, level = 0.94999999999999996) 
{
    cutoff <- stats::qchisq(level, df = 1)
    keep <- profile$LR <= cutoff
    data.frame(parameter = profile$parameter[1], lower = if (any(keep)) 
        min(profile$value[keep])
    else NA_real_, upper = if (any(keep)) 
        max(profile$value[keep])
    else NA_real_, cutoff = cutoff, stringsAsFactors = FALSE)
}
profile_likelihood <-
function (fit, parameter, values, maxit = 200) 
{
    if (!(parameter %in% names(fit$beta))) 
        stop("Only beta parameters are currently profiled.")
    rows <- lapply(values, function(v) {
        spec <- fit$spec
        fixed_beta <- fit$beta
        fixed_beta[parameter] <- v
        ll <- 0
        for (i in seq_len(nrow(fit$history))) {
            ll <- ll + forward_algorithm_regression(fit$history[i, 
                ], fit$initial_probs, fit$transition_matrix, 
                fit$detection_design, fixed_beta, fit$states, 
                fit$spec$unavailable_states, i)$logLik
        }
        data.frame(parameter = parameter, value = v, logLik = ll)
    })
    do.call(rbind, rows)
}
profile_likelihood_ci <-
function (fit, parameter = "p", values = NULL, ...) 
{
    prof <- profile_scalar_parameter(fit, parameter, values, 
        ...)
    ci <- profile_ci_from_lr(prof)
    attr(ci, "profile_table") <- prof
    ci$uncertainty_method <- "profile_likelihood"
    ci$uncertainty_status <- ifelse(is.finite(ci$lower_95), "computed", 
        "unavailable")
    ci
}
profile_likelihood_full <-
function (fit, parameter, values, maxit = 300) 
{
    if (!(parameter %in% names(fit$beta))) {
        stop("v0.5.0 full profiling currently supports beta coefficients by exact name.")
    }
    rows <- lapply(values, function(v) {
        fixed <- as.list(stats::setNames(v, parameter))
        prof_fit <- fit_robust_design_cr(fit$history, fit$occasion_table, 
            fit$spec, transition_structure = fit$transition_structure, 
            detection_formula = fit$detection_design$formula, 
            estimate_transition = FALSE, fixed = fixed, maxit = maxit, 
            hessian = FALSE)
        data.frame(parameter = parameter, value = v, logLik = prof_fit$logLik, 
            convergence = prof_fit$convergence, nuisance_reoptimized = TRUE, 
            stringsAsFactors = FALSE)
    })
    out <- do.call(rbind, rows)
    out$LR <- 2 * (max(out$logLik) - out$logLik)
    out
}
profile_parameter_ci <-
function (fit, parameter = "p", values = NULL, ...) 
{
    prof <- profile_scalar_parameter(fit, parameter, values, 
        ...)
    ci <- profile_ci_from_lr(prof)
    attr(ci, "profile_table") <- prof
    ci$uncertainty_method <- "profile_likelihood"
    ci$uncertainty_status <- ifelse(is.finite(ci$lower_95), "computed", 
        "unavailable")
    ci
}
profile_scalar_parameter <-
function (fit, parameter = "p", values = NULL, ...) 
{
    if (is.null(values)) {
        center <- if (inherits(fit, "resident_huggins_abundance_fit")) 
            fit$par[["lp"]]
        else fit$par[["lp"]] %||% qlogis(mean(fit$p_hat, na.rm = TRUE))
        values <- seq(center - 2, center + 2, length.out = 9)
    }
    rows <- lapply(values, function(v) {
        rr <- tryCatch(refit_with_fixed_parameter(fit, parameter, 
            v, ...), error = function(e) NULL)
        data.frame(parameter = parameter, fixed_value = v, real_value = .invlogit(v), 
            logLik = rr$logLik %||% NA_real_, convergence = rr$convergence %||% 
                1L)
    })
    tab <- do.call(rbind, rows)
    best <- max(tab$logLik, na.rm = TRUE)
    tab$LR <- 2 * (best - tab$logLik)
    tab
}
