profile_transition_matrix_estimated <-
function (fit, values = seq(0.050000000000000003, 0.94999999999999996, 
    by = 0.10000000000000001), maxit = 300) 
{
    states <- fit$states %||% fit$spec$states
    out <- list()
    for (from in states) for (to in states) out[[paste(from, 
        to, sep = "->")]] <- profile_transition_probability_estimated(fit, 
        from, to, values, maxit)
    out
}
profile_transition_probability <-
function (fit, from_state, to_state, values, backend = c("base", 
    "TMB"), maxit = 300) 
{
    backend <- match.arg(backend)
    states <- fit$states %||% fit$spec$states
    r <- match(from_state, states)
    s <- match(to_state, states)
    if (is.na(r) || is.na(s)) 
        stop("from_state and to_state must be valid state names.")
    rows <- lapply(values, function(v) {
        if (v <= 0 || v >= 1) 
            stop("Profiled transition probability must be between 0 and 1.")
        psi <- fit$transition_matrix %||% fit$spec$transition_matrix
        old_rest <- psi[r, -s]
        psi[r, s] <- v
        psi[r, -s] <- (1 - v) * old_rest/sum(old_rest)
        spec2 <- fit$spec
        spec2$transition_matrix <- validate_transition_matrix(psi, 
            states)
        prof_fit <- if (backend == "TMB" && tmb_available()) {
            fit_robust_design_tmb(fit$history, fit$occasion_table, 
                spec2, detection_formula = fit$detection_design$formula, 
                estimate_transition = FALSE, maxit = maxit)
        }
        else {
            fit_robust_design_cr(fit$history, fit$occasion_table, 
                spec2, transition_structure = build_transition_structure(states, 
                  "fixed", fixed_matrix = psi), detection_formula = fit$detection_design$formula, 
                estimate_transition = FALSE, maxit = maxit, hessian = FALSE)
        }
        data.frame(from_state = from_state, to_state = to_state, 
            value = v, logLik = prof_fit$logLik, convergence = prof_fit$convergence %||% 
                NA_integer_, nuisance_reoptimized = TRUE, backend_used = prof_fit$backend %||% 
                backend, stringsAsFactors = FALSE)
    })
    out <- do.call(rbind, rows)
    out$LR <- 2 * (max(out$logLik) - out$logLik)
    out
}
profile_transition_probability_estimated <-
function (fit, from_state, to_state, values = seq(0.050000000000000003, 
    0.94999999999999996, by = 0.10000000000000001), maxit = 300) 
{
    states <- fit$states %||% fit$spec$states
    r <- match(from_state, states)
    c <- match(to_state, states)
    if (is.na(r) || is.na(c)) 
        stop("from_state and to_state must be valid states.")
    rows <- list()
    for (v in values) {
        fixed <- fit$transition_matrix
        fixed[r, c] <- v
        other <- setdiff(seq_along(states), c)
        rem <- 1 - v
        if (rem <= 0) {
            rows[[length(rows) + 1L]] <- data.frame(from_state = from_state, 
                to_state = to_state, value = v, logLik = NA_real_, 
                convergence = NA, nuisance_reoptimized = FALSE, 
                backend_used = "base", stringsAsFactors = FALSE)
            next
        }
        fixed[r, other] <- normalize_prob(fixed[r, other]) * 
            rem
        free <- matrix(TRUE, length(states), length(states), 
            dimnames = list(states, states))
        free[r, c] <- FALSE
        ts <- transition_estimation_specification("estimate_custom_mask", 
            states, fixed, transition_free_mask = free)
        spec2 <- fit$spec
        spec2$transition_matrix <- fixed
        refit <- tryCatch(fit_robust_design_cr(fit$history, fit$occasion_table, 
            spec2, transition_structure = ts, estimate_transition = TRUE, 
            maxit = maxit, hessian = FALSE), error = function(e) e)
        rows[[length(rows) + 1L]] <- data.frame(from_state = from_state, 
            to_state = to_state, value = v, logLik = if (inherits(refit, 
                "error")) 
                NA_real_
            else refit$logLik, convergence = if (inherits(refit, 
                "error")) 
                NA
            else refit$convergence, nuisance_reoptimized = !inherits(refit, 
                "error"), backend_used = "base", stringsAsFactors = FALSE)
    }
    out <- do.call(rbind, rows)
    out$likelihood_ratio_statistic <- 2 * (max(out$logLik, na.rm = TRUE) - 
        out$logLik)
    diag <- transition_profile_grid_diagnostic(data.frame(out, 
        LR = out$likelihood_ratio_statistic))
    attr(out, "grid_diagnostic") <- diag
    out
}
profile_transition_row <-
function (fit, from_state, values = seq(0.050000000000000003, 
    0.94999999999999996, by = 0.10000000000000001), maxit = 300) 
{
    states <- fit$states %||% fit$spec$states
    out <- lapply(states, function(to) profile_transition_probability_estimated(fit, 
        from_state, to, values, maxit))
    names(out) <- states
    out
}
prompt_effort_units_for_type <-
function (effort_variable_type, default = NULL, input_provider = NULL) 
{
    allowed <- allowed_effort_units_for_type(effort_variable_type)
    cat("\nCompatible effort_units for ", effort_variable_type, 
        ":\n", sep = "")
    for (i in seq_along(allowed)) cat(i, ". ", allowed[i], "\n", 
        sep = "")
    if (effort_variable_type == "number_of_photographs") 
        cat("This is a raw count of images, not a measure of photographic efficiency.\n")
    if (effort_variable_type == "photographic_efficiency") 
        cat("This should be usable photographs divided by total photographs.\n")
    if (effort_variable_type == "individualization_efficiency") 
        cat("This should be individually identified animals divided by estimated photographed group size.\n")
    choice <- reprompt_until_valid("Enter effort_units option number or name: ", 
        parser = function(x) {
            x <- trimws(as.character(x))
            if (!nzchar(x) && !is.null(default)) 
                return(default)
            if (grepl("^[0-9]+$", x)) {
                idx <- as.integer(x)
                if (idx >= 1 && idx <= length(allowed)) 
                  return(allowed[idx])
            }
            if (x %in% allowed) 
                return(x)
            stop("Unit is not compatible with ", effort_variable_type, 
                ". Compatible units are: ", paste(allowed, collapse = ", "))
        }, input_provider = input_provider, default = default %||% 
            allowed[1], example = allowed[1])
    if (choice == "percentage") 
        warning("Percentages should be converted to proportions or scaled consistently before modeling.")
    choice
}
prompt_effort_values_for_simulation <-
function (config, input_provider = NULL) 
{
    cat("\nEffort values:\n")
    cat("These values document the effort scale used by the detection model. They are especially important when effort_scaling = raw.\n")
    default <- config$effort_values %||% "0, 1, 2"
    if (is.character(default)) 
        default <- parse_numeric_vector_input(default)
    vals <- safe_prompt_numeric_vector("effort_values", length_expected = NULL, 
        input_provider = input_provider, default = default, allow_default = TRUE, 
        example = "0, 1, 2")
    config$effort_values <- vals
    config$effort_reference_value <- if (identical(config$effort_scaling, 
        "raw")) {
        .resident_prompt_parameter("effort_reference_value", 
            "reference effort value used to interpret baseline detection probability.", 
            "finite numeric value in the same units as effort_values", 
            config$effort_reference_value %||% vals[1], input_provider, 
            parser = function(x) {
                v <- as.numeric(x)
                if (!is.finite(v)) 
                  stop("effort_reference_value must be finite.")
                v
            }, advice = "For raw effort, baseline_detection_probability is interpreted at this reference value.")
    }
    else {
        config$effort_reference_value %||% 0
    }
    config
}
