publication_readiness_report <-
function (fit, profile = NULL) 
{
    stress <- tryCatch(reviewer_stress_test(fit), error = function(e) NULL)
    pit <- parameter_identifiability_table(fit, profile)
    warnings <- fit_warning_summary(fit)
    suitable <- (is.null(stress) || isTRUE(stress$suitable_for_publication_inference)) && 
        !any(pit$classification == "non-identifiable") && !nrow(warnings)
    list(suitable_for_publication_inference = suitable, parameter_identifiability = pit, 
        warnings = warnings, recommended_simplifications = recommended_model_simplification(fit), 
        verdict = if (suitable) {
            "Provisionally publication-ready, conditional on reporting assumptions and uncertainty diagnostics."
        } else {
            "Not publication-ready without simplification, stronger data support, or additional diagnostics."
        })
}
rank_abundance_model_suitability <-
function (data, occasions = NULL) 
{
    diag <- abundance_assumption_diagnostics(data, occasions)
    closed <- .diag_status(diag, "closed_capture_closure")
    robust <- .diag_status(diag, "robust_design_structure")
    open <- .diag_status(diag, "open_population_signal")
    suff <- .diag_status(diag, "data_sufficiency")
    hetero <- .diag_status(diag, "detection_heterogeneity")
    sparse <- suff == "fail"
    rows <- list(data.frame(model_family = "observed_only", candidate_model = "observed_only", 
        implemented = TRUE, base = if (sparse) 90 else 65, stringsAsFactors = FALSE), 
        data.frame(model_family = "chao1_chao2", candidate_model = "chao1_chao2", 
            implemented = TRUE, base = if (sparse) 85 else 70, 
            stringsAsFactors = FALSE), data.frame(model_family = "closed_capture", 
            candidate_model = "closed_M0", implemented = TRUE, 
            base = if (closed == "pass" && !sparse) 88 else if (closed == 
                "review") 60 else 25, stringsAsFactors = FALSE), 
        data.frame(model_family = "closed_capture", candidate_model = "closed_Mh_mixture", 
            implemented = TRUE, base = if (closed %in% c("pass", 
                "review") && hetero != "pass" && !sparse) 82 else 45, 
            stringsAsFactors = FALSE), data.frame(model_family = "huggins_closed_capture", 
            candidate_model = "huggins_M0", implemented = TRUE, 
            base = if (closed == "pass" && !sparse) 78 else 40, 
            stringsAsFactors = FALSE), data.frame(model_family = "robust_design", 
            candidate_model = "robust_design_closed_primary", 
            implemented = TRUE, base = if (robust == "pass" && 
                !sparse) 90 else 20, stringsAsFactors = FALSE), 
        data.frame(model_family = "open_population", candidate_model = "jolly_seber", 
            implemented = FALSE, base = if (open == "pass") 70 else 25, 
            stringsAsFactors = FALSE), data.frame(model_family = "open_population", 
            candidate_model = "POPAN_like", implemented = FALSE, 
            base = if (open == "pass") 65 else 20, stringsAsFactors = FALSE), 
        data.frame(model_family = "markovian_state_space", candidate_model = "state_space_robust_design", 
            implemented = TRUE, base = if (open %in% c("pass", 
                "review") && !sparse) 80 else 45, stringsAsFactors = FALSE))
    tab <- do.call(rbind, rows)
    tab$score <- tab$base
    tab$score[!tab$implemented] <- pmin(tab$score[!tab$implemented], 
        35)
    tab[order(-tab$score, tab$model_family), , drop = FALSE]
}
rank_abundance_models <-
function (fits) 
compare_abundance_models(fits)[order(compare_abundance_models(fits)$estimator_section, 
    compare_abundance_models(fits)$AICc), , drop = FALSE]
rank_candidate_models <-
function (fits, criterion = "AICc", chat = 1) 
{
    ok <- fits[vapply(fits, function(x) is.finite(x$logLik %||% 
        NA_real_), logical(1))]
    tab <- do.call(compare_residency_models, c(ok, list(criterion = criterion, 
        chat = chat)))
    tab$identifiability_penalty <- vapply(ok, function(f) {
        id <- f$identifiability
        if (is.null(id)) 
            return(0)
        10 * id$singular_hessian + 5 * id$sparse_data + 5 * id$boundary_estimate
    }, numeric(1))
    tab$penalized_score <- tab[[criterion]] + tab$identifiability_penalty
    tab[order(tab$penalized_score), ]
}
rank_candidate_models_tmb <-
function (fits, criterion = "AICc", chat = 1) 
{
    ranked <- rank_candidate_models(fits, criterion, chat)
    ranked$convergence_penalty <- vapply(fits[ranked$model_id], 
        function(f) {
            if (is.null(f$convergence) || is.na(f$convergence)) 
                5
            else if (f$convergence == 0) 
                0
            else 10
        }, numeric(1))
    ranked$boundary_penalty <- vapply(fits[ranked$model_id], 
        function(f) {
            w <- fit_warning_summary(f)
            if (any(grepl("Boundary|random-effect", w$warning))) 
                5
            else 0
        }, numeric(1))
    ranked$penalized_score <- ranked$penalized_score + ranked$convergence_penalty + 
        ranked$boundary_penalty
    ranked[order(ranked$penalized_score), ]
}
rank_detection_assumption_models <-
function (tab) 
{
    tab <- tab[order(tab$AICc, tab$AIC, tab$n_parameters), , 
        drop = FALSE]
    tab$delta_AICc <- tab$AICc - min(tab$AICc, na.rm = TRUE)
    if (!"diagnostic_status" %in% names(tab)) 
        tab$diagnostic_status <- "review_required"
    tab$model_comparison_caution <- "Information criteria compare fitted candidate models but do not prove biological truth or identifiability. A lower AIC/AICc/BIC does not override convergence failures, boundary estimates, missing covariates, poor scaling, or biological implausibility."
    tab$recommendation <- ifelse(tab$diagnostic_warnings == "" & 
        tab$diagnostic_status %in% c("likely_supported", "review_required") & 
        tab$delta_AICc <= 2, "supported candidate", "review diagnostics or prefer simpler supported model")
    row.names(tab) <- NULL
    tab
}
rank_model_recommendations_for_assumption_review <-
function (analysis) 
{
    details <- abundance_model_detail_table(analysis)
    details <- assess_abundance_model_suitability(details, analysis)
    rank <- c(recommended = 1L, useful_baseline = 2L, acceptable_with_caution = 3L, 
        not_recommended = 4L, not_assessable = 5L, not_assessed = 6L)
    details$recommendation_rank <- unname(rank[details$display_suitability] %||% 
        99L)
    details <- details[order(details$recommendation_rank, details$option), 
        , drop = FALSE]
    details$suitability_rank <- seq_len(nrow(details))
    details
}
rank_transition_models <-
function (models) 
{
    rows <- lapply(names(models), function(name) {
        fit <- models[[name]]
        if (inherits(fit, "error")) {
            return(data.frame(model = name, transition_estimation = name, 
                logLik = NA_real_, n_parameters = NA_integer_, 
                AIC = NA_real_, AICc = NA_real_, BIC = NA_real_, 
                convergence = NA, hessian_status = "not_fit", 
                identifiability_warnings = conditionMessage(fit), 
                recommendation = "Model failed; do not use for transition inference.", 
                result_interpretation = paste0("The ", name, 
                  " transition model could not be fitted to these data."), 
                stringsAsFactors = FALSE))
        }
        n <- sum(as.matrix(fit$history) >= 0, na.rm = TRUE)
        k <- fit$npar
        aicc <- fit$AIC + (2 * k * (k + 1))/max(1, n - k - 1)
        diag <- diagnose_transition_identifiability(fit)
        bad <- length(diag$warnings) > 0
        data.frame(model = name, transition_estimation = name, 
            logLik = fit$logLik, n_parameters = k, AIC = fit$AIC, 
            AICc = aicc, BIC = fit$BIC %||% NA_real_, convergence = fit$convergence, 
            hessian_status = ifelse(isTRUE(transition_hessian_diagnostics(fit)$positive_definite), 
                "positive_definite", "problem"), identifiability_warnings = paste(diag$warnings, 
                collapse = " | "), recommendation = if (bad && 
                name != "fixed") 
                "Use simpler/fixed transition structure unless additional diagnostics support estimation."
            else "Candidate acceptable under implemented checks.", 
            result_interpretation = paste0("This row fits the ", 
                name, " transition matrix option and compares it using model-selection scores. Lower AIC, AICc, and BIC values are preferred, but only if diagnostics are acceptable."), 
            stringsAsFactors = FALSE)
    })
    out <- do.call(rbind, rows)
    out[order(out$AICc), ]
}
read_empirical_csv <-
function (path, format = NULL, occasion_dates = NULL, allow_synthetic_dates = FALSE, 
    ...) 
{
    dat <- read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
    nms <- names(dat)
    if (any(c("id", "ID", "individual", "Individual") %in% nms) && 
        any(c("date", "Date", "sampling_date") %in% nms)) {
        id_col <- intersect(c("id", "ID", "individual", "Individual"), 
            nms)[1]
        date_col <- intersect(c("date", "Date", "sampling_date"), 
            nms)[1]
        dat[[date_col]] <- as.Date(dat[[date_col]])
        if (any(is.na(dat[[date_col]]))) 
            stop("Empirical CSV contains missing or invalid survey dates.", 
                call. = FALSE)
        return(.resident_v090_as_resident_encounter_data(table(dat[[id_col]], 
            dat[[date_col]]) > 0, occasions = data.frame(occasion = seq_along(sort(unique(dat[[date_col]]))), 
            date = sort(unique(dat[[date_col]]))), raw = dat, 
            source = path))
    }
    read_wide_encounter_history(path, occasion_dates = occasion_dates, 
        allow_synthetic_dates = allow_synthetic_dates, ...)
}
read_excel_sightings_workbook <-
function (file) 
{
    if (requireNamespace("readxl", quietly = TRUE)) {
        sheet_names <- readxl::excel_sheets(file)
        sheets <- setNames(lapply(sheet_names, function(sh) as.data.frame(readxl::read_excel(file, 
            sheet = sh))), sheet_names)
    }
    else {
        sheets <- resident_read_xlsx_workbook_base(file)
    }
    long_sheets <- sheets[vapply(sheets, resident_is_long_sighting_frame, 
        logical(1))]
    if (length(long_sheets)) {
        cleaned <- Map(resident_clean_long_sighting_frame, long_sheets, 
            names(long_sheets))
        all_cols <- unique(unlist(lapply(cleaned, names), use.names = FALSE))
        cleaned <- lapply(cleaned, function(dat) {
            missing <- setdiff(all_cols, names(dat))
            for (m in missing) dat[[m]] <- NA_character_
            dat[, all_cols, drop = FALSE]
        })
        combined <- do.call(rbind, cleaned)
        out <- resident_try_import_data_frame(combined, file, 
            paste(names(long_sheets), collapse = ","))
        if (is.list(out) && !is.null(out$history)) {
            out$metadata$combined_sheets <- names(long_sheets)
            return(out)
        }
    }
    attempts <- list()
    for (sh in names(sheets)) {
        attempts[[sh]] <- resident_try_import_data_frame(sheets[[sh]], 
            file, sh)
        if (is.list(attempts[[sh]]) && !is.null(attempts[[sh]]$history)) 
            return(attempts[[sh]])
    }
    stop("No worksheet in the Excel file looked like a supported wide encounter-history table or SOCPROG long sightings table. Expected either columns id/date or one id column plus 0/1 occasion columns.", 
        call. = FALSE)
}
read_mark_encounter_history <-
function (path, occasion_dates = NULL, allow_synthetic_dates = FALSE, 
    ...) 
{
    lines <- readLines(path, warn = FALSE)
    lines <- trimws(lines[nzchar(trimws(lines))])
    parts <- strsplit(lines, "[[:space:],]+")
    ids <- vapply(parts, `[`, character(1), 1)
    hist <- vapply(parts, function(z) z[2], character(1))
    K <- max(nchar(hist))
    y <- t(vapply(strsplit(hist, ""), function(z) as.numeric(c(z, 
        rep(0, K - length(z)))), numeric(K)))
    rownames(y) <- ids
    dates <- resident_require_dates(occasion_dates, allow_synthetic_dates, 
        K)
    out <- as_resident_encounter_data(y, data.frame(occasion = seq_len(K), 
        date = dates), raw = lines, source = path, allow_synthetic_dates = allow_synthetic_dates)
    if (isTRUE(allow_synthetic_dates) && is.null(occasion_dates)) {
        attr(out, "synthetic_dates_used") <- TRUE
        attr(out, "synthetic_date_warning") <- "Synthetic dates were created for testing/template validation and should not be used for scientific inference."
    }
    out
}
read_mark_inp_format <-
function (file, start_date = as.Date("2020-01-01"), occasion_interval_days = 1, 
    occasion_file = NULL) 
{
    if (!file.exists(file)) 
        stop("File not found: ", file, call. = FALSE)
    lines <- resident_read_text_lines(file)
    lines <- trimws(lines[nzchar(trimws(lines))])
    lines <- lines[!grepl("^#", lines)]
    pattern <- "^/\\*([^*]+)\\*/\\s*([01]+)\\s+([0-9]+)\\s*;?"
    ok <- grepl(pattern, lines)
    if (!any(ok)) 
        stop("MARK .inp file must contain rows like /*id*/010101 1;", 
            call. = FALSE)
    ids <- sub(pattern, "\\1", lines[ok])
    histories <- sub(pattern, "\\2", lines[ok])
    freq <- as.integer(sub(pattern, "\\3", lines[ok]))
    widths <- nchar(histories)
    if (length(unique(widths)) != 1L) 
        stop("All MARK .inp encounter histories must have the same length.", 
            call. = FALSE)
    mat <- do.call(rbind, lapply(strsplit(histories, ""), as.integer))
    if (any(is.na(freq) | freq < 1L)) 
        freq <- rep(1L, length(ids))
    if (any(freq > 1L)) {
        mat <- mat[rep(seq_len(nrow(mat)), freq), , drop = FALSE]
        ids <- make.unique(rep(ids, freq), sep = "_")
    }
    rownames(mat) <- ids
    companion <- occasion_file %||% find_resident_companion_file(file, 
        "occasion_dates")
    if (!is.na(companion) && file.exists(companion)) {
        occ <- read_resident_occasion_table(companion)
        warnings <- character()
    }
    else {
        occ <- resident_occasion_table_from_dates(start_date + 
            (seq_len(ncol(mat)) - 1L) * occasion_interval_days, 
            source = "synthetic_unconfirmed")
        attr(occ, "synthetic_dates_used") <- TRUE
        warnings <- "MARK .inp file has no occasion-date companion; synthetic dates were generated for ordering only."
    }
    resident_make_import_result(mat, occ, raw = data.frame(id = ids, 
        encounter_history = histories, frequency = freq, stringsAsFactors = FALSE), 
        format = "MARK_INP", source_file = file, warnings = warnings, 
        metadata = list(occasion_file = if (!is.na(companion)) companion else NA_character_))
}
read_mark_occasion_dates <-
function (path = NULL, allow_synthetic_dates = FALSE, n_occasions = NULL, 
    ...) 
{
    if (is.null(path) || !file.exists(path)) {
        dates <- resident_require_dates(NULL, allow_synthetic_dates, 
            n_occasions, ...)
        return(data.frame(occasion = seq_along(dates), date = dates, 
            stringsAsFactors = FALSE))
    }
    dat <- read.csv(path, stringsAsFactors = FALSE)
    date_col <- intersect(c("date", "sampling_date", "occasion_date"), 
        names(dat))[1]
    if (is.na(date_col)) 
        stop("Occasion-date file must contain a date column.", 
            call. = FALSE)
    data.frame(occasion = seq_len(nrow(dat)), date = as.Date(dat[[date_col]]), 
        stringsAsFactors = FALSE)
}
read_program_mark_format <-
function (file, occasion_file = NULL, start_date = as.Date("2020-01-01"), 
    occasion_interval_days = 1, ...) 
{
    if (!file.exists(file)) 
        stop("File not found: ", file, call. = FALSE)
    lines <- resident_read_text_lines(file)
    dat <- tryCatch(utils::read.table(file, header = TRUE, stringsAsFactors = FALSE, 
        colClasses = "character", comment.char = "#"), error = function(e) stop("Could not read the Program MARK-style file. Expected whitespace-delimited columns named id and encounter_history. Details: ", 
        conditionMessage(e), call. = FALSE))
    names(dat) <- resident_clean_names(names(dat))
    if (!all(c("id", "encounter_history") %in% names(dat))) 
        stop("Program MARK-style file must contain columns named id and encounter_history.", 
            call. = FALSE)
    dat$encounter_history <- gsub("[^01]", "", as.character(dat$encounter_history))
    histories <- strsplit(dat$encounter_history, "")
    widths <- lengths(histories)
    if (length(unique(widths)) != 1L) 
        stop("All encounter_history strings must have the same length.", 
            call. = FALSE)
    history <- do.call(rbind, lapply(histories, function(z) as.integer(z)))
    rownames(history) <- as.character(dat$id)
    companion <- occasion_file %||% find_resident_companion_file(file, 
        "occasion_dates")
    occ <- NULL
    if (!is.na(companion) && file.exists(companion)) 
        occ <- read_resident_occasion_table(companion)
    if (is.null(occ)) {
        dates <- parse_program_mark_dates_from_comments(lines, 
            ncol(history))
        if (is.null(dates)) {
            dates <- start_date + (seq_len(ncol(history)) - 1L) * 
                occasion_interval_days
            warnings <- "No companion/date comment was found; synthetic dates were generated and will not be treated as confirmed field dates."
        }
        else warnings <- character()
        occ <- make_occasion_table(dates = dates)
        attr(occ, "real_dates_confirmed") <- FALSE
        attr(occ, "date_source") <- if (length(warnings)) 
            "synthetic_unconfirmed"
        else "mark_comment_unconfirmed"
    }
    else warnings <- character()
    resident_make_import_result(history, occ, raw = dat, format = "PROGRAM_MARK", 
        source_file = file, warnings = warnings, metadata = list(occasion_file = if (!is.na(companion)) companion else NA_character_))
}
read_resident_capture_file <-
function (file, format = "AUTO", ...) 
{
    format <- toupper(gsub("[ -]+", "_", format))
    if (format == "AUTO") 
        format <- resident_detect_import_format(file)
    switch(format, PROGRAM_MARK = read_program_mark_format(file, 
        ...), SOCPROG = read_socprog_format(file, ...), CSV_LONG = read_socprog_format(file, 
        ...), WIDE_CSV = read_wide_encounter_history_csv(file, 
        ...), MARK_INP = read_mark_inp_format(file, ...), EXCEL = read_excel_sightings_workbook(file), 
        METADATA = stop("This file is metadata/audit documentation, not an encounter-history input file. Use the referenced MARK, SOCPROG, wide CSV, or .inp data file.", 
            call. = FALSE), stop("Unsupported or unrecognized import format: ", 
            format, call. = FALSE))
}
read_resident_occasion_table <-
function (file) 
{
    dat <- utils::read.csv(file, stringsAsFactors = FALSE, comment.char = "#", 
        check.names = FALSE)
    names(dat) <- resident_clean_names(names(dat))
    if (!"date" %in% names(dat)) 
        stop("Occasion table must contain a date column.", call. = FALSE)
    dat$date <- suppressWarnings(as.Date(dat$date))
    if ("surveyed" %in% names(dat)) 
        dat$surveyed <- resident_parse_bool(dat$surveyed)
    if (!"occasion" %in% names(dat)) 
        dat$occasion <- seq_len(nrow(dat))
    dat <- dat[order(dat$occasion), , drop = FALSE]
    attr(dat, "real_dates_confirmed") <- FALSE
    attr(dat, "date_source") <- "file_supplied_unconfirmed"
    dat
}
read_socprog_format <-
function (file, occasion_file = NULL) 
{
    if (!file.exists(file)) 
        stop("File not found: ", file, call. = FALSE)
    dat <- tryCatch(utils::read.csv(file, stringsAsFactors = FALSE, 
        comment.char = "#", check.names = FALSE), error = function(e) stop("Could not read the SOCPROG/CSV long-format file. Expected columns id and date. Details: ", 
        conditionMessage(e), call. = FALSE))
    names(dat) <- resident_clean_names(names(dat))
    if (!"id" %in% names(dat)) 
        stop("SOCPROG/CSV long format must contain a column named id.", 
            call. = FALSE)
    if (!"date" %in% names(dat) && "survey_date" %in% names(dat)) 
        dat$date <- dat$survey_date
    if (!"date" %in% names(dat)) 
        stop("SOCPROG/CSV long format must contain a column named date, or a survey_date column that can be used as the date.", 
            call. = FALSE)
    dat$id <- as.character(dat$id)
    parsed_date <- resident_parse_dates_flexible(dat$date)
    if (any(is.na(parsed_date)) && "survey_date" %in% names(dat)) {
        parsed_survey_date <- resident_parse_dates_flexible(dat$survey_date)
        parsed_date[is.na(parsed_date)] <- parsed_survey_date[is.na(parsed_date)]
    }
    dat$date <- parsed_date
    if (any(is.na(dat$date))) 
        stop("SOCPROG/CSV long format contains dates that could not be parsed. Use YYYY-MM-DD when possible; examples like 03-May-17 are also supported.", 
            call. = FALSE)
    dat <- dat[!is.na(dat$id) & nzchar(trimws(dat$id)), , drop = FALSE]
    dates <- sort(unique(dat$date))
    ids <- sort(unique(dat$id))
    history <- matrix(0L, nrow = length(ids), ncol = length(dates), 
        dimnames = list(ids, as.character(dates)))
    idx_i <- match(dat$id, ids)
    idx_j <- match(dat$date, dates)
    history[cbind(idx_i, idx_j)] <- 1L
    companion <- occasion_file %||% find_resident_companion_file(file, 
        "occasion_table")
    occ <- NULL
    if (!is.na(companion) && file.exists(companion)) 
        occ <- read_resident_occasion_table(companion)
    if (is.null(occ)) {
        occ <- resident_occasion_table_from_dates(dates, source = "socprog_dates_unconfirmed")
    }
    resident_make_import_result(history, occ, raw = dat, format = "SOCPROG", 
        source_file = file, metadata = list(occasion_file = if (!is.na(companion)) companion else NA_character_))
}
read_socprog_sightings <-
function (path, allow_synthetic_dates = FALSE, ...) 
{
    dat <- read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
    date_col <- intersect(c("date", "Date", "sighting_date", 
        "sampling_date"), names(dat))[1]
    if (is.na(date_col) && !isTRUE(allow_synthetic_dates)) 
        stop("SocProg-style empirical input requires a survey date column.", 
            call. = FALSE)
    if (is.na(date_col)) 
        dat$date <- resident_require_dates(NULL, TRUE, nrow(dat))
    else dat[[date_col]] <- as.Date(dat[[date_col]])
    dat
}
read_wide_encounter_history <-
function (path, occasion_dates = NULL, allow_synthetic_dates = FALSE, 
    ...) 
{
    dat <- read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
    id_col <- intersect(c("id", "ID", "individual", "Individual"), 
        names(dat))[1]
    if (is.na(id_col)) 
        id_col <- names(dat)[1]
    hist_cols <- setdiff(names(dat), id_col)
    parsed_dates <- suppressWarnings(as.Date(rep(NA_character_, 
        length(hist_cols))))
    for (ii in seq_along(hist_cols)) parsed_dates[ii] <- tryCatch(suppressWarnings(as.Date(hist_cols[ii])), 
        error = function(e) as.Date(NA))
    date_like <- !is.na(parsed_dates)
    if (!any(date_like, na.rm = TRUE) && is.null(occasion_dates) && 
        !isTRUE(allow_synthetic_dates)) {
        stop("Wide input lacks date-like occasion columns. Provide an occasion-date file or set allow_synthetic_dates = TRUE only for testing/template validation.", 
            call. = FALSE)
    }
    y <- as.matrix(dat[, hist_cols, drop = FALSE])
    storage.mode(y) <- "numeric"
    rownames(y) <- dat[[id_col]]
    dates <- if (!is.null(occasion_dates)) 
        as.Date(occasion_dates)
    else if (any(date_like, na.rm = TRUE)) 
        parsed_dates
    else resident_require_dates(NULL, TRUE, ncol(y))
    out <- as_resident_encounter_data(y, occasions = data.frame(occasion = seq_len(ncol(y)), 
        date = dates), raw = dat, source = path, allow_synthetic_dates = allow_synthetic_dates)
    if (isTRUE(allow_synthetic_dates) && !any(date_like, na.rm = TRUE) && 
        is.null(occasion_dates)) {
        attr(out, "synthetic_dates_used") <- TRUE
        attr(out, "synthetic_date_warning") <- "Synthetic dates were created for testing/template validation and should not be used for scientific inference."
    }
    out
}
read_wide_encounter_history_csv <-
function (file, occasion_file = NULL) 
{
    dat <- utils::read.csv(file, stringsAsFactors = FALSE, check.names = FALSE, 
        comment.char = "#")
    if (ncol(dat) < 2L) 
        stop("Wide encounter-history CSV must contain an id column and at least one occasion column.", 
            call. = FALSE)
    names_clean <- resident_clean_names(names(dat))
    id_col <- which(names_clean %in% c("id", "individual_id", 
        "subject_id", "animal_id"))[1]
    if (is.na(id_col)) 
        id_col <- 1L
    ids <- as.character(dat[[id_col]])
    hist_cols <- setdiff(seq_along(dat), id_col)
    history <- as.matrix(dat[, hist_cols, drop = FALSE])
    storage.mode(history) <- "numeric"
    if (any(is.na(history))) 
        stop("Wide encounter-history CSV contains missing values in surveyed occasion columns. Use an occasion audit file to exclude no-effort columns before importing.", 
            call. = FALSE)
    history <- ifelse(history > 0, 1L, 0L)
    rownames(history) <- ids
    dates <- suppressWarnings(as.Date(names(dat)[hist_cols]))
    occ <- NULL
    if (!is.null(occasion_file) && file.exists(occasion_file)) 
        occ <- read_resident_occasion_table(occasion_file)
    if (is.null(occ)) {
        auto_occ <- find_resident_companion_file(file, "occasion_table")
        if (!is.na(auto_occ)) 
            occ <- read_resident_occasion_table(auto_occ)
    }
    if (is.null(occ)) {
        occ <- data.frame(occasion = seq_along(hist_cols), date = dates, 
            original_header_date = names(dat)[hist_cols], surveyed = TRUE, 
            stringsAsFactors = FALSE)
        attr(occ, "real_dates_confirmed") <- FALSE
        attr(occ, "date_source") <- "wide_csv_header_unconfirmed"
    }
    resident_make_import_result(history, occ, raw = dat, format = "WIDE_CSV", 
        source_file = file, metadata = list(occasion_file = occasion_file %||% 
            find_resident_companion_file(file, "occasion_table")))
}
