recommend_abundance_model_from_data <-
function (data, occasions = NULL) 
{
    tab <- abundance_model_recommendation_table(data, occasions)
    recommended <- tab[tab$suitability == "recommended" & tab$selectable, 
        , drop = FALSE]
    if (!nrow(recommended)) 
        recommended <- tab[tab$suitability == "acceptable_with_caution" & 
            tab$selectable, , drop = FALSE]
    if (!nrow(recommended)) 
        recommended <- tab[tab$selectable, , drop = FALSE]
    list(recommendation_table = tab, selected = if (nrow(recommended)) recommended[1, 
        , drop = FALSE] else tab[1, , drop = FALSE], diagnostics = abundance_assumption_diagnostics(data, 
        occasions), diagnostic_interpretation = "Model recommendation is a diagnostic guide, not proof that assumptions are true. Final model choice must consider study design, field conditions, biology, and diagnostics.")
}
recommend_detection_assumption_model <-
function (ranked) 
{
    if (!"diagnostic_status" %in% names(ranked)) 
        ranked$diagnostic_status <- "review_required"
    good <- ranked[ranked$diagnostic_warnings == "" & ranked$diagnostic_status %in% 
        c("likely_supported", "review_required"), , drop = FALSE]
    if (!nrow(good)) {
        return(data.frame(selected_by_information_criterion = ranked$option_name[1], 
            diagnostic_status = ranked$diagnostic_status[1], 
            biological_review_required = TRUE, final_recommendation = "constant", 
            reason = "All richer candidates had diagnostic warnings or weak support; use the simplest model and collect stronger data or simplify assumptions.", 
            model_comparison_caution = "Information criteria compare fitted candidate models but do not prove biological truth or identifiability. A lower AIC/AICc/BIC does not override convergence failures, boundary estimates, missing covariates, poor scaling, or biological implausibility.", 
            stringsAsFactors = FALSE))
    }
    best <- good[order(good$AICc, good$n_parameters), , drop = FALSE][1, 
        ]
    data.frame(selected_by_information_criterion = ranked$option_name[1], 
        diagnostic_status = best$diagnostic_status, biological_review_required = best$diagnostic_status != 
            "likely_supported", final_recommendation = best$option_name, 
        reason = "Selected among candidates without diagnostic warnings using corrected Akaike information criterion and simplicity when differences are small.", 
        model_comparison_caution = "Information criteria compare fitted candidate models but do not prove biological truth or identifiability. A lower AIC/AICc/BIC does not override convergence failures, boundary estimates, missing covariates, poor scaling, or biological implausibility.", 
        stringsAsFactors = FALSE)
}
recommend_model_structure <-
function (imported) 
{
    s <- summarize_capture_data(imported)
    detections <- s$total_capture_records
    n <- s$number_of_different_individuals
    occasions <- s$number_of_sampling_occasions
    recommendation <- if (detections < 20 || detections/max(1, 
        n) < 1.5) {
        "Start with a simple constant-detection robust-design model: detection_formula = ~ 1 and estimate_transition = FALSE."
    }
    else if (occasions < 10) {
        "Use a simple robust-design model. There are few sampling occasions, so avoid complex transition or covariate models."
    }
    else {
        "Start with constant detection, then compare effort-dependent detection and constrained transition models."
    }
    data.frame(recommendation = recommendation, test_all_model_structures = "Only test all candidate models after the simple model passes reliability checks.", 
        reliability_interpretation = "Complex models need enough detections. Starting simple reduces false confidence and easier-to-miss failures.", 
        stringsAsFactors = FALSE)
}
