recommend_primary_classifier <-
function (analysis, tab) 
{
    scores <- score_literature_classifier_suitability(analysis, 
        tab)
    diag <- primary_classifier_temporal_diagnostics(analysis, 
        tab)
    if (!nrow(scores)) {
        fallback <- resident_primary_literature_classifier_column(tab)
        classifier <- if (!is.na(fallback)) 
            resident_literature_classifier_label(fallback)
        else "No literature classifier available"
        return(list(classifier_column = fallback, classifier = classifier, 
            reason = "No scored classifier was available; fixed fallback order was used.", 
            confidence = "low", scores = scores, temporal_diagnostics = diag))
    }
    best <- scores[1, , drop = FALSE]
    second <- if (nrow(scores) > 1L) 
        scores[2, , drop = FALSE]
    else NULL
    margin <- if (!is.null(second)) 
        best$score - second$score
    else best$score
    confidence <- if (best$score >= 7 && margin >= 2) 
        "high"
    else if (best$score >= 4) 
        "moderate"
    else "low"
    reason <- paste0("Recommended by Huesca-style suitability scoring for goal '", 
        best$classification_goal, "': ", best$reason, ".")
    list(classifier_column = best$classifier_column, classifier = best$classifier, 
        reason = reason, confidence = confidence, scores = scores, 
        temporal_diagnostics = diag)
}
