recommended_model_simplification <-
function (fit) 
{
    ws <- fit_warning_summary(fit)$warning
    rec <- character(0)
    if (any(grepl("Sparse", ws))) 
        rec <- c(rec, "Reduce states/covariates or use constant-p robust design.")
    if (any(grepl("Hessian", ws))) 
        rec <- c(rec, "Use bootstrap/profile intervals and simplify transition structure.")
    if (any(grepl("Boundary", ws))) 
        rec <- c(rec, "Fix weakly supported transition probabilities or use biologically ordered constraints.")
    if (any(grepl("random-effect", ws))) 
        rec <- c(rec, "Drop unsupported random-effect components.")
    if (!length(rec)) 
        rec <- "No immediate simplification required; still report diagnostics."
    data.frame(recommendation = unique(rec), stringsAsFactors = FALSE)
}
refit_model <-
function (fit, new_history, ...) 
{
    if (inherits(fit, "resident_huggins_abundance_fit")) 
        fit_abundance_model(new_history, fit$abundance_model, 
            ...)
    else if (inherits(fit, "resident_closed_abundance_fit")) 
        fit_abundance_model(new_history, fit$abundance_model, 
            ...)
    else if (inherits(fit, "resident_cjs_fit")) 
        fit_cjs_model(new_history, fit$occasions, Phi = fit$Phi_formula, 
            p = fit$p_formula, ...)
    else stop("Bootstrap unavailable because this model lacks simulate/refit methods.", 
        call. = FALSE)
}
refit_with_fixed_parameter <-
function (fit, parameter, value, ...) 
{
    y <- fit$history
    if (inherits(fit, "resident_huggins_abundance_fit") && fit$abundance_model == 
        "huggins_M0" && parameter %in% c("p", "lp")) {
        ll <- huggins_loglik(c(lp = value), y, "huggins_M0")
        return(list(logLik = ll, parameter_value = value, convergence = 0L))
    }
    if (inherits(fit, "resident_closed_abundance_fit") && fit$abundance_model == 
        "closed_M0" && parameter %in% c("p", "lp")) {
        obj <- function(log_f0) -closed_capture_loglik(c(log_f0 = log_f0, 
            lp = value), y, "closed_M0")
        opt <- optimize(obj, interval = c(log(0.0001), log(max(1, 
            nrow(y) * 5))))
        return(list(logLik = -opt$objective, parameter_value = value, 
            nuisance = opt$minimum, convergence = 0L))
    }
    stop("Profile likelihood unavailable for this parameter/model.", 
        call. = FALSE)
}
