reprompt_until_valid <-
function (prompt, parser, input_provider = NULL, default = NULL, 
    example = NULL, max_retries = 5L, allow_default = TRUE) 
{
    tries <- 0L
    repeat {
        ans <- resident_safe_readline(prompt, input_provider)
        key <- tolower(trimws(ans))
        if (allow_default && tries == 0L && (key %in% c("", "default")) && 
            !is.null(default)) 
            return(default)
        if (key == "cancel") 
            stop("Configuration cancelled by user.")
        if (key == "back") 
            stop("Back navigation requested; restart the previous parameter section.")
        if (key == "help") {
            if (!is.null(example)) 
                cat("Example:", example, "\n")
            next
        }
        val <- tryCatch(parser(ans), error = function(e) e)
        if (!inherits(val, "error")) 
            return(val)
        resident_handle_input_error(val, example)
        tries <- tries + 1L
        if (tries >= max_retries) 
            stop("Maximum input retries reached.")
    }
}
require_dates_for_open_population <-
function (history, occasions = NULL, allow_synthetic_dates = FALSE, 
    data_type = c("empirical", "simulation", "test"), model = "open-population model") 
{
    data_type <- match.arg(data_type)
    if (data_type == "empirical") 
        validate_empirical_dates(occasions, allow_synthetic_dates, 
            model)
    if (is.null(occasions) && !isTRUE(allow_synthetic_dates)) {
        stop("This model requires valid survey dates or explicitly approved synthetic testing dates. No dates were found in the empirical input.", 
            call. = FALSE)
    }
    invisible(TRUE)
}
require_temporal_structure_for_model <-
function (analysis, model, input_provider = NULL, allow_infer = TRUE) 
{
    if (!temporal_structure_required(model)) 
        return(analysis)
    if (!is.null(analysis$temporal_structure)) 
        return(apply_temporal_structure_to_analysis(analysis))
    y <- extract_history(analysis, stage = "temporal-structure requirement")
    occ <- extract_occasions(analysis, stage = "temporal-structure requirement")
    st <- if (isTRUE(allow_infer) && is.null(input_provider)) 
        infer_primary_secondary_periods(y, occ)
    else ask_primary_secondary_periods(y, occ, input_provider)
    if (isTRUE(st$automatic)) 
        print_temporal_structure_review(st)
    apply_temporal_structure_to_analysis(store_temporal_structure(analysis, 
        st), st)
}
