requires_temporal_structure <-
function (model = NULL, formulas = NULL, time_varying = FALSE) 
{
    key <- tolower(as.character(model %||% ""))
    temporal_models <- tolower(c("robust_design_closed_primary", 
        "robust_design_huggins_primary", "state_space_robust_design", 
        "markovian_state", "multistate", "multistate/state-space", 
        "CJS", "jolly_seber", "POPAN_like", "jolly_seber_like", 
        "open_population", "robust_design"))
    formula_text <- paste(vapply(formulas %||% list(), function(f) paste(deparse(f), 
        collapse = ""), character(1)), collapse = " ")
    formula_temporal <- grepl("time|occasion|primary|secondary|Phi|pent|GammaPrime|GammaDoublePrime|transition|migration|state", 
        formula_text, ignore.case = TRUE)
    isTRUE(time_varying) || key %in% temporal_models || formula_temporal
}
residency_category_evidence_summary <-
function (analysis) 
{
    tab <- residency_category_proportion_table(analysis)
    data.frame(uncertainty_method = paste(unique(tab$uncertainty_method), 
        collapse = "; "), evidence_summary = paste(unique(tab$evidence_interpretation), 
        collapse = " "), warning = paste(unique(tab$warning[nzchar(tab$warning)]), 
        collapse = " "), stringsAsFactors = FALSE)
}
residency_category_proportion_table <-
function (analysis, ...) 
{
    old_result <- tryCatch(.old_residency_category_proportion_table_v086(analysis, 
        ...), error = function(e) NULL)
    if (!is.null(old_result)) 
        return(old_result)
    hist <- extract_history(analysis, stage = "residency category proportions")
    lit <- literature_residency_metrics_table(analysis)
    cls <- if ("Zolman" %in% names(lit)) 
        lit$Zolman
    else if ("Parra" %in% names(lit)) 
        lit$Parra
    else rep("unclassified", nrow(hist))
    tab <- as.data.frame(table(cls), stringsAsFactors = FALSE)
    names(tab) <- c("residency_category", "count")
    names(tab)[names(tab) == "count"] <- "n_individuals"
    tab$proportion <- tab$n_individuals/sum(tab$n_individuals)
    ci <- t(vapply(tab$n_individuals, wilson_binomial_interval, 
        numeric(2), n = sum(tab$n_individuals)))
    tab$lower_95 <- ci[, "lower"]
    tab$upper_95 <- ci[, "upper"]
    tab$uncertainty_method <- "descriptive binomial interval"
    tab$result_interpretation <- "Proportions summarize assigned residency categories for validated encounter histories."
    tab
}
residency_category_uncertainty_table <-
function (analysis) 
{
    cls <- individual_residency_classification(analysis)
    method <- choose_residency_uncertainty_method(analysis)
    n_total <- nrow(cls)
    tab <- as.data.frame(table(cls$assigned_residency_class), 
        stringsAsFactors = FALSE)
    names(tab) <- c("residency_category", "n_individuals")
    tab$proportion <- tab$n_individuals/max(1L, n_total)
    ints <- t(vapply(tab$n_individuals, wilson_binomial_interval, 
        numeric(2), n = n_total))
    tab$standard_error <- sqrt(tab$proportion * (1 - tab$proportion)/max(1L, 
        n_total))
    tab$lower_95 <- ints[, "lower"]
    tab$upper_95 <- ints[, "upper"]
    tab$uncertainty_method <- if (method == "posterior classification probability summary") {
        "posterior classification probability summary with descriptive Wilson interval"
    }
    else if (method == "LR/profile support available for profiled parameters only") {
        "descriptive binomial interval; LR/profile evidence is not category-level unless directly computed"
    }
    else method
    tab$evidence_metric <- ifelse(method == "posterior classification probability summary", 
        "classification confidence and Wilson interval", "Wilson binomial interval")
    tab$evidence_interpretation <- ifelse(grepl("LR/profile", 
        tab$uncertainty_method), "Likelihood-ratio evidence is available only for parameters directly profiled; transition-parameter support is not used as category-proportion uncertainty.", 
        "Intervals summarize category-proportion uncertainty or descriptive variation for the available classification table.")
    if (!is.null(analysis$profile_likelihood) || !is.null(analysis$transition_profile)) {
        tab$evidence_interpretation <- paste(tab$evidence_interpretation, 
            "LR/profile evidence was detected but is not used as category-proportion uncertainty unless category proportions were directly profiled.")
    }
    tab$warning <- ifelse(tab$uncertainty_method == "descriptive binomial interval", 
        "This is descriptive variation, not fitted-model uncertainty.", 
        "")
    tab
}
residency_class_summary <-
function (analysis) 
{
