resident_add_import_aliases <-
function (analysis) 
{
    if (!is.list(analysis)) 
        return(analysis)
    history <- analysis$data$history %||% analysis$observed %||% 
        analysis$encounter_data$history %||% NULL
    occasions <- analysis$data$occasions %||% analysis$occasions %||% 
        analysis$encounter_data$occasions %||% NULL
    if (!is.null(history)) {
        analysis$observed <- history
        if (is.null(analysis$history)) 
            analysis$history <- history
    }
    if (!is.null(occasions)) 
        analysis$occasions <- occasions
    if (is.null(analysis$encounter_data)) 
        analysis$encounter_data <- list()
    if (!is.null(history)) 
        analysis$encounter_data$history <- history
    if (!is.null(occasions)) 
        analysis$encounter_data$occasions <- occasions
    if (!is.null(analysis$data$format)) 
        analysis$source_format <- analysis$data$format
    if (!is.null(analysis$data$source_file)) 
        analysis$source_file <- analysis$data$source_file
    if (!is.null(analysis$data$validation)) 
        analysis$import_validation <- analysis$data$validation
    analysis
}
resident_category_plot_layout <-
function (n_panels) 
{
    if (n_panels <= 1L) 
        return(c(1L, 1L))
    if (n_panels <= 4L) 
        return(c(2L, 2L))
    if (n_panels <= 6L) 
        return(c(3L, 2L))
    c(ceiling(n_panels/3L), 3L)
}
