resident_dates_look_generated_default <-
function (dates) 
{
    dates <- as.Date(dates)
    dates <- dates[!is.na(dates)]
    if (!length(dates)) 
        return(FALSE)
    daily <- length(dates) > 1L && all(diff(sort(unique(dates))) == 
        1)
    starts_default <- min(dates) %in% as.Date(c("2000-01-01", 
        "2020-01-01"))
    daily && starts_default
