resident_detect_import_format <-
function (path) 
{
    ext <- tolower(tools::file_ext(path))
    base <- basename(path)
    if (ext %in% c("xlsx", "xls")) 
        return("EXCEL")
    if (ext == "inp") 
        return("MARK_INP")
    preview <- resident_read_text_lines(path)
    preview <- preview[seq_len(min(length(preview), 20L))]
    text <- paste(preview, collapse = "\n")
    if (grepl("encounter_history_wide", base, ignore.case = TRUE)) 
        return("WIDE_CSV")
    dat <- tryCatch(utils::read.csv(path, nrows = 1, stringsAsFactors = FALSE, 
        check.names = FALSE), error = function(e) NULL)
    if (!is.null(dat)) {
        nm <- resident_clean_names(names(dat))
        if (any(nm %in% c("dataset", "issue_type", "program_mark_file", 
            "source_file"))) 
            return("METADATA")
        if (all(c("id", "date") %in% nm)) 
            return("SOCPROG")
        date_headers <- tryCatch(suppressWarnings(as.Date(names(dat))), 
            error = function(e) rep(as.Date(NA), length(names(dat))))
        if (length(nm) > 2L && any(nm %in% c("id", "individual_id", 
            "subject_id", "animal_id")) && any(!is.na(date_headers))) 
            return("WIDE_CSV")
    }
    if (grepl("SOCPROG|sightings_long", base, ignore.case = TRUE) || 
        grepl("(^|[,[:space:]])id[,[:space:]]*date", text, ignore.case = TRUE)) 
        return("SOCPROG")
    if (grepl("PROGRAM_MARK_encounter_history", base, ignore.case = TRUE) || 
        grepl("encounter_history", text, ignore.case = TRUE)) 
        return("PROGRAM_MARK")
    "UNKNOWN"
}
