resident_draw_category_proportion_plot <-
function (plot_data, family, output_dir = table_output_options()$output_dir, 
    draw_to_active_device = TRUE) 
{
    block <- plot_data[plot_data$indicator_family == family, 
        , drop = FALSE]
    if (!nrow(block)) 
        return(NA_character_)
    classifiers <- unique(block$classifier)
    colors <- resident_plot_colors(length(classifiers))
    title <- unique(block$indicator_family_label)[1]
    subtitle <- "Panels identify the published classifier. Names for categories follow those from Huesca et al. (2024)."
    layout <- resident_category_plot_layout(length(classifiers))
    width <- max(1000L, min(2600L, 520L * layout[2]))
    height <- max(700L, min(2400L, 310L * layout[1]))
    if (is.null(output_dir) || !nzchar(output_dir)) 
        output_dir <- "Outputs"
    dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
    path <- .timestamped_output_path(paste0("category_proportions_", 
        family), "png", output_dir = output_dir)
    draw_plot <- function() {
        old_par <- graphics::par(no.readonly = TRUE)
        on.exit(suppressWarnings(try(graphics::par(old_par), 
            silent = TRUE)), add = TRUE)
        graphics::par(mfrow = layout, mar = c(4.5, 9, 3.2000000000000002, 
            1.2), oma = c(0, 0, 4, 0), xpd = FALSE)
        for (i in seq_along(classifiers)) {
            classifier <- classifiers[i]
            panel <- block[block$classifier == classifier, , 
                drop = FALSE]
            panel <- panel[order(panel$proportion, panel$category_axis_label), 
                , drop = FALSE]
            labels <- resident_short_plot_label(panel$category_axis_label, 
                width = 24L)
            graphics::barplot(panel$proportion, names.arg = labels, 
                horiz = TRUE, las = 1, xlim = c(0, max(0.050000000000000003, 
                  min(1, max(panel$proportion, na.rm = TRUE) * 
                    1.1499999999999999))), col = colors[i], border = NA, 
                xlab = "Proportion of individuals", main = resident_short_plot_label(classifier, 
                  width = 28L), cex.names = 0.71999999999999997, 
                cex.main = 0.90000000000000002)
            graphics::mtext(unique(panel$category_type_label)[1], 
                side = 3, line = 0.10000000000000001, cex = 0.68000000000000005)
        }
        if (length(classifiers) < prod(layout)) {
            for (j in seq_len(prod(layout) - length(classifiers))) graphics::plot.new()
        }
        graphics::mtext(title, outer = TRUE, line = 2.3999999999999999, 
            cex = 1.1000000000000001, font = 2)
        graphics::mtext(subtitle, outer = TRUE, line = 1.2, cex = 0.81999999999999995)
    }
    grDevices::png(path, width = width, height = height, res = 120)
    png_device <- grDevices::dev.cur()
    png_ok <- tryCatch({
        draw_plot()
        TRUE
    }, error = function(e) e, finally = {
        if (identical(grDevices::dev.cur(), png_device)) 
            try(grDevices::dev.off(), silent = TRUE)
    })
    if (inherits(png_ok, "error")) 
        stop(png_ok)
    if (isTRUE(draw_to_active_device)) {
        active <- safe_plot_wrapper(block, "proportion", "proportion", 
            function(z) draw_plot(), likely_cause = "the RStudio plot pane is too small or the graphics device is in an invalid state.", 
            suggested_action = paste("Use the saved full-size PNG:", 
                path))
        if (!isTRUE(active$ok)) 
            cat("Full-size plot saved to:", path, "\n")
    }
    path
}
