resident_excel_col_index <-
function (ref) 
{
    letters <- unlist(strsplit(gsub("[^A-Z]", "", ref), ""))
    if (!length(letters)) 
        return(NA_integer_)
    sum((match(letters, LETTERS)) * 26^rev(seq_along(letters) - 
        1L))
}
