resident_extract_summary_inputs <-
function (x, occasion_table = NULL) 
{
    if (is_resident_encounter_data(x)) 
        return(list(history = coerce_history_matrix(x$history, 
            stage = "capture summary"), occasions = x$occasions, 
            source = x$source %||% "resident_encounter_data", 
            synthetic = resident_dates_are_synthetic(x, x$occasions)))
    if (is.list(x) && !is.null(x$encounter_data)) 
        return(resident_extract_summary_inputs(x$encounter_data, 
            occasion_table))
    if (is.list(x) && !is.null(x$data)) 
        return(resident_extract_summary_inputs(x$data, occasion_table))
    if (is.list(x) && !is.null(x$history)) 
        return(list(history = coerce_history_matrix(x$history, 
            stage = "capture summary"), occasions = x$occasions %||% 
            occasion_table, source = x$source %||% "history_list", 
            synthetic = resident_dates_are_synthetic(x, x$occasions %||% 
                occasion_table)))
    if (is.list(x) && !is.null(x$observed)) 
        return(list(history = coerce_history_matrix(x$observed, 
            stage = "capture summary"), occasions = x$occasions %||% 
            occasion_table, source = "observed_list", synthetic = resident_dates_are_synthetic(x, 
            x$occasions %||% occasion_table)))
    list(history = coerce_history_matrix(x, stage = "capture summary"), 
        occasions = occasion_table, source = "matrix", synthetic = resident_dates_are_synthetic(x, 
            occasion_table))
}
