resident_format_summary_value <-
function (value, digits = getOption("resident.console.summary_digits", 
    3L)) 
{
    if (length(value) == 0L) 
        return("not available")
    value <- value[1]
    if (inherits(value, "Date")) 
        return(if (is.na(value)) "not available" else as.character(value))
    if (is.logical(value)) 
        return(if (is.na(value)) "not available" else if (isTRUE(value)) "yes" else "no")
    if (is.numeric(value)) {
        if (is.na(value) || !is.finite(value)) 
            return("not available")
        if (abs(value - round(value)) < .Machine$double.eps^0.5) 
            return(as.character(as.integer(round(value))))
        return(format(round(value, digits), trim = TRUE, scientific = FALSE))
    }
    txt <- trimws(as.character(value))
    if (!nzchar(txt) || is.na(txt)) 
        "not available"
    else txt
}
