resident_literature_category_summary <-
function (classification) 
{
    if (is.null(classification) || !is.data.frame(classification) || 
        !nrow(classification)) 
        return(NULL)
    cat_col <- if ("primary_literature_category" %in% names(classification)) 
        "primary_literature_category"
    else literature_category_columns(classification)[1]
    if (is.na(cat_col) || !length(cat_col)) 
        return(NULL)
    tab <- as.data.frame(table(classification[[cat_col]], useNA = "ifany"), 
        stringsAsFactors = FALSE)
    names(tab) <- c("residency_category", "number_of_individuals")
    tab$proportion <- tab$number_of_individuals/sum(tab$number_of_individuals)
    tab$classifier_used <- cat_col
    tab$result_interpretation <- "This summary counts individuals assigned to each literature-based residency/site-fidelity category."
    tab
}
resident_literature_classification_table <-
function (analysis) 
{
    metrics <- literature_residency_metrics_table(analysis)
    if (!"id" %in% names(metrics)) 
        metrics$id <- rownames(extract_history(analysis, stage = "literature residency classification"))
    cats <- literature_category_columns(metrics)
    keep <- unique(c("id", "occurrence", "permanence_days", "mean_interval_days", 
        "periodicity_per_day", cats))
    out <- metrics[, intersect(keep, names(metrics)), drop = FALSE]
    recommendation <- recommend_primary_classifier(analysis, 
        metrics)
    out$primary_literature_category <- resident_primary_literature_category(metrics, 
        recommendation)
    out$primary_classifier <- resident_primary_literature_classifier(metrics, 
        recommendation)
    out$primary_classifier_reason <- recommendation$reason
    out$primary_classifier_confidence <- recommendation$confidence
    out$classifier_basis <- "Published residency/site-fidelity rules computed from the observed encounter history. The primary classifier is selected by Huesca-style suitability scoring, with a fixed order used only as fallback."
    out$result_interpretation <- "These are literature-based classifications from observed detections. They do not account for missed detections the way a fitted robust-design or state-space model can."
    attr(out, "interpretation") <- "Literature-based classifications are computed from encounter-history metrics such as occurrence, permanence, and seasonal/yearly detection rules. They are useful for comparison and teaching, but they are not fitted model-state estimates."
    out
}
