resident_make_import_result <-
function (history, occasions, raw = NULL, format, source_file, 
    warnings = character(), metadata = list()) 
{
    history <- as.matrix(history)
    storage.mode(history) <- "integer"
    if (is.null(rownames(history)) || any(!nzchar(rownames(history)))) 
        rownames(history) <- paste0("Subject_", seq_len(nrow(history)))
    if (is.null(occasions) || !is.data.frame(occasions)) 
        occasions <- make_occasion_table(dates = seq_len(ncol(history)))
    if (!"occasion" %in% names(occasions)) 
        occasions$occasion <- seq_len(nrow(occasions))
    if (!"date" %in% names(occasions)) 
        occasions$date <- as.Date(NA)
    if (nrow(occasions) != ncol(history)) 
        stop("Occasion table has ", nrow(occasions), " rows but the history has ", 
            ncol(history), " occasions.", call. = FALSE)
    occasions$occasion <- seq_len(nrow(occasions))
    if (!"year" %in% names(occasions)) 
        occasions$year <- suppressWarnings(as.integer(format(as.Date(occasions$date), 
            "%Y")))
    if (!"month" %in% names(occasions)) 
        occasions$month <- suppressWarnings(as.integer(format(as.Date(occasions$date), 
            "%m")))
    if (!"season" %in% names(occasions)) 
        occasions$season <- ifelse(is.na(occasions$month), NA_integer_, 
            ((occasions$month - 1L)%/%3L) + 1L)
    attr(occasions, "real_dates_confirmed") <- isTRUE(attr(occasions, 
        "real_dates_confirmed"))
    list(history = history, occasions = occasions, raw = raw, 
        format = format, source_file = normalizePath(path.expand(source_file), 
            mustWork = FALSE), import_warnings = unique(warnings), 
        metadata = metadata)
}
resident_occasion_table_from_dates <-
function (dates, source = "file_supplied_unconfirmed") 
{
    dates <- as.Date(dates)
    out <- data.frame(occasion = seq_along(dates), date = dates, 
        year = suppressWarnings(as.integer(format(dates, "%Y"))), 
        month = suppressWarnings(as.integer(format(dates, "%m"))), 
        season = suppressWarnings(ifelse(is.na(dates), NA_integer_, 
            ((as.integer(format(dates, "%m")) - 1L)%/%3L) + 1L)), 
        surveyed = TRUE, stringsAsFactors = FALSE)
    attr(out, "real_dates_confirmed") <- FALSE
    attr(out, "date_source") <- source
    out
}
resident_parse_bool <-
function (x) 
{
    y <- tolower(trimws(as.character(x)))
    y %in% c("true", "t", "1", "yes", "y", "surveyed")
}
resident_parse_dates_flexible <-
function (x) 
{
    raw <- trimws(as.character(x))
    raw[raw %in% c("", "NA", "N/A", "NULL")] <- NA_character_
    stripped <- sub("\\s+.*$", "", raw)
    formats <- c("%Y-%m-%d", "%d-%b-%y", "%d-%b-%Y", "%m/%d/%Y", 
        "%d/%m/%Y", "%Y/%m/%d", "%d-%m-%Y", "%m-%d-%Y")
    out <- rep(as.Date(NA), length(raw))
    for (fmt in formats) {
        parsed <- suppressWarnings(as.Date(stripped, format = fmt))
        fill <- is.na(out) & !is.na(parsed)
        out[fill] <- parsed[fill]
    }
    parsed_default <- tryCatch(suppressWarnings(as.Date(raw)), 
        error = function(e) rep(as.Date(NA), length(raw)))
    fill <- is.na(out) & !is.na(parsed_default)
    out[fill] <- parsed_default[fill]
    out
}
resident_parse_yes_no_10 <-
function (x) 
{
    if (is.logical(x) && length(x) == 1L && !is.na(x)) 
        return(x)
    key <- tolower(trimws(as.character(x)))
    if (key %in% c("1", "yes", "y", "true", "t")) 
        return(TRUE)
    if (key %in% c("0", "no", "n", "false", "f")) 
        return(FALSE)
    stop("Enter 1 for yes/TRUE or 0 for no/FALSE.")
}
resident_pipeline_startup <-
function (ask_tmb = interactive(), ask_data_or_simulation = interactive(), 
    create_templates = TRUE, input_provider = NULL, show_load_message = TRUE) 
{
    if (isTRUE(show_load_message)) 
        .resident_v095_handle_post_simulation_menu_choice <- handle_post_simulation_menu_choice
    resident_export_output_dir <- function(analysis = NULL) {
        out <- NULL
        if (is.list(analysis)) {
            out <- analysis$run_output_dir %||% analysis$output_dir %||% 
                NULL
        }
        out <- out %||% table_output_options()$output_dir %||% 
            resident_default_output_dir() %||% "Outputs"
        out <- as.character(out)[1]
        if (is.na(out) || !nzchar(trimws(out))) 
            out <- "Outputs"
        dir.create(out, recursive = TRUE, showWarnings = FALSE)
        out
    }
    resident_export_path <- function(analysis, filename) {
        file.path(resident_export_output_dir(analysis), filename)
    }
    safe_export_capture_recapture_table_v096 <- function(analysis, 
        path = NULL) {
        if (is.null(path) || !nzchar(trimws(path))) 
            path <- resident_export_path(analysis, "capture_recapture_table.csv")
        dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
        utils::write.csv(safe_capture_recapture_table_from_analysis(analysis), 
            path, row.names = FALSE)
        path
    }
    safe_export_capture_data_summary_v096 <- function(analysis, 
        path = NULL) {
        if (is.null(path) || !nzchar(trimws(path))) 
            path <- resident_export_path(analysis, "capture_data_summary.csv")
        dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
        utils::write.csv(analysis_capture_data_summary(analysis), 
            path, row.names = FALSE)
        path
    }
    safe_export_discovery_summary_v096 <- function(analysis, 
        path = NULL) {
        if (is.null(path) || !nzchar(trimws(path))) 
            path <- resident_export_path(analysis, "discovery_summary.csv")
        dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
        analysis <- ensure_discovery_curve_table(analysis)
        utils::write.csv(analysis$discovery_curve_table, path, 
            row.names = FALSE)
        path
    }
    safe_export_residency_classification_v096 <- function(analysis, 
        path = NULL) {
        analysis <- ensure_literature_residency_outputs(analysis)
        if (is.null(path) || !nzchar(trimws(path))) 
            path <- resident_export_path(analysis, "residency_classification_results.csv")
        dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
        utils::write.csv(safe_individual_residency_table(analysis), 
            path, row.names = FALSE)
        list(analysis = analysis, path = path)
    }
    safe_export_literature_comparison_v096 <- function(analysis, 
        path = NULL) {
        analysis <- ensure_literature_residency_outputs(analysis)
        outdir <- resident_export_output_dir(analysis)
        comparison <- safe_literature_comparison_table(analysis)
        paths <- character()
        if (!is.null(comparison) && is.data.frame(comparison) && 
            nrow(comparison)) {
            if (is.null(path) || !nzchar(trimws(path))) 
                path <- file.path(outdir, "model_literature_comparison.csv")
            dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
            utils::write.csv(comparison, path, row.names = FALSE)
            paths <- c(model_literature_comparison = path)
        }
        else {
            status_path <- file.path(outdir, "model_literature_comparison_status.txt")
            status_lines <- c("Model-vs-literature comparison export status", 
                "", "No model-based individual residency-state table is stored in this analysis object.", 
                "Resident did not create a model_literature_comparison.csv file because that would imply a comparison that has not been fitted.", 
                "", "What was exported instead:", "- literature_classifier_summary.csv: category counts for each implemented literature classifier.", 
                "- literature_residency_classification_full.csv: full individual literature-based classification table.", 
                "", "Recommended next step:", "Fit a supported residency-state model that stores individual state probabilities/classes, then rerun this export option.")
            writeLines(status_lines, status_path)
            paths <- c(model_literature_comparison_status = status_path)
        }
        summary <- literature_classifier_summary_long(safe_individual_residency_table(analysis))
        if (!is.null(summary) && is.data.frame(summary) && nrow(summary)) {
            summary_path <- file.path(outdir, "literature_classifier_summary.csv")
            utils::write.csv(summary, summary_path, row.names = FALSE)
            paths <- c(paths, literature_classifier_summary = summary_path)
        }
        classification <- safe_individual_residency_table(analysis)
        if (!is.null(classification) && is.data.frame(classification) && 
            nrow(classification)) {
            classification_path <- file.path(outdir, "literature_residency_classification_full.csv")
            utils::write.csv(classification, classification_path, 
                row.names = FALSE)
            paths <- c(paths, literature_residency_classification_full = classification_path)
        }
        analysis$literature_export_paths <- paths
        list(analysis = analysis, paths = paths)
    }
    safe_export_chao_from_analysis_v096 <- function(analysis) {
        analysis <- update_analysis_with_chao_outputs(analysis)
        outdir <- resident_export_output_dir(analysis)
        paths <- export_chao_outputs(analysis, output_dir = outdir)
        analysis$chao_plot_paths <- paths
        list(analysis = analysis, paths = paths)
    }
    handle_post_simulation_menu_choice <- function(choice, analysis, 
        input_provider = NULL) {
        menu <- post_simulation_menu_definition()
        key <- normalize_menu_choice(choice, menu)
        if (identical(key, "export_capture_table")) {
            path <- .resident_prompt("Enter CSV path, or press Enter for the run-folder capture_recapture_table.csv: ", 
                input_provider)
            saved <- safe_export_capture_recapture_table_v096(analysis, 
                path)
            cat("Saved:", saved, "\n")
            return(invisible(list(analysis = analysis, finished = FALSE)))
        }
        if (identical(key, "export_capture_summary")) {
            path <- .resident_prompt("Enter CSV path, or press Enter for the run-folder capture_data_summary.csv: ", 
                input_provider)
            saved <- safe_export_capture_data_summary_v096(analysis, 
                path)
            cat("Saved:", saved, "\n")
            return(invisible(list(analysis = analysis, finished = FALSE)))
        }
        if (identical(key, "export_discovery")) {
            path <- .resident_prompt("Enter CSV path, or press Enter for the run-folder discovery_summary.csv: ", 
                input_provider)
            saved <- safe_export_discovery_summary_v096(analysis, 
                path)
            cat("Saved:", saved, "\n")
            return(invisible(list(analysis = analysis, finished = FALSE)))
        }
        if (identical(key, "export_residency")) {
            result <- safe_export_residency_classification_v096(analysis)
            analysis <- result$analysis
            cat("Saved:", result$path, "\n")
            return(invisible(list(analysis = analysis, finished = FALSE)))
        }
        if (identical(key, "export_literature")) {
            result <- safe_export_literature_comparison_v096(analysis)
            analysis <- result$analysis
            cat("Saved literature/comparison export files:\n")
            print(result$paths)
            return(invisible(list(analysis = analysis, finished = FALSE)))
        }
        if (identical(key, "export_chao")) {
            result <- safe_export_chao_from_analysis_v096(analysis)
            analysis <- result$analysis
            cat("Saved Chao outputs:\n")
            print(result$paths)
            return(invisible(list(analysis = analysis, finished = FALSE)))
        }
        .resident_v095_handle_post_simulation_menu_choice(choice, 
            analysis, input_provider)
    }
    cat(resident_load_message(), "\n", sep = "")
    cat("This software analyzes capture-recapture data, where 1 means detected and 0 means not detected.\n")
    cat("Important: not detected does not automatically mean absent.\n\n")
    cat("Step 1: Working directory:\n")
    cat(getwd(), "\n\n")
    cat("Step 2: Core functions loaded:\n")
    cat("fit_robust_design_cr available:", exists("fit_robust_design_cr"), 
        "\n\n")
    cat("Step 3: TMB availability:\n")
    cat("TMB available:", tmb_available(), "\n")
    cat("TMB is a compiled-model tool for the existing state-space backend. CJS, JS, and POPAN TMB acceleration is not claimed in this version.\n")
    if (ask_tmb && !tmb_available()) {
        ans <- .resident_prompt("Do you want to install TMB now? Enter 1 for yes or 0 for no: ", 
            input_provider)
        if (isTRUE(tryCatch(resident_parse_yes_no_10(ans), error = function(e) FALSE))) 
            install.packages("TMB")
    }
    cat("\nStep 4: Data templates:\n")
    if (isTRUE(create_templates)) 
        print(write_capture_recapture_templates())
    if (isTRUE(ask_data_or_simulation)) 
        return(resident_workflow(input_provider = input_provider))
    invisible(TRUE)
}
