resident_read_xlsx_shared_strings_base <-
function (unzip_dir) 
{
    path <- file.path(unzip_dir, "xl", "sharedStrings.xml")
    if (!file.exists(path)) 
        return(character())
    xml <- paste(readLines(path, warn = FALSE), collapse = "")
    si <- resident_regex_all("<si[\\s\\S]*?</si>", xml)
    vapply(si, function(one) {
        text_bits <- resident_regex_all("<t[^>]*>[\\s\\S]*?</t>", 
            one)
        text_bits <- gsub("^<t[^>]*>|</t>$", "", text_bits)
        resident_xml_text_decode(paste(text_bits, collapse = ""))
    }, character(1))
}
resident_read_xlsx_sheet_base <-
function (sheet_file, shared_strings = character()) 
{
    xml <- paste(readLines(sheet_file, warn = FALSE), collapse = "")
    row_xml <- resident_regex_all("<row\\b[^>]*>[\\s\\S]*?</row>", 
        xml)
    rows <- list()
    max_col <- 0L
    for (row in row_xml) {
        row_num <- suppressWarnings(as.integer(sub(".*\\br=\"([0-9]+)\".*", 
            "\\1", row)))
        if (is.na(row_num)) 
            row_num <- length(rows) + 1L
        cells <- resident_regex_all("<c\\b[^>]*>[\\s\\S]*?</c>", 
            row)
        vals <- list()
        for (cell in cells) {
            ref <- sub(".*\\br=\"([A-Z]+[0-9]+)\".*", "\\1", 
                cell)
            col <- resident_excel_col_index(ref)
            typ <- if (grepl("\\bt=\"s\"", cell)) 
                "s"
            else if (grepl("\\bt=\"inlineStr\"", cell)) 
                "inlineStr"
            else "n"
            value <- sub(".*<v>([\\s\\S]*?)</v>.*", "\\1", cell, 
                perl = TRUE)
            if (identical(value, cell)) 
                value <- ""
            if (identical(typ, "s") && nzchar(value)) {
                idx <- suppressWarnings(as.integer(value)) + 
                  1L
                value <- if (!is.na(idx) && idx >= 1L && idx <= 
                  length(shared_strings)) 
                  shared_strings[idx]
                else ""
            }
            else if (identical(typ, "inlineStr")) {
                text_bits <- resident_regex_all("<t[^>]*>[\\s\\S]*?</t>", 
                  cell)
                value <- gsub("^<t[^>]*>|</t>$", "", text_bits)
                value <- paste(value, collapse = "")
            }
            vals[[as.character(col)]] <- resident_xml_text_decode(value)
            max_col <- max(max_col, col, na.rm = TRUE)
        }
        rows[[as.character(row_num)]] <- vals
    }
    if (!length(rows) || max_col < 1L) 
        return(data.frame())
    max_row <- max(as.integer(names(rows)), na.rm = TRUE)
    mat <- matrix("", nrow = max_row, ncol = max_col)
    for (rn in names(rows)) {
        vals <- rows[[rn]]
        for (cn in names(vals)) mat[as.integer(rn), as.integer(cn)] <- vals[[cn]]
    }
    nonempty <- apply(mat, 1, function(z) any(nzchar(trimws(z))))
    mat <- mat[nonempty, , drop = FALSE]
    if (!nrow(mat)) 
        return(data.frame())
    header_row <- which(apply(mat, 1, function(z) any(nzchar(trimws(z)))))[1]
    headers <- trimws(mat[header_row, ])
    keep <- nzchar(headers)
    dat <- as.data.frame(mat[(header_row + 1L):nrow(mat), keep, 
        drop = FALSE], stringsAsFactors = FALSE)
    names(dat) <- make.unique(headers[keep], sep = "_")
    dat <- dat[apply(dat, 1, function(z) any(nzchar(trimws(z)))), 
        , drop = FALSE]
    dat
}
resident_read_xlsx_workbook_base <-
function (file) 
{
    tmp <- tempfile("resident_xlsx_")
    dir.create(tmp, recursive = TRUE, showWarnings = FALSE)
    utils::unzip(file, exdir = tmp)
    shared <- resident_read_xlsx_shared_strings_base(tmp)
    sheets <- list.files(file.path(tmp, "xl", "worksheets"), 
        pattern = "^sheet[0-9]+\\.xml$", full.names = TRUE)
    out <- list()
    for (sheet in sheets) {
        nm <- tools::file_path_sans_ext(basename(sheet))
        out[[nm]] <- resident_read_xlsx_sheet_base(sheet, shared)
    }
    out
}
resident_regex_all <-
function (pattern, x) 
{
    m <- gregexpr(pattern, x, perl = TRUE)
    out <- regmatches(x, m)[[1]]
    if (length(out) == 1L && identical(out, character(0))) 
        character()
    else out
}
resident_require_dates <-
function (occasion_dates = NULL, allow_synthetic_dates = FALSE, 
    n_occasions = NULL, date_origin = "2000-01-01", date_spacing = "day") 
{
    if (!is.null(occasion_dates)) 
        return(as.Date(occasion_dates))
    if (!isTRUE(allow_synthetic_dates)) {
        stop("Input data do not contain survey dates. Provide occasion dates or set allow_synthetic_dates = TRUE only for testing or template validation.", 
            call. = FALSE)
    }
    warning("Input data do not contain survey dates. Synthetic dates can be created only for testing or template validation. They should not be used for scientific inference.", 
        call. = FALSE)
    if (is.null(n_occasions)) 
        stop("n_occasions is required when synthetic dates are requested.", 
            call. = FALSE)
    seq.Date(as.Date(date_origin), by = date_spacing, length.out = n_occasions)
}
