        return(FALSE)
    threshold <- getOption("resident.console.list_column_threshold", 
        8L)
    max_rows <- getOption("resident.console.list_max_rows", 3L)
    if (!is.null(key_columns) && length(key_columns) < ncol(x)) 
        return(FALSE)
    nrow(x) <= max_rows && ncol(x) > threshold
