resident_summary_sections <-
function (x) 
{
    names_x <- names(x)
    section_for <- function(nm) {
        if (grepl("date|sampling_period|sampling_interval", nm)) 
            return("Sampling dates and time span")
        if (grepl("individual|occasion|capture|singleton|detected|identification|detection", 
            nm)) 
            return("Dataset size and capture frequency")
        if (grepl("status|warning|recommendation|reliability|suitability|assumption|risk", 
            nm)) 
            return("Status, assumptions, and recommendations")
        if (grepl("interpretation|note|meaning|plain", nm)) 
            return("Interpretation")
        "Other details"
    }
    stats::setNames(vapply(names_x, section_for, character(1)), 
        names_x)
}
