resident_with_option11_plot_state <-
function (draw, fallback = NULL, mar = c(3.5, 3.5, 2, 1)) 
{
    draw_expr <- substitute(draw)
    fallback_expr <- substitute(fallback)
    has_fallback <- !missing(fallback) && !identical(fallback_expr, 
        quote(NULL))
    eval_env <- parent.frame()
    op <- tryCatch(graphics::par(no.readonly = TRUE), error = function(e) NULL)
    if (!is.null(op)) 
        on.exit(suppressWarnings(try(graphics::par(op), silent = TRUE)), 
            add = TRUE)
    try(graphics::par(mar = mar), silent = TRUE)
    tryCatch({
        eval(draw_expr, envir = eval_env)
        TRUE
    }, error = function(e) {
        if (!resident_is_graphics_size_error(e)) 
            stop(e)
        if (!has_fallback) 
            return(FALSE)
        tryCatch({
            eval(fallback_expr, envir = eval_env)
            TRUE
        }, error = function(e2) {
            if (resident_is_graphics_size_error(e2)) 
                return(FALSE)
            stop(e2)
        })
    })
}
