reviewer_stress_test <-
function (fit, min_events_per_parameter = 5) 
{
    id <- validate_multistate_identifiability(fit, min_events_per_parameter)
    flags <- data.frame(item = c("overparameterization", "weak_identifiability", 
        "sparse_data", "boundary_estimates", "singular_hessian", 
        "p_availability_confounding", "temporary_emigration_detection_confounding", 
        "unstable_transitions", "misleading_classification_certainty"), 
        flag = "green", critique = "", recommendation = "", stringsAsFactors = FALSE)
    setflag <- function(item, level, critique, recommendation) {
        idx <- flags$item == item
        flags$flag[idx] <<- level
        flags$critique[idx] <<- critique
        flags$recommendation[idx] <<- recommendation
    }
    if (id$events_per_parameter < min_events_per_parameter) {
        setflag("overparameterization", "red", "Too few detections per estimated parameter.", 
            "Reduce covariates/states or use a simpler HMM/constant-p robust design.")
    }
    if (id$singular_hessian) {
        setflag("singular_hessian", "red", "The Hessian is singular or nearly singular.", 
            "Do not report Hessian SEs without bootstrap/profile support.")
        setflag("weak_identifiability", "red", "Likelihood curvature is insufficient for stable inference.", 
            "Run profile likelihood and parameter recovery before manuscript claims.")
    }
    if (id$sparse_data) {
        setflag("sparse_data", "yellow", "Encounter histories are sparse relative to model complexity.", 
            "Prefer parsimonious detection and transition structures.")
    }
    if (id$boundary_estimate) {
        setflag("boundary_estimates", "yellow", "At least one parameter is on a boundary scale.", 
            "Check profiles and consider fixed/constrained transitions.")
    }
    trans <- fit$transition_matrix
    if (!is.null(trans) && any(trans < 0.02 | trans > 0.97999999999999998)) {
        setflag("unstable_transitions", "yellow", "Some transition probabilities are near 0 or 1.", 
            "Constrain biologically implausible transitions or increase data support.")
    }
    certainty <- if (!is.null(fit$decoded_states)) 
        mean(fit$decoded_states$state_probability, na.rm = TRUE)
    else NA_real_
    if (is.finite(certainty) && certainty > 0.94999999999999996 && 
        id$sparse_data) {
        setflag("misleading_classification_certainty", "yellow", 
            "State certainty is high despite sparse data.", "Report classification uncertainty and confusion-matrix validation.")
    }
    if ("effort" %in% names(fit$beta) && abs(fit$beta["effort"]) > 
        3) {
        setflag("p_availability_confounding", "yellow", "Detection covariate effect is very large and may absorb availability variation.", 
            "Compare against no-temporary-emigration and constant-p models.")
    }
    suitable <- !any(flags$flag == "red")
    list(flags = flags, suitable_for_publication_inference = suitable, 
        reviewer_style_critique = if (suitable) {
            "The model is provisionally defensible if assumptions and uncertainty diagnostics are reported."
        } else {
            "The fitted model is not yet suitable for publication-grade inference without simplification or stronger data support."
        }, recommended_simplifications = unique(flags$recommendation[flags$flag != 
            "green" & nzchar(flags$recommendation)]))
}
