robust_design_likelihood <-
function (par, rd_array, spec, transition_structure, detection_design, 
    estimate_transition = TRUE, fixed = list(), detection_offset = 0) 
{
    states <- spec$states
    K <- length(states)
    nbeta <- ncol(detection_design$X)
    beta <- par[seq_len(nbeta)]
    names(beta) <- colnames(detection_design$X)
    if (length(fixed)) {
        fixed_vec <- unlist(fixed)
        beta[names(fixed_vec)[names(fixed_vec) %in% names(beta)]] <- as.numeric(fixed_vec[names(fixed_vec) %in% 
            names(beta)])
    }
    pos <- nbeta + 1L
    if (estimate_transition) {
        ntrans <- transition_parameter_count(transition_structure)
        transition <- estimate_transition_matrix(par[pos:(pos + 
            ntrans - 1L)], transition_structure)
    }
    else {
        transition <- spec$transition_matrix
    }
    ll <- 0
    for (i in seq_len(dim(rd_array$y)[1])) {
        ll <- ll + forward_algorithm_robust_design(robust_design_individual_matrix(rd_array, 
            i), rd_array, spec$initial_probs, transition, detection_design, 
            beta, states, spec$unavailable_states, individual_index = i, 
            detection_offset = detection_offset)$logLik
    }
    list(logLik = ll, beta = beta, transition_matrix = transition)
}
robust_design_mixture_likelihood <-
function (par, rd_array, spec, transition_structure, design, 
    mixture_spec, estimate_transition = FALSE) 
{
    nbeta <- ncol(design$X)
    beta <- par[seq_len(nbeta)]
    names(beta) <- colnames(design$X)
    pos <- nbeta + 1L
    if (estimate_transition) {
        ntrans <- transition_parameter_count(transition_structure)
        transition <- estimate_transition_matrix(par[pos:(pos + 
            ntrans - 1L)], transition_structure)
        pos <- pos + ntrans
    }
    else {
        transition <- spec$transition_matrix
    }
    C <- mixture_spec$n_classes
    pi <- if (C > 1) 
        softmax(c(par[pos:(pos + C - 2)], 0))
    else 1
    pos <- pos + max(0, C - 1)
    offsets <- if (C > 1) 
        c(par[pos:(pos + C - 2)], 0)
    else 0
    ll <- 0
    for (i in seq_len(dim(rd_array$y)[1])) {
        cls <- numeric(C)
        for (cc in seq_len(C)) {
            cls[cc] <- forward_algorithm_robust_design(robust_design_individual_matrix(rd_array, 
                i), rd_array, spec$initial_probs, transition, 
                design, beta, spec$states, spec$unavailable_states, 
                i, detection_offset = offsets[cc])$logLik
        }
        m <- max(cls)
        ll <- ll + m + log(sum(pi * exp(cls - m)))
    }
    list(logLik = ll, beta = beta, transition_matrix = transition, 
        mixture_pi = pi, mixture_offsets = offsets)
}
robust_design_parameter_table <-
function (fit) 
{
    pa <- fit$primary_abundance %||% data.frame()
    if (!nrow(pa)) 
        return(data.frame(status = "no_primary_period_rows", 
            diagnostic_interpretation = "Robust-design fit did not store primary-period rows.", 
            stringsAsFactors = FALSE))
    rows <- list()
    for (i in seq_len(nrow(pa))) {
        rows[[length(rows) + 1L]] <- data.frame(model_name = fit$model_name, 
            parameter = "p_hat", parameter_type = "derived_real_detection", 
            index = as.character(pa$primary_period[i]), link_function = "real", 
            beta_estimate = NA_real_, beta_SE = NA_real_, beta_lower_95 = NA_real_, 
            beta_upper_95 = NA_real_, real_estimate = pa$p_hat[i], 
            real_SE = NA_real_, real_lower_95 = NA_real_, real_upper_95 = NA_real_, 
            fixed_or_estimated = "derived", boundary_flag = isTRUE(pa$p_hat[i] <= 
                0.02 || pa$p_hat[i] >= 0.97999999999999998), 
            identifiable_status = "derived from primary submodel", 
            uncertainty_method = "primary_period_submodel", uncertainty_status = "unavailable", 
            uncertainty_warning = "Primary-period detection parameters were derived from closed-capture submodels; beta-level uncertainty was not stored.", 
            biological_meaning = "Primary-period detection probability.", 
            result_interpretation = "Primary-period detection parameters were derived from closed-capture submodels.", 
            stringsAsFactors = FALSE)
        rows[[length(rows) + 1L]] <- data.frame(model_name = fit$model_name, 
            parameter = "availability_probability", parameter_type = "derived_real_availability", 
            index = as.character(pa$primary_period[i]), link_function = "real", 
            beta_estimate = NA_real_, beta_SE = NA_real_, beta_lower_95 = NA_real_, 
            beta_upper_95 = NA_real_, real_estimate = pa$availability_probability[i], 
            real_SE = NA_real_, real_lower_95 = NA_real_, real_upper_95 = NA_real_, 
            fixed_or_estimated = "derived", boundary_flag = FALSE, 
            identifiable_status = "derived", uncertainty_method = "primary_period_summary", 
            uncertainty_status = "not_applicable", uncertainty_warning = "", 
            biological_meaning = "Proportion of detected individuals available in the primary period.", 
            result_interpretation = "No free beta parameters were stored, but derived real parameters are available below.", 
            stringsAsFactors = FALSE)
    }
    do.call(rbind, rows)
}
