robust_design_structure_check <-
function (history, occasions = NULL) 
{
    y <- extract_history(history, stage = "robust-design structure check")
    occ <- occasions %||% extract_occasions(history, stage = "robust-design structure check")
    primary <- occ$primary %||% occ$primary_period %||% occ$month %||% 
        rep(1L, ncol(y))
    counts <- table(primary)
    has_secondary <- length(counts) >= 2L && any(counts >= 2L)
    status <- if (has_secondary) 
        "pass"
    else "fail"
    data.frame(assumption = "robust_design_structure", diagnostic_value = paste0("primary_periods=", 
        length(counts), "; max_secondary=", if (length(counts)) 
            max(counts)
        else 0), status = status, consequence = "Robust-design abundance needs repeated secondary occasions inside primary periods.", 
        recommendation = if (status == "pass") 
            "Robust-design models may be considered."
        else "Do not recommend robust-design abundance without secondary occasions.", 
        stringsAsFactors = FALSE)
}
