robust_literature_comparison_table <-
function (fit, literature_classifications = NULL, history = NULL, 
    occasion_table = NULL) 
{
    if (is.null(literature_classifications)) {
        history <- history %||% fit$history
        occasion_table <- occasion_table %||% fit$occasion_table
        literature_classifications <- literature_classification_table(history, 
            occasion_table)
    }
    decoded <- fit$decoded_states
    out <- merge(decoded, literature_classifications, by = "id", 
        all.x = TRUE, sort = FALSE)
    attr(out, "interpretation") <- paste("robust_design_state is shown in the state column.", 
        "The literature columns are rule-based classifications repeated for each primary period of the same individual.", 
        "Differences between columns are expected because the robust-design model accounts for missed detections, while literature rules mainly summarize observed detections.", 
        "Use this table for comparison, not as proof that one definition is universally correct.")
    out
}
route_selected_model <-
function (analysis, selected, input_provider = NULL, ...) 
{
    model <- if (is.data.frame(selected)) 
        selected$candidate_model[1]
    else as.character(selected)[1]
    if (identical(model, "CJS_like")) {
        cat("CJS_like has been standardized to CJS.\n")
        model <- "CJS"
    }
    if (requires_temporal_structure(model)) 
        analysis <- temporal_model_gate(analysis = analysis, 
            model = model, input_provider = input_provider)$analysis
    if (identical(model, "CJS")) {
        fit <- fit_cjs_model(extract_history(analysis), extract_occasions(analysis), 
            temporal_structure = analysis$temporal_structure, 
            data_type = analysis$data_type %||% "empirical", 
            ...)
        analysis$survival_detection_fit <- fit
        print_cjs_interpretation(fit)
        return(analysis)
    }
    .resident_v093_route_selected_model(analysis, if (is.data.frame(selected)) 
        selected
    else model, ...)
}
