}
run_dolphin_validation_suite <-
function (scenarios = dolphin_simulation_scenarios(), replicates = 2, 
    seed = 1, maxit = 150) 
{
    rows <- list()
    n <- 1L
    for (s in seq_len(nrow(scenarios))) {
        for (r in seq_len(replicates)) {
            occ <- make_robust_design(make_occasion_table(n_occasions = scenarios$n_primary[s] * 
                scenarios$secondary[s]), primary = "month")
            occ$primary_period <- rep(seq_len(scenarios$n_primary[s]), 
                each = scenarios$secondary[s])
            occ$secondary_period <- ave(occ$occasion, occ$primary_period, 
                FUN = seq_along)
            spec <- state_space_specification()
            beta <- c(`(Intercept)` = scenarios$intercept[s], 
                effort = scenarios$effort_beta[s])
            sim <- simulate_state_space_cr(scenarios$N[s], occ, 
                spec, beta, individual_re_sd = scenarios$heterogeneity_sd[s], 
                seed = seed + 100 * s + r)
            fit <- fit_robust_design_cr(sim$observed, sim$occasions, 
                spec, estimate_transition = FALSE, maxit = maxit, 
                hessian = TRUE)
            rows[[n]] <- data.frame(scenario = scenarios$scenario[s], 
                replicate = r, true_intercept = beta["(Intercept)"], 
                est_intercept = fit$beta["(Intercept)"], true_effort = beta["effort"], 
                est_effort = fit$beta["effort"], convergence = fit$convergence, 
                singular_hessian = fit$identifiability$singular_hessian, 
                sparse_data = fit$identifiability$sparse_data, 
                classification_accuracy = classification_accuracy_from_fit(fit, 
                  sim), stringsAsFactors = FALSE)
            n <- n + 1L
        }
    }
    out <- do.call(rbind, rows)
    list(results = out, summary = summarize_dolphin_validation(out))
}
run_dolphin_validation_suite_tmb <-
function (scenarios = dolphin_simulation_scenarios(), replicates = 2, 
    seed = 1, maxit = 150, progress = TRUE) 
{
    rows <- list()
    n <- 1L
    for (s in seq_len(nrow(scenarios))) for (r in seq_len(replicates)) {
        if (progress) 
            message("TMB dolphin scenario ", scenarios$scenario[s], 
                " replicate ", r)
        occ <- make_robust_design(make_occasion_table(n_occasions = scenarios$n_primary[s] * 
            scenarios$secondary[s]), primary = "month")
        occ$primary_period <- rep(seq_len(scenarios$n_primary[s]), 
            each = scenarios$secondary[s])
        occ$secondary_period <- ave(occ$occasion, occ$primary_period, 
            FUN = seq_along)
        spec <- state_space_specification()
        beta <- c(`(Intercept)` = scenarios$intercept[s], effort = scenarios$effort_beta[s])
        sim <- simulate_state_space_cr(scenarios$N[s], occ, spec, 
            beta, individual_re_sd = scenarios$heterogeneity_sd[s], 
            seed = seed + 100 * s + r)
        fit <- fit_robust_design_tmb(sim$observed, sim$occasions, 
            spec, estimate_transition = FALSE, maxit = maxit)
        rows[[n]] <- data.frame(scenario = scenarios$scenario[s], 
            replicate = r, true_intercept = beta["(Intercept)"], 
            est_intercept = fit$beta["(Intercept)"], true_effort = beta["effort"], 
            est_effort = fit$beta["effort"], convergence = fit$convergence %||% 
                NA_integer_, backend = fit$backend %||% "TMB", 
            warning = fit$tmb_status %||% "", stringsAsFactors = FALSE)
        n <- n + 1L
    }
    out <- do.call(rbind, rows)
    list(results = out, summary = summarize_dolphin_validation(out))
}
