run_id <-
function (name = NULL, time = Sys.time()) 
{
    stamp <- format(time, "%Y-%m-%d_%H%M%S")
    if (!is.null(name) && nzchar(name)) 
        paste0("run_", stamp, "_", gsub("[^A-Za-z0-9_-]+", "_", 
            name))
    else paste0("run_", stamp)
