run_identifiability_study <-
function (scenarios = NULL, seed = 1, maxit = 150) 
{
    if (is.null(scenarios)) {
        scenarios <- data.frame(N = c(20, 80), n_primary = c(3, 
            8), secondary = c(1, 4), label = c("known_sparse_nonidentifiable", 
            "moderate_dolphin"), stringsAsFactors = FALSE)
    }
    rows <- vector("list", nrow(scenarios))
    for (s in seq_len(nrow(scenarios))) {
        rec <- run_parameter_recovery_study(n_replicates = 2, 
            N = scenarios$N[s], n_primary = scenarios$n_primary[s], 
            secondary_per_primary = scenarios$secondary[s], seed = seed + 
                s, maxit = maxit)
        rows[[s]] <- data.frame(scenario = scenarios$label[s], 
            N = scenarios$N[s], n_primary = scenarios$n_primary[s], 
            secondary = scenarios$secondary[s], convergence_rate = rec$convergence_rate, 
            singular_hessian_rate = rec$singular_hessian_rate, 
            boundary_estimate_rate = rec$boundary_estimate_rate, 
            mean_abs_bias = mean(abs(rec$replicates$bias), na.rm = TRUE), 
            classification_accuracy = mean(rec$replicates$classification_accuracy, 
                na.rm = TRUE), stringsAsFactors = FALSE)
    }
    do.call(rbind, rows)
}
run_identifiability_study_tmb <-
function (scenarios = NULL, seed = 1, maxit = 150) 
{
    scenarios <- scenarios %||% data.frame(N = c(20, 80), n_primary = c(4, 
        8), secondary = c(2, 4), label = c("small_sparse", "moderate"), 
        stringsAsFactors = FALSE)
    rows <- lapply(seq_len(nrow(scenarios)), function(s) {
        rec <- run_parameter_recovery_study_tmb(n_replicates = 2, 
            N = scenarios$N[s], n_primary = scenarios$n_primary[s], 
            secondary_per_primary = scenarios$secondary[s], seed = seed + 
                s, maxit = maxit, progress = FALSE)
        data.frame(scenario = scenarios$label[s], N = scenarios$N[s], 
            n_primary = scenarios$n_primary[s], secondary = scenarios$secondary[s], 
            mean_abs_bias = mean(abs(rec$replicates$bias), na.rm = TRUE), 
            convergence_rate = mean(rec$replicates$convergence == 
                0, na.rm = TRUE), backend = paste(unique(rec$replicates$backend), 
                collapse = ","), warnings = paste(unique(rec$replicates$warning[nzchar(rec$replicates$warning)]), 
                collapse = " | "), stringsAsFactors = FALSE)
    })
    do.call(rbind, rows)
}
run_interactive_analysis_workflow <-
function (input_provider = NULL, post_run_menu = TRUE) 
{
