    print_adaptive_table(recommend_model_structure(imported$data), 
        title = "Model-structure recommendation", export_prefix = "model_structure_recommendation")
    analysis <- make_analysis_object(imported = imported)
    analysis <- resident_add_import_aliases(analysis)
    analysis <- initialize_analysis_run(analysis, analysis_name = "empirical")
