run_interactive_simulation_workflow <-
function (input_provider = NULL, questionnaire = ask_simulation_parameters, 
    simulation_runner = run_configured_simulation, post_run_menu = TRUE) 
{
    repeat {
        config <- questionnaire(interactive = TRUE, defaults = FALSE, 
            input_provider = input_provider)
        config <- validate_simulation_parameters(config)
        confirmed <- confirm_simulation_configuration(config, 
            input_provider = input_provider)
        if (isTRUE(confirmed)) {
            sim <- simulation_runner(config)
            assign("sim", sim, envir = .GlobalEnv)
            analysis <- make_analysis_object(sim = sim, config = config)
            analysis <- initialize_analysis_run(analysis, analysis_name = "simulation")
            assign("analysis", analysis, envir = .GlobalEnv)
            if (isTRUE(post_run_menu)) 
                guided_analysis_next_step_menu(analysis, input_provider = input_provider)
            return(invisible(sim))
        }
        if (identical(attr(confirmed, "action"), "exit")) {
            cat("Simulation cancelled before running.\n")
            return(invisible(list(status = "cancelled_before_simulation", 
                config = config)))
        }
        cat("Returning to parameter editing.\n")
    }
}
run_parameter_recovery_study <-
function (n_replicates = 5, N = 60, n_primary = 8, secondary_per_primary = 3, 
    beta = c(`(Intercept)` = -1, effort = 0.5), spec = state_space_specification(), 
    seed = 1, maxit = 200) 
{
    rows <- vector("list", n_replicates)
    for (r in seq_len(n_replicates)) {
        occ <- make_robust_design(make_occasion_table(n_occasions = n_primary * 
            secondary_per_primary), primary = "month")
        occ$primary_period <- rep(seq_len(n_primary), each = secondary_per_primary)
        occ$secondary_period <- ave(occ$occasion, occ$primary_period, 
            FUN = seq_along)
        sim <- simulate_state_space_cr(N, occ, spec, beta = beta, 
            seed = seed + r)
        fit <- fit_robust_design_cr(sim$observed, sim$occasions, 
            spec, estimate_transition = FALSE, maxit = maxit, 
            hessian = TRUE)
        common <- intersect(names(beta), names(fit$beta))
        rows[[r]] <- data.frame(replicate = r, parameter = common, 
            truth = beta[common], estimate = fit$beta[common], 
            bias = fit$beta[common] - beta[common], relative_bias = (fit$beta[common] - 
                beta[common])/pmax(abs(beta[common]), 1e-08), 
            convergence = fit$convergence, singular_hessian = fit$identifiability$singular_hessian, 
            boundary_estimate = fit$identifiability$boundary_estimate, 
            classification_accuracy = classification_accuracy_from_fit(fit, 
                sim), stringsAsFactors = FALSE)
    }
    out <- do.call(rbind, rows)
    list(replicates = out, summary = aggregate(cbind(bias, relative_bias) ~ 
        parameter, out, mean, na.rm = TRUE), convergence_rate = mean(out$convergence == 
        0), singular_hessian_rate = mean(out$singular_hessian), 
        boundary_estimate_rate = mean(out$boundary_estimate))
}
run_parameter_recovery_study_tmb <-
function (n_replicates = 5, N = 60, n_primary = 8, secondary_per_primary = 3, 
    beta = c(`(Intercept)` = -1, effort = 0.5), spec = state_space_specification(), 
    seed = 1, maxit = 200, store_fits = FALSE, progress = TRUE) 
{
    rows <- vector("list", n_replicates)
    fits <- if (store_fits) 
        vector("list", n_replicates)
    else NULL
    for (r in seq_len(n_replicates)) {
        if (progress) 
            message("TMB recovery replicate ", r, "/", n_replicates)
        t0 <- proc.time()[["elapsed"]]
        occ <- make_robust_design(make_occasion_table(n_occasions = n_primary * 
            secondary_per_primary), primary = "month")
        occ$primary_period <- rep(seq_len(n_primary), each = secondary_per_primary)
        occ$secondary_period <- ave(occ$occasion, occ$primary_period, 
            FUN = seq_along)
        sim <- simulate_state_space_cr(N, occ, spec, beta = beta, 
            seed = seed + r)
        fit <- fit_robust_design_tmb(sim$observed, sim$occasions, 
            spec, estimate_transition = FALSE, maxit = maxit)
        if (store_fits) 
            fits[[r]] <- fit
        common <- intersect(names(beta), names(fit$beta))
        rows[[r]] <- data.frame(replicate = r, runtime_sec = proc.time()[["elapsed"]] - 
            t0, parameter = common, truth = beta[common], estimate = fit$beta[common], 
            bias = fit$beta[common] - beta[common], convergence = fit$convergence %||% 
                NA_integer_, backend = fit$backend %||% "TMB", 
            warning = fit$tmb_status %||% "", stringsAsFactors = FALSE)
    }
    out <- do.call(rbind, rows)
    list(replicates = out, summary = aggregate(cbind(bias = bias) ~ 
        parameter, out, mean, na.rm = TRUE), fits = fits)
}
run_power_analysis <-
function (N_values = c(30, 60, 120), n_replicates = 3, ...) 
{
    rows <- lapply(N_values, function(N) {
        rec <- run_parameter_recovery_study(N = N, n_replicates = n_replicates, 
            ...)
        data.frame(N = N, convergence_rate = rec$convergence_rate, 
            mean_abs_bias = mean(abs(rec$replicates$bias), na.rm = TRUE), 
            classification_accuracy = mean(rec$replicates$classification_accuracy, 
                na.rm = TRUE))
    })
    do.call(rbind, rows)
}
