run_resident_pipeline <-
function (model = c("closed", "jolly_seber"), sim_args = list(), 
    sampling = list(method = "daily"), resident_threshold = 0.5, 
    truth_mode = "availability", seed = NULL) 
{
    model <- match.arg(model)
    sim_args$seed <- sim_args$seed %||% seed
    sim <- if (model == "closed") {
        do.call(simulate_closed_population, sim_args)
    }
    else {
        do.call(simulate_js_open_population, sim_args)
    }
    schedule <- do.call(sampling_schedule, c(list(occasion_table = sim$occasions), 
        sampling))
    observed_sampled <- subset_history(sim$observed, schedule)
    true_sampled <- if (!is.null(sim$true_alive)) 
        subset_history(sim$true_alive, schedule)
    else NULL
    indices <- classify_rsf_indices(observed_sampled, schedule)
    pop <- population_summary(observed_sampled, schedule, true_sampled)
    truth <- truth_labels(sim, schedule, resident_threshold, 
        truth_mode)
    list(model = model, parameters = sim$parameters, sampling = sampling, 
        simulation = sim, schedule = schedule, observed = observed_sampled, 
        true_alive = true_sampled, indices = indices, population_summary = pop, 
        truth = truth, conway_validation = compare_classification(indices, 
            truth, "conway_general"))
}
run_sensitivity_grid <-
function (grid, model = c("closed", "jolly_seber"), sampling_methods = list(list(method = "daily")), 
    replicates = 1, seed = 1, store_fits = FALSE, classification_column = "conway_general") 
{
    model <- match.arg(model)
    scenarios <- expand.grid(grid, stringsAsFactors = FALSE)
    results <- list()
    k <- 1L
    for (s in seq_len(nrow(scenarios))) {
        for (r in seq_len(replicates)) {
            for (sampling in sampling_methods) {
                args <- as.list(scenarios[s, , drop = FALSE])
                args$seed <- seed + k
                fit <- run_resident_pipeline(model = model, sim_args = args, 
                  sampling = sampling, seed = seed + k)
                summary <- summarize_pipeline_result(fit, classification_column)
                scenario_values <- scenarios[s, , drop = FALSE]
                summary <- cbind(data.frame(scenario = s, replicate = r, 
                  stringsAsFactors = FALSE), scenario_values, 
                  summary)
                results[[k]] <- list(scenario = s, replicate = r, 
                  sampling_method = sampling$method, args = args, 
                  summary = summary, fit = if (store_fits) fit else NULL)
                k <- k + 1L
            }
        }
    }
    attr(results, "summary_table") <- do.call(rbind, lapply(results, 
        `[[`, "summary"))
    attr(results, "uncertainty_summary") <- uncertainty_summary(attr(results, 
        "summary_table"), group_cols = c("scenario", "model", 
        "sampling_method"))
    results
}
run_transition_matrix_sensitivity <-
function (base_config, matrices = NULL, simulation_runner = run_configured_simulation, 
    ...) 
{
    if (is.null(matrices)) {
        matrices <- transition_matrix_sensitivity_set(states = base_config$states %||% 
            default_residency_states(), transition_time_scale = base_config$transition_time_scale %||% 
            "month")
    }
    rows <- list()
    outputs <- list()
    for (nm in names(matrices)) {
        cfg <- base_config
        cfg$transition_matrix <- matrices[[nm]]
        cfg$transition_time_scale <- attr(matrices[[nm]], "transition_time_scale") %||% 
            cfg$transition_time_scale %||% "month"
        cfg$transition_matrix_type <- attr(matrices[[nm]], "matrix_type") %||% 
            nm
        result <- tryCatch(simulation_runner(cfg, ...), error = function(e) e)
        outputs[[nm]] <- result
        rows[[length(rows) + 1L]] <- data.frame(matrix_name = nm, 
            transition_time_scale = cfg$transition_time_scale, 
            matrix_type = cfg$transition_matrix_type, ok = !inherits(result, 
                "error"), message = if (inherits(result, "error")) 
                conditionMessage(result)
            else "completed", stringsAsFactors = FALSE)
    }
    structure(list(summary = do.call(rbind, rows), results = outputs, 
        matrices = matrices), class = "transition_matrix_sensitivity")
}
run_transition_parameter_recovery <-
function (replicates = 3, N = 80, n_occasions = 30, p = 0.34999999999999998, 
    transition_matrix = default_transition_matrix(), transition_estimation = "estimate_full", 
    maxit = 200, seed = 1) 
{
    rows <- list()
    for (b in seq_len(replicates)) {
        sim <- simulate_with_known_transition_matrix(N, n_occasions, 
            transition_matrix, p, seed + b)
        occ <- sim$occasions
        spec <- state_space_specification(states = rownames(transition_matrix), 
            unavailable_states = rownames(transition_matrix)[1], 
            transition_matrix = transition_matrix)
        fit <- tryCatch(fit_transition_model_base(sim$observed, 
            occ, spec, transition_estimation = transition_estimation, 
            maxit = maxit, hessian = TRUE), error = function(e) e)
        if (inherits(fit, "error")) {
            rows[[length(rows) + 1L]] <- data.frame(replicate = b, 
                from_state = NA, to_state = NA, true = NA_real_, 
                estimate = NA_real_, bias = NA_real_, relative_bias = NA_real_, 
                squared_error = NA_real_, covered = NA, convergence = NA, 
                on_boundary = NA, identifiable_status = "fit_failed", 
                stringsAsFactors = FALSE)
        }
        else {
            tab <- transition_estimate_table(fit)
            true_long <- transition_estimate_table(list(transition_matrix = transition_matrix, 
                states = rownames(transition_matrix), transition_estimation = "fixed"))
            key <- paste(tab$from_state, tab$to_state)
            hit <- match(key, paste(true_long$from_state, true_long$to_state))
            rows[[length(rows) + 1L]] <- data.frame(replicate = b, 
                from_state = tab$from_state, to_state = tab$to_state, 
                true = true_long$estimate[hit], estimate = tab$estimate, 
                bias = tab$estimate - true_long$estimate[hit], 
                relative_bias = (tab$estimate - true_long$estimate[hit])/pmax(1e-08, 
                  true_long$estimate[hit]), squared_error = (tab$estimate - 
                  true_long$estimate[hit])^2, covered = ifelse(is.finite(tab$lower_95), 
                  tab$lower_95 <= true_long$estimate[hit] & tab$upper_95 >= 
                    true_long$estimate[hit], NA), convergence = fit$convergence, 
                on_boundary = tab$on_boundary, identifiable_status = tab$identifiable_status, 
                stringsAsFactors = FALSE)
        }
    }
    out <- do.call(rbind, rows)
    structure(out, class = c("transition_parameter_recovery", 
        class(out)))
}
