safe_capture_recapture_table_from_analysis <-
function (analysis) 
{
    history <- tryCatch(extract_history(analysis, stage = "capture-recapture table"), 
        error = function(e) NULL)
    if (is.null(history) && !is.null(analysis$observed)) 
        history <- analysis$observed
    if (is.null(history) && !is.null(analysis$encounter_data$history)) 
        history <- analysis$encounter_data$history
    if (is.null(history) && !is.null(analysis$data$history)) 
        history <- analysis$data$history
    if (is.null(history) && !is.null(analysis$sim$observed)) 
        history <- analysis$sim$observed
    if (is.null(history)) 
        stop("No capture-recapture table is available in this analysis object.", 
            call. = FALSE)
    history <- coerce_history_matrix(history, stage = "capture-recapture table")
    tab <- as.data.frame(history, check.names = FALSE, stringsAsFactors = FALSE)
    ids <- rownames(history)
    if (is.null(ids) || any(!nzchar(ids))) 
        ids <- paste0("Subject_", sprintf("%03d", seq_len(nrow(tab))))
    data.frame(individual_id = ids, tab, check.names = FALSE, 
        stringsAsFactors = FALSE)
}
