safe_detection_review_from_analysis <-
function (analysis) 
{
    tab <- safe_capture_recapture_table_from_analysis(analysis)
    mat <- as.matrix(tab[, setdiff(names(tab), "individual_id"), 
        drop = FALSE])
    suppressWarnings(storage.mode(mat) <- "numeric")
    mat[is.na(mat)] <- 0
    detections_by_individual <- rowSums(mat, na.rm = TRUE)
    detections_by_occasion <- colSums(mat, na.rm = TRUE)
    diag <- abundance_data_diagnostics(analysis)
    summary <- data.frame(number_of_individuals = nrow(mat), 
        number_of_sampling_occasions = ncol(mat), total_detection_records = sum(mat, 
            na.rm = TRUE), overall_detection_rate = round(mean(mat == 
            1, na.rm = TRUE), 3), recaptured_individuals = sum(detections_by_individual >= 
            2), individuals_detected_once = sum(detections_by_individual == 
            1), occasions_with_no_detections = sum(detections_by_occasion == 
            0), interpretation = "A zero means not detected, not necessarily absent. This review screens whether detection histories support population-parameter models and identifies likely bias when assumptions are weak.", 
        stringsAsFactors = FALSE)
    audit <- build_model_assumption_audit(analysis)
    model_recommendations <- rank_model_recommendations_for_assumption_review(analysis)
    recommended_summary <- recommended_model_selection_summary(model_recommendations)
    analysis$detection_assumption_review <- summary
    analysis$model_assumption_audit <- audit
    analysis$model_assumption_recommendation <- model_recommendations
    analysis$model_assumption_recommended_models <- recommended_summary
    analysis$abundance_recommendation <- list(recommendation_table = model_recommendations, 
        recommended_models = recommended_summary, diagnostics = diag, 
        source = "v0.9.36_detection_review_assumption_audit")
    cat("\nModel-assumption and detection review\n")
    cat("=====================================\n")
    cat("This is the recommended checkpoint after reviewing the capture table and discovery summary, before computing residency/site-fidelity classifications or fitting population models.\n")
    print_console_table(summary, title = "Observed detection summary", 
        export_prefix = "detection_assumption_review")
    print_model_assumption_audit_list(audit)
    print_recommended_model_selection_summary(recommended_summary)
    print_abundance_model_detail_list(model_recommendations, 
        title = "Candidate population-parameter models ranked by current data support")
    invisible(analysis)
}
