safe_literature_comparison_table <-
function (analysis) 
{
    tab <- resident_data_frame_or_null(analysis$model_literature_comparison, 
        analysis$literature_comparison, analysis$model_vs_literature)
    if (!is.null(tab)) 
        return(tab)
    model_tab <- safe_residency_result_table(analysis)
    lit_tab <- safe_individual_residency_table(analysis)
    if (is.null(model_tab) || is.null(lit_tab)) 
        return(NULL)
    id_col_model <- intersect(c("id", "individual_id"), names(model_tab))[1]
    id_col_lit <- intersect(c("id", "individual_id"), names(lit_tab))[1]
    if (is.na(id_col_model) || is.na(id_col_lit)) 
        return(NULL)
    merged <- merge(model_tab, lit_tab, by.x = id_col_model, 
        by.y = id_col_lit, all = TRUE, suffixes = c("_model", 
            "_literature"))
    merged$result_interpretation <- "Rows compare fitted model-based residency-state outputs with literature-based classifications for the same individuals."
    merged
}
