safe_model_matrix <-
function (formula, data) 
{
    vars <- all.vars(formula)
    missing <- setdiff(vars, names(data))
    if (length(missing)) {
        formula <- ~1
    }
    else {
        for (v in vars) {
            if (all(is.na(data[[v]]))) 
                formula <- ~1
        }
    }
    mm <- stats::model.matrix(formula, data = data, na.action = stats::na.pass)
    mm[!is.finite(mm)] <- 0
    mm
}
