safe_plot_wrapper <-
function (data, x, y, plot_fun, group = NULL, likely_cause = NULL, 
    suggested_action = NULL) 
{
    chk <- validate_plot_data(data, x, y, group)
    if (!isTRUE(chk$ok)) {
        msg <- plot_error_context(chk$reason, likely_cause, suggested_action)
        cat(msg, "\n")
        return(invisible(list(ok = FALSE, message = msg)))
    }
    tryCatch({
        plot_fun(data)
        invisible(list(ok = TRUE, data = data))
    }, error = function(e) {
        msg <- plot_error_context(conditionMessage(e), likely_cause, 
            suggested_action)
        cat(msg, "\n")
        invisible(list(ok = FALSE, message = msg))
    })
}
