safe_select_and_fit_abundance_model <-
function (analysis, input_provider = NULL) 
{
    analysis <- safe_show_abundance_model_recommendation(analysis)
    models <- implemented_abundance_models()
    models <- models[!is.na(models)]
    cat("\nSelectable abundance models\n")
    for (i in seq_along(models)) cat(sprintf("%2d. %s\n", i, 
        models[i]))
    cat(" 0. Return without fitting\n")
    ans <- .resident_prompt("Enter abundance model number or name: ", 
        input_provider)
    key <- trimws(as.character(ans))
    if (!nzchar(key) || key == "0") {
        analysis$last_fit_status <- list(status = "cancelled", 
            reason = "User returned without selecting a model.")
        assign("analysis", analysis, envir = .GlobalEnv)
        return(analysis)
    }
    model <- if (grepl("^[0-9]+$", key) && as.integer(key) >= 
        1L && as.integer(key) <= length(models)) 
        models[as.integer(key)]
    else key
    if (!model %in% models) {
        cat("Model was not selected because it is not an implemented abundance model: ", 
            model, "\n", sep = "")
        analysis$last_fit_status <- list(status = "invalid_model", 
            model = model)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(analysis)
    }
    report <- print_selected_model_assumption_report(analysis, 
        model, title = "Selected model suitability before fitting")
    label <- if (!is.null(report) && nrow(report)) 
        report$display_suitability[1]
    else "not_assessed"
    if (!model_selection_allowed_without_warning(label)) {
        cat("\nWarning: this model is not recommended for the current data diagnostics.\n")
        cat("The software will still create a fitted or diagnostic result so option 23 can report what was produced. Interpret results with the assumption warnings above.\n")
    }
    analysis <- tryCatch({
        if (requires_temporal_structure(model)) {
            gate <- temporal_model_gate(analysis = analysis, 
                model = model, input_provider = input_provider, 
                data_type = analysis$data_type %||% "empirical")
            analysis <- gate$analysis
        }
        fit <- direct_abundance_fit(analysis, model)
        analysis$abundance_fit <- fit
        analysis$fitted_model <- fit
        analysis$model_fit <- fit
        analysis$model_results <- fit$estimates
        analysis$abundance_model_choice <- list(candidate_model = model, 
            source = "direct_v0.9.14", suitability = label)
        analysis$last_fit_status <- list(status = "fit_stored", 
            model = model, storage = c("analysis$abundance_fit", 
                "analysis$fitted_model", "analysis$model_fit", 
                "analysis$model_results"))
        assign("analysis", analysis, envir = .GlobalEnv)
        print_direct_abundance_fit(fit)
        analysis
    }, error = function(e) {
        cat("\nFit failed for selected model: ", model, "\n", 
            sep = "")
        cat("Reason reported by fitting function: ", conditionMessage(e), 
            "\n", sep = "")
        print_selected_model_assumption_report(analysis, model, 
            title = "Why this model may have failed")
        analysis$last_fit_status <- list(status = "fit_failed", 
            model = model, error = conditionMessage(e))
        assign("analysis", analysis, envir = .GlobalEnv)
        cat("Guidance: choose a model classified as recommended, useful_baseline, or acceptable_with_caution, or simplify the model/data structure before fitting.\n")
        analysis
    })
    analysis
}
