sampling_schedule <-
function (occasion_table, method = "daily", n = NULL, seed = NULL, 
    empirical_dates = NULL) 
{
    if (!is.null(seed)) 
        set.seed(seed)
    method <- tolower(method)
    dates <- occasion_table$date
    selected <- integer(0)
    choose_one <- function(idx) sample(idx, 1)
    choose_n <- function(idx, n) sort(sample(idx, min(length(idx), 
        n)))
    if (method %in% c("daily", "all", "all_dates")) {
        selected <- occasion_table$occasion
    }
    else if (method == "weekly") {
        week_id <- paste(format(dates, "%G"), format(dates, "%V"), 
            sep = "-")
        selected <- unlist(tapply(occasion_table$occasion, week_id, 
            choose_one))
    }
    else if (method == "monthly") {
        month_id <- format(dates, "%Y-%m")
        selected <- unlist(tapply(occasion_table$occasion, month_id, 
            choose_one))
    }
    else if (method == "twice_monthly") {
        month_id <- format(dates, "%Y-%m")
        selected <- unlist(tapply(occasion_table$occasion, month_id, 
            choose_n, n = 2))
    }
    else if (method == "consecutive_month") {
        if (is.null(n) || n < 1) 
            stop("consecutive_month requires n >= 1.")
        month_id <- format(dates, "%Y-%m")
        selected <- unlist(tapply(occasion_table$occasion, month_id, 
            function(idx) {
                if (length(idx) <= n) 
                  return(idx)
                start <- sample(seq_len(length(idx) - n + 1L), 
                  1)
                idx[start:(start + n - 1L)]
            }))
    }
    else if (method == "random") {
        if (is.null(n)) 
            stop("random sampling requires n.")
        selected <- sort(sample(occasion_table$occasion, min(n, 
            nrow(occasion_table))))
    }
    else if (method == "empirical") {
        if (is.null(empirical_dates)) 
            stop("empirical sampling requires empirical_dates.")
        empirical_dates <- as.Date(empirical_dates)
        selected <- occasion_table$occasion[occasion_table$date %in% 
            empirical_dates]
    }
    else {
        stop("Unknown sampling method: ", method)
    }
    selected <- sort(unique(as.integer(selected)))
    occasion_table[selected, , drop = FALSE]
}
