score_literature_classifier_suitability <-
function (analysis, tab) 
{
    meta <- literature_classifier_metadata()
    available <- intersect(meta$classifier_column, names(tab))
    if (!length(available)) 
        return(data.frame())
    diag <- primary_classifier_temporal_diagnostics(analysis, 
        tab)
    goal <- analysis_classification_goal(analysis)
    rows <- lapply(available, function(col) {
        info <- meta[match(col, meta$classifier_column), , drop = FALSE]
        score <- 0
        reasons <- character()
        if (goal == "site_fidelity") {
            if (grepl("site-fidelity|sighting-frequency", info$assessment_type, 
                ignore.case = TRUE)) {
                score <- score + 4
                reasons <- c(reasons, "matches the site-fidelity goal")
            }
            if (identical(col, "moller_category")) {
                score <- score + 2
                reasons <- c(reasons, "uses categorical temporal-use groups useful for site-fidelity comparison")
            }
            if (identical(col, "balmer_category")) {
                score <- score + 1
                reasons <- c(reasons, "Balmer is useful as a numerical sighting-frequency grouping, but not ideal as a named residency label")
            }
        }
        else if (goal == "simple") {
            if (identical(col, "conway_general")) {
                score <- score + 5
                reasons <- c(reasons, "simple to communicate")
            }
        }
        else {
            if (grepl("residency", info$assessment_type, ignore.case = TRUE)) {
                score <- score + 2
                reasons <- c(reasons, "matches the residency goal")
            }
            if (diag$has_monthly_support && col %in% c("chabanne_category", 
                "martin_category", "ananias_general")) {
                score <- score + 3
                reasons <- c(reasons, "uses monthly temporal structure supported by the data")
            }
            if (diag$has_seasonal_support && col %in% c("chabanne_category", 
                "conway_general", "dinis_category", "zolman_category", 
                "rosel_general")) {
                score <- score + 3
                reasons <- c(reasons, "uses seasonal temporal structure supported by the data")
            }
            if (diag$has_annual_support && col %in% c("dinis_category", 
                "martin_category", "conway_general", "rosel_general")) {
                score <- score + 2
                reasons <- c(reasons, "uses annual or multi-year structure supported by the data")
            }
        }
        if (isTRUE(diag$has_temporal_gaps) && identical(col, 
            "moller_category")) {
            score <- score + 3
            reasons <- c(reasons, "more tolerant fallback when temporal gaps are present")
        }
        if (identical(col, "balmer_category") && goal != "site_fidelity") {
            score <- score - 3
            reasons <- c(reasons, "numeric frequency class, not a named primary residency classifier")
        }
        if (!length(reasons)) 
            reasons <- "available but not the strongest match to the stated goal and temporal support"
        data.frame(classifier_column = col, classifier = info$classifier, 
            assessment_type = info$assessment_type, score = score, 
            reason = paste(unique(reasons), collapse = "; "), 
            classification_goal = goal, stringsAsFactors = FALSE)
    })
    out <- do.call(rbind, rows)
    fallback_order <- c("chabanne_category", "conway_general", 
        "zolman_category", "rosel_general", "diaz_category", 
        "ananias_general", "dinis_category", "martin_category", 
        "moller_category", "quintana_general", "balmer_category")
    out$fallback_rank <- match(out$classifier_column, fallback_order)
    out <- out[order(-out$score, out$fallback_rank), , drop = FALSE]
    rownames(out) <- NULL
    out
}
select_abundance_model_from_recommendation <-
function (analysis, input_provider = NULL, allow_auto = FALSE, 
    confirm_provider = input_provider) 
{
    rec <- get_last_abundance_recommendation(analysis)
    tab <- rec$recommendation_table
    if (!"row" %in% names(tab)) 
        tab$row <- seq_len(nrow(tab))
    print_compact_recommendation_table(tab)
    print_abundance_model_selection_prompt(rec)
    if (allow_auto && is.null(input_provider)) {
        selected <- tab[tab$selectable & tab$suitability %in% 
            c("recommended", "acceptable_with_caution"), , drop = FALSE]
        selected <- if (nrow(selected)) 
            selected[1, , drop = FALSE]
        else tab[tab$selectable, , drop = FALSE][1, , drop = FALSE]
    }
    else {
        repeat {
            ans <- .resident_prompt("Selection: ", input_provider)
            ans_trim <- trimws(as.character(ans))
            if (ans_trim == "0" || tolower(ans_trim) %in% c("return", 
                "back", "cancel", "exit")) 
                return(list(status = "cancelled", selected = NULL))
            selected <- if (grepl("^[0-9]+$", ans_trim)) 
                tab[tab$row == as.integer(ans_trim), , drop = FALSE]
            else tab[tolower(tab$candidate_model) == tolower(ans_trim), 
                , drop = FALSE]
            if (nrow(selected)) 
                break
            cat("Invalid model selection. Enter a row number, candidate model name, or 0 to return.\n")
        }
    }
    if (!nrow(selected) || !model_is_selectable(selected$candidate_model[1])) {
        cat("This model is not yet fully implemented or is not available for fitting in this workflow. Choose a selectable model or enter 0 to return.\n")
        return(list(status = "not_selectable", selected = selected))
    }
    if (identical(selected$suitability[1], "not_applicable")) {
        cat("Selected model is not applicable under current diagnostics.\n")
        ans <- .resident_prompt("Selected model is not applicable under current diagnostics. Type 1 to confirm fitting anyway, or 0 to return: ", 
            confirm_provider)
        if (!identical(trimws(as.character(ans)), "1")) 
            return(list(status = "cancelled", selected = selected))
    }
    else if (!(selected$suitability[1] %in% c("recommended", 
        "acceptable_with_caution"))) {
        cat("Warning: selected model is not recommended under current diagnostics.\n")
        ans <- .resident_prompt("Type 1 to confirm fitting this model, or 0 to return: ", 
            confirm_provider)
        if (!identical(trimws(as.character(ans)), "1")) 
            return(list(status = "cancelled", selected = selected))
    }
    print_selected_model_details(selected)
    list(status = "selected", selected = selected)
}
