show_import_format_examples <-
function (format = NULL) 
{
    fmt <- if (is.null(format)) 
        "ALL"
    else toupper(trimws(as.character(format)))
    examples <- resident_format_example_tables()
    cat("\nCapture-recapture import format examples\n")
    cat("=======================================\n")
    cat("In all formats, 1 means detected and 0 means not detected. A 0 does not prove the animal was absent; it means the animal was not detected during that sampling occasion.\n\n")
    if (fmt %in% c("ALL", "PROGRAM_MARK", "AUTO")) {
        cat("Program MARK-style encounter-history file\n")
        cat("Required columns: id, encounter_history. Optional column: frequency.\n")
        cat("Optional date line before the table: # dates: 2020-01-01 2020-01-07 2020-01-15\n")
        print_console_table(examples$PROGRAM_MARK, title = "Example PROGRAM_MARK table", 
            max_rows = nrow(examples$PROGRAM_MARK))
        cat("Meaning: each row is one individual. The encounter_history string gives detections across occasions. For example, 100100 means detected on occasions 1 and 4 only.\n\n")
    }
    if (fmt %in% c("ALL", "SOCPROG", "CSV_LONG", "AUTO")) {
        cat("SOCPROG-style long sighting file\n")
        cat("Required columns: id, date. Optional useful columns: group_id, site, area, effort, sex, age_class.\n")
        print_console_table(examples$SOCPROG, title = "Example SOCPROG table", 
            max_rows = nrow(examples$SOCPROG))
        cat("Meaning: each row is one sighting record. Resident converts these rows into an individual-by-occasion capture-history table. Duplicate id-date rows are treated as repeated records on the same occasion and are aggregated to detected = 1.\n\n")
    }
    if (fmt %in% c("ALL", "WIDE_CSV", "AUTO")) {
        cat("Wide CSV encounter-history file\n")
        cat("Required columns: one id column and one 0/1 column per sampling occasion. Date column names should be real dates when available.\n")
        print_console_table(examples$WIDE_CSV, title = "Example WIDE_CSV table", 
            max_rows = nrow(examples$WIDE_CSV))
        cat("Meaning: this is the matrix that most capture-recapture models use internally: rows are individuals, columns are occasions.\n\n")
    }
    if (fmt %in% c("ALL", "MARK_INP", "AUTO")) {
        cat("Original MARK .inp file\n")
        cat("Expected row pattern: /*individual_id*/010101 1; where the final number is the frequency.\n")
        print_console_table(examples$MARK_INP, title = "Example MARK_INP lines", 
            max_rows = nrow(examples$MARK_INP))
        cat("Meaning: this is a compact Program MARK input form. If no date companion file is supplied, Resident can analyze detections but must use synthetic occasion dates only for ordering.\n\n")
    }
    if (fmt %in% c("ALL", "EXCEL", "AUTO")) {
        cat("Excel workbook\n")
        cat("Excel import accepts a worksheet that looks like either the WIDE_CSV table or the SOCPROG table. It requires the optional readxl package.\n\n")
    }
    cat("Recommended next step: if you are unsure, choose option 3 so Resident can inspect the file before importing it.\n")
    invisible(examples)
}
