simulate_closed_population <-
function (N = 150, duration_days = 365, rmax = 73, start_date = Sys.Date(), 
    seed = NULL, keep_truth = TRUE, recapture_distribution = "gaussian", 
    recapture_params = list(), allow_zero = TRUE) 
{
    if (!is.null(seed)) 
        set.seed(seed)
    if (rmax < 1 || rmax > duration_days) {
        stop("rmax must be between 1 and duration_days.")
    }
    occasions <- make_occasion_table(start_date = start_date, 
        n_occasions = duration_days)
    observed <- matrix(0L, nrow = N, ncol = duration_days)
    recapture_target <- generate_recapture_counts(N = N, rmax = rmax, 
        distribution = recapture_distribution, params = recapture_params, 
        allow_zero = allow_zero)
    for (i in seq_len(N)) {
        if (recapture_target[i] > 0) {
            observed[i, sample(seq_len(duration_days), recapture_target[i])] <- 1L
        }
    }
    rownames(observed) <- paste0("Subject_", seq_len(N))
    colnames(observed) <- as.character(occasions$date)
    true_alive <- matrix(1L, nrow = N, ncol = duration_days, 
        dimnames = dimnames(observed))
    list(model = "closed", occasions = occasions, observed = observed, 
        true_alive = if (keep_truth) true_alive else NULL, entry_occasion = rep(1L, 
            N), recapture_target = recapture_target, parameters = list(N = N, 
            duration_days = duration_days, rmax = rmax, recapture_distribution = recapture_distribution, 
            recapture_params = recapture_params, allow_zero = allow_zero))
}
simulate_from_cjs_fit <-
function (fit, seed = NULL) 
{
    if (!is.null(seed)) 
        set.seed(seed)
    y <- fit$history
    matrix(rbinom(length(y), 1, rep(fit$p, each = nrow(y))), 
        nrow = nrow(y), dimnames = dimnames(y))
}
simulate_from_fit <-
function (fit, seed = NULL) 
{
    if (!is.null(seed)) 
        set.seed(seed)
    y <- fit$history
    if (is.null(y)) 
        stop("Bootstrap unavailable because this model lacks simulate/refit methods.", 
            call. = FALSE)
    if (inherits(fit, "resident_huggins_abundance_fit") || inherits(fit, 
        "resident_closed_abundance_fit")) {
        p <- mean(as.numeric(fit$p_hat), na.rm = TRUE)
        matrix(rbinom(length(y), 1, p), nrow = nrow(y), dimnames = dimnames(y))
    }
    else if (inherits(fit, "resident_cjs_fit")) {
        p <- mean(fit$p, na.rm = TRUE)
        matrix(rbinom(length(y), 1, p), nrow = nrow(y), dimnames = dimnames(y))
    }
    else stop("Bootstrap unavailable because this model lacks simulate/refit methods.", 
        call. = FALSE)
}
