simulate_js_open_population <-
function (N = 150, n_occasions = 365, p = 0.25, phi = 0.94999999999999996, 
    b = NULL, start_date = Sys.Date(), seed = NULL, drop_never_detected = FALSE) 
{
    if (!is.null(seed)) 
        set.seed(seed)
    occasions <- make_occasion_table(start_date = start_date, 
        n_occasions = n_occasions)
    b <- make_entry_probabilities(n_occasions, b)
    entry_counts <- as.vector(rmultinom(1, N, b))
    entry_occasion <- rep(seq_len(n_occasions), entry_counts)
    p_vec <- rep_len(p, n_occasions)
    phi_vec <- rep_len(phi, n_occasions - 1L)
    true_alive <- matrix(0L, nrow = N, ncol = n_occasions)
    detected <- matrix(0L, nrow = N, ncol = n_occasions)
    for (i in seq_len(N)) {
        true_alive[i, entry_occasion[i]] <- 1L
        if (entry_occasion[i] < n_occasions) {
            for (t in (entry_occasion[i] + 1L):n_occasions) {
                survived <- rbinom(1, 1, phi_vec[t - 1L])
                if (survived == 0L) 
                  break
                true_alive[i, t] <- 1L
            }
        }
        detected[i, ] <- rbinom(n_occasions, 1, p_vec)
    }
    observed <- true_alive * detected
    rownames(observed) <- rownames(true_alive) <- rownames(detected) <- paste0("Subject_", 
        seq_len(N))
    colnames(observed) <- colnames(true_alive) <- colnames(detected) <- as.character(occasions$date)
    keep <- rep(TRUE, N)
    if (drop_never_detected) 
        keep <- rowSums(observed) > 0
    list(model = "jolly_seber", occasions = occasions, observed = observed[keep, 
        , drop = FALSE], true_alive = true_alive[keep, , drop = FALSE], 
        detection_draw = detected[keep, , drop = FALSE], entry_occasion = entry_occasion[keep], 
        entry_counts = entry_counts, b = b, parameters = list(N = N, 
            n_occasions = n_occasions, p = p, phi = phi))
}
simulate_latent_residency_model <-
function (N = 100, n_occasions = 365, states = default_residency_states(), 
    initial_probs = NULL, transition_matrix = NULL, detection = NULL, 
    start_date = Sys.Date(), effort = NULL, effort_beta = 0, 
    individual_re_sd = 0, seed = NULL) 
{
    if (!is.null(seed)) 
        set.seed(seed)
    K <- length(states)
    if (is.null(initial_probs)) 
        initial_probs <- c(0.55000000000000004, 0.25, 0.14999999999999999, 
            0.050000000000000003)[seq_len(K)]
    initial_probs <- normalize_prob(initial_probs)
    if (is.null(transition_matrix)) 
        transition_matrix <- default_transition_matrix(states)
    transition_matrix <- validate_transition_matrix(transition_matrix, 
        states)
    detection <- state_detection_probabilities(states, detection)
    occasions <- make_occasion_table(start_date = start_date, 
        n_occasions = n_occasions)
    if (is.null(effort)) 
        effort <- occasions$effort
    z <- matrix(NA_integer_, nrow = N, ncol = n_occasions)
    y <- matrix(0L, nrow = N, ncol = n_occasions)
    p_it <- matrix(0, nrow = N, ncol = n_occasions)
    re <- stats::rnorm(N, mean = 0, sd = individual_re_sd)
    effort_scaled <- as.numeric(scale(effort))
    effort_scaled[!is.finite(effort_scaled)] <- 0
    for (i in seq_len(N)) {
        z[i, 1] <- sample(seq_len(K), 1, prob = initial_probs)
        if (n_occasions > 1) {
            for (t in 2:n_occasions) {
                z[i, t] <- sample(seq_len(K), 1, prob = transition_matrix[z[i, 
                  t - 1], ])
            }
        }
        for (t in seq_len(n_occasions)) {
            base_p <- detection[z[i, t]]
            if (base_p <= 0) {
                p_it[i, t] <- 0
            }
            else {
                eta <- logit(pmin(1 - 1e-08, pmax(1e-08, base_p))) + 
                  re[i] + effort_beta * effort_scaled[t]
                p_it[i, t] <- inv_logit(eta)
            }
            y[i, t] <- stats::rbinom(1, 1, p_it[i, t])
        }
    }
    rownames(y) <- rownames(z) <- rownames(p_it) <- paste0("Subject_", 
        seq_len(N))
    colnames(y) <- colnames(z) <- colnames(p_it) <- as.character(occasions$date)
    list(model = "latent_residency_hmm", states = states, occasions = occasions, 
        observed = y, latent_states = z, detection_probability = p_it, 
        initial_probs = initial_probs, transition_matrix = transition_matrix, 
        state_detection = detection, effort_beta = effort_beta, 
        individual_random_effect = re, parameters = list(N = N, 
            n_occasions = n_occasions))
}
simulate_state_space_cr <-
function (N = 100, occasion_table, spec = state_space_specification(), 
    beta = NULL, individual_re_sd = 0, finite_mixture = NULL, 
    individual_data = NULL, observation_data = NULL, seed = NULL) 
{
    if (!is.null(seed)) 
        set.seed(seed)
    states <- spec$states
    K <- length(states)
    Tn <- nrow(occasion_table)
    beta <- beta %||% c(`(Intercept)` = -1, effort = 0.5)
    z <- matrix(NA_integer_, N, Tn)
    y <- matrix(0L, N, Tn)
    p <- matrix(0, N, Tn)
    ids <- paste0("Subject_", seq_len(N))
    rownames(z) <- rownames(y) <- rownames(p) <- ids
    colnames(z) <- colnames(y) <- colnames(p) <- as.character(occasion_table$date)
    re <- stats::rnorm(N, 0, individual_re_sd)
    mix_class <- rep(1L, N)
    mix_offset <- rep(0, N)
    if (!is.null(finite_mixture)) {
        mix_class <- sample(seq_along(finite_mixture$pi), N, 
            TRUE, prob = finite_mixture$pi)
        mix_offset <- finite_mixture$offset[mix_class]
    }
    dummy_history <- matrix(0L, nrow = N, ncol = Tn, dimnames = list(ids, 
        colnames(y)))
    design <- state_detection_design(dummy_history, occasion_table, 
        states, spec$unavailable_states, spec$detection_formula, 
        individual_data, observation_data)
    X <- design$X
    beta_vec <- rep(0, ncol(X))
    names(beta_vec) <- colnames(X)
    beta_vec[intersect(names(beta), names(beta_vec))] <- beta[intersect(names(beta), 
        names(beta_vec))]
    eta_all <- as.vector(X %*% beta_vec)
    for (i in seq_len(N)) {
        z[i, 1] <- sample(seq_len(K), 1, prob = spec$initial_probs)
        if (Tn > 1) {
            for (t in 2:Tn) z[i, t] <- sample(seq_len(K), 1, 
                prob = spec$transition_matrix[z[i, t - 1], ])
        }
        for (t in seq_len(Tn)) {
            idx <- (i - 1L) * Tn + t
            if (states[z[i, t]] %in% spec$unavailable_states) {
                p[i, t] <- 0
            }
            else {
                p[i, t] <- inv_logit(eta_all[idx] + re[i] + mix_offset[i])
            }
            y[i, t] <- stats::rbinom(1, 1, p[i, t])
        }
    }
    list(model = "state_space_cr", spec = spec, occasions = occasion_table, 
        observed = y, latent_states = z, detection_probability = p, 
        beta = beta_vec, individual_random_effect = re, mixture_class = mix_class)
}
