simulation_study <-
function (n_replicates = 10, N = 80, n_occasions = 100, spec = state_space_specification(), 
    seed = 1, maxit = 200, store_fits = FALSE) 
{
    rows <- vector("list", n_replicates)
    fits <- if (store_fits) 
        vector("list", n_replicates)
    else NULL
    for (r in seq_len(n_replicates)) {
        occasions <- make_occasion_table(n_occasions = n_occasions)
        sim <- simulate_state_space_cr(N, occasions, spec, seed = seed + 
            r)
        fit <- fit_state_space_cr(sim$observed, sim$occasions, 
            spec, estimate_transition = FALSE, maxit = maxit, 
            hessian = FALSE)
        truth <- apply(sim$latent_states, 1, function(z) {
            tab <- table(factor(spec$states[z], levels = spec$states))
            names(tab)[which.max(tab)]
        })
        pred <- fit$classification$most_likely_state
        vm <- validation_metrics(truth, pred, positive = tail(spec$states, 
            1))
        beta_names <- intersect(names(sim$beta), names(fit$beta))
        bias <- mean(fit$beta[beta_names] - sim$beta[beta_names])
        rmse <- sqrt(mean((fit$beta[beta_names] - sim$beta[beta_names])^2))
        rows[[r]] <- data.frame(replicate = r, accuracy = vm$accuracy, 
            sensitivity = vm$sensitivity, specificity = vm$specificity, 
            precision = vm$precision, recall = vm$recall, beta_bias = bias, 
            beta_rmse = rmse, convergence = fit$convergence, 
            stringsAsFactors = FALSE)
        if (store_fits) 
            fits[[r]] <- fit
    }
    summary <- do.call(rbind, rows)
    list(replicate_summary = summary, aggregate = data.frame(metric = names(summary)[names(summary) != 
        "replicate"], mean = vapply(summary[names(summary) != 
        "replicate"], mean, numeric(1), na.rm = TRUE), sd = vapply(summary[names(summary) != 
        "replicate"], stats::sd, numeric(1), na.rm = TRUE), stringsAsFactors = FALSE), 
        fits = fits)
}
softmax <-
function (eta) 
{
    eta <- eta - max(eta)
    z <- exp(eta)
    z/sum(z)
}
softmax_row <-
function (eta) 
{
    eta <- as.numeric(eta)
    eta <- eta - max(eta)
    z <- exp(eta)
    z/sum(z)
}
