standardize_analysis_object <-
function (analysis, source = NULL) 
{
    ed <- if (!is.null(analysis$encounter_data)) {
        if (is_resident_encounter_data(analysis$encounter_data)) 
            analysis$encounter_data
        else as_resident_encounter_data(analysis$encounter_data$history, 
            analysis$encounter_data$occasions, raw = analysis$encounter_data, 
            source = source)
    }
    else {
        as_resident_encounter_data(extract_history(analysis, 
            stage = "standardize analysis object"), extract_occasions(analysis, 
            stage = "standardize analysis object"), raw = analysis, 
            source = source %||% "analysis")
    }
    analysis$encounter_data <- ed
    analysis$observed <- ed$history
    analysis$occasions <- ed$occasions
    analysis$history_source <- ed$source
    analysis$data_summary <- resident_encounter_data_summary(ed)
    analysis
}
