state_detection_design <-
function (history, occasion_table, states, unavailable_states = c("outside", 
    "unavailable"), detection_formula = ~effort, individual_data = NULL, 
    observation_data = NULL) 
{
    dat <- prepare_detection_data(history, occasion_table, individual_data, 
        observation_data)
    X <- safe_model_matrix(detection_formula, dat)
    list(data = dat, X = X, states = states, unavailable = states %in% 
        unavailable_states, formula = detection_formula)
}
state_detection_probabilities <-
function (states = default_residency_states(), detection = NULL) 
{
    K <- length(states)
    if (is.null(detection)) {
        detection <- c(unavailable = 0, visitor = 0.17999999999999999, 
            seasonal_resident = 0.34999999999999998, resident = 0.55000000000000004)
    }
    if (is.null(names(detection))) 
        names(detection) <- states[seq_along(detection)]
    out <- rep(0, K)
    names(out) <- states
    out[names(detection)] <- detection
    pmin(1 - 1e-08, pmax(0, out))
}
state_entropy <-
function (p) 
{
    p <- p[p > 0]
    -sum(p * log(p))
}
state_space_derived_parameter_table <-
function (fit) 
{
    if (!is.null(fit$error)) 
        return(data.frame(status = "not_fitted", diagnostic_interpretation = fit$error, 
            stringsAsFactors = FALSE))
    out <- tryCatch(derive_robust_design_parameters(fit), error = function(e) NULL)
    if (is.null(out)) 
        return(data.frame(status = "not_available", diagnostic_interpretation = "Derived state-space parameters could not be computed.", 
            stringsAsFactors = FALSE))
    if (is.data.frame(out)) 
        return(out)
    as.data.frame(out)
}
state_space_parameter_table <-
function (fit) 
{
    if (!is.null(fit$error)) 
        return(data.frame(status = "not_fitted", diagnostic_interpretation = fit$error, 
            stringsAsFactors = FALSE))
    tab <- tryCatch(parameter_table(fit), error = function(e) NULL)
    if (is.null(tab) || !nrow(tab)) {
        return(data.frame(parameter = "state_space_parameters", 
            estimate = NA_real_, standard_error = NA_real_, parameter_interpretation = "The state-space fit did not return a stable parameter table.", 
            stringsAsFactors = FALSE))
    }
    tab
}
state_space_specification <-
function (states = c("outside", "peripheral_user", "seasonal_resident", 
    "core_resident"), unavailable_states = c("outside", "unavailable"), 
    initial_probs = NULL, transition_matrix = NULL, detection_formula = ~effort, 
    transition_covariates = NULL, robust_primary = "season") 
{
    K <- length(states)
    if (is.null(initial_probs)) 
        initial_probs <- rep(1/K, K)
    initial_probs <- normalize_prob(initial_probs)
    names(initial_probs) <- states
    if (is.null(transition_matrix)) 
        transition_matrix <- default_transition_matrix(states)
    transition_matrix <- validate_transition_matrix(transition_matrix, 
        states)
    list(states = states, unavailable_states = intersect(unavailable_states, 
        states), available_states = setdiff(states, unavailable_states), 
        initial_probs = initial_probs, transition_matrix = transition_matrix, 
        detection_formula = detection_formula, transition_covariates = transition_covariates, 
        robust_primary = robust_primary)
}
