summarize_capture_data <-
function (imported) 
{
    if (is.null(imported$history)) 
        stop("Imported object does not contain a history matrix.")
    history <- as_binary_matrix(imported$history)
    if (nrow(history) < 1 || ncol(history) < 1) 
        stop("The capture-recapture history has no individuals or no sampling occasions.")
    occasions <- imported$occasions %||% make_occasion_table(n_occasions = ncol(history))
    captures <- rowSums(history, na.rm = TRUE)
    data.frame(initial_sampling_date = min(as.Date(occasions$date), 
        na.rm = TRUE), final_sampling_date = max(as.Date(occasions$date), 
        na.rm = TRUE), number_of_different_individuals = nrow(history), 
        number_of_sampling_occasions = ncol(history), minimum_capture_records_per_individual = min(captures), 
        maximum_capture_records_per_individual = max(captures), 
        total_capture_records = sum(history, na.rm = TRUE), interpretation_note = "A capture record means a detected individual on a sampling occasion. A zero means not detected, not necessarily absent.", 
        stringsAsFactors = FALSE)
}
