summarize_model_literature_agreement <-
function (comparison) 
{
    if (is.list(comparison) && !is.data.frame(comparison)) {
        comparison <- model_vs_literature_residency_comparison(comparison)
    }
    n <- nrow(comparison)
    prop <- function(cat) if (!n) 
        0
    else mean(comparison$agreement_category == cat, na.rm = TRUE)
    common <- names(sort(table(comparison$disagreement_type[comparison$disagreement_type != 
        ""]), decreasing = TRUE))[1] %||% ""
    data.frame(number_of_individuals_compared = n, percentage_strong_agreement = 100 * 
        prop("strong_agreement"), percentage_partial_agreement = 100 * 
        prop("partial_agreement"), percentage_conflicting = 100 * 
        mean(comparison$agreement_category %in% c("model_more_resident_than_metrics", 
            "metrics_more_resident_than_model", "conflicting_metrics"), 
            na.rm = TRUE), most_common_disagreement_type = common, 
        recommended_review_notes = "Review individuals with disagreement, sparse detections, low model confidence, or strong dependence on detection assumptions.", 
        interpretation = "Literature metrics are rule-based comparisons, not a gold standard.", 
        stringsAsFactors = FALSE)
}
summarize_pipeline_result <-
function (fit, classification_column = "conway_general") 
{
    validation <- compare_classification(fit$indices, fit$truth, 
        classification_column)
    idx <- fit$indices
    pop <- fit$population_summary
    classes <- sort(table(idx[[classification_column]]), decreasing = TRUE)
    data.frame(model = fit$model, sampling_method = fit$sampling$method %||% 
        NA_character_, n_individuals_output = nrow(fit$observed), 
        n_occasions_sampled = ncol(fit$observed), detected_individuals = sum(rowSums(fit$observed) > 
            0), final_discovered = max(pop$cumulative_individuals), 
        total_sightings = max(pop$cumulative_sightings), discovery_asymptotic = tail(pop$discovery_asymptotic, 
            1), plateau_length = tail(pop$plateau_length, 1), 
        mean_occurrence = mean(idx$occurrence, na.rm = TRUE), 
        median_occurrence = stats::median(idx$occurrence, na.rm = TRUE), 
        mean_permanence_days = mean(idx$permanence_days, na.rm = TRUE), 
        mean_interval_days = mean(idx$mean_interval_days, na.rm = TRUE), 
        resident_fraction = mean(tolower(as.character(idx[[classification_column]])) == 
            "resident", na.rm = TRUE), validation_accuracy = if (!is.null(validation)) 
            mean(validation$correct, na.rm = TRUE)
        else NA_real_, class_counts = paste(names(classes), as.integer(classes), 
            sep = "=", collapse = ";"), stringsAsFactors = FALSE)
}
summarize_random_effects <-
function (fit) 
{
    if (!identical(fit$backend, "TMB") || is.null(fit$sdreport)) {
        return(data.frame(component = character(0), estimate = numeric(0), 
            SE = numeric(0), lower_95_CI = numeric(0), upper_95_CI = numeric(0)))
    }
    s <- tryCatch(summary(fit$sdreport, "report"), error = function(e) NULL)
    if (is.null(s)) 
        return(data.frame())
    keep <- grepl("^sigma_", rownames(s))
    if (!any(keep)) 
        return(data.frame())
    est <- s[keep, "Estimate"]
    se <- s[keep, "Std. Error"]
    data.frame(component = rownames(s)[keep], estimate = est, 
        SE = se, lower_95_CI = est - 1.96 * se, upper_95_CI = est + 
            1.96 * se, stringsAsFactors = FALSE)
}
