summarize_transition_parameter_recovery <-
function (recovery) 
{
    ok <- recovery[is.finite(recovery$estimate), , drop = FALSE]
    if (!nrow(ok)) 
        return(data.frame(convergence_rate = 0, bias = NA_real_, 
            relative_bias = NA_real_, RMSE = NA_real_, root_mean_squared_error = NA_real_, 
            coverage = NA_real_, coverage_95 = NA_real_, boundary_rate = NA_real_, 
            identifiable_rate = NA_real_))
    rmse <- sqrt(mean(ok$squared_error, na.rm = TRUE))
    coverage <- mean(ok$covered, na.rm = TRUE)
    data.frame(convergence_rate = mean(ok$convergence == 0, na.rm = TRUE), 
        bias = mean(ok$bias, na.rm = TRUE), relative_bias = mean(ok$relative_bias, 
            na.rm = TRUE), RMSE = rmse, root_mean_squared_error = rmse, 
        coverage = coverage, coverage_95 = coverage, boundary_rate = mean(ok$on_boundary, 
            na.rm = TRUE), identifiable_rate = mean(ok$identifiable_status == 
            "estimable", na.rm = TRUE), stringsAsFactors = FALSE)
}
