synchronize_detection_formula_and_beta <-
function (config) 
{
    assumption <- config$detection_covariate_assumptions %||% 
        infer_detection_assumption_from_formula(config$detection_formula)
    use_state_detection <- assumption %in% c("state", "effort_plus_state", 
        "state_plus_individual_random_effect", "effort_plus_state_plus_individual_random_effect")
    required <- beta_terms_required_by_formula(config$detection_formula, 
        use_state_detection)
    beta <- config$beta
    if (is.null(beta) || is.null(names(beta))) 
        beta <- numeric()
    missing <- setdiff(required, names(beta))
    if (length(missing)) {
        defaults <- default_beta_for_detection_formula(config$detection_formula, 
            config$baseline_detection_probability %||% 0.25, 
            use_state_detection)
        beta <- c(beta, defaults[missing])
        config$validation_warnings <- unique(c(config$validation_warnings, 
            paste("Detection beta was missing required term(s):", 
                paste(missing, collapse = ", "), "Safe default values were inserted.")))
    }
    config$beta <- beta[unique(c(required, setdiff(names(beta), 
        required)))]
    config
}
