temporal_model_gate <-
function (analysis = NULL, history = NULL, occasions = NULL, 
    model = "model", input_provider = NULL, data_type = NULL, 
    temporal_structure = NULL, formulas = NULL) 
{
    if (!requires_temporal_structure(model, formulas = formulas)) 
        return(list(analysis = analysis, history = history, occasions = occasions, 
            temporal_structure = temporal_structure))
    y <- history %||% if (!is.null(analysis)) 
        extract_history(analysis, stage = "temporal gate")
    else NULL
    occ <- occasions %||% if (!is.null(analysis)) 
        tryCatch(extract_occasions(analysis, stage = "temporal gate"), 
            error = function(e) NULL)
    else NULL
    st <- ensure_temporal_structure(analysis, y, occ, model, 
        input_provider, data_type, temporal_structure)
    if (!is.null(occ)) {
        occ$primary_period <- st$primary_period
        occ$secondary_period <- st$secondary_period
    }
    if (!is.null(analysis)) {
        analysis$temporal_structure <- st
        if (!is.null(analysis$occasions)) 
            analysis$occasions <- occ
        if (!is.null(analysis$sim$occasions)) 
            analysis$sim$occasions <- occ
    }
    list(analysis = analysis, history = y, occasions = occ, temporal_structure = st)
}
temporal_structure_audit_report <-
function (analysis = NULL, model = NULL) 
{
    st <- analysis$temporal_structure %||% NULL
    if (is.null(st)) 
        return(data.frame(model = model %||% NA_character_, status = "missing", 
            source = NA_character_, confirmed = FALSE, stringsAsFactors = FALSE))
    data.frame(model = model %||% st$model_requiring_structure %||% 
        NA_character_, status = "available", source = temporal_structure_source(st), 
        confirmed = isTRUE(st$confirmed), confirmed_at = as.character(st$confirmed_at %||% 
            NA), stringsAsFactors = FALSE)
}
temporal_structure_diagnostics <-
function (history, occasions = NULL) 
{
    y <- coerce_history_matrix(history, stage = "temporal-structure diagnostics")
    if (is.null(occasions)) {
        return(data.frame(inferred_primary_periods = NA_character_, 
            inferred_secondary_periods = NA_character_, evidence_used = "No occasion table was supplied.", 
            inference_status = "failed", warnings = "Temporal structure cannot be inferred without occasion data.", 
            stringsAsFactors = FALSE))
    }
    occ <- as.data.frame(occasions)
    dates <- if ("date" %in% names(occ)) 
        as.Date(occ$date)
    else rep(as.Date(NA), nrow(occ))
    primary <- occ$primary_period %||% occ$primary %||% if (all(!is.na(dates))) 
        format(dates, "%Y-%m")
    else rep(NA_character_, nrow(occ))
    secondary <- occ$secondary_period %||% occ$secondary %||% 
        ave(seq_len(nrow(occ)), primary, FUN = seq_along)
    status <- if (all(!is.na(primary)) && length(unique(primary)) > 
        1L) 
        "usable"
    else "weak"
    data.frame(inferred_primary_periods = paste(unique(primary), 
        collapse = ", "), inferred_secondary_periods = paste(utils::head(secondary, 
        12), collapse = ", "), evidence_used = paste("occasion rows:", 
        nrow(occ), "history columns:", ncol(y), if (all(!is.na(dates))) 
            "valid dates present"
        else "valid dates absent"), inference_status = status, 
        warnings = if (identical(status, "usable")) 
            ""
        else "Only weak evidence was found; user confirmation is required.", 
        stringsAsFactors = FALSE)
}
