temporal_structure_required <-
function (model = NULL, formulas = NULL, time_varying = FALSE) 
{
    key <- tolower(as.character(model %||% ""))
    temporal_models <- tolower(c("robust_design_closed_primary", 
        "robust_design_huggins_primary", "state_space_robust_design", 
        "markovian_state", "multistate", "multistate/state-space", 
        "CJS", "jolly_seber", "POPAN_like", "jolly_seber_like", 
        "open_population", "robust_design"))
    formula_text <- paste(vapply(formulas %||% list(), function(f) paste(deparse(f), 
        collapse = ""), character(1)), collapse = " ")
    formula_temporal <- grepl("time|occasion|primary|secondary|Phi|pent|GammaPrime|GammaDoublePrime|transition|migration|state", 
        formula_text, ignore.case = TRUE)
    isTRUE(time_varying) || key %in% temporal_models || formula_temporal
}
