time_variation_check <-
function (history, occasions = NULL) 
{
    y <- extract_history(history, stage = "time variation check")
    detections <- colSums(y)
    cv <- if (mean(detections) > 0) 
        stats::sd(detections)/mean(detections)
    else NA_real_
    status <- if (is.na(cv)) 
        "fail"
    else if (cv < 0.75) 
        "pass"
    else "review"
    data.frame(assumption = "time_variation", diagnostic_value = paste0("occasion_detection_cv=", 
        round(cv, 3)), status = status, consequence = "Strong time variation can favor time-dependent detection models.", 
        recommendation = if (status == "review") 
            "Compare time-dependent detection models if data support them."
        else "No strong time-variation flag from this check.", 
        stringsAsFactors = FALSE)
}
