transition_boundary_diagnostics <-
function (transition_matrix, tol = 0.0001) 
{
    mat <- as.matrix(transition_matrix)
    data.frame(any_on_boundary = any(mat < tol | mat > 1 - tol), 
        min_probability = min(mat), max_probability = max(mat), 
        stringsAsFactors = FALSE)
}
transition_correlation_diagnostics <-
function (fit) 
{
    h <- fit$optim$hessian %||% NULL
    if (is.null(h)) 
        return(data.frame(max_abs_correlation = NA, warning = "Hessian unavailable", 
            stringsAsFactors = FALSE))
    inv <- tryCatch(solve(h), error = function(e) NULL)
    if (is.null(inv)) 
        return(data.frame(max_abs_correlation = NA, warning = "Hessian not invertible", 
            stringsAsFactors = FALSE))
    cor <- cov2cor(inv)
    diag(cor) <- 0
    data.frame(max_abs_correlation = max(abs(cor), na.rm = TRUE), 
        warning = if (max(abs(cor), na.rm = TRUE) > 0.94999999999999996) 
            "High parameter correlation."
        else "", stringsAsFactors = FALSE)
}
