        2), singletons = sum(detections_by_individual == 1), 
        sampling_occasions = ncol(h), stringsAsFactors = FALSE)
}
transition_estimate_table <-
function (fit, transition_time_scale = fit$transition_time_scale %||% 
    attr(fit$transition_matrix, "transition_time_scale") %||% 
    "month", legacy_names = FALSE) 
{
    mat <- as.matrix(fit$transition_matrix)
    states <- rownames(mat) %||% fit$states
    if (is.null(states)) 
        states <- seq_len(nrow(mat))
    fixed <- if (!is.null(fit$transition_structure)) 
        !fit$transition_structure$free
    else matrix(TRUE, nrow(mat), ncol(mat))
    if (!isTRUE(fit$estimate_transition) && (fit$transition_estimation %||% 
        "fixed") == "fixed") 
        fixed[, ] <- TRUE
    rows <- list()
    for (r in seq_len(nrow(mat))) {
        for (c in seq_len(ncol(mat))) {
            est <- mat[r, c]
            rows[[length(rows) + 1L]] <- data.frame(from_state = states[r], 
                to_state = states[c], estimate = est, SE = NA_real_, 
                lower_95 = NA_real_, upper_95 = NA_real_, fixed_or_estimated = if (fixed[r, 
                  c]) 
                  "fixed"
                else "estimated", fixed_by_model = fixed[r, c], 
                on_boundary = est < 0.0001 || est > 1 - 0.0001, 
                identifiable_status = if (fixed[r, c]) 
                  "fixed"
                else "estimable", backend = fit$backend %||% 
                  "base", transition_time_scale = transition_time_scale, 
                transition_interpretation = paste0("During one ", 
                  transition_time_scale, " transition step, this is the model ", 
                  if (fixed[r, c]) 
                    "assumption"
                  else "estimate", " for moving from ", states[r], 
                  " to ", states[c], "."), stringsAsFactors = FALSE)
        }
    }
    out <- do.call(rbind, rows)
    if (!is.null(fit$transition_sd_table)) {
        key <- paste(out$from_state, out$to_state)
        se_key <- paste(fit$transition_sd_table$from_state, fit$transition_sd_table$to_state)
        hit <- match(key, se_key)
        cols <- c("SE", "lower_95", "upper_95")
        for (col in cols) out[[col]] <- fit$transition_sd_table[[col]][hit]
    }
    if (isTRUE(legacy_names)) 
        out <- add_legacy_interpretation_names(out)
    out
}
transition_estimation_specification <-
function (transition_estimation = c("fixed", "estimate_full", 
    "estimate_diagonal_dominant", "estimate_adjacent", "estimate_custom_mask"), 
    states = default_residency_states(), fixed_matrix = NULL, 
    transition_free_mask = NULL) 
{
    transition_estimation <- match.arg(transition_estimation)
    states <- validate_state_vector(states)
    fixed_matrix <- fixed_matrix %||% default_transition_matrix(states)
    fixed_matrix <- validate_transition_matrix(fixed_matrix, 
        states)
    K <- length(states)
    if (transition_estimation == "fixed") {
        structure <- build_transition_structure(states, "fixed", 
            fixed_matrix = fixed_matrix)
    }
    else if (transition_estimation == "estimate_full") {
        structure <- build_transition_structure(states, "fully_estimated")
        structure$fixed <- fixed_matrix
    }
    else if (transition_estimation == "estimate_diagonal_dominant") {
        structure <- build_transition_structure(states, "diagonal_dominant")
        structure$fixed <- fixed_matrix
    }
    else if (transition_estimation == "estimate_adjacent") {
        free <- matrix(FALSE, K, K, dimnames = list(states, states))
        for (r in seq_len(K)) free[r, unique(pmax(1, pmin(K, 
            c(r - 1L, r, r + 1L))))] <- TRUE
        structure <- build_transition_structure(states, "partially_fixed", 
            fixed_matrix = fixed_matrix, free = free)
        structure$fixed[!free] <- pmax(structure$fixed[!free], 
            1e-08)
        structure$fixed <- sweep(structure$fixed, 1, rowSums(structure$fixed), 
            "/")
    }
    else {
        free <- validate_transition_free_mask(transition_free_mask, 
            states)
        structure <- build_transition_structure(states, "partially_fixed", 
            fixed_matrix = fixed_matrix, free = free)
    }
    structure$transition_estimation <- transition_estimation
    structure$parameter_labels <- transition_parameter_labels(structure)
    structure
}
transition_estimation_summary <-
function (fit, legacy_names = FALSE) 
{
    ts <- fit$transition_structure %||% transition_estimation_specification("fixed", 
        fit$states, fit$transition_matrix)
    tab <- transition_estimate_table(fit)
    hdiag <- transition_hessian_diagnostics(fit)
    out <- data.frame(transition_estimation = fit$transition_estimation %||% 
        ifelse(isTRUE(fit$estimate_transition), "estimate_full", 
            "fixed"), free_transition_parameters = transition_parameter_count(ts), 
        transition_free_parameter_count = transition_parameter_count(ts), 
        fixed_transition_cells = sum(tab$fixed_or_estimated == 
            "fixed"), hessian_positive_definite = hdiag$positive_definite, 
        any_boundary_estimates = any(tab$on_boundary), weak_identifiability = any(tab$identifiable_status %in% 
            c("weakly_estimable", "non_identifiable")), backend = fit$backend %||% 
            "base", recommendation = diagnose_transition_identifiability(fit)$recommendation, 
        reliability_warning = {
            warnings <- diagnose_transition_identifiability(fit)$warnings
            if (length(warnings)) 
                paste(warnings, collapse = "; ")
            else "No implemented transition-identifiability warning was triggered."
        }, result_interpretation = if (isTRUE(fit$estimate_transition)) {
            "The transition matrix was estimated from the encounter-history data. These values are model-based estimates of hidden state movement, not simple counts of sightings."
        }
        else {
            "The transition matrix was held fixed. These values are modelling assumptions used to interpret hidden state movement."
        }, stringsAsFactors = FALSE)
    if (isTRUE(legacy_names)) 
        out <- add_legacy_interpretation_names(out)
    out
}
transition_hessian_diagnostics <-
function (fit) 
{
    h <- fit$optim$hessian %||% NULL
    if (is.null(h)) 
        return(data.frame(hessian_available = FALSE, positive_definite = NA, 
            condition_number = NA, stringsAsFactors = FALSE))
    ev <- tryCatch(eigen(h, symmetric = TRUE, only.values = TRUE)$values, 
        error = function(e) NA_real_)
    pd <- all(is.finite(ev)) && min(ev) > 1e-08
    cn <- if (all(is.finite(ev)) && min(abs(ev)) > 0) 
        max(abs(ev))/min(abs(ev))
    else Inf
    data.frame(hessian_available = TRUE, positive_definite = pd, 
        condition_number = cn, stringsAsFactors = FALSE)
}
