transition_matrix_diagnostics <-
function (transition_matrix, transition_time_scale = attr(transition_matrix, 
    "transition_time_scale") %||% "month", matrix_type = attr(transition_matrix, 
    "matrix_type") %||% "custom") 
{
    transition_time_scale <- validate_transition_timescale(transition_time_scale)
    mat <- validate_transition_matrix(transition_matrix)
    diag_values <- diag(mat)
    warnings <- character()
    unavailable_to_resident <- mat[1, ncol(mat)]
    resident_to_unavailable <- mat[nrow(mat), 1]
    diagonal_dominant <- all(diag_values >= apply(mat, 1, max) - 
        9.9999999999999998e-13)
    if (transition_time_scale == "day" && any(diag_values < 0.94999999999999996)) {
        warnings <- c(warnings, "Daily transition matrices should usually have diagonal values of at least 0.95.")
    }
    if (transition_time_scale == "month" && mat[nrow(mat), ncol(mat)] < 
        0.69999999999999996) {
        warnings <- c(warnings, "Monthly resident-to-resident probability is below 0.70.")
    }
    if (transition_time_scale == "year" && all(diag_values > 
        0.94999999999999996)) {
        warnings <- c(warnings, "Yearly transition matrix has very high persistence in every state.")
    }
    if (unavailable_to_resident > 0.10000000000000001) {
        warnings <- c(warnings, "Direct unavailable-to-resident transition is greater than 0.10.")
    }
    if (resident_to_unavailable > 0.20000000000000001) {
        warnings <- c(warnings, "Resident-to-unavailable transition is greater than 0.20.")
    }
    if (matrix_type != "custom" && !diagonal_dominant) {
        warnings <- c(warnings, "Default matrix is not diagonal-dominant in every row.")
    }
    recommendation <- if (length(warnings)) {
        "Review the transition time scale, matrix values, and biological justification; run sensitivity analysis or use local estimates if available."
    }
    else {
        "No transition-matrix diagnostic warnings under the implemented rules."
    }
    data.frame(transition_time_scale = transition_time_scale, 
        min_diagonal = min(diag_values), max_diagonal = max(diag_values), 
        unavailable_to_resident = unavailable_to_resident, resident_to_unavailable = resident_to_unavailable, 
        diagonal_dominant = diagonal_dominant, warnings = if (length(warnings)) 
            paste(warnings, collapse = " | ")
        else "", recommendation = recommendation, stringsAsFactors = FALSE)
}
