transition_matrix_to_parameters <-
function (transition_matrix, transition_structure) 
{
    mat <- validate_transition_matrix(transition_matrix, transition_structure$states)
    free <- transition_structure$free
    pars <- numeric()
    for (r in seq_len(nrow(mat))) {
        free_cols <- which(free[r, ])
        if (length(free_cols) <= 1L) 
            next
        fixed_mass <- sum(transition_structure$fixed[r, !free[r, 
            ]])
        p_free <- mat[r, free_cols]/max(9.9999999999999998e-13, 
            1 - fixed_mass)
        pars <- c(pars, inverse_softmax_reference(p_free))
    }
    names(pars) <- transition_parameter_labels(transition_structure)
    pars
}
