transition_profile_confint <-
function (profile, level = 0.94999999999999996) 
{
    cutoff <- stats::qchisq(level, df = 1)
    keep <- profile$LR <= cutoff
    data.frame(from_state = profile$from_state[1], to_state = profile$to_state[1], 
        lower = if (any(keep)) 
            min(profile$value[keep])
        else NA_real_, upper = if (any(keep)) 
            max(profile$value[keep])
        else NA_real_, cutoff = cutoff, stringsAsFactors = FALSE)
}
transition_profile_estimated_confint <-
function (profile, cutoff = stats::qchisq(0.94999999999999996, 
    1)) 
{
    lr <- profile$likelihood_ratio_statistic
    ok <- is.finite(lr) & lr <= cutoff
    best_edge <- which.min(lr) %in% c(1L, length(lr))
    if (!any(ok) || best_edge) {
        return(data.frame(lower = NA_real_, upper = NA_real_, 
            cutoff = cutoff, valid_confidence_interval = FALSE, 
            reason = if (best_edge) "Profile optimum is at grid boundary." else "No supported grid values.", 
            stringsAsFactors = FALSE))
    }
    data.frame(lower = min(profile$value[ok]), upper = max(profile$value[ok]), 
        cutoff = cutoff, valid_confidence_interval = TRUE, reason = "", 
        stringsAsFactors = FALSE)
}
transition_profile_evidence_summary <-
function (profile) 
{
    tab <- if ("LR" %in% names(profile)) 
        interpret_transition_profile(profile)
    else profile
    diag <- transition_profile_grid_diagnostic(tab)
    poor <- tab$value[tab$likelihood_ratio_statistic > 3.8399999999999999]
    list(transition = paste(diag$from_state, "to", diag$to_state), 
        best_supported_value = diag$best_supported_value, supported_values_lr_3.84 = diag$supported_values_lr_3.84, 
        poorly_supported_values = paste(poor, collapse = ", "), 
        grid_diagnostic = diag)
}
transition_profile_grid_diagnostic <-
function (profile) 
{
    tab <- if ("LR" %in% names(profile)) 
        interpret_transition_profile(profile)
    else profile
    lr <- tab$likelihood_ratio_statistic
    values <- tab$value
    best_i <- which.min(lr)
    upper_edge <- best_i == length(lr)
    lower_edge <- best_i == 1
    decreasing_with_value <- all(diff(lr) <= 1e-08)
    increasing_with_value <- all(diff(lr) >= -1e-08)
    direction <- if (decreasing_with_value) 
        "improves_as_value_increases"
    else if (increasing_with_value) 
        "improves_as_value_decreases"
    else "interior_or_irregular"
    supported <- values[lr <= 3.8399999999999999]
    step <- stats::median(diff(sort(unique(values))), na.rm = TRUE)
    if (!is.finite(step) || step <= 0) 
        step <- 0.10000000000000001
    suggested <- if (upper_edge && decreasing_with_value) {
        pmin(0.98999999999999999, values[best_i] + step * seq_len(4))
    }
    else if (lower_edge && increasing_with_value) {
        pmax(0.01, values[best_i] - step * seq_len(4))
    }
    else numeric(0)
    data.frame(from_state = tab$from_state[1], to_state = tab$to_state[1], 
        best_supported_value = values[best_i], best_value_at_grid_edge = upper_edge || 
            lower_edge, profile_direction = direction, supported_values_lr_3.84 = paste(supported, 
            collapse = ", "), grid_extension_recommended = (upper_edge && 
            decreasing_with_value) || (lower_edge && increasing_with_value), 
        suggested_next_values = paste(unique(round(suggested, 
            4)), collapse = ", "), interpretation = if (upper_edge && 
            decreasing_with_value) {
            "The best-supported tested value is at the upper edge of the grid. This indicates that the likelihood may continue improving beyond the tested range. The profile should be extended to larger transition probabilities before interpreting the maximum or support interval."
        }
        else if (lower_edge && increasing_with_value) {
            "The best-supported tested value is at the lower edge of the grid. This indicates that the likelihood may continue improving below the tested range. The profile should be extended to smaller transition probabilities before interpreting the maximum or support interval."
        }
        else {
            "The tested grid appears to include an interior or non-monotonic evidence pattern."
        }, caution = if ((upper_edge && decreasing_with_value) || 
            (lower_edge && increasing_with_value)) {
            "Do not claim a final confidence interval until the grid brackets the optimum."
        }
        else {
            "Values with likelihood_ratio_statistic <= 3.84 are approximately supported under a conventional one-parameter likelihood-ratio reference."
        }, stringsAsFactors = FALSE)
}
transition_sdreport_table <-
function (fit) 
{
    ext <- extract_tmb_transition_estimates(fit)
    est <- ext$Psi_estimate
    se <- ext$Psi_SE
    rows <- list()
    for (r in seq_len(nrow(est))) for (c in seq_len(ncol(est))) {
        rows[[length(rows) + 1L]] <- data.frame(from_state = rownames(est)[r], 
            to_state = colnames(est)[c], estimate = est[r, c], 
            SE = se[r, c], lower_95 = if (is.finite(se[r, c])) 
                max(0, est[r, c] - 1.96 * se[r, c])
            else NA_real_, upper_95 = if (is.finite(se[r, c])) 
                min(1, est[r, c] + 1.96 * se[r, c])
            else NA_real_, stringsAsFactors = FALSE)
    }
    do.call(rbind, rows)
}
translate_warning_interpretation <-
function (warning) 
{
    if (!length(warning) || all(is.na(warning))) 
        return(character(0))
    out <- warning
    out <- gsub("Singular or near-singular Hessian\\.", "The data do not clearly support stable uncertainty estimates (technical detail: singular or near-singular Hessian).", 
        out)
    out <- gsub("Sparse data for requested model complexity\\.", 
        "There may be too few detections for the requested model complexity (technical detail: sparse data).", 
        out)
    out <- gsub("Boundary-scale parameter estimates\\.", "One or more estimates are very close to an edge, such as almost zero or almost one (technical detail: boundary estimate).", 
        out)
    out
}
true_vs_estimated_abundance_plot_data <-
function (analysis, fit = NULL) 
{
    if (is.null(fit)) 
        fit <- analysis$abundance_fit %||% analysis$state_space_fit
    truth <- extract_true_abundance_series(analysis)
    est <- extract_estimated_abundance_series(fit)
    if (is.null(truth)) 
        return(list(ok = FALSE, reason = "true-vs-estimated abundance requires simulation truth; empirical data do not contain known true abundance."))
    if (is.null(est)) 
        return(list(ok = FALSE, reason = "estimated abundance is missing."))
    tab <- merge(truth, est, by = "occasion", all = FALSE)
    if (!nrow(tab)) 
        return(list(ok = FALSE, reason = "truth and estimated abundance have no shared occasions."))
    list(ok = TRUE, data = tab)
}
truncate_table_columns <-
function (x, max_col_width = 24L, digits = 3L) 
{
    out <- x
    for (nm in names(out)) {
        vals <- vapply(out[[nm]], format_table_value, character(1), 
            digits = digits)
        vals[is.na(vals)] <- "NA"
        too_long <- nchar(vals) > max_col_width
        vals[too_long] <- paste0(substr(vals[too_long], 1L, max(1L, 
            max_col_width - 3L)), .ascii_ellipsis())
        out[[nm]] <- vals
    }
    out
}
truth_labels <-
function (sim, schedule, resident_threshold = 0.5, mode = c("availability", 
    "realized_use", "sampled_use")) 
{
    mode <- match.arg(mode)
    source <- switch(mode, availability = sim$true_alive, realized_use = sim$observed, 
        sampled_use = sim$observed)
    if (is.null(source)) 
        return(NULL)
    selected <- if (mode == "realized_use") 
        as_binary_matrix(source)
    else subset_history(source, schedule)
    frac_present <- rowMeans(selected)
    data.frame(id = rownames(selected), truth_mode = mode, true_presence_fraction = frac_present, 
        true_resident = frac_present >= resident_threshold, stringsAsFactors = FALSE)
}
uncertainty_diagnostics <-
function (fit) 
{
    id <- fit$identifiability %||% validate_multistate_identifiability(fit)
    data.frame(singular_hessian = id$singular_hessian, boundary_estimate = id$boundary_estimate, 
        sparse_data = id$sparse_data, hessian_available = !is.null(fit$optim$hessian), 
        uncertainty_reliable = !(id$singular_hessian || id$boundary_estimate || 
            id$sparse_data), recommendation = if (id$singular_hessian || 
            id$sparse_data) {
            "Use a simpler model and profile/bootstrap intervals; do not rely only on Hessian SEs."
        }
        else {
            "Hessian uncertainty is provisionally usable; confirm with bootstrap/profile checks."
        }, stringsAsFactors = FALSE)
}
uncertainty_engine <-
function (fit, table = NULL, ci_method = "auto", R = 20L, level = 0.94999999999999996, 
    seed = 1L) 
{
    method <- choose_uncertainty_method(fit, ci_method)
    if (method == "hessian_delta") 
        return(list(method = method, vcov = vcov_from_fit(fit), 
            bootstrap = NULL, report = uncertainty_method_report(fit, 
                ci_method)))
    if (method == "jackknife_diagnostic") 
        return(list(method = method, vcov = NULL, bootstrap = jackknife_diagnostic_ci(fit), 
            report = uncertainty_method_report(fit, ci_method)))
    list(method = method, vcov = NULL, bootstrap = parametric_bootstrap_ci(fit, 
        R = R, level = level, seed = seed), report = uncertainty_method_report(fit, 
        ci_method))
}
uncertainty_method_report <-
function (fit, requested = "auto") 
{
    method <- choose_uncertainty_method(fit, requested)
    data.frame(model_name = fit$model_name %||% fit$abundance_model %||% 
        "unknown", selected_method = method, status = if (method == 
        "hessian_delta") 
        "computed"
    else "approximated", diagnostic_interpretation = if (method == 
        "hessian_delta") 
        "Stable curvature was available."
    else "Fallback uncertainty was selected because stable curvature was unavailable.", 
        stringsAsFactors = FALSE)
}
uncertainty_summary <-
function (summary_table, group_cols = c("model", "sampling_method")) 
{
    numeric_cols <- names(summary_table)[vapply(summary_table, 
        is.numeric, logical(1))]
    numeric_cols <- setdiff(numeric_cols, c("scenario", "replicate"))
    groups <- interaction(summary_table[group_cols], drop = TRUE, 
        lex.order = TRUE)
    out <- lapply(split(summary_table, groups), function(dat) {
        base <- dat[1, intersect(group_cols, names(dat)), drop = FALSE]
        stats <- lapply(numeric_cols, function(col) {
            x <- dat[[col]]
            data.frame(metric = col, mean = mean(x, na.rm = TRUE), 
                sd = stats::sd(x, na.rm = TRUE), q025 = stats::quantile(x, 
                  0.025000000000000001, na.rm = TRUE, names = FALSE), 
                median = stats::median(x, na.rm = TRUE), q975 = stats::quantile(x, 
                  0.97499999999999998, na.rm = TRUE, names = FALSE), 
                stringsAsFactors = FALSE)
        })
        cbind(base[rep(1, length(numeric_cols)), , drop = FALSE], 
            do.call(rbind, stats))
    })
    do.call(rbind, out)
}
