    final_sampling_date <- as.Date(final_sampling_date)
    if (is.na(initial_sampling_date) || is.na(final_sampling_date)) {
        stop("initial_sampling_date and final_sampling_date must be valid dates.")
    }
    if (final_sampling_date <= initial_sampling_date) {
        stop("final_sampling_date must be after initial_sampling_date.")
    }
    data.frame(initial_sampling_date = initial_sampling_date, 
        final_sampling_date = final_sampling_date, sampling_period_days = as.integer(final_sampling_date - 
            initial_sampling_date) + 1L)
