function (value, detection_formula = NULL) 
{
    norm <- normalize_detection_covariate_assumptions(value, 
        detection_formula)
    if (!(norm$detection_covariate_assumptions %in% detection_assumption_options())) {
        stop("detection_covariate_assumptions must be one of: ", 
            paste(detection_assumption_options(), collapse = ", "))
    }
