validate_detection_covariates <-
function (formula, data) 
{
    vars <- all.vars(formula)
    problems <- character(0)
    missing <- setdiff(vars, names(data))
    if (length(missing)) 
        problems <- c(problems, paste("missing covariates:", 
            paste(missing, collapse = ", ")))
    present <- intersect(vars, names(data))
    all_missing <- present[vapply(data[present], function(x) all(is.na(x)), 
        logical(1))]
    if (length(all_missing)) 
        problems <- c(problems, paste("all-NA covariates:", paste(all_missing, 
            collapse = ", ")))
    bad <- present[vapply(data[present], function(x) is.matrix(x) || 
        is.data.frame(x), logical(1))]
    if (length(bad)) 
        problems <- c(problems, paste("malformed covariates:", 
            paste(bad, collapse = ", ")))
    problems
}
validate_detection_formula <-
function (detection_formula) 
{
    if (!inherits(detection_formula, "formula")) 
        stop("detection_formula must be an R formula, for example ~ 1 or ~ effort.")
    TRUE
}
validate_detection_parameters <-
function (p = NULL, state_detection = NULL, unavailable_states = NULL) 
{
    if (!is.null(p)) {
        vals <- as.numeric(p)
        if (any(!is.finite(vals) | vals < 0 | vals > 1)) 
            stop("Detection probabilities must be between 0 and 1.")
        if (any(vals < 0.050000000000000003)) 
            warning("Detection probability below 0.05 means most available individuals may be missed.")
        if (any(vals > 0.80000000000000004)) 
            warning("Detection probability above 0.80 may make the simulation unrealistically easy.")
    }
    if (!is.null(state_detection)) {
        vals <- as.numeric(state_detection)
        if (any(!is.finite(vals) | vals < 0 | vals > 1)) 
            stop("state_detection probabilities must be between 0 and 1.")
        if (!is.null(unavailable_states)) {
            hit <- intersect(names(state_detection), unavailable_states)
            if (length(hit) && any(state_detection[hit] != 0)) {
                stop("Unavailable or outside states must have detection probability 0.")
            }
        }
    }
    TRUE
}
validate_detection_stage <-
function (config) 
{
    config <- synchronize_detection_formula_and_beta(config)
    assumption <- config$detection_covariate_assumptions %||% 
        infer_detection_assumption_from_formula(config$detection_formula)
    use_state_detection <- assumption %in% c("state", "effort_plus_state", 
        "state_plus_individual_random_effect", "effort_plus_state_plus_individual_random_effect")
    validate_parameter_stage("detection model", "beta", validate_beta_values(config$beta, 
        config$detection_formula, use_state_detection), "run synchronize_detection_formula_and_beta() or choose a simpler detection assumption")
    validate_parameter_stage("detection model", "state_detection", 
        validate_state_detection(config$state_detection, config$states, 
            config$unavailable_states), "enter one probability per state and set unavailable states to 0")
    validate_parameter_stage("detection model", "effort_units", 
        validate_effort_units_for_type(config$effort_variable_type, 
            config$effort_units), "choose compatible effort units for the selected effort variable type")
    config
}
