validate_import_file_before_analysis <-
function (path, format = c("PROGRAM_MARK", "SOCPROG", "CSV_LONG", 
    "WIDE_CSV", "MARK_INP", "EXCEL", "AUTO")) 
{
    format <- toupper(gsub("[ -]+", "_", as.character(format[1])))
    if (!nzchar(path %||% "")) 
        return(list(ok = FALSE, status = "invalid", selected_format = format, 
            detected_format = NA_character_, path = path, problems = .import_problem_table("No file path was provided.", 
                "Enter a full path to a data file or type exit."), 
            warnings = character(), imported = NULL))
    path <- path.expand(path)
    if (!file.exists(path)) 
        return(list(ok = FALSE, status = "invalid", selected_format = format, 
            detected_format = NA_character_, path = path, problems = .import_problem_table("File does not exist.", 
                "Check the spelling of the path, or drag the file into the R console to paste its full path."), 
            warnings = character(), imported = NULL))
    detected <- if (format == "AUTO") 
        resident_detect_import_format(path)
    else format
    if (detected %in% c("UNKNOWN", "METADATA")) 
        return(list(ok = FALSE, status = "invalid", selected_format = format, 
            detected_format = detected, path = path, problems = .import_problem_table("The file is not a direct encounter-history input file.", 
                "Choose a MARK, SOCPROG, wide encounter-history CSV, .inp, or supported Excel workbook."), 
            warnings = character(), imported = NULL))
    attempt <- .validate_import_for_format(path, detected)
    if (!isTRUE(attempt$ok)) 
        return(list(ok = FALSE, status = "invalid", selected_format = format, 
            detected_format = detected, path = path, problems = attempt$problems, 
            warnings = attempt$warnings, imported = attempt$imported %||% 
                NULL, attempts = list(attempt)))
    imported <- attempt$imported
    check <- check_capture_data_format(imported)
    check$summary <- capture_data_summary(imported$history, imported$occasions, 
        data_type = "empirical")
    list(ok = TRUE, status = "valid", selected_format = format, 
        detected_format = detected, path = path, problems = .import_problem_table(), 
        warnings = attempt$warnings, date_status = attempt$date_status, 
        imported = imported, check = check, attempts = list(attempt))
}
validate_inferential_model <-
function (N = 80, n_occasions = 120, seed = 1, maxit = 300) 
{
    sim <- simulate_latent_residency_model(N = N, n_occasions = n_occasions, 
        seed = seed)
    fit <- fit_residency_hmm(sim$observed, sim$occasions, states = sim$states, 
        transition_matrix = sim$transition_matrix, estimate_transition = FALSE, 
        maxit = maxit)
    true_major <- apply(sim$latent_states, 1, function(z) {
        tab <- table(factor(sim$states[z], levels = sim$states))
        names(tab)[which.max(tab)]
    })
    pred_major <- fit$classification$most_likely_state
    names(pred_major) <- fit$classification$id
    state_metrics <- validation_metrics(true_major[names(pred_major)], 
        pred_major, positive = "resident")
    detection_rmse <- sqrt(mean((fit$detection_prob - sim$state_detection)^2))
    transition_rmse <- sqrt(mean((fit$transition_matrix - sim$transition_matrix)^2))
    list(simulation = sim, fit = fit, state_metrics = state_metrics, 
        detection_rmse = detection_rmse, transition_rmse = transition_rmse)
}
validate_initial_probs <-
function (initial_probs, states) 
{
    if (is.null(initial_probs)) 
        return(TRUE)
    if (length(initial_probs) != length(states)) 
        stop("initial_probs length must match states.")
    if (any(!is.finite(initial_probs)) || any(initial_probs < 
        0)) 
        stop("initial_probs must be non-negative finite values.")
    if (abs(sum(initial_probs) - 1) > 9.9999999999999995e-07) 
        stop("initial_probs must sum to 1.")
    TRUE
}
validate_menu_definition <-
function (menu) 
{
    if (!is.data.frame(menu) || !all(c("option", "key", "label") %in% 
        names(menu))) {
        stop("Menu definition must contain option, key, and label.", 
            call. = FALSE)
    }
    if (nrow(menu) < 1L || menu$option[nrow(menu)] != 0L) {
        stop("Every menu must print option 0 last.", call. = FALSE)
    }
    actions <- menu$option[-nrow(menu)]
    if (length(actions) && !identical(actions, seq_len(length(actions)))) {
        stop("Menu action numbering must start at 1 and be continuous before option 0.", 
            call. = FALSE)
    }
    if (any(menu$option[-nrow(menu)] == 0L)) 
        stop("Only the final menu row may use option 0.", call. = FALSE)
    if (!.exit_like_label_v088(menu$label[nrow(menu)])) {
        stop("The final option 0 must be Exit, Finish, Cancel, Back, or Return.", 
            call. = FALSE)
    }
    if (any(.exit_like_label_v088(menu$label[-nrow(menu)]))) {
        stop("No positive integer option may be Exit, Finish, Cancel, Back, or Return.", 
            call. = FALSE)
    }
    TRUE
}
validate_model_registry <-
function (registry = model_registry()) 
{
    need <- c("model_family", "candidate_model", "model_role", 
        "implemented", "selectable_from_abundance_menu", "fit_function")
    miss <- setdiff(need, names(registry))
    if (length(miss)) 
        stop("Model registry is missing columns: ", paste(miss, 
            collapse = ", "), call. = FALSE)
    if (anyDuplicated(registry$candidate_model)) 
        stop("Model registry contains duplicate candidate_model values.", 
            call. = FALSE)
    TRUE
}
validate_multistate_identifiability <-
function (fit, min_events_per_parameter = 5) 
{
    y <- fit$rd_array$y
    detections <- sum(y, na.rm = TRUE)
    npar <- fit$npar %||% length(fit$optim$par)
    h <- fit$optim$hessian
    eig <- if (!is.null(h) && all(is.finite(h))) 
        tryCatch(eigen(h, symmetric = TRUE, only.values = TRUE)$values, 
            error = function(e) NA_real_)
    else NA_real_
    singular <- any(!is.finite(eig)) || any(eig <= sqrt(.Machine$double.eps))
    boundary <- any(abs(fit$optim$par) > 8)
    sparse <- detections/max(1, npar) < min_events_per_parameter
    data.frame(detections = detections, n_parameters = npar, 
        events_per_parameter = detections/max(1, npar), singular_hessian = singular, 
        boundary_estimate = boundary, sparse_data = sparse, identifiable = !(singular || 
            boundary || sparse), stringsAsFactors = FALSE)
}
validate_occasion_table <-
function (occasions = NULL, history = NULL, stage = "occasion validation") 
{
    if (is.null(occasions)) {
        K <- if (!is.null(history)) 
            ncol(validate_history_matrix(history, stage = stage))
        else 0L
        labels <- if (!is.null(history)) 
            colnames(validate_history_matrix(history, stage = stage))
        else character()
        dates <- .safe_as_date(labels)
        occasions <- data.frame(occasion = seq_len(K), date = dates, 
            stringsAsFactors = FALSE)
    }
    if (!is.data.frame(occasions)) 
        stop_history_error(stage, occasions, "occasion table is not a data.frame.")
    if (!"occasion" %in% names(occasions)) 
        occasions$occasion <- seq_len(nrow(occasions))
    if (!"date" %in% names(occasions)) {
        possible <- intersect(c("Date", "survey_date", "sampling_date"), 
            names(occasions))
        occasions$date <- if (length(possible)) 
            occasions[[possible[1]]]
        else as.Date(rep(NA, nrow(occasions)))
    }
    occasions$date <- .safe_as_date(occasions$date)
    if (!"year" %in% names(occasions)) 
        occasions$year <- ifelse(is.na(occasions$date), NA_integer_, 
            as.integer(format(occasions$date, "%Y")))
    if (!"month" %in% names(occasions)) 
        occasions$month <- ifelse(is.na(occasions$date), NA_integer_, 
            as.integer(format(occasions$date, "%m")))
    if (!"season" %in% names(occasions)) {
        occasions$season <- ifelse(is.na(occasions$month), NA_character_, 
            c("winter", "winter", "spring", "spring", "spring", 
                "summer", "summer", "summer", "autumn", "autumn", 
                "autumn", "winter")[occasions$month])
    }
    if (!"effort" %in% names(occasions)) 
        occasions$effort <- NA_real_
    occasions
}
validate_output_stage <-
function (config) 
{
    if (!is.logical(config$compare_to_observed) || length(config$compare_to_observed) != 
        1 || is.na(config$compare_to_observed)) {
        stop("Validation stage: output. Parameter: compare_to_observed. Issue: compare_to_observed must be TRUE or FALSE. Suggested fix: enter TRUE or FALSE.")
    }
    config
}
validate_parameter_range <-
function (parameter, value, config = NULL) 
{
    p <- .parameter_key(parameter)
    if (p %in% c("p", "phi", "baseline_detection_probability")) {
        v <- as.numeric(value)
        if (length(v) != 1 || !is.finite(v) || v < 0 || v > 1) 
            stop(parameter, " must be a probability in [0,1].")
    }
    if (p %in% c("state_detection", "initial_probs", "b")) {
        v <- as.numeric(value)
        if (any(!is.finite(v)) || any(v < 0 | v > 1)) 
            stop(parameter, " must contain probabilities in [0,1].")
    }
    if (p == "transition_matrix") {
        m <- as.matrix(value)
        if (any(!is.finite(m)) || any(m < 0)) 
            stop("transition_matrix must contain finite non-negative probabilities.")
        if (any(abs(rowSums(m) - 1) > 9.9999999999999995e-07)) 
            stop("transition_matrix rows must sum to 1.")
    }
    if (p %in% c("N", "requested_number_of_sampling_occasions", 
        "rmax")) {
        v <- as.numeric(value)
        if (length(v) != 1 || !is.finite(v) || v < 1) 
            stop(parameter, " must be positive.")
    }
    if (p == "individual_re_sd" && as.numeric(value) < 0) 
        stop("individual_re_sd must be non-negative.")
    if (p %in% c("effort_detection_effect", "beta")) {
        if (any(!is.finite(as.numeric(value)))) 
            stop(parameter, " must be finite.")
    }
    TRUE
}
validate_parameter_stage <-
function (stage, parameter, expr, suggested_fix = "") 
{
    tryCatch(expr, error = function(e) {
        stop("Validation stage: ", stage, ". Parameter: ", parameter, 
            ". Issue: ", conditionMessage(e), if (nzchar(suggested_fix)) 
                paste0(" Suggested fix: ", suggested_fix)
            else "", call. = FALSE)
    })
}
