function (specification) 
{
    stopifnot(is.list(specification))
    TRUE
}
validate_parameter_value <-
function (parameter, value, config = list()) 
{
    p <- .parameter_key(parameter)
    if (p == "sigma_individual_detection") {
        v <- as.numeric(value)
        if (length(v) != 1 || is.na(v) || !is.finite(v) || v < 
            0) {
            stop("sigma_individual_detection must be a finite numeric value >= 0.")
        }
        return(TRUE)
    }
    TRUE
}
