    flag_suspicious_parameter_value(parameter, value, config)
}
validate_plot_data <-
function (data, x, y, group = NULL) 
{
    chk <- finite_xy_check(data, x, y)
    if (!isTRUE(chk$ok)) 
        return(chk)
    if (!is.null(group) && !(group %in% names(data))) {
        return(list(ok = FALSE, reason = paste("grouping column is missing:", 
            group)))
    }
    if (!is.null(group) && !any(!is.na(data[[group]]))) {
        return(list(ok = FALSE, reason = "no group has valid plot data"))
    }
    chk
}
validate_primary_secondary_design <-
function (config) 
{
    primary <- config$primary_period
    secondary <- config$secondary_period_design
    if (!(primary %in% .allowed_simulation_options("primary_period"))) {
        stop("primary_period must be one of: ", paste(.allowed_simulation_options("primary_period"), 
            collapse = ", "))
    }
    if (!(secondary %in% .allowed_simulation_options("secondary_period_design"))) {
        stop("secondary_period_design must be one of: ", paste(.allowed_simulation_options("secondary_period_design"), 
            collapse = ", "))
    }
    dates <- .configured_sampling_dates(config)
    if (!length(dates)) 
        stop("At least one selected sampling occasion is required.")
    primary_id <- .primary_ids(dates, primary)
    tab <- table(primary_id)
    if (any(tab < 1)) 
        stop("Each primary period must contain at least one secondary occasion.")
    if (isTRUE(config$robust_design_inference) && any(tab < 2)) {
        warning("Robust-design inference is more stable with at least 2 secondary occasions per primary period.")
    }
    TRUE
}
validate_primary_secondary_periods <-
function (structure, n_occasions = NULL) 
{
    if (is.null(structure$primary_period) || is.null(structure$secondary_period)) 
        stop("Temporal structure must include primary_period and secondary_period.", 
            call. = FALSE)
    if (!is.null(n_occasions) && (length(structure$primary_period) != 
        n_occasions || length(structure$secondary_period) != 
        n_occasions)) 
        stop("Temporal structure length must match the number of sampling occasions.", 
            call. = FALSE)
    TRUE
}
validate_recapture_distribution <-
function (distribution, params = list(), rmax = NULL) 
{
    distribution <- tolower(distribution)
    allowed <- .allowed_simulation_options("recapture_distribution")
    if (!(distribution %in% allowed)) {
        stop("recapture_distribution must be one of: ", paste(allowed, 
            collapse = ", "))
    }
    positive <- function(x, name) {
        if (!is.finite(x) || x <= 0) 
            stop(name, " must be positive.")
    }
    if (distribution == "gaussian") {
        positive(params$mean %||% 1, "gaussian mean")
        positive(params$sd %||% 1, "gaussian sd")
        if (!is.null(rmax) && (params$mean %||% 1) > rmax) 
            warning("gaussian mean exceeds rmax.")
    }
    if (distribution == "exponential") 
        positive(params$rate %||% 1, "exponential rate")
    if (distribution == "chisq") {
        positive(params$df %||% 2, "chisq df")
        positive(params$scale %||% 1, "chisq scale")
    }
    if (distribution == "negative_binomial") {
        positive(params$mu %||% 1, "negative_binomial mu")
        positive(params$size %||% 1, "negative_binomial size")
        if (!is.null(rmax) && (params$mu %||% 1) > rmax) 
            warning("negative_binomial mu exceeds rmax.")
    }
    if (distribution == "poisson") {
        positive(params$lambda %||% 1, "poisson lambda")
        if (!is.null(rmax) && (params$lambda %||% 1) > rmax) 
            warning("poisson lambda exceeds rmax.")
    }
    if (distribution == "beta_binomial") {
        positive(params$shape1 %||% 1, "beta_binomial shape1")
        positive(params$shape2 %||% 1, "beta_binomial shape2")
    }
    TRUE
}
validate_recapture_distribution_parameters <-
function (distribution, params = list(), rmax = NULL) 
{
    distribution <- tolower(distribution)
    allowed <- .allowed_simulation_options("recapture_distribution")
    if (!(distribution %in% allowed)) 
        stop("recapture_distribution must be one of: ", paste(allowed, 
            collapse = ", "))
    positive <- function(x, name) {
        if (is.null(x) || length(x) != 1 || !is.finite(as.numeric(x)) || 
            as.numeric(x) <= 0) {
            stop(name, " must be a positive number.")
        }
    }
    if (distribution == "gaussian") {
        positive(params$mean, "gaussian mean")
        positive(params$sd, "gaussian sd")
        if (!is.null(rmax) && params$mean > rmax) 
            warning("gaussian mean exceeds rmax.")
    }
    else if (distribution == "exponential") {
        positive(params$rate, "exponential rate")
    }
    else if (distribution == "chisq") {
        positive(params$df, "chisq df")
        positive(params$scale, "chisq scale")
    }
    else if (distribution == "negative_binomial") {
        positive(params$mu, "negative_binomial mu")
        positive(params$size, "negative_binomial size")
        if (!is.null(rmax) && params$mu > rmax) 
            warning("negative_binomial mu exceeds rmax.")
    }
    else if (distribution == "poisson") {
        positive(params$lambda, "poisson lambda")
        if (!is.null(rmax) && params$lambda > rmax) 
            warning("poisson lambda exceeds rmax.")
    }
    else if (distribution == "beta_binomial") {
        positive(params$shape1, "beta_binomial shape1")
        positive(params$shape2, "beta_binomial shape2")
    }
    TRUE
}
validate_resident_encounter_data <-
function (x) 
{
    if (!is_resident_encounter_data(x)) 
        stop_history_error("resident_encounter_data validation", 
            x, "object is not class resident_encounter_data.")
    validate_history_occasion_alignment(x$history, x$occasions, 
        "resident_encounter_data validation")
    TRUE
}
validate_sampling_occasions <-
function (number_of_sampling_occasions, initial_sampling_date, 
    final_sampling_date, occasion_unit = "day") 
{
    n <- .as_positive_integer(number_of_sampling_occasions, "number_of_sampling_occasions")
    dr <- validate_date_range(initial_sampling_date, final_sampling_date)
    if (!(occasion_unit %in% .allowed_simulation_options("occasion_unit"))) {
        stop("occasion_unit must be one of: ", paste(.allowed_simulation_options("occasion_unit"), 
            collapse = ", "))
    }
    if (occasion_unit == "day" && n > dr$sampling_period_days) {
        stop("number_of_sampling_occasions cannot exceed the number of available calendar days when occasion_unit = 'day'.")
    }
    if (n < 2) 
        warning("Fewer than 2 sampling occasions make capture-recapture inference scientifically weak.")
    TRUE
}
validate_simulation_parameters <-
function (config) 
{
    if (is.null(config) || !is.list(config)) 
        stop("config must be a list of simulation parameters.")
    config <- modifyList(simulation_parameter_defaults(), config)
    config <- migrate_detection_assumption_notes(config)
    config <- configure_detection_model_from_assumption(config$detection_covariate_assumptions, 
        config = config, interactive = FALSE, custom_formula = config$detection_formula)
    config$requested_number_of_sampling_occasions <- config$requested_number_of_sampling_occasions %||% 
        config$number_of_sampling_occasions
    config$number_of_sampling_occasions <- config$requested_number_of_sampling_occasions
    config$N <- .as_positive_integer(config$N, "N")
    if (config$N < 20) 
        warning("N below 20 may produce unstable estimates.")
    if (config$N > 1000) 
        warning("N above 1000 may make computations slow.")
    validate_date_range(config$initial_sampling_date, config$final_sampling_date)
    validate_sampling_occasions(config$requested_number_of_sampling_occasions, 
        config$initial_sampling_date, config$final_sampling_date, 
        config$occasion_unit)
    config$possible_number_of_dates <- length(.possible_dates(config))
    validate_actual_sampling_design(config)
    dates <- .configured_sampling_dates(config)
    config$selected_sampling_dates <- dates
    config$actual_number_of_sampling_occasions <- length(dates)
    config$actual_number_of_sampling_occasions_after_sampling_design <- length(dates)
    config$reason_actual_differs_from_requested <- .sampling_difference_reason(config)
    config$rmax <- .as_positive_integer(config$rmax, "rmax")
    if (config$rmax > config$actual_number_of_sampling_occasions) {
        stop("rmax cannot be greater than the actual number of selected sampling occasions.")
    }
    if (!(config$simulation_model %in% .allowed_simulation_options("simulation_model"))) {
        stop("simulation_model must be one of: ", paste(.allowed_simulation_options("simulation_model"), 
            collapse = ", "))
    }
    validate_recapture_distribution_parameters(config$recapture_distribution, 
        config$recapture_params, config$rmax)
    keep_recapture <- .recapture_parameter_names(config$recapture_distribution)
    config$recapture_params <- if (length(keep_recapture)) 
        config$recapture_params[keep_recapture]
    else list()
    validate_detection_parameters(config$p, config$state_detection, 
        config$unavailable_states)
    config$states <- validate_state_vector(config$states)
    validate_initial_probs(config$initial_probs, config$states)
    if (config$simulation_model %in% c("latent_residency", "state_space_robust_design")) {
        config$transition_time_scale <- validate_transition_timescale(config$transition_time_scale %||% 
            "month")
        config$transition_matrix_type <- config$transition_matrix_type %||% 
            "biologically_informed"
        config$transition_matrix_source <- config$transition_matrix_source %||% 
            if (is.null(config$transition_matrix)) 
                "default"
            else "custom"
        if (is.null(config$transition_matrix)) {
            config$transition_matrix <- default_transition_matrix_by_timescale(config$states, 
                transition_time_scale = config$transition_time_scale, 
                matrix_type = config$transition_matrix_type)
            config$transition_matrix_source <- "default"
        }
        else {
            config$transition_matrix <- validate_transition_matrix_timescale(config$transition_matrix, 
                states = config$states, transition_time_scale = config$transition_time_scale, 
                matrix_type = if (config$transition_matrix_source == 
                  "custom") 
                  "custom"
                else config$transition_matrix_type)
        }
        warn_transition_matrix_if_needed(config$transition_matrix, 
            transition_time_scale = config$transition_time_scale, 
            matrix_type = config$transition_matrix_type, occasion_unit = config$occasion_unit, 
            explanation = config$transition_time_scale_explanation)
    }
    config <- validate_transition_stage(config)
    config <- validate_detection_stage(config)
    if (!(config$effort_variable_type %in% effort_variable_type_options())) {
        stop("effort_variable_type must be one of: ", paste(effort_variable_type_options(), 
            collapse = ", "))
    }
    if (!(config$effort_units %in% effort_units_options())) {
        stop("effort_units must be one of: ", paste(effort_units_options(), 
            collapse = ", "))
    }
    validate_effort_units_for_type(config$effort_variable_type, 
        config$effort_units)
    if ((config$effort_variable_type == "custom" || config$effort_units == 
        "custom") && !nzchar(config$effort_custom_definition %||% 
        "")) {
        stop("effort_custom_definition is required when effort_variable_type or effort_units is custom.")
    }
    if (!(config$effort_scaling %in% c("raw", "mean_centered", 
        "z_score", "min_max_0_1"))) {
        stop("effort_scaling must be one of: raw, mean_centered, z_score, min_max_0_1")
    }
    config <- validate_output_stage(config)
    validate_entry_probabilities(config$b, config$actual_number_of_sampling_occasions)
    validate_primary_secondary_design(config)
    config$parameter_warnings <- collect_parameter_warnings(config)
    det_warn <- detection_assumption_warning_rules(config$detection_covariate_assumptions, 
        config$observed_data, config)
    if (length(det_warn)) {
        det_warn_tab <- data.frame(parameter = "detection_covariate_assumptions", 
            warning = det_warn, stringsAsFactors = FALSE)
        config$parameter_warnings <- rbind(config$parameter_warnings, 
            det_warn_tab)
    }
    config$validation_warnings <- unique(c(config$validation_warnings, 
        config$parameter_warnings$warning))
    config$configuration_review <- simulation_configuration_review(config)
    class(config) <- c("resident_simulation_config", setdiff(class(config), 
        "resident_simulation_config"))
    config
}
validate_state_detection <-
function (state_detection, states, unavailable_states = character()) 
{
    if (is.null(state_detection)) 
        return(TRUE)
    states <- validate_state_vector(states)
    if (length(state_detection) != length(states)) {
        if (length(state_detection) == 1 && length(states) > 
            1) {
            stop("state_detection requires one value per state. You entered one value, but there are ", 
                length(states), " states.")
        }
        stop("state_detection length must equal number of states. Expected ", 
            length(states), " values but received ", length(state_detection), 
            ".")
    }
    if (is.null(names(state_detection))) 
        names(state_detection) <- states
    if (!all(states %in% names(state_detection))) {
        stop("state_detection must include all states in this order: ", 
            paste(states, collapse = ", "))
    }
    vals <- as.numeric(state_detection[states])
    if (any(!is.finite(vals))) 
        stop("state_detection values must be numeric and finite.")
    if (any(vals < 0 | vals > 1)) 
        stop("state_detection values must be probabilities in [0,1].")
    hit <- intersect(unavailable_states, states)
    if (length(hit) && any(vals[match(hit, states)] != 0)) {
        stop("Unavailable states must have detection = 0. Nonzero unavailable state(s): ", 
            paste(hit[vals[match(hit, states)] != 0], collapse = ", "))
    }
    TRUE
}
validate_state_vector <-
function (states) 
{
    if (is.null(states) || !length(states) || any(!nzchar(states))) 
        stop("states must be a non-empty character vector.")
    if (anyDuplicated(states)) 
        stop("states must be unique.")
    as.character(states)
}
validate_tmb_design_matrices <-
function (tmb_data) 
{
    d <- tmb_data$data
    problems <- character(0)
    if (dim(d$X_detection)[1] != d$N * d$Tobs) {
        problems <- c(problems, "X_detection must have N * Tobs rows.")
    }
    if (any(!is.finite(d$X_detection))) 
        problems <- c(problems, "X_detection contains non-finite values.")
    if (length(d$initial_probs) != d$S) 
        problems <- c(problems, "initial_probs length must equal number of states.")
    if (!all(dim(d$Psi_fixed) == c(d$S, d$S))) 
        problems <- c(problems, "Psi_fixed must be S x S.")
    list(ok = !length(problems), problems = problems)
}
validate_transition_free_mask <-
function (transition_free_mask, states = NULL) 
{
    if (is.null(transition_free_mask)) 
        stop("transition_free_mask is required for estimate_custom_mask.")
    mask <- as.matrix(transition_free_mask)
    if (!all(mask %in% c(TRUE, FALSE))) 
        stop("transition_free_mask must be a logical matrix.")
    if (!is.null(states)) {
        if (!all(dim(mask) == c(length(states), length(states)))) {
            stop("transition_free_mask dimensions must match states.")
        }
        rownames(mask) <- colnames(mask) <- states
    }
    if (any(rowSums(mask) < 1)) 
        stop("Each transition_free_mask row must contain at least one TRUE value.")
    mask
}
validate_transition_matrix <-
function (transition_matrix, states = NULL, tol = 1e-08) 
{
    transition_matrix <- as.matrix(transition_matrix)
    if (!is.null(states) && any(dim(transition_matrix) != length(states))) {
        stop("transition_matrix dimensions must match states.")
    }
    if (any(transition_matrix < 0 | !is.finite(transition_matrix))) {
        stop("transition_matrix must contain finite non-negative probabilities.")
    }
    rs <- rowSums(transition_matrix)
    if (any(abs(rs - 1) > tol)) 
        stop("transition_matrix rows must sum to 1.")
    transition_matrix
}
validate_transition_matrix_timescale <-
function (transition_matrix, states = NULL, transition_time_scale = attr(transition_matrix, 
    "transition_time_scale") %||% "month", matrix_type = attr(transition_matrix, 
    "matrix_type") %||% "custom") 
{
    transition_time_scale <- validate_transition_timescale(transition_time_scale)
    mat <- validate_transition_matrix(transition_matrix, states)
    if (is.null(rownames(mat)) && !is.null(states)) 
        rownames(mat) <- states
    if (is.null(colnames(mat)) && !is.null(states)) 
        colnames(mat) <- states
    .attach_transition_matrix_attributes(mat, transition_time_scale, 
        matrix_type)
}
validate_transition_parameters <-
function (transition_matrix = NULL, states = NULL, initial_probs = NULL, 
    phi = NULL) 
{
    if (!is.null(phi) && (!is.finite(phi) || phi < 0 || phi > 
        1)) 
        stop("phi must be between 0 and 1.")
    if (!is.null(initial_probs)) {
        if (any(initial_probs < 0) || abs(sum(initial_probs) - 
            1) > 9.9999999999999995e-07) {
            stop("initial_probs must be non-negative and sum to 1.")
        }
    }
    if (!is.null(transition_matrix)) {
        m <- as.matrix(transition_matrix)
        if (any(!is.finite(m)) || any(m < 0)) 
            stop("transition_matrix cannot contain negative or non-finite probabilities.")
        if (any(abs(rowSums(m) - 1) > 9.9999999999999995e-07)) 
            stop("Each transition_matrix row must sum to 1.")
        if (!is.null(states) && (nrow(m) != length(states) || 
            ncol(m) != length(states))) {
            stop("transition_matrix dimensions must match the number of states.")
        }
    }
    TRUE
}
