validation_metrics <-
function (truth, predicted, positive = "resident") 
{
    truth <- as.character(truth)
    predicted <- as.character(predicted)
    levels <- sort(unique(c(truth, predicted)))
    cm <- table(factor(truth, levels = levels), factor(predicted, 
        levels = levels))
    acc <- sum(diag(cm))/sum(cm)
    pos_truth <- truth == positive
    pos_pred <- predicted == positive
    tp <- sum(pos_truth & pos_pred)
    tn <- sum(!pos_truth & !pos_pred)
    fp <- sum(!pos_truth & pos_pred)
    fn <- sum(pos_truth & !pos_pred)
    list(confusion_matrix = cm, accuracy = acc, sensitivity = if ((tp + 
        fn) > 0) tp/(tp + fn) else NA_real_, specificity = if ((tn + 
        fp) > 0) tn/(tn + fp) else NA_real_, precision = if ((tp + 
        fp) > 0) tp/(tp + fp) else NA_real_, recall = if ((tp + 
        fn) > 0) tp/(tp + fn) else NA_real_)
}
vcov_from_fit <-
function (fit) 
{
    h <- fit$optim$hessian %||% fit$hessian
    if (is.null(h) || !is.matrix(h) || !all(is.finite(h))) 
        return(NULL)
    vc <- tryCatch(solve(h), error = function(e) NULL)
    if (is.null(vc) || !all(is.finite(vc))) 
        return(NULL)
    if (!is.null(fit$par) && length(fit$par) == nrow(vc)) 
        dimnames(vc) <- list(names(fit$par), names(fit$par))
    vc
}
warn_transition_matrix_if_needed <-
function (transition_matrix, transition_time_scale = attr(transition_matrix, 
    "transition_time_scale") %||% "month", matrix_type = attr(transition_matrix, 
    "matrix_type") %||% "custom", occasion_unit = NULL, explanation = NULL) 
{
    diag <- transition_matrix_diagnostics(transition_matrix, 
        transition_time_scale, matrix_type)
    if (nzchar(diag$warnings)) 
        warning(diag$warnings, call. = FALSE)
    if (!is.null(occasion_unit) && occasion_unit %in% c("day", 
        "week", "month")) {
        strong <- (occasion_unit == "day" && transition_time_scale %in% 
            c("season", "year")) || (occasion_unit == "week" && 
            transition_time_scale == "year") || (occasion_unit == 
            "month" && transition_time_scale == "day")
        if (strong && !nzchar(explanation %||% "")) {
            warning("transition_time_scale differs strongly from occasion_unit; provide a transition_time_scale_explanation when this is intentional.", 
                call. = FALSE)
        }
    }
    invisible(diag)
}
