wilson_binomial_interval <-
function (x, n, conf_level = 0.94999999999999996) 
{
    if (n <= 0) 
        return(c(lower = NA_real_, upper = NA_real_))
    z <- stats::qnorm(1 - (1 - conf_level)/2)
    phat <- x/n
    denom <- 1 + z^2/n
    center <- (phat + z^2/(2 * n))/denom
    half <- z * sqrt((phat * (1 - phat)/n) + z^2/(4 * n^2))/denom
    c(lower = max(0, center - half), upper = min(1, center + 
        half))
}
wrap_table_header <-
function (header, width) 
{
    header <- as.character(header)
    if (nchar(header) <= width) 
        return(header)
    header <- gsub("_", " ", header, fixed = TRUE)
    header <- gsub("([a-z])([A-Z])", "\\1 \\2", header)
    wrapped <- strwrap(header, width = max(4L, width))
    if (!length(wrapped)) 
        wrapped <- ""
    wrapped
}
wrap_table_text <-
function (text, width = 78L, prefix = "") 
{
    text <- paste(as.character(text), collapse = " ")
    if (!nzchar(text)) 
        return(character())
    paste0(prefix, strwrap(text, width = width - nchar(prefix)))
}
