write_import_templates <-
function (output_dir = resident_default_output_dir()) 
{
    if (is.null(output_dir) || !nzchar(trimws(output_dir))) 
        output_dir <- "Outputs"
    dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
    mark_path <- file.path(output_dir, "template_PROGRAM_MARK_encounter_history.txt")
    socprog_path <- file.path(output_dir, "template_SOCPROG_sightings_long_format.csv")
    wide_path <- file.path(output_dir, "template_WIDE_CSV_encounter_history.csv")
    inp_path <- file.path(output_dir, "template_MARK_INP_encounter_history.inp")
    guide_path <- file.path(output_dir, "template_capture_recapture_format_guide.txt")
    mark_lines <- c("# Resident Program MARK-style encounter history template", 
        "# Required columns: id encounter_history", "# Optional column: frequency", 
        "# Optional date line. Use real survey dates only:", 
        "# dates: 2020-01-01 2020-01-07 2020-01-15 2020-01-22 2020-01-29 2020-02-05", 
        "# encounter_history uses 1 = detected and 0 = not detected across sampling occasions", 
        "id encounter_history frequency", "Dolphin_001 100100 1", 
        "Dolphin_002 010000 1", "Dolphin_003 001011 1")
    examples <- resident_format_example_tables()
    writeLines(mark_lines, mark_path)
    utils::write.csv(examples$SOCPROG, socprog_path, row.names = FALSE)
    utils::write.csv(examples$WIDE_CSV, wide_path, row.names = FALSE)
    writeLines(examples$MARK_INP$example_line, inp_path)
    writeLines(c("Resident capture-recapture import format guide", 
        "", "PROGRAM_MARK format:", "- One row per individual.", 
        "- Required columns: id, encounter_history.", "- encounter_history must contain only 0 and 1 and all rows must have the same length.", 
        "- Optional first date line starts with '# dates:' followed by one date per sampling occasion.", 
        "", "SOCPROG format:", "- One row per sighting record.", 
        "- Required columns: id, date.", "- Dates must use YYYY-MM-DD whenever possible.", 
        "- Duplicate records for the same id and date are aggregated to detected = 1.", 
        "", "WIDE_CSV format:", "- One row per individual.", 
        "- One id column plus one 0/1 column per sampling occasion.", 
        "- Occasion column names should be real dates such as 2020-01-05 when possible.", 
        "", "MARK_INP format:", "- Original Program MARK compact rows such as /*Dolphin_001*/100100 1;.", 
        "- Use a matching occasion-date companion file when real dates are needed for time-based summaries.", 
        "", "EXCEL format:", "- Requires install.packages('readxl').", 
        "- At least one worksheet must look like WIDE_CSV or SOCPROG.", 
        "", "Important interpretation:", "- 1 means detected.", 
        "- 0 means not detected, not necessarily absent.", "- Resident will check the file before accepting it into the analysis."), 
        guide_path)
    out <- data.frame(template = c("PROGRAM_MARK", "SOCPROG", 
        "WIDE_CSV", "MARK_INP", "FORMAT_GUIDE"), path = c(mark_path, 
        socprog_path, wide_path, inp_path, guide_path), stringsAsFactors = FALSE)
    attr(out, "interpretation") <- "These files are examples/templates only. Replace the example IDs and dates with your own field data before analysis."
    out
}
