# v0.9.41 Option 7/8 residency-state workflow repair.
resident_get_exact_slot <- function(x, name) {
    if (!is.list(x) || !name %in% names(x)) return(NULL)
    x[[name, exact = TRUE]]
}

resident_valid_model_based_residency_table <- function(tab) {
    if (is.null(tab) || !is.data.frame(tab) || !nrow(tab)) return(FALSE)
    has_id <- any(c("id", "individual_id") %in% names(tab))
    has_state <- any(c("most_likely_state", "model_based_state", "assigned_state") %in% names(tab))
    has_probability <- any(c("resident_probability", "availability_probability", "state_probability", "classification_confidence") %in% names(tab))
    looks_like_status <- all(c("check", "status", "detail", "output_type") %in% names(tab))
    isTRUE(has_id && has_state && has_probability && !looks_like_status)
}

.safe_model_based_residency_table <- function(analysis) {
    slots <- c("model_based_residency_results", "model_based_residency",
               "residency_state_results", "state_classification",
               "state_space_results", "residency_results")
    for (slot in slots) {
        tab <- resident_get_exact_slot(analysis, slot)
        if (resident_valid_model_based_residency_table(tab)) return(tab)
    }
    NULL
}

safe_residency_result_table <- function(analysis) {
    tab <- .safe_model_based_residency_table(analysis)
    if (is.null(tab)) return(NULL)
    warn_cols <- intersect(c("classification_warning", "warning"), names(tab))
    if (length(warn_cols) && any(grepl("provisional observed-data summary|no fitted model",
        as.character(tab[[warn_cols[1]]]), ignore.case = TRUE))) return(NULL)
    tab
}

model_fit_slot_for_residency_status <- function(analysis) {
    slots <- c("residency_state_fit", "state_space_fit", "survival_detection_fit",
               "abundance_fit", "fitted_model", "model_fit")
    for (slot in slots) {
        fit <- resident_get_exact_slot(analysis, slot)
        if (!is.null(fit)) return(list(slot = paste0("analysis$", slot), fit = fit))
    }
    list(slot = NA_character_, fit = NULL)
}

model_based_residency_results <- function(analysis, ...) {
    analysis <- standardize_analysis_object(analysis, source = analysis$history_source %||% "analysis")
    fit <- resident_get_exact_slot(analysis, "residency_state_fit") %||%
        resident_get_exact_slot(analysis, "state_space_fit") %||%
        resident_get_exact_slot(analysis, "fit")
    if (!is.null(fit)) {
        tmp <- analysis
        tmp$fit <- fit
        return(.old_model_based_residency_results_v086(tmp, ...))
    }
    .old_model_based_residency_results_v086(analysis, ...)
}

resident_prepare_model_based_residency_table <- function(fit, analysis) {
    tmp <- analysis
    tmp$fit <- fit
    tab <- model_based_residency_results(tmp)
    if (!resident_valid_model_based_residency_table(tab)) {
        stop("The residency-state fit did not produce a valid individual state-classification table.", call. = FALSE)
    }
    tab$model_based_method <- fit$model_name %||% fit$model %||% "state_space_robust_design"
    tab$model_fit_convergence <- fit$convergence %||% NA_integer_
    tab$model_fit_note <- if (isTRUE((fit$convergence %||% 1L) == 0L)) {
        "Optimization reported convergence. Interpret with the model-assumption review and uncertainty diagnostics."
    } else {
        "Diagnostic state classification was produced, but optimization did not report full convergence. Use for screening and review before inferential claims."
    }
    tab$result_interpretation <- "Model-based residency-state classification from the state-space/robust-design backend. It accounts for imperfect detection through the fitted detection/state model, but it still depends on the assumptions listed in Option 4."
    tab
}

fit_model_based_residency_from_review <- function(analysis, input_provider = NULL,
                                                 maxit = getOption("resident.option7.state_maxit", 5L),
                                                 hessian = FALSE) {
    if (is.null(resident_get_exact_slot(analysis, "model_assumption_recommendation"))) {
        cat("\nOption 7 needs the model-assumption review from Option 4. Computing that review first.\n")
        analysis <- safe_detection_review_from_analysis(analysis)
    }
    existing <- safe_residency_result_table(analysis)
    if (!is.null(existing)) {
        print_console_table(existing, title = "Model-based residency-state results",
            export_prefix = "model_based_residency_results")
        print_interpretation_box("These are stored model-based residency-state results. Option 8 can compare them with literature-based classifications.")
        return(analysis)
    }
    cat("\nFitting diagnostic state-space residency model for Option 7\n")
    cat("==========================================================\n")
    cat("Resident will use the current model-assumption review and the state-space/robust-design backend to classify individual residency states.\n")
    cat("This is a model-based classification workflow. If optimization warnings are reported, treat the table as diagnostic until stronger fitting diagnostics are reviewed.\n")
    fit <- tryCatch(
        fit_state_space_model_from_analysis(analysis, maxit = maxit, hessian = hessian),
        error = function(e) e
    )
    if (inherits(fit, "error") || !is.null(fit$error)) {
        msg <- if (inherits(fit, "error")) conditionMessage(fit) else fit$error
        analysis$last_residency_state_fit_status <- list(status = "failed", model = "state_space_robust_design", error = msg)
        resident_print_unavailable("Model-based residency-state results",
            paste("The state-space residency model could not be fitted:", msg),
            "Review Option 4 assumptions, define temporal structure when required, or continue with literature-based classifications in Options 5 and 6.")
        return(analysis)
    }
    fit$model_name <- fit$model_name %||% "state_space_robust_design"
    tab <- resident_prepare_model_based_residency_table(fit, analysis)
    analysis$residency_state_fit <- fit
    analysis$state_space_fit <- fit
    analysis$model_based_residency_results <- tab
    analysis$residency_state_results <- tab
    analysis$last_residency_state_fit_status <- list(status = "fit_stored",
        model = fit$model_name, rows = nrow(tab),
        storage = c("analysis$residency_state_fit", "analysis$state_space_fit",
                    "analysis$model_based_residency_results", "analysis$residency_state_results"))
    assign("analysis", analysis, envir = .GlobalEnv)
    print_console_table(tab, title = "Model-based residency-state results",
        key_columns = c("id", "most_likely_state", "resident_probability",
                        "availability_probability", "classification_confidence",
                        "model_fit_note"),
        export_prefix = "model_based_residency_results")
    print_interpretation_box("Option 7 has fitted/stored a model-based residency-state table. The state names are model states; they should be interpreted together with Option 4 assumptions and the convergence note.")
    analysis
}

.resident_v098_handle_post_simulation_menu_choice <- handle_post_simulation_menu_choice
handle_post_simulation_menu_choice <- function(choice, analysis, input_provider = NULL) {
    menu <- post_simulation_menu_definition()
    key <- normalize_menu_choice(choice, menu)
    if (identical(key, "model_residency")) {
        analysis <- fit_model_based_residency_from_review(analysis, input_provider = input_provider)
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    if (identical(key, "literature_comparison")) {
        analysis <- ensure_literature_residency_outputs(analysis)
        if (is.null(safe_residency_result_table(analysis))) {
            analysis <- fit_model_based_residency_from_review(analysis, input_provider = input_provider)
        }
        tab <- safe_literature_comparison_table(analysis)
        if (is.null(tab)) {
            resident_print_unavailable("Model-vs-literature comparison",
                "The comparison could not be built because a valid model-based residency-state table or literature-classification table is still missing.",
                "Run Option 4, then Option 7, then return to Option 8.")
        } else {
            analysis$model_literature_comparison <- tab
            print_console_table(tab, title = "Model-vs-literature residency comparison",
                export_prefix = "model_literature_comparison")
            print_interpretation_box("Rows compare the fitted model-based residency-state classification with the literature-based residency/site-fidelity classifications for the same individuals.")
        }
        assign("analysis", analysis, envir = .GlobalEnv)
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    .resident_v098_handle_post_simulation_menu_choice(choice, analysis, input_provider)
}


# v0.9.41 import, comparison display, and model-category plotting repairs.
resident_file_looks_like_mark_inp <- function(path) {
    ext <- tolower(tools::file_ext(path))
    if (identical(ext, "inp")) return(TRUE)
    lines <- tryCatch(resident_read_text_lines(path), error = function(e) character())
    lines <- trimws(lines[nzchar(trimws(lines))])
    lines <- lines[seq_len(min(length(lines), 30L))]
    any(grepl("^/\\*[^*]+\\*/\\s*[01]+\\s+[0-9]+\\s*;?", lines))
}

resident_resolve_import_format <- function(path, selected_format) {
    selected <- toupper(gsub("[ -]+", "_", as.character(selected_format %||% "AUTO")))
    detected <- resident_detect_import_format(path)
    if (identical(selected, "AUTO")) return(list(format = detected, detected = detected, note = character()))
    if (identical(selected, "PROGRAM_MARK") && resident_file_looks_like_mark_inp(path)) {
        return(list(format = "MARK_INP", detected = "MARK_INP",
            note = "The selected Program MARK table reader was changed to MARK_INP because the file uses original MARK .inp rows such as /*id*/0101 1;."))
    }
    list(format = selected, detected = detected, note = character())
}

validate_import_file_before_analysis <- function(path, format = c("PROGRAM_MARK", "SOCPROG", "CSV_LONG",
    "WIDE_CSV", "MARK_INP", "EXCEL", "AUTO")) {
    selected <- toupper(gsub("[ -]+", "_", as.character(format[1])))
    if (!nzchar(path %||% ""))
        return(list(ok = FALSE, status = "invalid", selected_format = selected,
            detected_format = NA_character_, path = path, problems = .import_problem_table("No file path was provided.",
                "Enter a full path to a data file or type exit."), warnings = character(), imported = NULL))
    path <- path.expand(path)
    if (!file.exists(path))
        return(list(ok = FALSE, status = "invalid", selected_format = selected,
            detected_format = NA_character_, path = path, problems = .import_problem_table("File does not exist.",
                "Check the spelling of the path, or drag the file into the R console to paste its full path."), warnings = character(), imported = NULL))
    resolved <- resident_resolve_import_format(path, selected)
    detected <- resolved$format
    if (detected %in% c("UNKNOWN", "METADATA"))
        return(list(ok = FALSE, status = "invalid", selected_format = selected,
            detected_format = resolved$detected, path = path, problems = .import_problem_table("The file is not a direct encounter-history input file.",
                "Choose a MARK, SOCPROG, wide encounter-history CSV, .inp, or supported Excel workbook."), warnings = resolved$note, imported = NULL))
    attempt <- .validate_import_for_format(path, detected)
    warnings <- c(resolved$note, attempt$warnings)
    if (!isTRUE(attempt$ok))
        return(list(ok = FALSE, status = "invalid", selected_format = selected,
            detected_format = resolved$detected, resolved_format = detected, path = path,
            problems = attempt$problems, warnings = warnings,
            imported = attempt$imported %||% NULL, attempts = list(attempt)))
    imported <- attempt$imported
    check <- check_capture_data_format(imported)
    check$summary <- capture_data_summary(imported$history, imported$occasions, data_type = "empirical")
    list(ok = TRUE, status = "valid", selected_format = selected,
        detected_format = resolved$detected, resolved_format = detected, path = path,
        problems = .import_problem_table(), warnings = warnings,
        date_status = attempt$date_status, imported = imported, check = check,
        attempts = list(attempt))
}

read_resident_capture_file <- function(file, format = "AUTO", ...) {
    selected <- toupper(gsub("[ -]+", "_", format))
    resolved <- resident_resolve_import_format(file, selected)
    switch(resolved$format,
        PROGRAM_MARK = read_program_mark_format(file, ...),
        SOCPROG = read_socprog_format(file, ...),
        CSV_LONG = read_socprog_format(file, ...),
        WIDE_CSV = read_wide_encounter_history_csv(file, ...),
        MARK_INP = read_mark_inp_format(file, ...),
        EXCEL = read_excel_sightings_workbook(file),
        METADATA = stop("This file is metadata/audit documentation, not an encounter-history input file. Use the referenced MARK, SOCPROG, wide encounter-history CSV, or .inp data file.", call. = FALSE),
        stop("Unsupported or unrecognized import format: ", resolved$format, call. = FALSE))
}

model_based_state_proportion_table <- function(analysis) {
    tab <- safe_residency_result_table(analysis)
    if (is.null(tab)) return(NULL)
    state_col <- intersect(c("most_likely_state", "model_based_state", "assigned_state"), names(tab))[1]
    if (is.na(state_col)) return(NULL)
    counts <- as.data.frame(table(as.character(tab[[state_col]])), stringsAsFactors = FALSE)
    names(counts) <- c("model_state", "number_of_individuals")
    counts$proportion <- counts$number_of_individuals / max(1L, sum(counts$number_of_individuals))
    counts$classifier <- unique(tab$model_based_method %||% "state_space_robust_design")[1]
    counts$assessment_type <- "model-based residency-state classification"
    counts$category_type <- "model states"
    counts$result_interpretation <- "Model-based proportions summarize the individual states assigned by Option 7. They are not literature-rule categories."
    counts
}

print_model_literature_comparison_readable <- function(tab, n = 12L) {
    if (is.null(tab) || !is.data.frame(tab) || !nrow(tab)) return(invisible(NULL))
    id_col <- intersect(c("id", "individual_id"), names(tab))[1]
    state_col <- intersect(c("most_likely_state", "model_based_state", "assigned_state"), names(tab))[1]
    model_cols <- intersect(c(id_col, state_col, "resident_probability", "availability_probability", "classification_confidence", "model_fit_note"), names(tab))
    lit_cols <- intersect(c(id_col, "primary_classifier", "primary_literature_category", "chabanne_category", "moller_category", "dinis_category", "conway_general", "balmer_category"), names(tab))
    cat("\nModel-vs-literature residency comparison\n")
    cat("======================================\n")
    cat("The complete comparison is wide, so the console shows readable blocks. The full table is still stored/exported with all columns. Rows compare one individual at a time: model-based states from Option 7 are shown beside literature classifications from Option 5.\n")
    print_console_table(tab[, unique(model_cols), drop = FALSE], title = "Model-based state columns", max_rows = n, export_prefix = "model_literature_comparison_model_columns")
    print_console_table(tab[, unique(lit_cols), drop = FALSE], title = "Literature-classification columns", max_rows = n, export_prefix = "model_literature_comparison_literature_columns")
    cat("\nDetailed comparison for first ", min(n, nrow(tab)), " individuals\n", sep = "")
    cat("--------------------------------------------------\n")
    for (i in seq_len(min(n, nrow(tab)))) {
        row <- tab[i, , drop = FALSE]
        cat("\n", as.character(row[[id_col]][1]), "\n", sep = "")
        if (!is.na(state_col)) cat("- Model state: ", as.character(row[[state_col]][1]), "\n", sep = "")
        for (nm in setdiff(unique(c(model_cols, lit_cols)), c(id_col, state_col))) {
            if (nm %in% names(row)) cat("- ", resident_pretty_summary_label(nm), ": ", resident_format_summary_value(row[[nm]][1], digits = 3L), "\n", sep = "")
        }
    }
    print_interpretation_box("Option 8 compares model-based states from Option 7 with literature-based classifications from Option 5. Disagreement is expected for some individuals because the model accounts for missed detections while literature rules summarize observed detections.")
    invisible(tab)
}

print_combined_category_proportions <- function(analysis) {
    analysis <- ensure_literature_residency_outputs(analysis)
    lit <- safe_category_proportion_table(analysis)
    if (!is.null(lit)) {
        print_console_table(lit, title = "Literature-classification category proportions",
            export_prefix = "literature_classification_category_proportions")
    }
    model <- model_based_state_proportion_table(analysis)
    if (!is.null(model)) {
        analysis$model_based_state_proportions <- model
        print_console_table(model, title = "Model-based residency-state proportions from Option 7",
            key_columns = c("model_state", "number_of_individuals", "proportion", "classifier", "result_interpretation"),
            export_prefix = "model_based_state_proportions")
        print_interpretation_box("The model-based table summarizes states assigned by Option 7. It complements, but does not replace, the literature-classification proportions.")
    } else {
        resident_print_unavailable("Model-based residency-state proportions",
            "No Option 7 model-based residency-state table is stored yet.",
            "Run Option 7 first if you want model-based state proportions. Literature proportions above remain valid without Option 7.")
    }
    analysis
}

prepare_model_based_state_plot_data <- function(analysis) {
    model <- model_based_state_proportion_table(analysis)
    if (is.null(model)) return(NULL)
    data.frame(classifier = model$classifier,
        assessment_type = model$assessment_type,
        category_type = model$category_type,
        category = model$model_state,
        number_of_individuals = model$number_of_individuals,
        proportion = model$proportion,
        indicator_family = "model_based_residency_state",
        indicator_family_label = "Model-based residency states from Option 7",
        category_axis_label = model$model_state,
        category_type_label = "model states",
        plot_interpretation = "Bars summarize the model-based residency states assigned by Option 7.",
        stringsAsFactors = FALSE)
}

safe_plot_category_from_analysis <- function(analysis) {
    plot_data <- prepare_category_proportion_plot_data(analysis)
    model_plot_data <- prepare_model_based_state_plot_data(analysis)
    if (is.null(plot_data) && is.null(model_plot_data)) {
        resident_print_unavailable("Residency and site-fidelity category proportion plot",
            "No literature-classification or model-based category table is available yet.",
            "Use option 5 for literature classifications and optionally option 7 for model-based state classifications, then run option 14 again.")
        return(analysis)
    }
    if (!is.null(model_plot_data)) plot_data <- rbind(plot_data, model_plot_data)
    csv_path <- .timestamped_output_path("category_proportion_plot_data", "csv", output_dir = table_output_options()$output_dir)
    utils::write.csv(plot_data, csv_path, row.names = FALSE)
    families <- intersect(c("residency", "sighting_frequency_proxy", "true_site_fidelity", "model_based_residency_state"), unique(plot_data$indicator_family))
    png_paths <- vapply(families, function(fam) resident_draw_category_proportion_plot(plot_data, fam, draw_to_active_device = TRUE), character(1))
    analysis$category_proportion_plot_data <- plot_data
    analysis$category_proportion_plot_data_csv <- csv_path
    analysis$category_proportion_plot_png <- png_paths
    cat("\nResidency and site-fidelity literature/model category proportion plots\n")
    cat("=================================================================\n")
    cat("Plots are split by biological meaning: literature residency classifications, sighting-frequency/site-use proxy classifications, true site-fidelity indices when available, and model-based residency states when Option 7 has been run.\n")
    cat("Panels identify the published classifier or the model source. Names for categories follow those from Huesca et al. (2024). Model-based states are labelled separately when Option 7 results are available. The x-axis is the proportion of individuals.\n")
    if (is.null(model_plot_data)) cat("No model-based state plot was added because Option 7 results are not stored yet. The literature plots remain available.\n")
    if (!"true_site_fidelity" %in% unique(plot_data$indicator_family)) cat("No true site-fidelity index is plotted because the current table does not contain a spatial site-use index. Frequency-based rules are shown as proxy classifications instead.\n")
    cat("Plot data saved to:", csv_path, "\n")
    for (fam in names(png_paths)) cat(unique(plot_data$indicator_family_label[plot_data$indicator_family == fam])[1], "plot saved to:", png_paths[[fam]], "\n")
    analysis
}

.resident_v099_handle_post_simulation_menu_choice <- handle_post_simulation_menu_choice
handle_post_simulation_menu_choice <- function(choice, analysis, input_provider = NULL) {
    menu <- post_simulation_menu_definition()
    key <- normalize_menu_choice(choice, menu)
    if (identical(key, "literature_comparison")) {
        analysis <- ensure_literature_residency_outputs(analysis)
        if (is.null(safe_residency_result_table(analysis))) analysis <- fit_model_based_residency_from_review(analysis, input_provider = input_provider)
        tab <- safe_literature_comparison_table(analysis)
        if (is.null(tab)) {
            resident_print_unavailable("Model-vs-literature comparison",
                "The comparison could not be built because a valid model-based residency-state table or literature-classification table is still missing.",
                "Run Option 4, then Option 7, then return to Option 8.")
        } else {
            analysis$model_literature_comparison <- tab
            print_model_literature_comparison_readable(tab)
        }
        assign("analysis", analysis, envir = .GlobalEnv)
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    if (identical(key, "category_proportions")) {
        analysis <- print_combined_category_proportions(analysis)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    if (identical(key, "plot_category")) {
        analysis <- safe_plot_category_from_analysis(analysis)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    .resident_v099_handle_post_simulation_menu_choice(choice, analysis, input_provider)
}

# v0.9.41 Option 7 and Option 21 teaching-display upgrades.
resident_format_bool_status <- function(x, yes = "available", no = "not available") {
    if (isTRUE(x)) yes else no
}

resident_option21_data_snapshot <- function(analysis) {
    diag <- abundance_data_diagnostics(analysis)
    if (!isTRUE(diag$ok)) {
        return(data.frame(item = "data availability", current_value = diag$reason,
            meaning = "Resident could not read a capture-recapture history for abundance-model screening.",
            why_it_matters = "Model recommendations require a valid individual-by-occasion encounter history.",
            stringsAsFactors = FALSE))
    }
    date_status <- NA_character_
    sampling_period <- NA_character_
    cap <- tryCatch(analysis_capture_data_summary(analysis), error = function(e) NULL)
    if (is.data.frame(cap) && nrow(cap)) {
        date_status <- as.character(cap$date_status[1])
        if ("sampling_period_days" %in% names(cap)) sampling_period <- as.character(cap$sampling_period_days[1])
    }
    data.frame(
        item = c("individuals", "sampling occasions", "detection records", "overall detection rate",
            "recaptured individuals", "individuals detected once", "empty occasions", "temporal structure",
            "survey-date status", "sampling-period length"),
        current_value = c(diag$n_ids, diag$n_occ, diag$total_detections,
            round(diag$detection_rate, 3), diag$recaptured_individuals,
            diag$singletons, diag$occasions_with_no_detections,
            resident_format_bool_status(diag$robust_design_supported, "primary/secondary periods available", "primary/secondary periods not defined"),
            date_status %||% "not stored", sampling_period %||% "not available"),
        meaning = c("Number of different individuals in the encounter history.",
            "Number of sampling occasions or survey periods in the encounter history.",
            "Total number of one-values in the encounter history.",
            "Proportion of individual-occasion cells with a detection.",
            "Individuals detected on two or more occasions.",
            "Individuals detected on exactly one occasion.",
            "Sampling occasions with no detections at all.",
            "Whether robust-design primary and secondary periods are already available.",
            "Whether dates should be treated as observed survey dates, synthetic dates, or absent dates.",
            "Approximate time span covered by the stored sampling dates when available."),
        why_it_matters = c("Sets the number of animals available for classification and abundance screening.",
            "Open-population and time-varying models need enough temporal replication.",
            "Sparse data make complex abundance models unstable.",
            "Very low detection creates uncertainty about missed individuals.",
            "Recaptures are what let capture-recapture models estimate detection rather than just count animals.",
            "Many single detections suggest missed individuals, temporary presence, or detection heterogeneity.",
            "Empty occasions can destabilize time-varying detection models.",
            "Robust Design models require correct primary and secondary grouping before fitting.",
            "Dates affect temporal grouping, discovery curves, and interpretation of open-population designs.",
            "Long spans may violate closure unless shorter closed periods are defined."),
        stringsAsFactors = FALSE
    )
}

resident_suitability_is_positive <- function(x) {
    x <- as.character(x)
    x %in% c("recommended", "useful_baseline", "acceptable_with_caution")
}

resident_suitability_is_deferred <- function(x) {
    x <- as.character(x)
    x %in% c("not_recommended", "not_assessable")
}

resident_option21_next_step <- function(details) {
    if (!is.data.frame(details) || !nrow(details)) {
        return("Use Option 4 to review assumptions, then return to Option 21.")
    }
    positives <- details[resident_suitability_is_positive(details$display_suitability), , drop = FALSE]
    if (!nrow(positives)) positives <- details[seq_len(min(1L, nrow(details))), , drop = FALSE]
    row <- positives[1, , drop = FALSE]
    paste0("Recommended next step: use Option 22 and enter model menu option ", row$option,
        " (", row$candidate_model, "). This fits the model; Option 21 only recommends and teaches.")
}

print_option7_residency_state_learning_note <- function() {
    cat("\nOption 7 residency-state guide\n")
    cat("==============================\n")
    cat("Question answered: Which residency or availability state is most supported for each individual?\n")
    cat("Output level: individual dolphins, one row per identified animal.\n")
    cat("Important distinction: this is not the abundance recommendation. It classifies individual states; Option 21 evaluates which abundance/population-parameter models are suitable for the whole dataset.\n")
    cat("How to read the table: resident_probability and availability_probability are model-based probabilities. A high availability_probability can still occur with no detection because the model allows missed detections.\n")
    cat("Use next: Option 8 compares these model-based states with literature classifications, Option 9 summarizes proportions, and Option 14 can plot the model-state proportions.\n")
    invisible(TRUE)
}

print_option21_teaching_report <- function(analysis) {
    if (is.null(resident_get_exact_slot(analysis, "model_assumption_recommendation"))) {
        analysis <- safe_detection_review_from_analysis(analysis)
    }
    details <- rank_model_recommendations_for_assumption_review(analysis)
    snapshot <- resident_option21_data_snapshot(analysis)
    positives <- details[resident_suitability_is_positive(details$display_suitability), , drop = FALSE]
    deferred <- details[resident_suitability_is_deferred(details$display_suitability), , drop = FALSE]
    top <- if (nrow(positives)) positives[1, , drop = FALSE] else details[1, , drop = FALSE]
    cat("\nAbundance model recommendation and learning guide\n")
    cat("================================================\n")
    cat("Question answered: Which abundance or population-parameter model is most suitable for the current encounter history?\n")
    cat("Output level: model families and data assumptions, not individual residency classes. Option 7 handles individual residency-state classification.\n")
    cat("Teaching purpose: this report explains why a model is recommended, cautious, or deferred before the user fits anything in Option 22.\n")
    print_console_table(snapshot, title = "Data snapshot used for model screening",
        export_prefix = "option21_abundance_data_snapshot")
    cat("\nFirst recommended action\n")
    cat("------------------------\n")
    cat("Model: ", top$candidate_model, "\n", sep = "")
    cat("Model menu option for Option 22: ", top$option, "\n", sep = "")
    cat("Suitability for these data: ", top$display_suitability, "\n", sep = "")
    cat("Why this model is useful now: ", top$recommendation, "\n", sep = "")
    cat("What it estimates: ", top$estimates, "\n", sep = "")
    if (nrow(positives) > 1L) {
        alt <- positives[seq_len(min(3L, nrow(positives))), c("suitability_rank", "option", "candidate_model", "display_suitability", "recommendation"), drop = FALSE]
        print_console_table(alt, title = "Useful alternatives to consider after the first model",
            export_prefix = "option21_useful_alternatives")
    }
    if (nrow(deferred)) {
        avoid <- deferred[seq_len(min(6L, nrow(deferred))), c("suitability_rank", "option", "candidate_model", "display_suitability", "assumptions_status", "expected_risk"), drop = FALSE]
        print_console_table(avoid, title = "Models to defer until assumptions or data support improve",
            export_prefix = "option21_models_to_defer")
    }
    cat("\nAssumption teaching checkpoints\n")
    cat("-------------------------------\n")
    cat("Closure: closed-capture models require a period where animals do not enter, leave, die, or become newly available. If the study spans a long period, define shorter closed periods or prefer open/robust designs.\n")
    cat("Detection probability: capture-recapture abundance depends on estimating animals that were present but missed. Recaptures are essential for this.\n")
    cat("Temporal structure: Robust Design, Jolly-Seber, POPAN-style, and state-space models need meaningful time ordering; Robust Design also needs primary and secondary periods.\n")
    cat("Heterogeneity: if some dolphins are much easier to detect than others, simple constant-detection models can be biased.\n")
    cat("\nComplete model cards\n")
    cat("--------------------\n")
    print_abundance_model_detail_list(details, title = "Abundance model cards")
    cat("\nNext step\n")
    cat("---------\n")
    cat(resident_option21_next_step(details), "\n", sep = "")
    cat("Reminder: Option 21 does not fit a model. Use Option 22 to fit one, then Option 23 to show fitted abundance estimates.\n")
    analysis$abundance_recommendation <- list(recommendation_table = details,
        diagnostics = attr(details, "diagnostics"), snapshot = snapshot,
        source = "v0.9.41_teaching_abundance_model_suitability")
    analysis$option21_teaching_snapshot <- snapshot
    analysis$option21_next_step <- resident_option21_next_step(details)
    analysis
}

.resident_v100_handle_post_simulation_menu_choice <- handle_post_simulation_menu_choice
handle_post_simulation_menu_choice <- function(choice, analysis, input_provider = NULL) {
    menu <- post_simulation_menu_definition()
    key <- normalize_menu_choice(choice, menu)
    if (identical(key, "model_residency")) {
        print_option7_residency_state_learning_note()
        analysis <- fit_model_based_residency_from_review(analysis, input_provider = input_provider)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    if (identical(key, "abundance_recommendation")) {
        analysis <- print_option21_teaching_report(analysis)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(invisible(list(analysis = analysis, finished = FALSE)))
    }
    .resident_v100_handle_post_simulation_menu_choice(choice, analysis, input_provider)
}


# v0.9.41 Option 22 guided abundance fitting wizard.
resident_option22_status_metadata <- function() {
    data.frame(
        candidate_model = c("observed_only", "chao1_chao2", "closed_M0", "closed_Mt", "closed_Mb",
            "closed_Mh_mixture", "huggins_M0", "huggins_Mt", "robust_design_closed_primary",
            "robust_design_huggins_primary", "jolly_seber", "POPAN_like"),
        model_group = c("Descriptive / first-look", "Descriptive / first-look",
            rep("Closed-population models", 4), rep("Huggins conditional models", 2),
            rep("Robust Design abundance models", 2), rep("Open-population abundance models", 2)),
        implementation_status = c("fully_functional_descriptive", "fully_functional_descriptive",
            "functional_direct_likelihood", "diagnostic_simplified", "diagnostic_simplified",
            "diagnostic_simplified", "diagnostic_simplified", "diagnostic_simplified",
            "diagnostic_requires_temporal_structure", "diagnostic_requires_temporal_structure",
            "diagnostic_open_population_summary", "diagnostic_open_population_summary"),
        comparable_likelihood_group = c("not_likelihood", "not_likelihood", "closed_direct", rep("not_comparable_yet", 9)),
        status_meaning = c(
            "Counts detected individuals only; no model for missed animals is fitted.",
            "Computes Chao-style descriptive lower-bound estimates from rare detections.",
            "Fits the current direct closed-capture likelihood used by Resident.",
            "Produces a stored diagnostic/simplified result; full time-varying closed likelihood is planned.",
            "Produces a stored diagnostic/simplified result; full behavioral-response likelihood is planned.",
            "Produces a stored diagnostic/simplified result; full heterogeneity likelihood is planned.",
            "Produces a stored diagnostic/simplified result; full Huggins conditional likelihood is planned.",
            "Produces a stored diagnostic/simplified result; full time-varying Huggins likelihood is planned.",
            "Prompts for primary/secondary periods and produces a diagnostic result; full robust-design likelihood is planned.",
            "Prompts for primary/secondary periods and produces a diagnostic result; full Huggins robust-design likelihood is planned.",
            "Prompts for temporal structure and produces an open-population diagnostic summary; full Jolly-Seber likelihood is planned.",
            "Prompts for temporal structure and produces a POPAN-like diagnostic summary; full POPAN likelihood is planned."),
        student_caution = c(
            "Use as the minimum number known to be alive/identified, not total abundance.",
            "Useful first correction, but sensitive to singletons and doubletons.",
            "Interpret only if closure is biologically defensible.",
            "Good for teaching/model exploration; do not report as final Program MARK-equivalent inference.",
            "Requires a biological reason for trap response or changed detection after first sighting.",
            "Can overfit sparse data; many recaptures are needed for heterogeneity.",
            "Remember that Huggins abundance is derived, not directly estimated as N.",
            "Needs enough detections across occasions to support time-varying detection.",
            "Requires correct primary/secondary periods and closure within primary periods.",
            "Requires robust-design structure and should be treated as diagnostic in this version.",
            "Use to learn about open-population signals, not as final Jolly-Seber inference yet.",
            "Use to learn about superpopulation logic, not as final Program MARK POPAN inference yet."),
        stringsAsFactors = FALSE
    )
}

resident_option22_model_status_table <- function(analysis) {
    details <- tryCatch(rank_model_recommendations_for_assumption_review(analysis), error = function(e) abundance_model_detail_table(analysis))
    details <- details[details$candidate_model %in% implemented_abundance_models(), , drop = FALSE]
    meta <- resident_option22_status_metadata()
    out <- merge(details, meta, by = "candidate_model", all.x = TRUE, sort = FALSE)
    if ("implementation_status.y" %in% names(out)) out$implementation_status <- out$implementation_status.y
    else if ("implementation_status.x" %in% names(out)) out$implementation_status <- out$implementation_status.x
    out$implementation_status.x <- NULL
    out$implementation_status.y <- NULL
    out <- out[match(implemented_abundance_models(), out$candidate_model), , drop = FALSE]
    out$option22_number <- seq_len(nrow(out))
    out$is_selectable_option22 <- TRUE
    keep <- unique(c("option22_number", "candidate_model", "model_group", "display_suitability",
        "implementation_status", "comparable_likelihood_group", "status_meaning", "student_caution",
        "option", "estimates", "main_assumption_or_caution", "recommendation", names(out)))
    keep <- intersect(keep, names(out))
    out <- out[, keep, drop = FALSE]
    row.names(out) <- NULL
    out
}

resident_option22_print_grouped_menu <- function(status_tab) {
    cat("\nGrouped selectable abundance models\n")
    cat("===================================\n")
    groups <- unique(status_tab$model_group)
    for (grp in groups) {
        cat("\n", grp, "\n", sep = "")
        cat(strrep("-", nchar(grp)), "\n", sep = "")
        rows <- status_tab[status_tab$model_group == grp, , drop = FALSE]
        for (i in seq_len(nrow(rows))) {
            cat(sprintf("%2d. %-34s [%s]\n", rows$option22_number[i], rows$candidate_model[i], rows$implementation_status[i]))
        }
    }
    cat("\nNot selectable here\n")
    cat("-------------------\n")
    cat("CJS / Cormack-Jolly-Seber: not an abundance model. It estimates apparent survival/persistence and detection for already observed/marked individuals, so it belongs in survival/detection workflows, not Option 22 abundance fitting.\n")
    cat(" 0. Return without fitting\n")
    invisible(status_tab)
}

resident_option22_print_prefit_wizard <- function(analysis) {
    if (is.null(resident_get_exact_slot(analysis, "model_assumption_recommendation"))) {
        analysis <- safe_detection_review_from_analysis(analysis)
    }
    status_tab <- resident_option22_model_status_table(analysis)
    snapshot <- resident_option21_data_snapshot(analysis)
    cat("\nOption 22: Select and fit abundance/population model\n")
    cat("====================================================\n")
    cat("Question answered: Which abundance or population-parameter model should be fitted now?\n")
    cat("Output level: fitted model object and abundance/population summaries for the whole dataset. Option 7 remains the individual residency-state workflow.\n")
    cat("Safety rule: descriptive and diagnostic outputs are labelled as such. Full likelihood model comparison is only appropriate inside comparable likelihood groups.\n")
    print_console_table(snapshot, title = "Data readiness snapshot before fitting",
        export_prefix = "option22_data_readiness_snapshot")
    recommended <- tryCatch(resident_option21_next_step(status_tab), error = function(e) NULL)
    if (!is.null(recommended)) {
        cat("\nRecommendation carried into Option 22\n")
        cat("------------------------------------\n")
        cat(recommended, "\n", sep = "")
    }
    compact <- status_tab[, intersect(c("option22_number", "candidate_model", "model_group",
        "display_suitability", "implementation_status", "comparable_likelihood_group"), names(status_tab)), drop = FALSE]
    print_console_table(compact, title = "Option 22 model status overview",
        export_prefix = "option22_model_status_overview")
    resident_option22_print_grouped_menu(status_tab)
    analysis$option22_model_status <- status_tab
    analysis$option22_data_readiness_snapshot <- snapshot
    analysis
}

resident_option22_print_selected_card <- function(status_tab, model) {
    row <- status_tab[status_tab$candidate_model == model, , drop = FALSE]
    if (!nrow(row)) return(invisible(NULL))
    cat("\nSelected model teaching card\n")
    cat("============================\n")
    cat("Selected model: ", row$candidate_model[1], "\n", sep = "")
    cat("Model group: ", row$model_group[1], "\n", sep = "")
    cat("Implementation status: ", row$implementation_status[1], "\n", sep = "")
    cat("Comparable likelihood group: ", row$comparable_likelihood_group[1], "\n", sep = "")
    cat("What it estimates: ", row$estimates[1], "\n", sep = "")
    cat("Main assumption/caution: ", row$main_assumption_or_caution[1], "\n", sep = "")
    cat("Current-version status: ", row$status_meaning[1], "\n", sep = "")
    cat("Student caution: ", row$student_caution[1], "\n", sep = "")
    invisible(row)
}

resident_option22_needs_interactive_confirmation <- function(status, input_provider = NULL) {
    is.null(input_provider) && interactive() && grepl("diagnostic|planned|not_comparable", status, ignore.case = TRUE)
}

resident_option22_confirm_diagnostic <- function(status, input_provider = NULL) {
    if (!resident_option22_needs_interactive_confirmation(status, input_provider)) return(TRUE)
    ans <- .resident_prompt("This model is diagnostic/simplified in this version. Enter 1 to continue for teaching/exploration or 0 to choose another model: ", input_provider)
    isTRUE(tryCatch(resident_parse_yes_no_10(ans), error = function(e) FALSE))
}

resident_option22_print_next_steps <- function(model) {
    cat("\nFit/storage confirmation and next steps\n")
    cat("=======================================\n")
    cat("Selected model result was stored for downstream abundance outputs.\n")
    cat("Stored locations: analysis$abundance_fit, analysis$fitted_model, analysis$model_fit, and analysis$model_results.\n")
    cat("Recommended next steps: Option 23 shows fitted abundance estimates; Option 24 shows MARK-style parameter output; Option 25 shows derived parameters; Option 26 plots abundance estimates; Option 28 exports abundance outputs.\n")
    cat("Model-comparison reminder: compare likelihood models only within the same comparable_likelihood_group. Descriptive counts, Chao estimators, diagnostic summaries, conditional likelihoods, and full likelihoods should not be combined in one unrestricted information-criterion table.\n")
    invisible(model)
}

.resident_v101_safe_select_and_fit_abundance_model <- safe_select_and_fit_abundance_model
safe_select_and_fit_abundance_model <- function(analysis, input_provider = NULL) {
    analysis <- resident_option22_print_prefit_wizard(analysis)
    models <- implemented_abundance_models()
    models <- models[!is.na(models)]
    status_tab <- analysis$option22_model_status
    ans <- .resident_prompt("Enter abundance model number or name: ", input_provider)
    key <- trimws(as.character(ans))
    if (!nzchar(key) || key == "0") {
        analysis$last_fit_status <- list(status = "cancelled", reason = "User returned without selecting a model.")
        assign("analysis", analysis, envir = .GlobalEnv)
        return(analysis)
    }
    model <- if (grepl("^[0-9]+$", key) && as.integer(key) >= 1L && as.integer(key) <= length(models)) models[as.integer(key)] else key
    if (toupper(model) %in% c("CJS", "CJS_LIKE", "CORMACK_JOLLY_SEBER")) {
        cat("CJS / Cormack-Jolly-Seber is not selectable in Option 22 because it is not an abundance model. Use survival/detection workflows for CJS-style questions.\n")
        analysis$last_fit_status <- list(status = "not_abundance_model", model = model)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(analysis)
    }
    if (!model %in% models) {
        cat("Model was not selected because it is not an implemented abundance model: ", model, "\n", sep = "")
        analysis$last_fit_status <- list(status = "invalid_model", model = model)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(analysis)
    }
    selected_status <- status_tab[status_tab$candidate_model == model, , drop = FALSE]
    resident_option22_print_selected_card(status_tab, model)
    if (!resident_option22_confirm_diagnostic(selected_status$implementation_status[1], input_provider = input_provider)) {
        cat("Model fitting cancelled before running the diagnostic/simplified model.\n")
        analysis$last_fit_status <- list(status = "cancelled_diagnostic_model", model = model)
        assign("analysis", analysis, envir = .GlobalEnv)
        return(analysis)
    }
    report <- print_selected_model_assumption_report(analysis, model, title = "Selected model suitability before fitting")
    label <- if (!is.null(report) && nrow(report)) report$display_suitability[1] else "not_assessed"
    if (!model_selection_allowed_without_warning(label)) {
        cat("\nWarning: this model is not recommended for the current data diagnostics.\n")
        cat("The software will still create a fitted or diagnostic result so option 23 can report what was produced. Interpret results with the assumption warnings above.\n")
    }
    analysis <- tryCatch({
        if (requires_temporal_structure(model)) {
            gate <- temporal_model_gate(analysis = analysis, model = model,
                input_provider = input_provider, data_type = analysis$data_type %||% "empirical")
            analysis <- gate$analysis
        }
        fit <- direct_abundance_fit(analysis, model)
        fit$implementation_status <- selected_status$implementation_status[1]
        fit$comparable_likelihood_group <- selected_status$comparable_likelihood_group[1]
        analysis$abundance_fit <- fit
        analysis$fitted_model <- fit
        analysis$model_fit <- fit
        analysis$model_results <- fit$estimates
        analysis$abundance_model_choice <- list(candidate_model = model,
            source = "direct_v0.9.41_guided_option22", suitability = label,
            implementation_status = selected_status$implementation_status[1],
            comparable_likelihood_group = selected_status$comparable_likelihood_group[1])
        analysis$last_fit_status <- list(status = "fit_stored", model = model,
            storage = c("analysis$abundance_fit", "analysis$fitted_model", "analysis$model_fit", "analysis$model_results"))
        assign("analysis", analysis, envir = .GlobalEnv)
        print_direct_abundance_fit(fit)
        resident_option22_print_next_steps(model)
        analysis
    }, error = function(e) {
        cat("\nFit failed for selected model: ", model, "\n", sep = "")
        cat("Reason reported by fitting function: ", conditionMessage(e), "\n", sep = "")
        print_selected_model_assumption_report(analysis, model, title = "Why this model may have failed")
        analysis$last_fit_status <- list(status = "fit_failed", model = model, error = conditionMessage(e))
        assign("analysis", analysis, envir = .GlobalEnv)
        cat("Guidance: choose a model classified as recommended, useful_baseline, or acceptable_with_caution, or simplify the model/data structure before fitting.\n")
        analysis
    })
    analysis
}

cat(resident_load_message(), "\n", sep = "")
if (interactive() && isTRUE(getOption("resident_pipeline.autostart", TRUE))) { resident_pipeline_startup(ask_tmb = interactive(), ask_data_or_simulation = TRUE, create_templates = TRUE, input_provider = NULL, show_load_message = FALSE) }
